pub fn validate_path2_native_checked_core_frame_v1(
    frame: &Path2NativeCheckedCoreFrameV1,
) -> Result<(), String> {
    if frame.native_boundary_version != PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION {
        return Err(format!(
            "Path 2 native checked-core frame version mismatch: got {}, expected {}",
            frame.native_boundary_version, PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION
        ));
    }
    if frame.parameter_set_id != PATH2_NATIVE_CHECKED_CORE_PARAMETER_SET_Q12289 {
        return Err(format!(
            "Path 2 native checked-core parameter set mismatch: got {}, expected {}",
            frame.parameter_set_id, PATH2_NATIVE_CHECKED_CORE_PARAMETER_SET_Q12289
        ));
    }
    if frame.verifier_family_id != PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12 {
        return Err(format!(
            "Path 2 native checked-core verifier family mismatch: got {}, expected {}",
            frame.verifier_family_id, PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12
        ));
    }
    match frame.aggregation_mode {
        PATH2_NATIVE_AGGREGATION_MODE_DIRECT
        | PATH2_NATIVE_AGGREGATION_MODE_AGGREGATE_COMPATIBLE => Ok(()),
        mode => Err(format!(
            "Path 2 native checked-core aggregation mode {mode} is reserved"
        )),
    }
}

pub fn path2_native_checked_core_frame_v1_bytes(
    frame: &Path2NativeCheckedCoreFrameV1,
) -> Result<Vec<u8>, String> {
    validate_path2_native_checked_core_frame_v1(frame)?;

    let mut out = Vec::with_capacity(PATH2_NATIVE_CHECKED_CORE_FRAME_BYTES);
    out.extend_from_slice(PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.as_bytes());
    out.extend_from_slice(&frame.native_boundary_version.to_le_bytes());
    out.extend_from_slice(&frame.parameter_set_id.to_le_bytes());
    out.extend_from_slice(&frame.verifier_family_id.to_le_bytes());
    for digest in [
        &frame.account_creation_domain_digest,
        &frame.spend_verifier_domain_digest,
        &frame.chain_or_application_domain_digest,
        &frame.fork_or_epoch_scope_digest,
    ] {
        out.extend_from_slice(digest);
    }
    out.push(frame.aggregation_mode);
    for digest in [
        &frame.native_boundary_digest,
        &frame.p_account_digest,
        &frame.p_spend_digest,
        &frame.p_lifecycle_digest,
        &frame.p_transcript_digest,
        &frame.p_state_digest,
        &frame.message_digest,
        &frame.current_state_digest,
        &frame.proof_commitment,
    ] {
        out.extend_from_slice(digest);
    }
    debug_assert_eq!(out.len(), PATH2_NATIVE_CHECKED_CORE_FRAME_BYTES);
    Ok(out)
}

fn read_path2_native_checked_core_digest(bytes: &[u8], offset: &mut usize) -> [u8; DIGEST_BYTES] {
    let mut digest = [0_u8; DIGEST_BYTES];
    digest.copy_from_slice(&bytes[*offset..*offset + DIGEST_BYTES]);
    *offset += DIGEST_BYTES;
    digest
}

pub fn decode_path2_native_checked_core_frame_v1(
    bytes: &[u8],
) -> Result<Path2NativeCheckedCoreFrameV1, String> {
    if bytes.len() != PATH2_NATIVE_CHECKED_CORE_FRAME_BYTES {
        return Err(format!(
            "Path 2 native checked-core frame has {} bytes, expected {}",
            bytes.len(),
            PATH2_NATIVE_CHECKED_CORE_FRAME_BYTES
        ));
    }
    if !bytes.starts_with(PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.as_bytes()) {
        return Err("Path 2 native checked-core frame domain mismatch".to_string());
    }

    let mut offset = PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.len();
    let native_boundary_version = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]);
    offset += 2;
    let parameter_set_id = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]);
    offset += 2;
    let verifier_family_id = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]);
    offset += 2;

    let account_creation_domain_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let spend_verifier_domain_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let chain_or_application_domain_digest =
        read_path2_native_checked_core_digest(bytes, &mut offset);
    let fork_or_epoch_scope_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let aggregation_mode = bytes[offset];
    offset += 1;
    let native_boundary_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_account_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_spend_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_lifecycle_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_transcript_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_state_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let message_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let current_state_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let proof_commitment = read_path2_native_checked_core_digest(bytes, &mut offset);
    debug_assert_eq!(offset, PATH2_NATIVE_CHECKED_CORE_FRAME_BYTES);

    let frame = Path2NativeCheckedCoreFrameV1 {
        native_boundary_version,
        parameter_set_id,
        verifier_family_id,
        account_creation_domain_digest,
        spend_verifier_domain_digest,
        chain_or_application_domain_digest,
        fork_or_epoch_scope_digest,
        aggregation_mode,
        native_boundary_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_transcript_digest,
        p_state_digest,
        message_digest,
        current_state_digest,
        proof_commitment,
    };
    validate_path2_native_checked_core_frame_v1(&frame)?;
    Ok(frame)
}

pub fn path2_native_checked_core_frame_v1_challenge(
    frame: &Path2NativeCheckedCoreFrameV1,
) -> Result<[u8; CHALLENGE_BYTES], String> {
    // Re-hosted to Poseidon2 (2026-06-18, approved): recursion-friendly FS for the
    // checked-core relation. Prover + verifier both route through here, so the change
    // is consistent; only the challenge VALUES change. The main LINEAR_SIGMA
    // transaction challenge (`challenge_bytes`) still uses the SHA-256 derivation and
    // its KAT corpus is untouched.
    Ok(hash_frame_to_challenge_bytes_poseidon2(
        &path2_native_checked_core_frame_v1_bytes(frame)?,
    ))
}

pub fn path2_native_checked_core_frame_v1_digest(
    frame: &Path2NativeCheckedCoreFrameV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(path2_native_checked_core_frame_v1_bytes(frame)?).into())
}

pub fn public_native_account_view_v1(
    native_boundary_version: u16,
    parameter_set_id: u16,
    verifier_family_id: u16,
    aggregation_mode: u8,
    native_boundary_digest: [u8; DIGEST_BYTES],
    p_context_digest: [u8; DIGEST_BYTES],
    p_account_digest: [u8; DIGEST_BYTES],
    p_spend_digest: [u8; DIGEST_BYTES],
    p_lifecycle_digest: [u8; DIGEST_BYTES],
    p_transcript_digest: [u8; DIGEST_BYTES],
    p_state_digest: [u8; DIGEST_BYTES],
    public_lifecycle_marker: u8,
    public_state_root: [u8; DIGEST_BYTES],
    obstruction_flags_digest: [u8; DIGEST_BYTES],
) -> Result<PublicNativeAccountViewV1, String> {
    let context_probe = Path2NativeCheckedCoreFrameV1 {
        native_boundary_version,
        parameter_set_id,
        verifier_family_id,
        account_creation_domain_digest: [0_u8; DIGEST_BYTES],
        spend_verifier_domain_digest: [0_u8; DIGEST_BYTES],
        chain_or_application_domain_digest: [0_u8; DIGEST_BYTES],
        fork_or_epoch_scope_digest: [0_u8; DIGEST_BYTES],
        aggregation_mode,
        native_boundary_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_transcript_digest,
        p_state_digest,
        message_digest: [0_u8; DIGEST_BYTES],
        current_state_digest: public_state_root,
        proof_commitment: [0_u8; DIGEST_BYTES],
    };
    validate_path2_native_checked_core_frame_v1(&context_probe)?;
    Ok(PublicNativeAccountViewV1 {
        schema: PATH2_PUBLIC_NATIVE_ACCOUNT_VIEW_SCHEMA,
        native_boundary_version,
        parameter_set_id,
        verifier_family_id,
        aggregation_mode,
        native_boundary_digest,
        p_context_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_transcript_digest,
        p_state_digest,
        public_lifecycle_marker,
        public_state_root,
        obstruction_flags_digest,
    })
}

pub fn public_native_account_view_v1_json(
    view: &PublicNativeAccountViewV1,
) -> Result<String, String> {
    serde_json::to_string(view).map_err(|err| format!("encode public native account view: {err}"))
}

pub fn public_native_spend_view_v1(
    checked_core_frame: &Path2NativeCheckedCoreFrameV1,
    checked_core_proof_bytes: &[u8],
) -> Result<PublicNativeSpendViewV1, String> {
    validate_path2_native_checked_core_frame_v1(checked_core_frame)?;
    if checked_core_proof_bytes.len() != PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES {
        return Err(format!(
            "Path 2 native checked-core proof has {} bytes, expected {}",
            checked_core_proof_bytes.len(),
            PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES
        ));
    }
    Ok(PublicNativeSpendViewV1 {
        schema: PATH2_PUBLIC_NATIVE_SPEND_VIEW_SCHEMA,
        native_boundary_digest: checked_core_frame.native_boundary_digest,
        checked_core_frame_digest: path2_native_checked_core_frame_v1_digest(checked_core_frame)?,
        message_digest: checked_core_frame.message_digest,
        current_state_digest: checked_core_frame.current_state_digest,
        proof_commitment: checked_core_frame.proof_commitment,
        checked_core_proof_bytes_digest: Sha256::digest(checked_core_proof_bytes).into(),
        checked_core_proof_byte_len: checked_core_proof_bytes
            .len()
            .try_into()
            .map_err(|_| "checked-core proof byte length overflow".to_string())?,
    })
}

pub fn public_native_spend_view_v1_json(view: &PublicNativeSpendViewV1) -> Result<String, String> {
    serde_json::to_string(view).map_err(|err| format!("encode public native spend view: {err}"))
}

fn path2_active_native_public_output_has_no_private_material_v1(rendered: &str) -> bool {
    let forbidden_markers = [
        "AuthorizationLocal",
        "private_signing",
        "private_trapdoor",
        "raw_pad_seed",
        "pad_seed",
        "pad_source",
        "opening_tuple",
        "opening_commitment",
        "opening_preimage",
        "unmasked_projection",
        "account_projection",
        "gauge",
        "randomizer",
        "blinding",
        "transparent_query_opening",
        "range_witness",
        "digit_witness",
        "carrier_transcript_binding",
        "projection_carrier",
        "checked_core_signature_or_proof_bytes",
    ];
    forbidden_markers
        .iter()
        .all(|marker| !rendered.contains(marker))
}

pub fn path2_native_no_export_serializer_evidence_v1(
    accept_output: &str,
    reject_output: &str,
    storage_output: &str,
) -> Path2NativeNoExportSerializerEvidenceV1 {
    let accept_output_digest: [u8; DIGEST_BYTES] = Sha256::digest(accept_output.as_bytes()).into();
    let reject_output_digest: [u8; DIGEST_BYTES] = Sha256::digest(reject_output.as_bytes()).into();
    let storage_output_digest: [u8; DIGEST_BYTES] =
        Sha256::digest(storage_output.as_bytes()).into();
    let active_output_tags_pinned = accept_output.contains(PATH2_PUBLIC_NATIVE_SPEND_VIEW_SCHEMA)
        && reject_output.contains(PATH2_NATIVE_VERIFIER_PIPELINE_VERDICT_SCHEMA)
        && storage_output.contains(PATH2_NATIVE_STORAGE_LIFECYCLE_HARDENING_SCOPE_SCHEMA);
    let accept_has_allowlisted_surface = accept_output.contains("native_boundary_digest")
        && accept_output.contains("checked_core_frame_digest")
        && accept_output.contains("checked_core_proof_bytes_digest")
        && accept_output.contains("checked_core_proof_byte_len")
        && !accept_output.contains("proof_bytes\":[");
    let reject_has_allowlisted_surface = reject_output.contains("public_boundary_accepted")
        && reject_output.contains("production_accepted")
        && reject_output.contains("rejection_code")
        && !reject_output.contains("\"production_accepted\":true");
    let storage_has_allowlisted_surface = storage_output.contains("target_chain_storage_artifacts")
        && storage_output.contains("lifecycle_safety_artifacts")
        && storage_output.contains("data_availability_artifacts")
        && storage_output.contains("restore_reorg_artifacts")
        && storage_output.contains("\"hardening_complete\":false");
    let denylist_exclusion_checked =
        path2_active_native_public_output_has_no_private_material_v1(accept_output)
            && path2_active_native_public_output_has_no_private_material_v1(reject_output)
            && path2_active_native_public_output_has_no_private_material_v1(storage_output);
    let serializer_negative_controls_passed =
        !path2_active_native_public_output_has_no_private_material_v1(
            "raw_pad_seed opening_preimage unmasked_projection transparent_query_opening",
        );
    let public_output_policy_pinned = active_output_tags_pinned
        && accept_has_allowlisted_surface
        && reject_has_allowlisted_surface
        && storage_has_allowlisted_surface
        && denylist_exclusion_checked;
    Path2NativeNoExportSerializerEvidenceV1 {
        schema: PATH2_NATIVE_NO_EXPORT_SERIALIZER_EVIDENCE_SCHEMA,
        schema_matches: true,
        report_digest_verified: accept_output_digest != [0_u8; DIGEST_BYTES]
            && reject_output_digest != [0_u8; DIGEST_BYTES]
            && storage_output_digest != [0_u8; DIGEST_BYTES],
        active_output_tags_pinned,
        public_output_policy_pinned,
        accept_serializer_bound: accept_has_allowlisted_surface,
        reject_serializer_bound: reject_has_allowlisted_surface,
        storage_serializer_bound: storage_has_allowlisted_surface,
        denylist_exclusion_checked,
        serializer_negative_controls_passed,
        accept_output_digest,
        reject_output_digest,
        storage_output_digest,
        cleanup_policy: "active native accept/reject/storage serializer evidence is digest-only and denylist-screened",
    }
}

pub fn path2_native_no_export_serializer_evidence_v1_frame(
    evidence: &Path2NativeNoExportSerializerEvidenceV1,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(&mut frame, b"schema", evidence.schema.as_bytes());
    append_u64(
        &mut frame,
        b"schema_matches",
        u64::from(evidence.schema_matches),
    );
    append_u64(
        &mut frame,
        b"report_digest_verified",
        u64::from(evidence.report_digest_verified),
    );
    append_u64(
        &mut frame,
        b"active_output_tags_pinned",
        u64::from(evidence.active_output_tags_pinned),
    );
    append_u64(
        &mut frame,
        b"public_output_policy_pinned",
        u64::from(evidence.public_output_policy_pinned),
    );
    append_u64(
        &mut frame,
        b"accept_serializer_bound",
        u64::from(evidence.accept_serializer_bound),
    );
    append_u64(
        &mut frame,
        b"reject_serializer_bound",
        u64::from(evidence.reject_serializer_bound),
    );
    append_u64(
        &mut frame,
        b"storage_serializer_bound",
        u64::from(evidence.storage_serializer_bound),
    );
    append_u64(
        &mut frame,
        b"denylist_exclusion_checked",
        u64::from(evidence.denylist_exclusion_checked),
    );
    append_u64(
        &mut frame,
        b"serializer_negative_controls_passed",
        u64::from(evidence.serializer_negative_controls_passed),
    );
    append_frame(
        &mut frame,
        b"accept_output_digest",
        &evidence.accept_output_digest,
    );
    append_frame(
        &mut frame,
        b"reject_output_digest",
        &evidence.reject_output_digest,
    );
    append_frame(
        &mut frame,
        b"storage_output_digest",
        &evidence.storage_output_digest,
    );
    append_frame(
        &mut frame,
        b"cleanup_policy",
        evidence.cleanup_policy.as_bytes(),
    );
    frame
}

pub fn path2_native_no_export_serializer_evidence_v1_digest(
    evidence: &Path2NativeNoExportSerializerEvidenceV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(
        Sha256::digest(path2_native_no_export_serializer_evidence_v1_frame(
            evidence,
        ))
        .into(),
    )
}

pub fn path2_native_no_export_serializer_evidence_all_facts_true(
    evidence: &Path2NativeNoExportSerializerEvidenceV1,
) -> bool {
    evidence.schema == PATH2_NATIVE_NO_EXPORT_SERIALIZER_EVIDENCE_SCHEMA
        && evidence.schema_matches
        && evidence.report_digest_verified
        && evidence.active_output_tags_pinned
        && evidence.public_output_policy_pinned
        && evidence.accept_serializer_bound
        && evidence.reject_serializer_bound
        && evidence.storage_serializer_bound
        && evidence.denylist_exclusion_checked
        && evidence.serializer_negative_controls_passed
}

pub fn verify_path2_native_no_export_serializer_evidence_v1(
    accept_output: &str,
    reject_output: &str,
    storage_output: &str,
    evidence: &Path2NativeNoExportSerializerEvidenceV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    let expected =
        path2_native_no_export_serializer_evidence_v1(accept_output, reject_output, storage_output);
    if expected != *evidence {
        return Err("Path 2 native no-export serializer evidence mismatch".to_string());
    }
    if !path2_native_no_export_serializer_evidence_all_facts_true(evidence) {
        return Err(
            "Path 2 native no-export serializer evidence has an unsatisfied component fact"
                .to_string(),
        );
    }
    path2_native_no_export_serializer_evidence_v1_digest(evidence)
}

fn path2_source_window_digest_v1(
    source: &str,
    start_marker: &str,
    end_marker: &str,
    label: &str,
) -> [u8; DIGEST_BYTES] {
    let start = source
        .find(start_marker)
        .unwrap_or_else(|| panic!("{label} source start marker missing"));
    let end = source[start..]
        .find(end_marker)
        .map(|offset| start + offset)
        .unwrap_or_else(|| panic!("{label} source end marker missing"));
    Sha256::digest(source[start..end].as_bytes()).into()
}

