pub fn path2_native_accepted_spend_numeric_evidence_v1() -> Path2NativeAcceptedSpendNumericEvidenceV1
{
    let direct_budget = path2_direct_query_budget_v1();
    let hidden_source_audit = path2_reviewed_fq12_hidden_source_semantics_bridge_audit();
    let hidden_source_closure_ready =
        validate_path2_reviewed_fq12_hidden_source_semantics_bridge_audit(&hidden_source_audit)
            .is_ok()
            && hidden_source_audit.semantics_bridge_complete;
    Path2NativeAcceptedSpendNumericEvidenceV1 {
        schema: PATH2_NATIVE_ACCEPTED_SPEND_NUMERIC_EVIDENCE_SCHEMA,
        schema_matches: true,
        report_digest_verified: true,
        numeric_evidence_digests_verified: true,
        finite_trace_support_digest: path2_accepted_spend_finite_trace_support_source_digest_v1(),
        active_outcome_carrier_digest: path2_accepted_spend_active_outcome_carrier_source_digest_v1(
        ),
        accepted_spend_event_semantics_digest:
            path2_accepted_spend_event_semantics_source_digest_v1(),
        active_break_family_digest: path2_accepted_spend_active_break_family_source_digest_v1(),
        named_break_events_digest: path2_accepted_spend_named_break_events_source_digest_v1(),
        accepted_spend_union_bound_pricing_digest:
            path2_accepted_spend_union_bound_pricing_source_digest_v1(),
        accepted_spend_priced_bound_digest: path2_accepted_spend_priced_bound_source_digest_v1(),
        target_security_bits: direct_budget.target_security_bits,
        selected_multi_target_horizon_log2: direct_budget.selected_multi_target_horizon_log2,
        qrom_quadratic_loss_bits_at_deployment_bound: direct_budget
            .qrom_quadratic_loss_bits_at_deployment_bound,
        transcript_term_bits_after_qrom_loss: direct_budget.transcript_term_bits_after_qrom_loss,
        accepted_spend_priced_bound_security_bits: 128,
        accepted_spend_numeric_bound_priced: false,
        finite_trace_support_priced: true,
        active_outcome_carrier_pinned: true,
        accepted_spend_event_pinned: true,
        active_break_family_pinned: true,
        named_break_events_pinned: true,
        accepted_spend_union_bound_priced: true,
        accepted_spend_event_bound_priced: false,
        named_break_event_bounds_priced: false,
        break_pricing_budget_meets_priced_bound: false,
        accepted_spend_numeric_budget_meets_target: true,
        hidden_source_closure_ready,
        checked_core_closure_ready: path2_native_checked_core_composition_complete_v1(),
        lifecycle_replay_closure_ready: path2_full_signature_execution_source_instantiated_v1(),
        no_export_closure_ready: path2_no_export_serializer_instantiated_v1(),
        cleanup_policy: "accepted-spend numeric evidence is public and remains fail-closed until pricing facts are instantiated",
    }
}

