pub fn path2_native_checked_core_byte_instantiation_evidence_v1_digest(
    evidence: &Path2NativeCheckedCoreByteInstantiationEvidenceV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(
        Sha256::digest(path2_native_checked_core_byte_instantiation_evidence_v1_frame(evidence))
            .into(),
    )
}

pub fn path2_native_checked_core_byte_instantiation_evidence_all_facts_true(
    evidence: &Path2NativeCheckedCoreByteInstantiationEvidenceV1,
) -> bool {
    let expected_hash_byte_domain_evidence = path2_native_hash_byte_domain_evidence_v1();
    let Ok(expected_hash_byte_domain_evidence_digest) =
        verify_path2_native_hash_byte_domain_evidence_v1(&expected_hash_byte_domain_evidence)
    else {
        return false;
    };
    evidence.schema == PATH2_NATIVE_CHECKED_CORE_BYTE_INSTANTIATION_EVIDENCE_SCHEMA
        && evidence.accepted
        && evidence.checked_core_acceptor_accepts
        && evidence.parser_matches_native_handle
        && evidence.proof_length_eq
        && evidence.proof_canonical
        && evidence.decoded_proof_commitment_eq
        && evidence.parsed_response_syndrome_eq
        && evidence.frame_bytes_eq
        && evidence.verifier_handle_eq
        && evidence.parser_equality
        && evidence.hash_and_syndrome_eq
        && evidence.short_proof_rejected
        && evidence.noncanonical_proof_rejected
        && evidence.commitment_mismatch_rejected
        && evidence.verifier_handle_mismatch_rejected
        && evidence.hash_byte_domain_evidence_digest == expected_hash_byte_domain_evidence_digest
        && evidence.hash_byte_domain_evidence_verified
        && evidence.hash_byte_domain_evidence_facts_all_true
        && evidence.checked_core_frame_domain_matches_hash_evidence
        && evidence.checked_core_frame_bytes_use_hash_domain_prefix
        && evidence.checked_core_challenge_uses_hash_domain_frame
        && evidence.checked_core_frame_digest_matches_hash_domain_frame
        && evidence.proof_byte_len as usize == PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES
}

pub fn verify_path2_native_checked_core_byte_instantiation_evidence_v1(
    bundle: &Path2NativeProjectionBundleV1,
    checked_core_proof_bytes: &[u8],
    evidence: &Path2NativeCheckedCoreByteInstantiationEvidenceV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    let expected =
        path2_native_checked_core_byte_instantiation_evidence_v1(bundle, checked_core_proof_bytes)?;
    if expected != *evidence {
        return Err("Path 2 native checked-core byte evidence mismatch".to_string());
    }
    if !path2_native_checked_core_byte_instantiation_evidence_all_facts_true(evidence) {
        return Err(
            "Path 2 native checked-core byte evidence has an unsatisfied component fact"
                .to_string(),
        );
    }
    path2_native_checked_core_byte_instantiation_evidence_v1_digest(evidence)
}

fn validate_path2_native_context_fields(
    native_boundary_version: u16,
    parameter_set_id: u16,
    verifier_family_id: u16,
    aggregation_mode: u8,
) -> Result<(), String> {
    let frame = Path2NativeCheckedCoreFrameV1 {
        native_boundary_version,
        parameter_set_id,
        verifier_family_id,
        account_creation_domain_digest: [0_u8; DIGEST_BYTES],
        spend_verifier_domain_digest: [0_u8; DIGEST_BYTES],
        chain_or_application_domain_digest: [0_u8; DIGEST_BYTES],
        fork_or_epoch_scope_digest: [0_u8; DIGEST_BYTES],
        aggregation_mode,
        native_boundary_digest: [0_u8; DIGEST_BYTES],
        p_account_digest: [0_u8; DIGEST_BYTES],
        p_spend_digest: [0_u8; DIGEST_BYTES],
        p_lifecycle_digest: [0_u8; DIGEST_BYTES],
        p_transcript_digest: [0_u8; DIGEST_BYTES],
        p_state_digest: [0_u8; DIGEST_BYTES],
        message_digest: [0_u8; DIGEST_BYTES],
        current_state_digest: [0_u8; DIGEST_BYTES],
        proof_commitment: [0_u8; DIGEST_BYTES],
    };
    validate_path2_native_checked_core_frame_v1(&frame)
}

pub fn path2_native_context_projection_v1_bytes(
    projection: &Path2NativeContextProjectionV1,
) -> Result<Vec<u8>, String> {
    validate_path2_native_context_fields(
        projection.native_boundary_version,
        projection.parameter_set_id,
        projection.verifier_family_id,
        projection.aggregation_mode,
    )?;
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_PROJECTION_CONTEXT_DOMAIN.as_bytes());
    out.extend_from_slice(&projection.native_boundary_version.to_le_bytes());
    out.extend_from_slice(&projection.parameter_set_id.to_le_bytes());
    out.extend_from_slice(&projection.verifier_family_id.to_le_bytes());
    for digest in [
        &projection.account_creation_domain_digest,
        &projection.spend_verifier_domain_digest,
        &projection.chain_or_application_domain_digest,
        &projection.fork_or_epoch_scope_digest,
    ] {
        out.extend_from_slice(digest);
    }
    out.push(projection.aggregation_mode);
    Ok(out)
}

pub fn path2_native_account_projection_v1_bytes(
    projection: &Path2NativeAccountProjectionV1,
) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_PROJECTION_ACCOUNT_DOMAIN.as_bytes());
    for digest in [
        &projection.account_id,
        &projection.account_namespace_digest,
        &projection.public_key_identity,
        &projection.creation_namespace_digest,
        &projection.admission_state_namespace_digest,
    ] {
        out.extend_from_slice(digest);
    }
    out
}

pub fn path2_native_public_key_identity_digest_v1(
    spend_verifier_family_id: u16,
    checked_core_verifier_handle_digest: [u8; DIGEST_BYTES],
) -> Result<[u8; DIGEST_BYTES], String> {
    if spend_verifier_family_id != PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12 {
        return Err(format!(
            "Path 2 native public-key identity verifier family mismatch: got {}, expected {}",
            spend_verifier_family_id, PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12
        ));
    }
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_PUBLIC_KEY_IDENTITY_DOMAIN.as_bytes());
    out.extend_from_slice(&spend_verifier_family_id.to_le_bytes());
    out.extend_from_slice(&checked_core_verifier_handle_digest);
    Ok(Sha256::digest(out).into())
}

pub fn path2_native_spend_authorization_class_digest_v1(
    spend_verifier_family_id: u16,
    checked_core_verifier_handle_digest: [u8; DIGEST_BYTES],
    public_key_identity: [u8; DIGEST_BYTES],
    allowed_authorization_local_mode: u8,
    allowed_state_transition_class_digest: [u8; DIGEST_BYTES],
    aggregation_mode: u8,
    spend_domain_separator_digest: [u8; DIGEST_BYTES],
) -> Result<[u8; DIGEST_BYTES], String> {
    if spend_verifier_family_id != PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12 {
        return Err(format!(
            "Path 2 native authorization class verifier family mismatch: got {}, expected {}",
            spend_verifier_family_id, PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12
        ));
    }
    validate_path2_native_context_fields(
        PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION,
        PATH2_NATIVE_CHECKED_CORE_PARAMETER_SET_Q12289,
        spend_verifier_family_id,
        aggregation_mode,
    )?;
    if allowed_authorization_local_mode != PATH2_NATIVE_AUTHORIZATION_LOCAL_MODE_DIRECT {
        return Err(format!(
            "Path 2 native authorization class local mode mismatch: got {}, expected {}",
            allowed_authorization_local_mode, PATH2_NATIVE_AUTHORIZATION_LOCAL_MODE_DIRECT
        ));
    }
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_AUTHORIZATION_CLASS_DOMAIN.as_bytes());
    out.extend_from_slice(&spend_verifier_family_id.to_le_bytes());
    out.extend_from_slice(&checked_core_verifier_handle_digest);
    out.extend_from_slice(&public_key_identity);
    out.push(allowed_authorization_local_mode);
    out.extend_from_slice(&allowed_state_transition_class_digest);
    out.push(aggregation_mode);
    out.extend_from_slice(&spend_domain_separator_digest);
    Ok(Sha256::digest(out).into())
}

pub fn path2_native_spend_projection_v1_bytes(
    projection: &Path2NativeSpendProjectionV1,
) -> Result<Vec<u8>, String> {
    if projection.spend_verifier_family_id != PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12 {
        return Err(format!(
            "Path 2 native spend projection verifier family mismatch: got {}, expected {}",
            projection.spend_verifier_family_id, PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12
        ));
    }
    validate_path2_native_context_fields(
        PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION,
        PATH2_NATIVE_CHECKED_CORE_PARAMETER_SET_Q12289,
        projection.spend_verifier_family_id,
        projection.aggregation_mode,
    )?;
    if projection.allowed_authorization_local_mode != PATH2_NATIVE_AUTHORIZATION_LOCAL_MODE_DIRECT {
        return Err(format!(
            "Path 2 native spend projection authorization-local mode mismatch: got {}, expected {}",
            projection.allowed_authorization_local_mode,
            PATH2_NATIVE_AUTHORIZATION_LOCAL_MODE_DIRECT
        ));
    }
    let expected_authorization_class_digest = path2_native_spend_authorization_class_digest_v1(
        projection.spend_verifier_family_id,
        projection.checked_core_verifier_handle_digest,
        projection.public_key_identity,
        projection.allowed_authorization_local_mode,
        projection.allowed_state_transition_class_digest,
        projection.aggregation_mode,
        projection.spend_domain_separator_digest,
    )?;
    if projection.spend_authorization_class_digest != expected_authorization_class_digest {
        return Err(
            "Path 2 native spend projection authorization class digest mismatch".to_string(),
        );
    }
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_PROJECTION_SPEND_DOMAIN.as_bytes());
    out.extend_from_slice(&projection.spend_verifier_family_id.to_le_bytes());
    for digest in [
        &projection.spend_authorization_class_digest,
        &projection.checked_core_verifier_handle_digest,
        &projection.public_key_identity,
    ] {
        out.extend_from_slice(digest);
    }
    out.push(projection.allowed_authorization_local_mode);
    out.extend_from_slice(&projection.allowed_state_transition_class_digest);
    out.push(projection.aggregation_mode);
    out.extend_from_slice(&projection.spend_domain_separator_digest);
    Ok(out)
}

pub fn path2_native_lifecycle_projection_v1_bytes(
    projection: &Path2NativeLifecycleProjectionV1,
) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_PROJECTION_LIFECYCLE_DOMAIN.as_bytes());
    out.extend_from_slice(&projection.slot_id.to_le_bytes());
    out.push(projection.live_status_marker);
    for digest in [
        &projection.lifecycle_anchor,
        &projection.nullifier_namespace_digest,
        &projection.consume_once_rule_digest,
        &projection.replay_domain_digest,
        &projection.restore_or_reorg_scope_digest,
    ] {
        out.extend_from_slice(digest);
    }
    out
}

pub fn path2_native_state_projection_v1_bytes(
    projection: &Path2NativeStateProjectionV1,
) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_PROJECTION_STATE_DOMAIN.as_bytes());
    out.extend_from_slice(&projection.account_state_root_before);
    out.extend_from_slice(&projection.admitted_boundary_id);
    out.push(projection.live_state_requirement);
    for digest in [
        &projection.consumed_successor_state_class,
        &projection.data_availability_requirement,
        &projection.aggregation_state_boundary,
    ] {
        out.extend_from_slice(digest);
    }
    out
}

pub fn path2_native_transcript_projection_v1_bytes(
    projection: &Path2NativeTranscriptProjectionV1,
) -> Result<Vec<u8>, String> {
    validate_path2_native_context_fields(
        PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION,
        PATH2_NATIVE_CHECKED_CORE_PARAMETER_SET_Q12289,
        PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12,
        projection.aggregation_mode,
    )?;
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_PROJECTION_TRANSCRIPT_DOMAIN.as_bytes());
    for digest in [
        &projection.native_boundary_digest,
        &projection.p_context_digest,
        &projection.p_account_digest,
        &projection.p_spend_digest,
        &projection.p_lifecycle_digest,
        &projection.p_state_digest,
        &projection.checked_core_frame_domain_digest,
    ] {
        out.extend_from_slice(digest);
    }
    out.push(projection.aggregation_mode);
    Ok(out)
}

