pub fn reviewed_fq12_selected_projection_invalid_opening_public_reason(
    internal_reason: &str,
) -> &str {
    if internal_reason.starts_with("reviewed Fq12 masked witness state18 projection")
        || internal_reason.starts_with("reviewed Fq12 masked state18 packed witness")
        || internal_reason.starts_with("reviewed Fq12 packed witness state18")
        || internal_reason
            == "reviewed Fq12 masked witness state18 projection carrier tuple exported a hidden-material break"
        || internal_reason == "reviewed Fq12 projection carrier check bytes mismatch"
        || internal_reason == "reviewed Fq12 projection carrier transcript binding mismatch"
        || internal_reason == "state-assisted witness commitment mismatch"
        || internal_reason == "state-assisted randomizer commitment mismatch"
        || internal_reason == "state-assisted opening commitment mismatch"
        || internal_reason == "state-assisted hidden-source opening commitment mismatch"
        || internal_reason == "state-assisted restore anchor mismatch"
        || internal_reason == "state-assisted pad seed digest mismatch"
    {
        PRODUCTION_SELECTED_PROJECTION_INVALID_OPENING_REASON
    } else {
        internal_reason
    }
}

pub fn reviewed_fq12_selected_projection_invalid_carrier_public_reason(
    internal_reason: &str,
) -> &str {
    if internal_reason.contains("projection carrier")
        || internal_reason.contains("fallback projection carrier")
        || internal_reason.starts_with("hidden-source fallback projection carrier")
        || internal_reason
            == "reviewed Fq12 masked witness state18 projection carrier tuple exported a hidden-material break"
        || internal_reason == "state-assisted witness commitment mismatch"
        || internal_reason == "state-assisted randomizer commitment mismatch"
        || internal_reason == "state-assisted opening commitment mismatch"
        || internal_reason == "state-assisted hidden-source opening commitment mismatch"
        || internal_reason == "state-assisted restore anchor mismatch"
        || internal_reason == "state-assisted pad seed digest mismatch"
        || internal_reason == "reviewed Fq12 state-assisted hidden-source statement mismatch"
        || internal_reason == "account randomizer commitment mismatch"
    {
        PRODUCTION_SELECTED_PROJECTION_INVALID_CARRIER_REASON
    } else {
        reviewed_fq12_selected_projection_invalid_opening_public_reason(internal_reason)
    }
}

fn reviewed_fq12_selected_projection_public_reject(internal_reason: String) -> String {
    reviewed_fq12_selected_projection_invalid_carrier_public_reason(&internal_reason).to_string()
}

pub fn hidden_source_fallback_pad_prf_projection_values_from_seed(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
) -> Result<(Vec<String>, Vec<u16>), String> {
    let mut symbols = Vec::new();
    let mut values = Vec::new();
    for (lane, symbol) in HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS
        .iter()
        .enumerate()
    {
        if !symbol.starts_with("pad_seed_projection[") {
            continue;
        }
        let Some((block, coord)) = hidden_source_fallback_pad_projection_block_coord(symbol) else {
            return Err(format!(
                "hidden-source fallback pad projection symbol is unknown: {symbol}"
            ));
        };
        if block >= GROUPS || coord >= LOCAL_FREE {
            return Err(format!(
                "hidden-source fallback pad projection symbol is out of range: {symbol}"
            ));
        }
        let residues = reviewed_fq12_pad_residues_from_seed_bounded(pad_seed, block)?;
        symbols.push((*symbol).to_string());
        values.push(hidden_source_fallback_mul_mod_q(
            HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_COEFFICIENTS[lane],
            residues[coord],
        ));
    }
    Ok((symbols, values))
}

pub fn verify_hidden_source_fallback_pad_prf_seed_or_export(
    input: &HiddenSourceFallbackProjectionPadPrfSeedReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    let (pad_projection_symbols, recomputed_pad_projection_values) =
        match hidden_source_fallback_pad_prf_projection_values_from_seed(&input.pad_seed) {
            Ok(values) => values,
            Err(err) => {
                return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                    err,
                );
            }
        };
    let replay = HiddenSourceFallbackProjectionPadPrfProjectionReplayInput {
        projection_carrier_bytes: input.projection_carrier_bytes,
        decoded_carrier: input.decoded_carrier,
        pad_seed_opening_frame: input.pad_seed_opening_frame.clone(),
        pad_statement_bytes: input.pad_statement_bytes.clone(),
        pad_projection_symbols,
        recomputed_pad_projection_values,
        sha256_pad_prf_domain: input.sha256_pad_prf_domain.clone(),
    };
    verify_hidden_source_fallback_pad_prf_projection_or_export(&replay)
}

pub fn hidden_source_fallback_projection_values_from_hidden_material(
    account_witness_opening: &HiddenSourceFallbackProjectionAccountWitnessOpening,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
) -> Result<[u16; HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES], String> {
    let (account_symbols, account_values) =
        hidden_source_fallback_account_projection_values_from_opening(account_witness_opening)?;
    let (pad_symbols, pad_values) =
        hidden_source_fallback_pad_prf_projection_values_from_seed(pad_seed)?;
    let mut out = [0_u16; HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES];
    let mut filled = [false; HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES];

    for (symbol, value) in account_symbols.iter().zip(account_values.iter()) {
        let Some(lane) = HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS
            .iter()
            .position(|candidate| candidate == symbol)
        else {
            return Err(format!(
                "hidden-source fallback account projection symbol is not selected: {symbol}"
            ));
        };
        out[lane] = *value;
        filled[lane] = true;
    }
    for (symbol, value) in pad_symbols.iter().zip(pad_values.iter()) {
        let Some(lane) = HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS
            .iter()
            .position(|candidate| candidate == symbol)
        else {
            return Err(format!(
                "hidden-source fallback pad projection symbol is not selected: {symbol}"
            ));
        };
        out[lane] = *value;
        filled[lane] = true;
    }
    if filled.iter().any(|is_filled| !*is_filled) {
        return Err(
            "hidden-source fallback hidden material did not fill all projection lanes".to_string(),
        );
    }
    Ok(out)
}

pub fn verify_hidden_source_fallback_hidden_material_projection_or_export(
    input: &HiddenSourceFallbackProjectionHiddenMaterialReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    let recomputed_projection_values =
        match hidden_source_fallback_projection_values_from_hidden_material(
            &input.account_witness_opening,
            &input.pad_seed,
        ) {
            Ok(values) => values,
            Err(err) => {
                return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                    err,
                );
            }
        };
    let replay = HiddenSourceFallbackProjectionOpeningProjectionReplayInput {
        projection_carrier_bytes: input.projection_carrier_bytes,
        decoded_carrier: input.decoded_carrier,
        serialized_hidden_relation_statement: input.serialized_hidden_relation_statement.clone(),
        account_witness_opening_frame: input.account_witness_opening_frame.clone(),
        pad_seed_opening_frame: input.pad_seed_opening_frame.clone(),
        claimed_projection_symbols: input.decoded_carrier.lanes,
        recomputed_projection_values,
    };
    verify_hidden_source_fallback_opening_projection_or_export(&replay)
}

fn verify_hidden_source_fallback_hidden_material_frame_projection_or_export(
    input: &HiddenSourceFallbackProjectionHiddenMaterialFrameReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    let account_witness_opening = match decode_hidden_source_fallback_account_witness_opening_frame(
        &input.account_witness_opening_frame,
    ) {
        Ok(opening) => opening,
        Err(err) => {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                err,
            );
        }
    };
    let replay = HiddenSourceFallbackProjectionHiddenMaterialReplayInput {
        projection_carrier_bytes: input.projection_carrier_bytes,
        decoded_carrier: input.decoded_carrier,
        serialized_hidden_relation_statement: input.serialized_hidden_relation_statement.clone(),
        account_witness_opening_frame: input.account_witness_opening_frame.clone(),
        account_witness_opening,
        pad_seed_opening_frame: input.pad_seed_opening_frame.clone(),
        pad_seed: input.pad_seed,
    };
    verify_hidden_source_fallback_hidden_material_projection_or_export(&replay)
}

