pub fn path2_account_stark_payload_public_rejection_class(error: &str) -> &'static str {
    if error.contains("account-creation STARK: payload bundle is empty") {
        return PATH2_PUBLIC_RESULT_REJECT_MALFORMED_PUBLIC_INPUT;
    }
    if error.contains("account-creation STARK production verification is fail-closed") {
        return PATH2_PUBLIC_RESULT_INTERNAL_ERROR_FAIL_CLOSED;
    }
    if error.contains("account-creation STARK verify failed")
        || error.contains("deployed anchor mismatch")
    {
        return PATH2_PUBLIC_RESULT_REJECT_CREATION_EVIDENCE;
    }
    if error.contains("account-creation STARK:") {
        return PATH2_PUBLIC_RESULT_REJECT_BINDING_MISMATCH;
    }
    PATH2_PUBLIC_RESULT_INTERNAL_ERROR_FAIL_CLOSED
}

pub fn path2_account_creation_frame_public_rejection_class(error: &str) -> &'static str {
    if error.contains("frame version mismatch")
        || error.contains("not live")
        || error.contains("evidence domain mismatch")
        || error.contains("evidence version mismatch")
        || error.contains("unsupported evidence kind")
    {
        return PATH2_PUBLIC_RESULT_REJECT_MALFORMED_PUBLIC_INPUT;
    }
    if error.contains("mismatch") {
        return PATH2_PUBLIC_RESULT_REJECT_BINDING_MISMATCH;
    }
    PATH2_PUBLIC_RESULT_INTERNAL_ERROR_FAIL_CLOSED
}

pub fn path2_direct_account_binding_public_result_class(
    error: &ProductionAccountBindingError,
) -> Path2PublicResultClassV1 {
    path2_direct_account_binding_public_result_class_for_reason(error.reason())
}

pub fn path2_direct_account_binding_public_result_class_for_reason(
    reason: &str,
) -> Path2PublicResultClassV1 {
    if reason.contains("resource limit") || reason.contains("oversized public input") {
        return Path2PublicResultClassV1::RejectResourceLimit;
    }
    if reason.contains("unsupported version") || reason.contains("unsupported mode") {
        return Path2PublicResultClassV1::RejectUnsupportedVersion;
    }
    if reason.contains("has ") && reason.contains("bytes, expected")
        || reason.contains("not canonical")
        || reason.contains("non-canonical")
        || reason.contains("malformed")
        || reason.contains("frame version mismatch")
        || reason.contains("evidence domain mismatch")
        || reason.contains("evidence version mismatch")
        || reason.contains("unsupported evidence kind")
    {
        return Path2PublicResultClassV1::RejectMalformedPublicInput;
    }
    if reason.contains("production verification is fail-closed")
        || reason.contains("callback failed")
        || reason.contains("internal")
    {
        return Path2PublicResultClassV1::InternalErrorFailClosed;
    }
    if reason.contains("not admitted in state namespace")
        || reason.contains("account-creation STARK verify failed")
        || reason.contains("deployed anchor mismatch")
        || reason.contains("hidden-source proof")
    {
        return Path2PublicResultClassV1::RejectCreationEvidence;
    }
    if reason.contains("already consumed")
        || reason.contains("already in spent ledger")
        || reason.contains("slot id is out of range")
        || reason.contains("slot reservation is not active")
        || reason.contains("not live")
        || reason.contains("stale")
        || reason.contains("burned")
        || reason.contains("duplicate")
    {
        return Path2PublicResultClassV1::RejectLifecycleState;
    }
    if reason.contains("does not match prevalidated leaf")
        || reason.contains("public-key identity mismatch")
        || reason.contains("consumed authorization mismatch")
        || reason.contains("creation statement digest mismatch")
    {
        return Path2PublicResultClassV1::RejectBindingMismatch;
    }
    if reason.contains("Path 2 checked-core")
        || reason.contains("account randomizer commitment mismatch")
        || reason.contains("sigma equation mismatch")
        || reason.contains("public local fiber-state mismatch")
        || reason.contains("public pad-opening mismatch")
        || reason.contains("challenge mismatch")
    {
        return Path2PublicResultClassV1::RejectCheckedCore;
    }
    if reason.contains("policy") {
        return Path2PublicResultClassV1::RejectPolicy;
    }
    if reason.contains("mismatch") || reason.contains("binding") {
        return Path2PublicResultClassV1::RejectBindingMismatch;
    }
    Path2PublicResultClassV1::InternalErrorFailClosed
}

pub fn path2_account_stark_payload_byte_model_report_v1(
) -> Path2AccountStarkPayloadByteModelReportV1 {
    let field_order = &PATH2_ACCOUNT_STARK_PAYLOAD_BYTE_MODEL_FIELDS;
    let mut report = Path2AccountStarkPayloadByteModelReportV1 {
        digest: [0_u8; DIGEST_BYTES],
        domain: PATH2_ACCOUNT_STARK_PAYLOAD_BYTE_MODEL_REPORT_DOMAIN,
        selected_payload_type: "Path2AccountStarkCreationPayloadV1",
        payload_schema: PATH2_ACCOUNT_STARK_CREATION_PAYLOAD_SCHEMA,
        payload_version: 1,
        account_stark_verifier_version: PATH2_ACCOUNT_STARK_VERIFIER_VERSION,
        payload_frame_function: "path2_account_stark_creation_payload_v1_frame",
        payload_digest_function: "path2_account_stark_creation_payload_v1_digest",
        digest_algorithm: "SHA-256",
        field_order,
        field_count: field_order.len(),
        masked_projection_lane_count: HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES,
        masked_projection_bytes: HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES
            * core::mem::size_of::<u16>(),
        fixed_data_bytes_excluding_bundle:
            PATH2_ACCOUNT_STARK_PAYLOAD_FIXED_DATA_BYTES_EXCLUDING_BUNDLE,
        fixed_frame_overhead_excluding_bundle:
            PATH2_ACCOUNT_STARK_PAYLOAD_FRAME_FIXED_OVERHEAD_EXCLUDING_BUNDLE,
        bundle_nonempty_required: true,
        bundle_variable_length: true,
        full_proof_bytes_inlined_in_manifest: false,
        deterministic_kat_digest_pins_bundle_bytes: true,
        public_payload_exports_private_material: false,
        byte_model_pinned: true,
        deployment_ready: false,
    };
    report.digest = path2_account_stark_payload_byte_model_report_v1_digest(&report);
    report
}

pub fn path2_account_stark_payload_byte_model_report_v1_digest(
    report: &Path2AccountStarkPayloadByteModelReportV1,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(path2_account_stark_payload_byte_model_report_v1_frame(
        report,
    ))
    .into()
}

pub fn validate_path2_account_stark_payload_byte_model_report_v1(
    report: &Path2AccountStarkPayloadByteModelReportV1,
) -> Result<(), String> {
    let expected = path2_account_stark_payload_byte_model_report_v1();
    if expected != *report {
        return Err("Path 2 account-STARK payload byte model report mismatch".to_string());
    }
    if path2_account_stark_payload_byte_model_report_v1_digest(report) != report.digest {
        return Err("Path 2 account-STARK payload byte model report digest mismatch".to_string());
    }
    if !report.bundle_nonempty_required
        || !report.bundle_variable_length
        || !report.deterministic_kat_digest_pins_bundle_bytes
        || report.full_proof_bytes_inlined_in_manifest
        || report.public_payload_exports_private_material
        || !report.byte_model_pinned
        || report.deployment_ready
    {
        return Err(
            "Path 2 account-STARK payload byte model unexpectedly changes deployment policy"
                .to_string(),
        );
    }
    Ok(())
}

