pub fn validate_path2_account_stark_payload_kat_boundary_report_v1(
    report: &Path2AccountStarkPayloadKatBoundaryReportV1,
) -> Result<(), String> {
    let expected = path2_account_stark_payload_kat_boundary_report_v1();
    if expected != *report {
        return Err("Path 2 account-STARK payload KAT boundary report mismatch".to_string());
    }
    if path2_account_stark_payload_kat_boundary_report_v1_digest(report) != report.digest {
        return Err("Path 2 account-STARK payload KAT boundary report digest mismatch".to_string());
    }
    let byte_model_report = path2_account_stark_payload_byte_model_report_v1();
    if report.payload_byte_model_report_digest != byte_model_report.digest {
        return Err(
            "Path 2 account-STARK payload KAT boundary byte model digest mismatch".to_string(),
        );
    }
    if report.payload_kat_corpus_reduction_lean_theorem
        != PATH2_ACCOUNT_STARK_PAYLOAD_KAT_CORPUS_REDUCTION_LEAN_THEOREM
        || !report.payload_kat_corpus_reduction_bound
    {
        return Err(
            "Path 2 account-STARK payload KAT boundary lost Lean reduction binding".to_string(),
        );
    }
    Ok(())
}

