fn lean_source_module_has_forbidden_stubs_for_names_v1(lean_source: &str, names: &[&str]) -> bool {
    let stripped_source = lean_source_without_comments_and_strings_v1(lean_source);
    let lean_source = stripped_source.as_str();
    let declaration_block_contains_name = |kind: &str, name: &str| -> bool {
        lean_source
            .match_indices(&format!("\n{kind}"))
            .any(|(index, _)| {
                let window = &lean_source[index..lean_source.len().min(index + 1024)];
                window.contains(name)
            })
    };
    let forbidden_declaration_stub = ["axiom", "constant", "opaque"].iter().any(|kind| {
        names
            .iter()
            .any(|name| declaration_block_contains_name(kind, name))
    });
    let forbidden_variable_stub = lean_source
        .match_indices("\nvariable")
        .map(|(index, _)| &lean_source[index..lean_source.len().min(index + 1024)])
        .any(|variable_window| names.iter().any(|name| variable_window.contains(name)));
    forbidden_declaration_stub || forbidden_variable_stub
}

fn lean_source_module_has_non_stub_declarations_for_names_v1(
    lean_source: &str,
    names: &[&str],
) -> bool {
    let stripped_source = lean_source_without_comments_and_strings_v1(lean_source);
    let lean_source = stripped_source.as_str();
    let declaration_kinds = ["abbrev", "def", "private abbrev", "private def"];
    names.iter().all(|name| {
        declaration_kinds.iter().any(|kind| {
            let marker = format!("\n{kind} {name}");
            lean_source.match_indices(&marker).any(|(index, _)| {
                let name_end = index + marker.len();
                lean_source[name_end..].chars().next().is_none_or(|next| {
                    !(next.is_ascii_alphanumeric() || next == '_' || next == '\'')
                })
            })
        })
    })
}

fn lean_source_selected_rust_definition_body_is_direct_constant_lambda_v1(
    lean_source: &str,
    name: &str,
    max_body_len: usize,
) -> bool {
    let stripped_source = lean_source_without_comments_and_strings_v1(lean_source);
    let lean_source = stripped_source.as_str();
    let declaration_starts = [
        format!("\nabbrev {name}"),
        format!("\ndef {name}"),
        format!("\nprivate abbrev {name}"),
        format!("\nprivate def {name}"),
    ];
    declaration_starts.iter().any(|start_marker| {
        lean_source.match_indices(start_marker).any(|(start, _)| {
            let name_end = start + start_marker.len();
            if lean_source[name_end..]
                .chars()
                .next()
                .is_some_and(|next| next.is_ascii_alphanumeric() || next == '_' || next == '\'')
            {
                return false;
            }
            let declaration_window_end =
                lean_source.floor_char_boundary(lean_source.len().min(start + max_body_len));
            let declaration_window = &lean_source[start..declaration_window_end];
            let Some(body_start) = [":=", "\nwhere", " where"]
                .iter()
                .filter_map(|body_marker| {
                    declaration_window
                        .find(body_marker)
                        .map(|offset| offset + body_marker.len())
                })
                .min()
            else {
                return false;
            };
            let body_window = &declaration_window[body_start..];
            let next_top_level_declaration = [
                "\nabbrev ",
                "\naxiom ",
                "\nclass ",
                "\nconstant ",
                "\ndef ",
                "\ninductive ",
                "\ninstance ",
                "\nnamespace ",
                "\nopaque ",
                "\nopen ",
                "\nprivate abbrev ",
                "\nprivate def ",
                "\nprivate theorem ",
                "\nsection ",
                "\nstructure ",
                "\ntheorem ",
                "\nvariable ",
            ]
            .iter()
            .filter_map(|marker| body_window.find(marker))
            .min()
            .unwrap_or(body_window.len());
            let normalized_body = body_window[..next_top_level_declaration]
                .split_whitespace()
                .collect::<String>();
            let mut stripped_outer_body = normalized_body.as_str();
            while stripped_outer_body.starts_with('(') && stripped_outer_body.ends_with(')') {
                stripped_outer_body = &stripped_outer_body[1..stripped_outer_body.len() - 1];
            }
            [normalized_body.as_str(), stripped_outer_body]
                .iter()
                .any(|body| {
                    ["True", "False", "(True)", "(False)"].iter().any(|value| {
                        *body == *value
                            || (1..=12)
                                .any(|arity| *body == format!("fun{}=>{value}", "_".repeat(arity)))
                    })
                })
        })
    })
}

fn lean_source_has_incomplete_proof_token_v1(lean_source: &str) -> bool {
    let stripped_source = lean_source_without_comments_and_strings_v1(lean_source);
    ["sorry", "admit"].iter().any(|token| {
        stripped_source
            .split(|c: char| !c.is_ascii_alphanumeric() && c != '_')
            .any(|part| part == *token)
    })
}

