fn lean_source_without_comments_and_strings_v1(source: &str) -> String {
    let mut stripped = String::with_capacity(source.len());
    let bytes = source.as_bytes();
    let mut idx = 0;
    let mut block_depth = 0_u32;
    let mut in_line_comment = false;
    let mut in_string = false;
    let mut string_escape = false;
    while idx < bytes.len() {
        if in_string {
            if bytes[idx] == b'\n' {
                stripped.push('\n');
                string_escape = false;
            } else if string_escape {
                string_escape = false;
            } else if bytes[idx] == b'\\' {
                string_escape = true;
            } else if bytes[idx] == b'"' {
                in_string = false;
            }
            idx += source[idx..]
                .chars()
                .next()
                .map(char::len_utf8)
                .unwrap_or(1);
            continue;
        }
        if in_line_comment {
            if bytes[idx] == b'\n' {
                in_line_comment = false;
                stripped.push('\n');
            }
            idx += source[idx..]
                .chars()
                .next()
                .map(char::len_utf8)
                .unwrap_or(1);
            continue;
        }
        if block_depth > 0 {
            if idx + 1 < bytes.len() && bytes[idx] == b'/' && bytes[idx + 1] == b'-' {
                block_depth += 1;
                idx += 2;
            } else if idx + 1 < bytes.len() && bytes[idx] == b'-' && bytes[idx + 1] == b'/' {
                block_depth -= 1;
                idx += 2;
            } else {
                if bytes[idx] == b'\n' {
                    stripped.push('\n');
                }
                idx += source[idx..]
                    .chars()
                    .next()
                    .map(char::len_utf8)
                    .unwrap_or(1);
            }
            continue;
        }
        if idx + 1 < bytes.len() && bytes[idx] == b'-' && bytes[idx + 1] == b'-' {
            in_line_comment = true;
            idx += 2;
            continue;
        }
        if idx + 1 < bytes.len() && bytes[idx] == b'/' && bytes[idx + 1] == b'-' {
            block_depth = 1;
            idx += 2;
            continue;
        }
        if bytes[idx] == b'"' {
            in_string = true;
            idx += 1;
            continue;
        }
        let Some(ch) = source[idx..].chars().next() else {
            break;
        };
        stripped.push(ch);
        idx += ch.len_utf8();
    }
    stripped
}

fn lean_declaration_marker_has_exact_name_v1(
    source: &str,
    marker_start: usize,
    marker: &str,
) -> bool {
    source[marker_start + marker.len()..]
        .chars()
        .next()
        .is_none_or(|next| !(next.is_ascii_alphanumeric() || next == '_' || next == '\''))
}

fn lean_source_has_exact_declaration_marker_v1(source: &str, marker: &str) -> bool {
    source
        .match_indices(marker)
        .any(|(index, _)| lean_declaration_marker_has_exact_name_v1(source, index, marker))
}

fn lean_source_find_exact_declaration_marker_v1(source: &str, marker: &str) -> Option<usize> {
    source
        .match_indices(marker)
        .find(|(index, _)| lean_declaration_marker_has_exact_name_v1(source, *index, marker))
        .map(|(index, _)| index)
}

fn lean_identifier_boundary_byte_v1(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'\'' || byte == b'.'
}

fn lean_source_contains_exact_identifier_v1(source: &str, identifier: &str) -> bool {
    source.match_indices(identifier).any(|(index, _)| {
        let before_is_identifier = index
            .checked_sub(1)
            .and_then(|before_index| source.as_bytes().get(before_index))
            .is_some_and(|byte| lean_identifier_boundary_byte_v1(*byte));
        let after_index = index + identifier.len();
        let after_is_identifier = source
            .as_bytes()
            .get(after_index)
            .is_some_and(|byte| lean_identifier_boundary_byte_v1(*byte));
        !before_is_identifier && !after_is_identifier
    })
}

