pub fn path2_reviewed_fq12_five_source_closure_evidence_all_facts_true(
    evidence: &Path2ReviewedFq12FiveSourceClosureEvidenceV1,
) -> bool {
    evidence.schema == PATH2_REVIEWED_FQ12_FIVE_SOURCE_CLOSURE_EVIDENCE_SCHEMA
        && evidence.bridge_audit_validated
        && evidence.hash_byte_domain_evidence_verified
        && evidence.hidden_source_frame_domain_matches_hash_evidence
        && evidence.hidden_source_statement_frame_uses_hash_domain_field
        && evidence.hidden_source_statement_digest_uses_hash_domain_frame
        && evidence.hidden_source_proof_domain_matches_hash_evidence
        && evidence.hidden_source_proof_transcript_frame_uses_hash_domain_field
        && evidence.hidden_source_proof_transcript_digest_uses_hash_domain_frame
        && evidence.projection_carrier_domain_matches_hash_evidence
        && evidence.projection_carrier_binding_frame_uses_hash_domain_field
        && evidence.projection_carrier_binding_digest_splits_to_check_and_transcript
        && evidence.account_witness_opening_domain_matches_hash_evidence
        && evidence.account_witness_opening_digest_uses_hash_domain_frame
        && evidence.pad_seed_opening_domain_matches_hash_evidence
        && evidence.pad_seed_opening_digest_uses_hash_domain_frame
        && evidence.pad_opening_view_domain_matches_hash_evidence
        && evidence.pad_opening_statement_digest_uses_hash_domain_frame
        && evidence.direct_query_budget_schema_matches
        && evidence.direct_query_budget_mode_is_direct_single_slot
        && evidence.direct_query_budget_excludes_q_batch_from_active_symbols
        && evidence.direct_query_budget_marks_q_batch_inactive
        && evidence.direct_query_budget_optional_aggregation_terms_q_batch_only
        && evidence.lean_direct_query_budget_keeps_q_batch_inactive_present
        && evidence.boundary_base_evidence_verified
        && evidence.role_root_lift_evidence_verified
        && evidence.selected_source_route_evidence_verified
        && evidence.field_local_evidence_verified
        && evidence.shared_digest_frame_witness_evidence_verified
        && evidence.selected_rust_model_five_source_inputs_ready
        && evidence.rust_payload_projection_law_present
        && evidence.rust_extraction_certificate_availability_present
        && evidence.role_root_lift_source_present
        && evidence.selected_source_route_byte_source_present
        && evidence.assembly_field_local_native_components_present
        && evidence.compatibility_field_extraction_components_present
        && evidence.shared_digest_frame_witness_byte_source_contract_present
        && evidence.active_field_local_digest_frame_witness_byte_component_surfaces_present
        && evidence.lean_active_five_source_boundary_route_present
        && evidence.lean_full_signature_hidden_source_handoff_present
}

pub fn path2_reviewed_fq12_five_source_closure_evidence_report_verified_v1(
    evidence: &Path2ReviewedFq12FiveSourceClosureEvidenceV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    let expected = path2_reviewed_fq12_five_source_closure_evidence_v1()?;
    if expected != *evidence {
        return Err("Path 2 reviewed Fq12 five-source closure evidence mismatch".to_string());
    }
    if evidence.schema != PATH2_REVIEWED_FQ12_FIVE_SOURCE_CLOSURE_EVIDENCE_SCHEMA {
        return Err(
            "Path 2 reviewed Fq12 five-source closure evidence schema mismatch".to_string(),
        );
    }
    if !evidence.schema_matches {
        return Err(
            "Path 2 reviewed Fq12 five-source closure evidence schema was not matched".to_string(),
        );
    }
    if !evidence.bridge_audit_digest_bound {
        return Err(
            "Path 2 reviewed Fq12 five-source bridge audit digest was not bound".to_string(),
        );
    }
    if !evidence.bridge_audit_validated {
        return Err("Path 2 reviewed Fq12 five-source bridge audit was not validated".to_string());
    }
    if !evidence.boundary_base_evidence_verified
        || !evidence.role_root_lift_evidence_verified
        || !evidence.selected_source_route_evidence_verified
        || !evidence.field_local_evidence_verified
        || !evidence.shared_digest_frame_witness_evidence_verified
    {
        return Err(
            "Path 2 reviewed Fq12 five-source sub-evidence report was not verified".to_string(),
        );
    }
    if !evidence.report_digest_verified {
        return Err(
            "Path 2 reviewed Fq12 five-source closure evidence digest was not verified".to_string(),
        );
    }
    path2_reviewed_fq12_five_source_closure_evidence_v1_digest(evidence)
}

pub fn verify_path2_reviewed_fq12_five_source_closure_evidence_v1(
    evidence: &Path2ReviewedFq12FiveSourceClosureEvidenceV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    let digest = path2_reviewed_fq12_five_source_closure_evidence_report_verified_v1(evidence)?;
    if !path2_reviewed_fq12_five_source_closure_evidence_all_facts_true(evidence) {
        return Err(
            "Path 2 reviewed Fq12 five-source closure evidence has an unsatisfied component fact"
                .to_string(),
        );
    }
    Ok(digest)
}

