pub fn path2_reviewed_fq12_native_representative_assembly_certificate_v1(
    full_opening_cert: &Path2ReviewedFq12FullNativeOpeningCertificateV1,
    payload_binding: &Path2ReviewedFq12HiddenSourcePayloadBindingV1,
    extraction_cert: &Path2ReviewedFq12HiddenRelationExtractionCertificateV1,
    creation_binding: &Path2CreationProofBindingV1,
    bundle: &Path2NativeProjectionBundleV1,
    checked_core_proof_bytes: &[u8],
    private_fiber: &Path2NativePrivateFiberStateV1,
) -> Result<Path2ReviewedFq12NativeRepresentativeAssemblyCertificateV1, String> {
    verify_path2_reviewed_fq12_full_native_opening_certificate_v1(
        full_opening_cert,
        payload_binding,
        extraction_cert,
        creation_binding,
        bundle,
        checked_core_proof_bytes,
        private_fiber,
    )?;
    let assembly = assemble_path2_native_boundary_v1(bundle, checked_core_proof_bytes)?;
    if full_opening_cert.native_boundary_digest != assembly.native_boundary_digest {
        return Err("Path 2 native representative assembly boundary mismatch".to_string());
    }
    if full_opening_cert.local_section_digest != assembly.p_account_digest
        || full_opening_cert.lifecycle_slot_digest != assembly.p_lifecycle_digest
        || full_opening_cert.trace_witness_digest != assembly.p_transcript_digest
    {
        return Err("Path 2 native representative assembly projection mismatch".to_string());
    }
    if full_opening_cert.packed_residues_digest != creation_binding.packed_witness_commitment
        || full_opening_cert.randomizer_digest != creation_binding.randomizer_commitment
        || full_opening_cert.selected_account_projection_digest
            != extraction_cert.account_projection_digest
        || full_opening_cert.pad_source_digest != creation_binding.pad_source_commitment
        || full_opening_cert.opening_tuple_digest != creation_binding.opening_tuple_commitment
        || full_opening_cert.projection_relation_digest
            != creation_binding.projection_relation_commitment
        || full_opening_cert.gauge_digest != creation_binding.gauge_commitment
    {
        return Err("Path 2 native representative assembly role mismatch".to_string());
    }
    let representative_digest = path2_reviewed_fq12_native_representative_digest_v1(
        &full_opening_cert.native_boundary_digest,
        &full_opening_cert.local_section_digest,
        &full_opening_cert.packed_residues_digest,
        &full_opening_cert.randomizer_digest,
        &full_opening_cert.selected_account_projection_digest,
        &full_opening_cert.pad_source_digest,
        &full_opening_cert.opening_tuple_digest,
        &full_opening_cert.projection_relation_digest,
        &full_opening_cert.lifecycle_slot_digest,
        &full_opening_cert.trace_witness_digest,
        &full_opening_cert.gauge_digest,
    );
    let mut cert = Path2ReviewedFq12NativeRepresentativeAssemblyCertificateV1 {
        schema: PATH2_REVIEWED_FQ12_NATIVE_REPRESENTATIVE_ASSEMBLY_CERTIFICATE_DOMAIN,
        role_lift_certificate_digest: full_opening_cert.role_lift_certificate_digest,
        payload_binding_digest: full_opening_cert.payload_binding_digest,
        extraction_certificate_digest: full_opening_cert.extraction_certificate_digest,
        creation_proof_binding_digest: full_opening_cert.creation_proof_binding_digest,
        native_boundary_digest: full_opening_cert.native_boundary_digest,
        slot_id: full_opening_cert.slot_id,
        hidden_source_statement_digest: full_opening_cert.hidden_source_statement_digest,
        reviewed_active_lane_statement_digest: full_opening_cert
            .reviewed_active_lane_statement_digest,
        native_role_root_commitment: full_opening_cert.native_role_root_commitment,
        full_opening_digest: full_opening_cert.full_opening_digest,
        local_section_digest: full_opening_cert.local_section_digest,
        packed_residues_digest: full_opening_cert.packed_residues_digest,
        randomizer_digest: full_opening_cert.randomizer_digest,
        selected_account_projection_digest: full_opening_cert.selected_account_projection_digest,
        pad_source_digest: full_opening_cert.pad_source_digest,
        opening_tuple_digest: full_opening_cert.opening_tuple_digest,
        projection_relation_digest: full_opening_cert.projection_relation_digest,
        lifecycle_slot_digest: full_opening_cert.lifecycle_slot_digest,
        trace_witness_digest: full_opening_cert.trace_witness_digest,
        gauge_digest: full_opening_cert.gauge_digest,
        representative_digest,
        assembly_certificate_digest: [0_u8; DIGEST_BYTES],
    };
    cert.assembly_certificate_digest =
        path2_reviewed_fq12_native_representative_assembly_certificate_v1_digest(&cert)?;
    Ok(cert)
}

