pub fn verify_path2_native_boundary_trace_column_manifest(
    manifest: &Path2NativeBoundaryTraceColumnManifestV1,
) -> Result<(), String> {
    if manifest.schema != PATH2_NATIVE_BOUNDARY_TRACE_COLUMN_MANIFEST_SCHEMA {
        return Err("Path 2 native-boundary trace column manifest schema mismatch".to_string());
    }
    if manifest.profile_id != PATH2_NATIVE_BOUNDARY_TRACE_COLUMN_MANIFEST_PROFILE_ID {
        return Err("Path 2 native-boundary trace column manifest profile mismatch".to_string());
    }
    if manifest.proof_family != PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY {
        return Err(
            "Path 2 native-boundary trace column manifest proof family mismatch".to_string(),
        );
    }
    verify_path2_two_view_column_profile_id(manifest.column_profile)?;
    if manifest.semantic_core_relation_layout_digest
        != path2_transparent_relation_layout_v1_digest()?
    {
        return Err(
            "Path 2 native-boundary trace column manifest core layout mismatch".to_string(),
        );
    }
    if manifest.semantic_core_witness_lanes != PATH2_TRANSPARENT_DESCENT_WITNESS_LANES as u16 {
        return Err("Path 2 native-boundary trace semantic core lane mismatch".to_string());
    }
    if manifest.masked_lane_floor != PATH2_NATIVE_BOUNDARY_TRACE_MASKED_LANE_FLOOR {
        return Err("Path 2 native-boundary trace masked lane floor mismatch".to_string());
    }
    if manifest.range_account_lane_floor != PATH2_NATIVE_BOUNDARY_TRACE_RANGE_ACCOUNT_LANE_FLOOR {
        return Err("Path 2 native-boundary trace range/account lane floor mismatch".to_string());
    }
    if manifest.range_account_delta_lanes
        != manifest.range_account_lane_floor - manifest.masked_lane_floor
    {
        return Err("Path 2 native-boundary trace range/account delta mismatch".to_string());
    }
    if manifest.relation_rows_optimistic <= PATH2_TRANSPARENT_DESCENT_RELATION_ROWS as u16
        || manifest.relation_rows_working < manifest.relation_rows_optimistic
        || manifest.relation_rows_stress < manifest.relation_rows_working
    {
        return Err("Path 2 native-boundary trace row model mismatch".to_string());
    }

    let mut expected_start = 0_u16;
    let mut semantic_core_lanes = 0_u16;
    let mut class_ids = BTreeSet::new();
    for class in manifest.classes {
        if class.class_id == 0 || !class_ids.insert(class.class_id) {
            return Err("Path 2 native-boundary trace column manifest duplicate class".to_string());
        }
        if class.start_lane != expected_start || class.lane_count == 0 {
            return Err(
                "Path 2 native-boundary trace column manifest lanes are not contiguous".to_string(),
            );
        }
        expected_start += class.lane_count;
        if class.semantic_core {
            semantic_core_lanes += class.lane_count;
        }
        let profile_entry = path2_two_view_column_profile_entry(class.role_id)?;
        if class.column_set_id != profile_entry.hidden_column_set_id {
            return Err(
                "Path 2 native-boundary trace column manifest column set mismatch".to_string(),
            );
        }
        match class.visibility_class {
            PATH2_TWO_VIEW_VISIBILITY_COMMITTED_HIDDEN
            | PATH2_TWO_VIEW_VISIBILITY_EXTRACTOR_HIDDEN
            | PATH2_TWO_VIEW_VISIBILITY_RANGE_PRIVATE
            | PATH2_TWO_VIEW_VISIBILITY_BLINDING_PRIVATE
            | PATH2_TWO_VIEW_VISIBILITY_SIMULATOR_ONLY => {}
            PATH2_TWO_VIEW_VISIBILITY_PUBLIC
            | PATH2_TWO_VIEW_VISIBILITY_DERIVED_PUBLIC
            | PATH2_TWO_VIEW_VISIBILITY_MASKED_PUBLIC => {
                return Err(
                    "Path 2 native-boundary trace column manifest exposes public private lane"
                        .to_string(),
                );
            }
            _ => {
                return Err(
                    "Path 2 native-boundary trace column manifest unknown visibility".to_string(),
                );
            }
        }
        if class.opens_publicly {
            return Err(
                "Path 2 native-boundary trace column manifest opens private lane".to_string(),
            );
        }
    }
    if semantic_core_lanes != manifest.semantic_core_witness_lanes {
        return Err("Path 2 native-boundary trace semantic core coverage mismatch".to_string());
    }
    if expected_start != manifest.range_account_lane_floor {
        return Err("Path 2 native-boundary trace lane coverage mismatch".to_string());
    }
    Ok(())
}

pub fn path2_native_boundary_trace_column_manifest_v1_digest() -> Result<[u8; DIGEST_BYTES], String>
{
    let manifest = path2_native_boundary_trace_column_manifest_v1()?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_NATIVE_BOUNDARY_TRACE_COLUMN_MANIFEST_SCHEMA.as_bytes(),
    );
    append_u64(&mut frame, b"profile_id", manifest.profile_id as u64);
    append_frame(
        &mut frame,
        b"proof_family",
        manifest.proof_family.as_bytes(),
    );
    append_u64(
        &mut frame,
        b"column_profile",
        manifest.column_profile as u64,
    );
    append_frame(
        &mut frame,
        b"semantic_core_relation_layout_digest",
        &manifest.semantic_core_relation_layout_digest,
    );
    append_u64(
        &mut frame,
        b"semantic_core_witness_lanes",
        manifest.semantic_core_witness_lanes as u64,
    );
    append_u64(
        &mut frame,
        b"masked_lane_floor",
        manifest.masked_lane_floor as u64,
    );
    append_u64(
        &mut frame,
        b"range_account_lane_floor",
        manifest.range_account_lane_floor as u64,
    );
    append_u64(
        &mut frame,
        b"range_account_delta_lanes",
        manifest.range_account_delta_lanes as u64,
    );
    append_u64(
        &mut frame,
        b"relation_rows_optimistic",
        manifest.relation_rows_optimistic as u64,
    );
    append_u64(
        &mut frame,
        b"relation_rows_working",
        manifest.relation_rows_working as u64,
    );
    append_u64(
        &mut frame,
        b"relation_rows_stress",
        manifest.relation_rows_stress as u64,
    );
    for class in manifest.classes {
        append_u64(&mut frame, b"class_id", class.class_id as u64);
        append_u64(&mut frame, b"role_id", class.role_id as u64);
        append_u64(&mut frame, b"start_lane", class.start_lane as u64);
        append_u64(&mut frame, b"lane_count", class.lane_count as u64);
        append_u64(&mut frame, b"column_set_id", class.column_set_id as u64);
        append_u64(
            &mut frame,
            b"visibility_class",
            class.visibility_class as u64,
        );
        append_u64(&mut frame, b"semantic_core", u64::from(class.semantic_core));
        append_u64(
            &mut frame,
            b"opens_publicly",
            u64::from(class.opens_publicly),
        );
    }
    Ok(Sha256::digest(frame).into())
}

pub fn path2_transparent_query_schedule_v1() -> Result<Path2TransparentQueryScheduleV1, String> {
    let schedule = Path2TransparentQueryScheduleV1 {
        schema: PATH2_TRANSPARENT_QUERY_SCHEDULE_SCHEMA,
        profile_id: PATH2_TRANSPARENT_QUERY_SCHEDULE_PROFILE_ID,
        proof_family: PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY,
        column_profile: PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
        trace_column_manifest_digest: path2_native_boundary_trace_column_manifest_v1_digest()?,
        fallback_threshold_bytes: PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES,
        entries: [
            Path2TransparentQueryScheduleEntryV1 {
                trace_rows: 256,
                query_count: 16,
                native_working_floor_bytes: 8_704,
                native_stress_floor_bytes: 9_728,
                status: PATH2_TRANSPARENT_QUERY_SCHEDULE_STATUS_NATIVE_PLANNING_OVERLAY,
            },
            Path2TransparentQueryScheduleEntryV1 {
                trace_rows: 512,
                query_count: 20,
                native_working_floor_bytes: 11_504,
                native_stress_floor_bytes: 12_784,
                status: PATH2_TRANSPARENT_QUERY_SCHEDULE_STATUS_NATIVE_PLANNING_OVERLAY,
            },
            Path2TransparentQueryScheduleEntryV1 {
                trace_rows: 1024,
                query_count: 24,
                native_working_floor_bytes: 14_560,
                native_stress_floor_bytes: 16_096,
                status: PATH2_TRANSPARENT_QUERY_SCHEDULE_STATUS_NATIVE_PLANNING_OVERLAY,
            },
        ],
    };
    verify_path2_transparent_query_schedule(&schedule)?;
    Ok(schedule)
}

pub fn verify_path2_transparent_query_schedule(
    schedule: &Path2TransparentQueryScheduleV1,
) -> Result<(), String> {
    if schedule.schema != PATH2_TRANSPARENT_QUERY_SCHEDULE_SCHEMA {
        return Err("Path 2 transparent query schedule schema mismatch".to_string());
    }
    if schedule.profile_id != PATH2_TRANSPARENT_QUERY_SCHEDULE_PROFILE_ID {
        return Err("Path 2 transparent query schedule profile mismatch".to_string());
    }
    if schedule.proof_family != PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY {
        return Err("Path 2 transparent query schedule proof family mismatch".to_string());
    }
    verify_path2_two_view_column_profile_id(schedule.column_profile)?;
    if schedule.trace_column_manifest_digest
        != path2_native_boundary_trace_column_manifest_v1_digest()?
    {
        return Err("Path 2 transparent query schedule trace manifest mismatch".to_string());
    }
    if schedule.fallback_threshold_bytes != PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES
    {
        return Err("Path 2 transparent query schedule fallback threshold mismatch".to_string());
    }

    let expected = [
        (256_u16, 16_u16, 8_704_u32, 9_728_u32),
        (512, 20, 11_504, 12_784),
        (1024, 24, 14_560, 16_096),
    ];
    for (entry, (trace_rows, query_count, working_floor, stress_floor)) in
        schedule.entries.into_iter().zip(expected)
    {
        if entry.trace_rows != trace_rows || entry.query_count != query_count {
            return Err("Path 2 transparent query schedule row/query mismatch".to_string());
        }
        if entry.native_working_floor_bytes != working_floor
            || entry.native_stress_floor_bytes != stress_floor
        {
            return Err("Path 2 transparent query schedule byte floor mismatch".to_string());
        }
        if entry.native_working_floor_bytes >= entry.native_stress_floor_bytes
            || entry.native_stress_floor_bytes >= schedule.fallback_threshold_bytes
        {
            return Err("Path 2 transparent query schedule threshold mismatch".to_string());
        }
        if entry.status != PATH2_TRANSPARENT_QUERY_SCHEDULE_STATUS_NATIVE_PLANNING_OVERLAY {
            return Err("Path 2 transparent query schedule status mismatch".to_string());
        }
    }
    Ok(())
}

pub fn path2_transparent_query_schedule_v1_digest() -> Result<[u8; DIGEST_BYTES], String> {
    let schedule = path2_transparent_query_schedule_v1()?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_QUERY_SCHEDULE_SCHEMA.as_bytes(),
    );
    append_u64(&mut frame, b"profile_id", schedule.profile_id as u64);
    append_frame(
        &mut frame,
        b"proof_family",
        schedule.proof_family.as_bytes(),
    );
    append_u64(
        &mut frame,
        b"column_profile",
        schedule.column_profile as u64,
    );
    append_frame(
        &mut frame,
        b"trace_column_manifest_digest",
        &schedule.trace_column_manifest_digest,
    );
    append_u64(
        &mut frame,
        b"fallback_threshold_bytes",
        schedule.fallback_threshold_bytes as u64,
    );
    for entry in schedule.entries {
        append_u64(&mut frame, b"trace_rows", entry.trace_rows as u64);
        append_u64(&mut frame, b"query_count", entry.query_count as u64);
        append_u64(
            &mut frame,
            b"native_working_floor_bytes",
            entry.native_working_floor_bytes as u64,
        );
        append_u64(
            &mut frame,
            b"native_stress_floor_bytes",
            entry.native_stress_floor_bytes as u64,
        );
        append_u64(&mut frame, b"status", entry.status as u64);
    }
    Ok(Sha256::digest(frame).into())
}

pub fn verify_path2_transparent_query_schedule_pair(
    trace_rows: u16,
    query_count: u16,
) -> Result<(), String> {
    let schedule = path2_transparent_query_schedule_v1()?;
    if schedule
        .entries
        .iter()
        .any(|entry| entry.trace_rows == trace_rows && entry.query_count == query_count)
    {
        Ok(())
    } else if schedule
        .entries
        .iter()
        .any(|entry| entry.trace_rows == trace_rows)
    {
        Err("Path 2 transparent proof query count does not match active schedule".to_string())
    } else {
        Err("Path 2 transparent proof unsupported trace row count".to_string())
    }
}

pub fn verify_path2_transparent_query_schedule_count(query_count: u16) -> Result<(), String> {
    let schedule = path2_transparent_query_schedule_v1()?;
    if schedule
        .entries
        .iter()
        .any(|entry| entry.query_count == query_count)
    {
        Ok(())
    } else {
        Err("Path 2 transparent proof query count is outside active schedule".to_string())
    }
}

pub fn path2_native_boundary_trace_proof_family_interface_v1(
) -> Result<Path2NativeBoundaryTraceProofFamilyInterfaceV1, String> {
    let interface = Path2NativeBoundaryTraceProofFamilyInterfaceV1 {
        schema: PATH2_NATIVE_BOUNDARY_TRACE_PROOF_FAMILY_INTERFACE_SCHEMA,
        profile_id: PATH2_NATIVE_BOUNDARY_TRACE_PROOF_FAMILY_INTERFACE_PROFILE_ID,
        family: PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY,
        column_profile: PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
        trace_column_manifest_digest: path2_native_boundary_trace_column_manifest_v1_digest()?,
        query_schedule_digest: path2_transparent_query_schedule_v1_digest()?,
        native_boundary_relation_row_floor: PATH2_NATIVE_BOUNDARY_TRACE_RELATION_ROWS_WORKING,
        native_boundary_relation_class_floors_required: true,
        knowledge_soundness_mode: PATH2_NATIVE_BOUNDARY_TRACE_KNOWLEDGE_FULL_TRACE_ROLE_COMPLETE,
        zero_knowledge_mode: PATH2_NATIVE_BOUNDARY_TRACE_ZK_MASKED_OR_SIMULATED_OPENINGS,
        qrom_schedule_mode: PATH2_NATIVE_BOUNDARY_TRACE_QROM_NATIVE_BOUNDARY_SCHEDULE,
        norm_range_mode: PATH2_NATIVE_BOUNDARY_TRACE_RANGE_HYBRID_BASE128,
        blinding_noise_mode: PATH2_NATIVE_BOUNDARY_TRACE_BLINDING_EXTRACTOR_BOUNDED,
        blinding_noise_policy_id: PATH2_NATIVE_BOUNDARY_TRACE_BLINDING_NOISE_POLICY_ID,
        blinding_noise_centered_bound: PATH2_DESCENT_SIS_BLINDING_CENTERED_BOUND as u16,
        sis_role_matrix_rows: PATH2_DESCENT_SIS_SELECTED_ROLE_MATRIX_ROWS as u16,
        role_subcommitment_link_mode:
            PATH2_NATIVE_BOUNDARY_TRACE_ROLE_SUBCOMMITMENTS_CREATION_BINDING,
        opening_tuple_account_binding_rows_required: true,
        checked_core_residue_compatibility_rows_required: true,
        role_authentication_material_simulatable_required: true,
        mask_freshness_required: true,
        unique_mask_domain_per_opened_cell_required: true,
        opened_row_component_digest_bound_required: true,
        parent_trace_commitment_extractable_required: true,
        extracted_trace_relation_knowledge_required: true,
        masked_opening_consistency_required: true,
        parent_trace_extraction_composition_required: true,
        trace_assembly_existence_required: true,
        trace_assembly_roles_complete_required: true,
        trace_assembly_derived_roles_required: true,
        trace_assembly_fiber_required: true,
        trace_assembly_local_valid_required: true,
        trace_assembly_descent_consistent_required: true,
        same_trace_range_rows_required: true,
        range_row_soundness_required: true,
        range_rows_to_norm_required: true,
        same_trace_blinding_rows_required: true,
        blinding_row_soundness_required: true,
        blinding_rows_to_bound_required: true,
        lean_atomic_full_interface_endpoint_present: true,
        lean_selected_profile_atomic_endpoint_present: true,
        lean_account_admission_adapter_endpoint_present: true,
        qrom_extractor_rewind_bound_required: true,
        double_trace_binding_break_exported: true,
        full_trace_extraction_required: true,
        role_complete_extractor_required: true,
        creation_binding_role_subcommitments_required: true,
        inner_commitment_binding_break_exported: true,
        no_raw_hidden_openings: true,
        qrom_ledger_bound: true,
        fallback_threshold_bytes: PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES,
    };
    verify_path2_native_boundary_trace_proof_family_interface(&interface)?;
    Ok(interface)
}

pub fn verify_path2_native_boundary_trace_proof_family_interface(
    interface: &Path2NativeBoundaryTraceProofFamilyInterfaceV1,
) -> Result<(), String> {
    if interface.schema != PATH2_NATIVE_BOUNDARY_TRACE_PROOF_FAMILY_INTERFACE_SCHEMA {
        return Err(
            "Path 2 native-boundary trace proof-family interface schema mismatch".to_string(),
        );
    }
    if interface.profile_id != PATH2_NATIVE_BOUNDARY_TRACE_PROOF_FAMILY_INTERFACE_PROFILE_ID {
        return Err(
            "Path 2 native-boundary trace proof-family interface profile mismatch".to_string(),
        );
    }
    if interface.family != PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY {
        return Err(
            "Path 2 native-boundary trace proof-family interface family mismatch".to_string(),
        );
    }
    verify_path2_two_view_column_profile_id(interface.column_profile)?;
    if interface.trace_column_manifest_digest
        != path2_native_boundary_trace_column_manifest_v1_digest()?
    {
        return Err(
            "Path 2 native-boundary trace proof-family interface manifest mismatch".to_string(),
        );
    }
    if interface.query_schedule_digest != path2_transparent_query_schedule_v1_digest()? {
        return Err(
            "Path 2 native-boundary trace proof-family interface schedule mismatch".to_string(),
        );
    }
    if interface.native_boundary_relation_row_floor
        != PATH2_NATIVE_BOUNDARY_TRACE_RELATION_ROWS_WORKING
    {
        return Err(
            "Path 2 native-boundary trace proof-family interface relation row floor mismatch"
                .to_string(),
        );
    }
    if !interface.native_boundary_relation_class_floors_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks relation class floors"
                .to_string(),
        );
    }
    if interface.knowledge_soundness_mode
        != PATH2_NATIVE_BOUNDARY_TRACE_KNOWLEDGE_FULL_TRACE_ROLE_COMPLETE
    {
        return Err(
            "Path 2 native-boundary trace proof-family interface knowledge mode mismatch"
                .to_string(),
        );
    }
    if interface.zero_knowledge_mode != PATH2_NATIVE_BOUNDARY_TRACE_ZK_MASKED_OR_SIMULATED_OPENINGS
    {
        return Err(
            "Path 2 native-boundary trace proof-family interface ZK mode mismatch".to_string(),
        );
    }
    if interface.qrom_schedule_mode != PATH2_NATIVE_BOUNDARY_TRACE_QROM_NATIVE_BOUNDARY_SCHEDULE {
        return Err(
            "Path 2 native-boundary trace proof-family interface QROM mode mismatch".to_string(),
        );
    }
    if interface.norm_range_mode != PATH2_NATIVE_BOUNDARY_TRACE_RANGE_HYBRID_BASE128 {
        return Err(
            "Path 2 native-boundary trace proof-family interface range mode mismatch".to_string(),
        );
    }
    if interface.blinding_noise_mode != PATH2_NATIVE_BOUNDARY_TRACE_BLINDING_EXTRACTOR_BOUNDED {
        return Err(
            "Path 2 native-boundary trace proof-family interface blinding mode mismatch"
                .to_string(),
        );
    }
    if interface.blinding_noise_policy_id != PATH2_NATIVE_BOUNDARY_TRACE_BLINDING_NOISE_POLICY_ID {
        return Err(
            "Path 2 native-boundary trace proof-family interface blinding policy mismatch"
                .to_string(),
        );
    }
    if interface.blinding_noise_centered_bound != PATH2_DESCENT_SIS_BLINDING_CENTERED_BOUND as u16 {
        return Err(
            "Path 2 native-boundary trace proof-family interface blinding bound mismatch"
                .to_string(),
        );
    }
    if interface.sis_role_matrix_rows != PATH2_DESCENT_SIS_SELECTED_ROLE_MATRIX_ROWS as u16 {
        return Err(
            "Path 2 native-boundary trace proof-family interface SIS role rows mismatch"
                .to_string(),
        );
    }
    for role in [
        PATH2_DESCENT_SIS_ROLE_PAD_SOURCE,
        PATH2_DESCENT_SIS_ROLE_PROJECTION_RELATION,
        PATH2_DESCENT_SIS_ROLE_OPENING_TUPLE,
    ] {
        let sanity =
            path2_descent_sis_hardness_sanity(role, PATH2_DESCENT_SIS_SELECTED_ROLE_MATRIX_ROWS)?;
        if sanity.verdict != PATH2_DESCENT_SIS_SANITY_VERDICT_FULL_COLUMN_RANK_PRIVATE_ONLY {
            return Err(
                "Path 2 native-boundary trace proof-family interface selected SIS role matrix is not full-rank private-only"
                    .to_string(),
            );
        }
    }
    if interface.role_subcommitment_link_mode
        != PATH2_NATIVE_BOUNDARY_TRACE_ROLE_SUBCOMMITMENTS_CREATION_BINDING
    {
        return Err(
            "Path 2 native-boundary trace proof-family interface role link mode mismatch"
                .to_string(),
        );
    }
    if !interface.opening_tuple_account_binding_rows_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks opening tuple account-binding rows"
                .to_string(),
        );
    }
    if !interface.checked_core_residue_compatibility_rows_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks checked-core residue compatibility rows"
                .to_string(),
        );
    }
    if !interface.role_authentication_material_simulatable_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks role-authentication simulator"
                .to_string(),
        );
    }
    if !interface.mask_freshness_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks mask freshness".to_string(),
        );
    }
    if !interface.unique_mask_domain_per_opened_cell_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks unique mask domains"
                .to_string(),
        );
    }
    if !interface.opened_row_component_digest_bound_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks opened-row component binding"
                .to_string(),
        );
    }
    if !interface.parent_trace_commitment_extractable_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks parent trace commitment extraction"
                .to_string(),
        );
    }
    if !interface.extracted_trace_relation_knowledge_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks extracted trace relation knowledge"
                .to_string(),
        );
    }
    if !interface.masked_opening_consistency_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks masked opening consistency"
                .to_string(),
        );
    }
    if !interface.parent_trace_extraction_composition_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks parent trace extraction composition"
                .to_string(),
        );
    }
    if !interface.trace_assembly_existence_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks trace assembly existence"
                .to_string(),
        );
    }
    if !interface.trace_assembly_roles_complete_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks trace assembly role completeness"
                .to_string(),
        );
    }
    if !interface.trace_assembly_derived_roles_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks trace assembly derived roles"
                .to_string(),
        );
    }
    if !interface.trace_assembly_fiber_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks trace assembly fiber proof"
                .to_string(),
        );
    }
    if !interface.trace_assembly_local_valid_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks trace assembly local validity"
                .to_string(),
        );
    }
    if !interface.trace_assembly_descent_consistent_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks trace assembly descent consistency"
                .to_string(),
        );
    }
    if !interface.same_trace_range_rows_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks same-trace range rows"
                .to_string(),
        );
    }
    if !interface.range_row_soundness_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks range row soundness"
                .to_string(),
        );
    }
    if !interface.range_rows_to_norm_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks range rows-to-norm proof"
                .to_string(),
        );
    }
    if !interface.same_trace_blinding_rows_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks same-trace blinding rows"
                .to_string(),
        );
    }
    if !interface.blinding_row_soundness_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks blinding row soundness"
                .to_string(),
        );
    }
    if !interface.blinding_rows_to_bound_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks blinding rows-to-bound proof"
                .to_string(),
        );
    }
    if !interface.lean_atomic_full_interface_endpoint_present {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks Lean atomic full-interface endpoint"
                .to_string(),
        );
    }
    if !interface.lean_selected_profile_atomic_endpoint_present {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks Lean selected-profile atomic endpoint"
                .to_string(),
        );
    }
    if !interface.lean_account_admission_adapter_endpoint_present {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks Lean account-admission adapter endpoint"
                .to_string(),
        );
    }
    if !interface.qrom_extractor_rewind_bound_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks QROM extractor rewind bound"
                .to_string(),
        );
    }
    if !interface.double_trace_binding_break_exported {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks double trace binding break"
                .to_string(),
        );
    }
    if !interface.full_trace_extraction_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks full trace extraction"
                .to_string(),
        );
    }
    if !interface.role_complete_extractor_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks role-complete extraction"
                .to_string(),
        );
    }
    if !interface.creation_binding_role_subcommitments_required {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks creation-binding role handles"
                .to_string(),
        );
    }
    if !interface.inner_commitment_binding_break_exported {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks inner commitment binding break"
                .to_string(),
        );
    }
    if !interface.no_raw_hidden_openings {
        return Err(
            "Path 2 native-boundary trace proof-family interface allows raw hidden openings"
                .to_string(),
        );
    }
    if !interface.qrom_ledger_bound {
        return Err(
            "Path 2 native-boundary trace proof-family interface lacks QROM ledger binding"
                .to_string(),
        );
    }
    if interface.fallback_threshold_bytes != PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES
    {
        return Err(
            "Path 2 native-boundary trace proof-family interface fallback threshold mismatch"
                .to_string(),
        );
    }
    Ok(())
}

