pub fn path2_transparent_proof_friendly_inner_commitment_plan_v1(
) -> Path2TransparentProofFriendlyInnerCommitmentPlanV1 {
    let proof_friendly_inner_commitment_bindings_pinned = true;
    let inner_commitment_scheme_id =
        path2_transparent_proof_friendly_inner_commitment_scheme_id_v1();
    let mut plan = Path2TransparentProofFriendlyInnerCommitmentPlanV1 {
        digest: [0_u8; DIGEST_BYTES],
        schema: PATH2_TRANSPARENT_PROOF_FRIENDLY_INNER_COMMITMENT_PLAN_SCHEMA,
        inner_commitment_scheme_id,
        inner_commitment_modulus: Q,
        inner_commitment_rows: PATH2_DESCENT_SIS_SELECTED_ROLE_MATRIX_ROWS as u16,
        pad_source_inner_commitment_domain: PATH2_DESCENT_SIS_PAD_SOURCE_MATRIX_DOMAIN,
        opening_tuple_inner_commitment_domain: PATH2_DESCENT_SIS_OPENING_TUPLE_MATRIX_DOMAIN,
        projection_relation_inner_commitment_domain:
            PATH2_DESCENT_SIS_PROJECTION_RELATION_MATRIX_DOMAIN,
        role_separated_algebraic_opening_domain:
            PATH2_DESCENT_SIS_TRANSCRIPT_COMMITMENT_MATRIX_DOMAIN,
        outer_sha_consensus_handles_retained: true,
        packed_witness_canonical_residue_packing_required: true,
        pad_source_inner_commitment_required: true,
        opening_tuple_inner_commitment_required: true,
        projection_relation_inner_commitment_required: true,
        role_separated_algebraic_opening_required: true,
        no_raw_pad_seed_or_projection_openings: true,
        proof_friendly_inner_commitment_bindings_pinned,
        current_sha_pad_seed_digest_primary_binding_allowed: false,
        deployable_inner_commitment_instantiated: false,
    };
    plan.digest = path2_transparent_proof_friendly_inner_commitment_plan_v1_digest(&plan)
        .expect("constructed Path 2 transparent proof-friendly inner commitment plan must hash");
    plan
}

pub fn path2_transparent_proof_friendly_inner_commitment_scheme_id_v1() -> [u8; DIGEST_BYTES] {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"profile",
        PATH2_TRANSPARENT_PROOF_FRIENDLY_INNER_COMMITMENT_SCHEME_PROFILE.as_bytes(),
    );
    append_u64(&mut frame, b"modulus", Q as u64);
    append_u64(
        &mut frame,
        b"rows",
        PATH2_DESCENT_SIS_SELECTED_ROLE_MATRIX_ROWS as u64,
    );
    append_frame(
        &mut frame,
        b"pad_source_domain",
        PATH2_DESCENT_SIS_PAD_SOURCE_MATRIX_DOMAIN.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"opening_tuple_domain",
        PATH2_DESCENT_SIS_OPENING_TUPLE_MATRIX_DOMAIN.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"projection_relation_domain",
        PATH2_DESCENT_SIS_PROJECTION_RELATION_MATRIX_DOMAIN.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"role_separated_opening_domain",
        PATH2_DESCENT_SIS_TRANSCRIPT_COMMITMENT_MATRIX_DOMAIN.as_bytes(),
    );
    Sha256::digest(frame).into()
}

pub fn path2_transparent_proof_friendly_inner_commitment_plan_v1_digest(
    plan: &Path2TransparentProofFriendlyInnerCommitmentPlanV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    if plan.schema != PATH2_TRANSPARENT_PROOF_FRIENDLY_INNER_COMMITMENT_PLAN_SCHEMA {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan schema mismatch".to_string(),
        );
    }
    if plan.inner_commitment_scheme_id
        != path2_transparent_proof_friendly_inner_commitment_scheme_id_v1()
        || plan.inner_commitment_scheme_id == [0_u8; DIGEST_BYTES]
    {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan scheme mismatch".to_string(),
        );
    }
    if plan.inner_commitment_modulus != Q
        || plan.inner_commitment_rows != PATH2_DESCENT_SIS_SELECTED_ROLE_MATRIX_ROWS as u16
    {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan parameter mismatch"
                .to_string(),
        );
    }
    if plan.pad_source_inner_commitment_domain != PATH2_DESCENT_SIS_PAD_SOURCE_MATRIX_DOMAIN
        || plan.opening_tuple_inner_commitment_domain
            != PATH2_DESCENT_SIS_OPENING_TUPLE_MATRIX_DOMAIN
        || plan.projection_relation_inner_commitment_domain
            != PATH2_DESCENT_SIS_PROJECTION_RELATION_MATRIX_DOMAIN
        || plan.role_separated_algebraic_opening_domain
            != PATH2_DESCENT_SIS_TRANSCRIPT_COMMITMENT_MATRIX_DOMAIN
    {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan domain mismatch".to_string(),
        );
    }
    let commitment_domains = [
        plan.pad_source_inner_commitment_domain,
        plan.opening_tuple_inner_commitment_domain,
        plan.projection_relation_inner_commitment_domain,
        plan.role_separated_algebraic_opening_domain,
    ];
    for (index, domain) in commitment_domains.iter().enumerate() {
        if domain.is_empty() || commitment_domains[..index].contains(domain) {
            return Err(
                "Path 2 transparent proof-friendly inner commitment plan domain mismatch"
                    .to_string(),
            );
        }
    }
    if !plan.outer_sha_consensus_handles_retained
        || !plan.packed_witness_canonical_residue_packing_required
        || !plan.pad_source_inner_commitment_required
        || !plan.opening_tuple_inner_commitment_required
        || !plan.projection_relation_inner_commitment_required
        || !plan.role_separated_algebraic_opening_required
        || !plan.no_raw_pad_seed_or_projection_openings
    {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan omits required binding"
                .to_string(),
        );
    }
    if plan.current_sha_pad_seed_digest_primary_binding_allowed {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan leaves SHA pad digest as primary binding"
                .to_string(),
        );
    }
    let expected_bindings_pinned = plan.outer_sha_consensus_handles_retained
        && plan.packed_witness_canonical_residue_packing_required
        && plan.pad_source_inner_commitment_required
        && plan.opening_tuple_inner_commitment_required
        && plan.projection_relation_inner_commitment_required
        && plan.role_separated_algebraic_opening_required
        && plan.no_raw_pad_seed_or_projection_openings
        && !plan.current_sha_pad_seed_digest_primary_binding_allowed;
    if plan.proof_friendly_inner_commitment_bindings_pinned != expected_bindings_pinned {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan binding status mismatch"
                .to_string(),
        );
    }
    if plan.deployable_inner_commitment_instantiated {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan incorrectly marks instantiated"
                .to_string(),
        );
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_PROOF_FRIENDLY_INNER_COMMITMENT_PLAN_SCHEMA.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"inner_commitment_scheme_id",
        &plan.inner_commitment_scheme_id,
    );
    append_u64(
        &mut frame,
        b"inner_commitment_modulus",
        plan.inner_commitment_modulus as u64,
    );
    append_u64(
        &mut frame,
        b"inner_commitment_rows",
        plan.inner_commitment_rows as u64,
    );
    append_frame(
        &mut frame,
        b"pad_source_inner_commitment_domain",
        plan.pad_source_inner_commitment_domain.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"opening_tuple_inner_commitment_domain",
        plan.opening_tuple_inner_commitment_domain.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"projection_relation_inner_commitment_domain",
        plan.projection_relation_inner_commitment_domain.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"role_separated_algebraic_opening_domain",
        plan.role_separated_algebraic_opening_domain.as_bytes(),
    );
    append_u64(
        &mut frame,
        b"outer_sha_consensus_handles_retained",
        u64::from(plan.outer_sha_consensus_handles_retained),
    );
    append_u64(
        &mut frame,
        b"packed_witness_canonical_residue_packing_required",
        u64::from(plan.packed_witness_canonical_residue_packing_required),
    );
    append_u64(
        &mut frame,
        b"pad_source_inner_commitment_required",
        u64::from(plan.pad_source_inner_commitment_required),
    );
    append_u64(
        &mut frame,
        b"opening_tuple_inner_commitment_required",
        u64::from(plan.opening_tuple_inner_commitment_required),
    );
    append_u64(
        &mut frame,
        b"projection_relation_inner_commitment_required",
        u64::from(plan.projection_relation_inner_commitment_required),
    );
    append_u64(
        &mut frame,
        b"role_separated_algebraic_opening_required",
        u64::from(plan.role_separated_algebraic_opening_required),
    );
    append_u64(
        &mut frame,
        b"no_raw_pad_seed_or_projection_openings",
        u64::from(plan.no_raw_pad_seed_or_projection_openings),
    );
    append_u64(
        &mut frame,
        b"proof_friendly_inner_commitment_bindings_pinned",
        u64::from(plan.proof_friendly_inner_commitment_bindings_pinned),
    );
    append_u64(
        &mut frame,
        b"current_sha_pad_seed_digest_primary_binding_allowed",
        u64::from(plan.current_sha_pad_seed_digest_primary_binding_allowed),
    );
    append_u64(
        &mut frame,
        b"deployable_inner_commitment_instantiated",
        u64::from(plan.deployable_inner_commitment_instantiated),
    );
    Ok(Sha256::digest(frame).into())
}

pub fn validate_path2_transparent_proof_friendly_inner_commitment_plan_v1(
    plan: &Path2TransparentProofFriendlyInnerCommitmentPlanV1,
) -> Result<(), String> {
    let expected = path2_transparent_proof_friendly_inner_commitment_plan_v1();
    if *plan != expected {
        return Err("Path 2 transparent proof-friendly inner commitment plan mismatch".to_string());
    }
    if path2_transparent_proof_friendly_inner_commitment_plan_v1_digest(plan)? != plan.digest {
        return Err(
            "Path 2 transparent proof-friendly inner commitment plan digest mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn path2_transparent_hidden_relation_constraint_plan_v1(
) -> Path2TransparentHiddenRelationConstraintPlanV1 {
    let inner_commitment_plan = path2_transparent_proof_friendly_inner_commitment_plan_v1();
    let reference_constraint_check_profile_digest =
        path2_transparent_hidden_relation_reference_constraint_check_profile_digest_v1();
    let pad_seed_binding_required = true;
    let prf_mask_derivation_required = true;
    let packed_witness_repack_required = true;
    let role_commitment_consistency_required = true;
    let proof_friendly_inner_commitment_bindings_pinned =
        inner_commitment_plan.proof_friendly_inner_commitment_bindings_pinned;
    let proof_friendly_inner_commitments_implemented =
        inner_commitment_plan.deployable_inner_commitment_instantiated;
    let reference_pad_seed_binding_checked = true;
    let reference_prf_mask_derivation_checked = true;
    let reference_packed_witness_repack_checked = true;
    let reference_role_commitment_consistency_checked = true;
    let reference_hidden_relation_checks_implemented = reference_pad_seed_binding_checked
        && reference_prf_mask_derivation_checked
        && reference_packed_witness_repack_checked
        && reference_role_commitment_consistency_checked;
    let pad_seed_binding_implemented = false;
    let prf_mask_derivation_implemented = false;
    let packed_witness_repack_implemented = false;
    let role_commitment_consistency_implemented = false;
    let full_hidden_relation_constraints_implemented = proof_friendly_inner_commitments_implemented
        && pad_seed_binding_implemented
        && prf_mask_derivation_implemented
        && packed_witness_repack_implemented
        && role_commitment_consistency_implemented;
    let mut plan = Path2TransparentHiddenRelationConstraintPlanV1 {
        digest: [0_u8; DIGEST_BYTES],
        schema: PATH2_TRANSPARENT_HIDDEN_RELATION_CONSTRAINT_PLAN_SCHEMA,
        proof_friendly_inner_commitment_plan_digest: inner_commitment_plan.digest,
        reference_constraint_check_profile_digest,
        proof_friendly_inner_commitments_required: true,
        proof_friendly_inner_commitment_bindings_pinned,
        pad_seed_binding_required,
        prf_mask_derivation_required,
        packed_witness_repack_required,
        role_commitment_consistency_required,
        proof_friendly_inner_commitments_implemented,
        reference_pad_seed_binding_checked,
        reference_prf_mask_derivation_checked,
        reference_packed_witness_repack_checked,
        reference_role_commitment_consistency_checked,
        reference_hidden_relation_checks_implemented,
        pad_seed_binding_implemented,
        prf_mask_derivation_implemented,
        packed_witness_repack_implemented,
        role_commitment_consistency_implemented,
        full_hidden_relation_constraints_implemented,
    };
    plan.digest = path2_transparent_hidden_relation_constraint_plan_v1_digest(&plan)
        .expect("constructed Path 2 transparent hidden relation plan must hash");
    plan
}

pub fn path2_transparent_hidden_relation_reference_constraint_check_profile_digest_v1(
) -> [u8; DIGEST_BYTES] {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"profile",
        b"DESCENDER_PATH2_TRANSPARENT_HIDDEN_RELATION_REFERENCE_CONSTRAINT_CHECK_PROFILE_V1",
    );
    append_frame(
        &mut frame,
        b"inner_commitment_scheme_id",
        &path2_transparent_proof_friendly_inner_commitment_scheme_id_v1(),
    );
    append_frame(
        &mut frame,
        b"hidden_relation_witness_check_schema",
        PATH2_TRANSPARENT_HIDDEN_RELATION_WITNESS_CHECK_SCHEMA.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"trace_origin_witness_check_schema",
        PATH2_TRANSPARENT_TRACE_ORIGIN_WITNESS_CHECK_SCHEMA.as_bytes(),
    );
    for label in [
        b"pad_seed_binding_checked".as_slice(),
        b"prf_mask_derivation_checked".as_slice(),
        b"packed_witness_repack_checked".as_slice(),
        b"masked_projection_public_seam_checked".as_slice(),
        b"pad_source_role_commitment_checked".as_slice(),
        b"projection_relation_role_commitment_checked".as_slice(),
        b"native_role_root_checked".as_slice(),
        b"opening_tuple_role_handle_bound".as_slice(),
        b"trace_roots_recomputed_from_hidden_witness".as_slice(),
        b"constraint_roots_recomputed_from_hidden_witness".as_slice(),
        b"same_hidden_witness_check_bound".as_slice(),
        b"no_raw_witness_or_blinding_seed_export".as_slice(),
    ] {
        append_frame(&mut frame, b"required_check", label);
    }
    Sha256::digest(frame).into()
}

pub fn path2_transparent_hidden_relation_constraint_plan_v1_digest(
    plan: &Path2TransparentHiddenRelationConstraintPlanV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    if plan.schema != PATH2_TRANSPARENT_HIDDEN_RELATION_CONSTRAINT_PLAN_SCHEMA {
        return Err("Path 2 transparent hidden relation plan schema mismatch".to_string());
    }
    let inner_commitment_plan = path2_transparent_proof_friendly_inner_commitment_plan_v1();
    validate_path2_transparent_proof_friendly_inner_commitment_plan_v1(&inner_commitment_plan)?;
    if plan.proof_friendly_inner_commitment_plan_digest != inner_commitment_plan.digest {
        return Err(
            "Path 2 transparent hidden relation plan inner commitment digest mismatch".to_string(),
        );
    }
    if plan.reference_constraint_check_profile_digest
        != path2_transparent_hidden_relation_reference_constraint_check_profile_digest_v1()
        || plan.reference_constraint_check_profile_digest == [0_u8; DIGEST_BYTES]
    {
        return Err(
            "Path 2 transparent hidden relation plan reference check profile mismatch".to_string(),
        );
    }
    if !plan.proof_friendly_inner_commitments_required
        || !plan.pad_seed_binding_required
        || !plan.prf_mask_derivation_required
        || !plan.packed_witness_repack_required
        || !plan.role_commitment_consistency_required
    {
        return Err(
            "Path 2 transparent hidden relation plan omits required constraint".to_string(),
        );
    }
    if plan.proof_friendly_inner_commitments_implemented
        != inner_commitment_plan.deployable_inner_commitment_instantiated
    {
        return Err(
            "Path 2 transparent hidden relation plan inner commitment implementation mismatch"
                .to_string(),
        );
    }
    if plan.proof_friendly_inner_commitment_bindings_pinned
        != inner_commitment_plan.proof_friendly_inner_commitment_bindings_pinned
    {
        return Err(
            "Path 2 transparent hidden relation plan inner commitment binding status mismatch"
                .to_string(),
        );
    }
    if !plan.reference_pad_seed_binding_checked
        || !plan.reference_prf_mask_derivation_checked
        || !plan.reference_packed_witness_repack_checked
        || !plan.reference_role_commitment_consistency_checked
    {
        return Err("Path 2 transparent hidden relation plan omits reference check".to_string());
    }
    let expected_reference = plan.reference_pad_seed_binding_checked
        && plan.reference_prf_mask_derivation_checked
        && plan.reference_packed_witness_repack_checked
        && plan.reference_role_commitment_consistency_checked;
    if plan.reference_hidden_relation_checks_implemented != expected_reference {
        return Err("Path 2 transparent hidden relation plan reference check mismatch".to_string());
    }
    let expected_full = plan.proof_friendly_inner_commitments_implemented
        && plan.pad_seed_binding_implemented
        && plan.prf_mask_derivation_implemented
        && plan.packed_witness_repack_implemented
        && plan.role_commitment_consistency_implemented;
    if plan.full_hidden_relation_constraints_implemented != expected_full {
        return Err("Path 2 transparent hidden relation plan full relation mismatch".to_string());
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_HIDDEN_RELATION_CONSTRAINT_PLAN_SCHEMA.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"proof_friendly_inner_commitment_plan_digest",
        &plan.proof_friendly_inner_commitment_plan_digest,
    );
    append_frame(
        &mut frame,
        b"reference_constraint_check_profile_digest",
        &plan.reference_constraint_check_profile_digest,
    );
    append_u64(
        &mut frame,
        b"proof_friendly_inner_commitments_required",
        u64::from(plan.proof_friendly_inner_commitments_required),
    );
    append_u64(
        &mut frame,
        b"proof_friendly_inner_commitment_bindings_pinned",
        u64::from(plan.proof_friendly_inner_commitment_bindings_pinned),
    );
    append_u64(
        &mut frame,
        b"pad_seed_binding_required",
        u64::from(plan.pad_seed_binding_required),
    );
    append_u64(
        &mut frame,
        b"prf_mask_derivation_required",
        u64::from(plan.prf_mask_derivation_required),
    );
    append_u64(
        &mut frame,
        b"packed_witness_repack_required",
        u64::from(plan.packed_witness_repack_required),
    );
    append_u64(
        &mut frame,
        b"role_commitment_consistency_required",
        u64::from(plan.role_commitment_consistency_required),
    );
    append_u64(
        &mut frame,
        b"proof_friendly_inner_commitments_implemented",
        u64::from(plan.proof_friendly_inner_commitments_implemented),
    );
    append_u64(
        &mut frame,
        b"reference_pad_seed_binding_checked",
        u64::from(plan.reference_pad_seed_binding_checked),
    );
    append_u64(
        &mut frame,
        b"reference_prf_mask_derivation_checked",
        u64::from(plan.reference_prf_mask_derivation_checked),
    );
    append_u64(
        &mut frame,
        b"reference_packed_witness_repack_checked",
        u64::from(plan.reference_packed_witness_repack_checked),
    );
    append_u64(
        &mut frame,
        b"reference_role_commitment_consistency_checked",
        u64::from(plan.reference_role_commitment_consistency_checked),
    );
    append_u64(
        &mut frame,
        b"reference_hidden_relation_checks_implemented",
        u64::from(plan.reference_hidden_relation_checks_implemented),
    );
    append_u64(
        &mut frame,
        b"pad_seed_binding_implemented",
        u64::from(plan.pad_seed_binding_implemented),
    );
    append_u64(
        &mut frame,
        b"prf_mask_derivation_implemented",
        u64::from(plan.prf_mask_derivation_implemented),
    );
    append_u64(
        &mut frame,
        b"packed_witness_repack_implemented",
        u64::from(plan.packed_witness_repack_implemented),
    );
    append_u64(
        &mut frame,
        b"role_commitment_consistency_implemented",
        u64::from(plan.role_commitment_consistency_implemented),
    );
    append_u64(
        &mut frame,
        b"full_hidden_relation_constraints_implemented",
        u64::from(plan.full_hidden_relation_constraints_implemented),
    );
    Ok(Sha256::digest(frame).into())
}

pub fn validate_path2_transparent_hidden_relation_constraint_plan_v1(
    plan: &Path2TransparentHiddenRelationConstraintPlanV1,
) -> Result<(), String> {
    let expected = path2_transparent_hidden_relation_constraint_plan_v1();
    if *plan != expected {
        return Err("Path 2 transparent hidden relation plan mismatch".to_string());
    }
    if path2_transparent_hidden_relation_constraint_plan_v1_digest(plan)? != plan.digest {
        return Err("Path 2 transparent hidden relation plan digest mismatch".to_string());
    }
    Ok(())
}

pub fn path2_transparent_trace_to_binding_relation_layer_v1(
) -> Path2TransparentTraceToBindingRelationLayerV1 {
    let relation_layout_digest = path2_transparent_relation_layout_v1_digest()
        .expect("Path 2 transparent relation layout must hash");
    let hidden_relation_plan = path2_transparent_hidden_relation_constraint_plan_v1();
    let current_core_negative_target = path2_transparent_current_core_negative_target_v1();
    let full_hidden_relation_public_certificate_proof_verified = false;
    let reference_hidden_relation_checks_implemented =
        hidden_relation_plan.reference_hidden_relation_checks_implemented;
    let reference_trace_to_binding_bridge_implemented =
        reference_hidden_relation_checks_implemented;
    let trace_to_binding_relation_implemented = hidden_relation_plan
        .full_hidden_relation_constraints_implemented
        && full_hidden_relation_public_certificate_proof_verified;
    let mut layer = Path2TransparentTraceToBindingRelationLayerV1 {
        digest: [0_u8; DIGEST_BYTES],
        schema: PATH2_TRANSPARENT_TRACE_TO_BINDING_RELATION_LAYER_SCHEMA,
        relation_layout_digest,
        hidden_relation_constraint_plan_digest: hidden_relation_plan.digest,
        current_core_negative_target_digest: current_core_negative_target.digest,
        pad_seed_to_leaf_digest_required: true,
        prf_masks_to_pad_seed_slot_required: true,
        packed_witness_repack_to_binding_required: true,
        role_commitments_to_binding_required: true,
        native_role_root_consistency_required: true,
        trace_roots_bind_role_columns_required: true,
        public_masked_projection_seam_required: true,
        zero_knowledge_witness_hiding_required: true,
        local_trace_binding_check_records_required: true,
        full_hidden_relation_suite_binding_required: true,
        local_trace_binding_check_records_carried: true,
        reference_hidden_relation_checks_implemented,
        full_hidden_relation_suite_binding_checked: true,
        full_hidden_relation_local_bridge_digest_checked: true,
        direct_payload_statement_bridge_checked: true,
        public_view_only_verifier_rejection_only: true,
        account_creation_proof_bytes_endpoint_required: true,
        backend_certificate_payload_only_verifier_rejection_only: true,
        backend_certificate_proof_bundle_endpoint_required: true,
        full_hidden_relation_reference_certificate_bridge_verified: true,
        reference_trace_to_binding_bridge_implemented,
        full_hidden_relation_public_certificate_proof_verified,
        trace_to_binding_relation_implemented,
    };
    layer.digest = path2_transparent_trace_to_binding_relation_layer_v1_digest(&layer)
        .expect("constructed Path 2 transparent trace-to-binding relation layer must hash");
    layer
}

pub fn path2_transparent_trace_to_binding_relation_layer_v1_digest(
    layer: &Path2TransparentTraceToBindingRelationLayerV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    if layer.schema != PATH2_TRANSPARENT_TRACE_TO_BINDING_RELATION_LAYER_SCHEMA {
        return Err("Path 2 transparent trace-to-binding layer schema mismatch".to_string());
    }
    let relation_layout = path2_transparent_relation_layout_v1();
    verify_path2_transparent_relation_layout(&relation_layout)?;
    let relation_layout_digest = path2_transparent_relation_layout_v1_digest()?;
    let hidden_relation_plan = path2_transparent_hidden_relation_constraint_plan_v1();
    validate_path2_transparent_hidden_relation_constraint_plan_v1(&hidden_relation_plan)?;
    let current_core_negative_target = path2_transparent_current_core_negative_target_v1();
    validate_path2_transparent_current_core_negative_target_v1(&current_core_negative_target)?;
    if layer.relation_layout_digest != relation_layout_digest {
        return Err(
            "Path 2 transparent trace-to-binding layer relation layout mismatch".to_string(),
        );
    }
    if relation_layout.full_hidden_relation_constraints_enforced
        != hidden_relation_plan.full_hidden_relation_constraints_implemented
    {
        return Err(
            "Path 2 transparent trace-to-binding layer relation layout hidden relation mismatch"
                .to_string(),
        );
    }
    if layer.hidden_relation_constraint_plan_digest != hidden_relation_plan.digest {
        return Err(
            "Path 2 transparent trace-to-binding layer hidden relation plan mismatch".to_string(),
        );
    }
    if layer.current_core_negative_target_digest != current_core_negative_target.digest {
        return Err(
            "Path 2 transparent trace-to-binding layer current-core negative target mismatch"
                .to_string(),
        );
    }
    if !layer.pad_seed_to_leaf_digest_required
        || !layer.prf_masks_to_pad_seed_slot_required
        || !layer.packed_witness_repack_to_binding_required
        || !layer.role_commitments_to_binding_required
        || !layer.native_role_root_consistency_required
        || !layer.trace_roots_bind_role_columns_required
        || !layer.public_masked_projection_seam_required
        || !layer.zero_knowledge_witness_hiding_required
        || !layer.local_trace_binding_check_records_required
        || !layer.full_hidden_relation_suite_binding_required
    {
        return Err(
            "Path 2 transparent trace-to-binding layer omits required relation".to_string(),
        );
    }
    if !layer.local_trace_binding_check_records_carried {
        return Err(
            "Path 2 transparent trace-to-binding layer check records are not carried".to_string(),
        );
    }
    if layer.reference_hidden_relation_checks_implemented
        != hidden_relation_plan.reference_hidden_relation_checks_implemented
    {
        return Err(
            "Path 2 transparent trace-to-binding layer reference hidden relation check mismatch"
                .to_string(),
        );
    }
    if !layer.reference_hidden_relation_checks_implemented {
        return Err(
            "Path 2 transparent trace-to-binding layer reference hidden relation checks are missing"
                .to_string(),
        );
    }
    if !layer.full_hidden_relation_suite_binding_checked {
        return Err(
            "Path 2 transparent trace-to-binding layer suite binding is not checked".to_string(),
        );
    }
    if !layer.full_hidden_relation_local_bridge_digest_checked {
        return Err(
            "Path 2 transparent trace-to-binding layer local bridge digest is not checked"
                .to_string(),
        );
    }
    if !layer.direct_payload_statement_bridge_checked {
        return Err(
            "Path 2 transparent trace-to-binding layer direct statement bridge is not checked"
                .to_string(),
        );
    }
    if !layer.public_view_only_verifier_rejection_only {
        return Err(
            "Path 2 transparent trace-to-binding layer public-view-only verifier is accepting"
                .to_string(),
        );
    }
    if !layer.account_creation_proof_bytes_endpoint_required {
        return Err(
            "Path 2 transparent trace-to-binding layer account-creation proof-bytes endpoint missing"
                .to_string(),
        );
    }
    if !layer.backend_certificate_payload_only_verifier_rejection_only {
        return Err(
            "Path 2 transparent trace-to-binding layer backend certificate payload-only verifier is accepting"
                .to_string(),
        );
    }
    if !layer.backend_certificate_proof_bundle_endpoint_required {
        return Err(
            "Path 2 transparent trace-to-binding layer backend certificate proof bundle endpoint missing"
                .to_string(),
        );
    }
    if !layer.full_hidden_relation_reference_certificate_bridge_verified {
        return Err(
            "Path 2 transparent trace-to-binding layer reference certificate bridge check missing"
                .to_string(),
        );
    }
    let expected_reference_bridge = layer.local_trace_binding_check_records_carried
        && layer.reference_hidden_relation_checks_implemented
        && layer.full_hidden_relation_suite_binding_checked
        && layer.full_hidden_relation_local_bridge_digest_checked
        && layer.direct_payload_statement_bridge_checked
        && layer.public_view_only_verifier_rejection_only
        && layer.account_creation_proof_bytes_endpoint_required
        && layer.backend_certificate_payload_only_verifier_rejection_only
        && layer.backend_certificate_proof_bundle_endpoint_required
        && layer.full_hidden_relation_reference_certificate_bridge_verified;
    if layer.reference_trace_to_binding_bridge_implemented != expected_reference_bridge {
        return Err(
            "Path 2 transparent trace-to-binding layer reference bridge implementation mismatch"
                .to_string(),
        );
    }
    if layer.full_hidden_relation_public_certificate_proof_verified
        && !hidden_relation_plan.full_hidden_relation_constraints_implemented
    {
        return Err(
            "Path 2 transparent trace-to-binding layer public certificate proof cannot be verified before full hidden relation constraints are implemented"
                .to_string(),
        );
    }
    let expected_implemented = hidden_relation_plan.full_hidden_relation_constraints_implemented
        && layer.full_hidden_relation_public_certificate_proof_verified;
    if layer.trace_to_binding_relation_implemented != expected_implemented {
        return Err(
            "Path 2 transparent trace-to-binding layer implementation mismatch".to_string(),
        );
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_TRACE_TO_BINDING_RELATION_LAYER_SCHEMA.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"relation_layout_digest",
        &layer.relation_layout_digest,
    );
    append_frame(
        &mut frame,
        b"hidden_relation_constraint_plan_digest",
        &layer.hidden_relation_constraint_plan_digest,
    );
    append_frame(
        &mut frame,
        b"current_core_negative_target_digest",
        &layer.current_core_negative_target_digest,
    );
    append_u64(
        &mut frame,
        b"pad_seed_to_leaf_digest_required",
        u64::from(layer.pad_seed_to_leaf_digest_required),
    );
    append_u64(
        &mut frame,
        b"prf_masks_to_pad_seed_slot_required",
        u64::from(layer.prf_masks_to_pad_seed_slot_required),
    );
    append_u64(
        &mut frame,
        b"packed_witness_repack_to_binding_required",
        u64::from(layer.packed_witness_repack_to_binding_required),
    );
    append_u64(
        &mut frame,
        b"role_commitments_to_binding_required",
        u64::from(layer.role_commitments_to_binding_required),
    );
    append_u64(
        &mut frame,
        b"native_role_root_consistency_required",
        u64::from(layer.native_role_root_consistency_required),
    );
    append_u64(
        &mut frame,
        b"trace_roots_bind_role_columns_required",
        u64::from(layer.trace_roots_bind_role_columns_required),
    );
    append_u64(
        &mut frame,
        b"public_masked_projection_seam_required",
        u64::from(layer.public_masked_projection_seam_required),
    );
    append_u64(
        &mut frame,
        b"zero_knowledge_witness_hiding_required",
        u64::from(layer.zero_knowledge_witness_hiding_required),
    );
    append_u64(
        &mut frame,
        b"local_trace_binding_check_records_required",
        u64::from(layer.local_trace_binding_check_records_required),
    );
    append_u64(
        &mut frame,
        b"full_hidden_relation_suite_binding_required",
        u64::from(layer.full_hidden_relation_suite_binding_required),
    );
    append_u64(
        &mut frame,
        b"local_trace_binding_check_records_carried",
        u64::from(layer.local_trace_binding_check_records_carried),
    );
    append_u64(
        &mut frame,
        b"reference_hidden_relation_checks_implemented",
        u64::from(layer.reference_hidden_relation_checks_implemented),
    );
    append_u64(
        &mut frame,
        b"full_hidden_relation_suite_binding_checked",
        u64::from(layer.full_hidden_relation_suite_binding_checked),
    );
    append_u64(
        &mut frame,
        b"full_hidden_relation_local_bridge_digest_checked",
        u64::from(layer.full_hidden_relation_local_bridge_digest_checked),
    );
    append_u64(
        &mut frame,
        b"direct_payload_statement_bridge_checked",
        u64::from(layer.direct_payload_statement_bridge_checked),
    );
    append_u64(
        &mut frame,
        b"public_view_only_verifier_rejection_only",
        u64::from(layer.public_view_only_verifier_rejection_only),
    );
    append_u64(
        &mut frame,
        b"account_creation_proof_bytes_endpoint_required",
        u64::from(layer.account_creation_proof_bytes_endpoint_required),
    );
    append_u64(
        &mut frame,
        b"backend_certificate_payload_only_verifier_rejection_only",
        u64::from(layer.backend_certificate_payload_only_verifier_rejection_only),
    );
    append_u64(
        &mut frame,
        b"backend_certificate_proof_bundle_endpoint_required",
        u64::from(layer.backend_certificate_proof_bundle_endpoint_required),
    );
    append_u64(
        &mut frame,
        b"full_hidden_relation_reference_certificate_bridge_verified",
        u64::from(layer.full_hidden_relation_reference_certificate_bridge_verified),
    );
    append_u64(
        &mut frame,
        b"reference_trace_to_binding_bridge_implemented",
        u64::from(layer.reference_trace_to_binding_bridge_implemented),
    );
    append_u64(
        &mut frame,
        b"full_hidden_relation_public_certificate_proof_verified",
        u64::from(layer.full_hidden_relation_public_certificate_proof_verified),
    );
    append_u64(
        &mut frame,
        b"trace_to_binding_relation_implemented",
        u64::from(layer.trace_to_binding_relation_implemented),
    );
    Ok(Sha256::digest(frame).into())
}

