    off += 2;
    let digest = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
    let public_inputs_digest = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
    let full_hidden_relation_proof_contract_digest =
        bytes[off..off + DIGEST_BYTES].try_into().unwrap();
