    off += DIGEST_BYTES;
    let leaf_context_digest = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
    let creation_proof_binding_digest = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
    let slot_id = u64::from_le_bytes(bytes[off..off + 8].try_into().unwrap());
    off += 8;
    let hidden_source_statement_digest = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
    let matrix_domain_transcript_digest = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
