    let constraint_commitment_root = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
    let column_profile = u16::from_le_bytes(bytes[off..off + 2].try_into().unwrap());
    off += 2;
    let trace_rows = u16::from_le_bytes(bytes[off..off + 2].try_into().unwrap());
    off += 2;
    let query_count = u16::from_le_bytes(bytes[off..off + 2].try_into().unwrap());
    off += 2;
    let query_index = u16::from_le_bytes(bytes[off..off + 2].try_into().unwrap());
    off += 2;
    let read_bool = |byte: u8| -> Result<bool, String> {
        match byte {
            0 => Ok(false),
            1 => Ok(true),
            _ => Err(
                "Path 2 transparent full hidden relation subproof statement boolean mismatch"
                    .to_string(),
            ),
        }
    };
    let hidden_relation_witness_check_required = read_bool(bytes[off])?;
    off += 1;
    let trace_origin_witness_check_required = read_bool(bytes[off])?;
    off += 1;
    let trace_roots_bound_to_hidden_witness_required = read_bool(bytes[off])?;
