    off += DIGEST_BYTES;
    let packed_witness_commitment = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
    let randomizer_commitment = bytes[off..off + DIGEST_BYTES].try_into().unwrap();
    off += DIGEST_BYTES;
