pub fn validate_path2_transparent_production_soundness_obligations_v1(
    obligations: &Path2TransparentProductionSoundnessObligationsV1,
) -> Result<(), String> {
    let expected = path2_transparent_production_soundness_obligations_v1();
    if *obligations != expected {
        return Err("Path 2 transparent production obligations mismatch".to_string());
    }
    if path2_transparent_production_soundness_obligations_v1_digest(obligations)?
        != obligations.digest
    {
        return Err("Path 2 transparent production obligations digest mismatch".to_string());
    }
    Ok(())
}

pub fn path2_transparent_proof_family_capability_v1(
) -> Result<Path2TransparentProofFamilyCapabilityV1, String> {
    let trace_column_manifest = path2_native_boundary_trace_column_manifest_v1()?;
    let hidden_relation_plan = path2_transparent_hidden_relation_constraint_plan_v1();
    validate_path2_transparent_hidden_relation_constraint_plan_v1(&hidden_relation_plan)?;
    let trace_to_binding_layer = path2_transparent_trace_to_binding_relation_layer_v1();
    validate_path2_transparent_trace_to_binding_relation_layer_v1(&trace_to_binding_layer)?;
    let current_core_negative_target = path2_transparent_current_core_negative_target_v1();
    validate_path2_transparent_current_core_negative_target_v1(&current_core_negative_target)?;
    let backend_sufficiency_target =
        path2_transparent_full_relation_backend_sufficiency_target_v1();
    validate_path2_transparent_full_relation_backend_sufficiency_target_v1(
        &backend_sufficiency_target,
    )?;
    let full_hidden_relation_proof_contract =
        path2_transparent_full_hidden_relation_proof_contract_v1();
    validate_path2_transparent_full_hidden_relation_proof_contract_v1(
        &full_hidden_relation_proof_contract,
    )?;
    let production_obligations = path2_transparent_production_soundness_obligations_v1();
    validate_path2_transparent_production_soundness_obligations_v1(&production_obligations)?;
    let capability = Path2TransparentProofFamilyCapabilityV1 {
        schema: PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_SCHEMA,
        profile_id: PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_PROFILE_ID,
        family: PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY,
        relation_layout_digest: path2_transparent_relation_layout_v1_digest()?,
        hidden_relation_constraint_plan_digest: hidden_relation_plan.digest,
        proof_friendly_inner_commitment_plan_digest: production_obligations
            .proof_friendly_inner_commitment_plan_digest,
        reference_constraint_check_profile_digest: production_obligations
            .reference_constraint_check_profile_digest,
        trace_to_binding_relation_layer_digest: trace_to_binding_layer.digest,
        current_core_negative_target_digest: current_core_negative_target.digest,
        backend_sufficiency_target_digest: backend_sufficiency_target.digest,
        full_hidden_relation_proof_contract_digest: full_hidden_relation_proof_contract.digest,
        backend_payload_contract_digest: production_obligations.backend_payload_contract_digest,
        backend_acceptance_verifier_digest: production_obligations
            .backend_acceptance_verifier_digest,
        proof_friendly_role_commitment_verifier_digest: production_obligations
            .proof_friendly_role_commitment_verifier_digest,
        disabled_backend_proof_payload_digest: production_obligations
            .disabled_backend_proof_payload_digest,
        external_coded_sis_review_target_digest: production_obligations
            .external_coded_sis_review_target_digest,
        trace_column_manifest_digest: path2_native_boundary_trace_column_manifest_v1_digest()?,
        query_schedule_digest: path2_transparent_query_schedule_v1_digest()?,
        trace_proof_family_interface_digest:
            path2_native_boundary_trace_proof_family_interface_v1_digest()?,
        column_profile: PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
        active_witness_lane_floor: trace_column_manifest.range_account_lane_floor,
        native_boundary_relation_rows: trace_column_manifest.relation_rows_working,
        parent_root_binding: true,
        typed_role_subcommitments: true,
        creation_binding_role_handles_bound: true,
        local_trace_binding_payload_shape_checked: production_obligations
            .local_trace_binding_payload_shape_checked,
        local_trace_binding_public_envelope_checked: production_obligations
            .local_trace_binding_public_envelope_checked,
        local_trace_binding_check_records_carried: production_obligations
            .local_trace_binding_check_records_carried,
        reference_hidden_relation_checks_implemented: production_obligations
            .reference_hidden_relation_checks_implemented,
        full_hidden_relation_suite_binding_checked: production_obligations
            .full_hidden_relation_suite_binding_checked,
        full_hidden_relation_local_bridge_digest_checked: production_obligations
            .full_hidden_relation_local_bridge_digest_checked,
        direct_payload_statement_bridge_checked: production_obligations
            .direct_payload_statement_bridge_checked,
        public_view_only_verifier_rejection_only: production_obligations
            .public_view_only_verifier_rejection_only,
        account_creation_proof_bytes_endpoint_required: production_obligations
            .account_creation_proof_bytes_endpoint_required,
        backend_certificate_payload_only_verifier_rejection_only: production_obligations
            .backend_certificate_payload_only_verifier_rejection_only,
        backend_certificate_proof_bundle_endpoint_required: production_obligations
            .backend_certificate_proof_bundle_endpoint_required,
        full_hidden_relation_reference_certificate_bridge_verified: production_obligations
            .full_hidden_relation_reference_certificate_bridge_verified,
        reference_trace_to_binding_bridge_implemented: production_obligations
            .reference_trace_to_binding_bridge_implemented,
        full_hidden_relation_public_certificate_proof_verified: production_obligations
            .full_hidden_relation_public_certificate_proof_verified,
        backend_certificate_obligation_set_pinned: production_obligations
            .backend_certificate_obligation_set_pinned,
        backend_certificate_acceptance_prerequisites_pinned: production_obligations
            .backend_certificate_acceptance_prerequisites_pinned,
        proof_payload_contract_bindings_pinned: production_obligations
            .proof_payload_contract_bindings_pinned,
        proof_payload_contract_implemented: production_obligations
            .proof_payload_contract_implemented,
        proof_friendly_inner_commitment_bindings_pinned: production_obligations
            .proof_friendly_inner_commitment_bindings_pinned,
        proof_friendly_inner_commitments_implemented: production_obligations
            .proof_friendly_inner_commitments_implemented,
        full_hidden_relation_constraint_checks_pinned: production_obligations
            .full_hidden_relation_constraint_checks_pinned,
        pad_seed_binding_constraint_enforced: production_obligations
            .pad_seed_binding_constraint_enforced,
        prf_mask_derivation_constraint_enforced: production_obligations
            .prf_mask_derivation_constraint_enforced,
        packed_witness_repack_constraint_enforced: production_obligations
            .packed_witness_repack_constraint_enforced,
        role_commitment_consistency_constraint_enforced: production_obligations
            .role_commitment_consistency_constraint_enforced,
        full_hidden_relation_constraints_enforced: production_obligations
            .full_hidden_relation_constraints_enforced,
        trace_to_binding_relation_layer_implemented: production_obligations
            .trace_to_binding_relation_layer_implemented,
        full_relation_backend_certificate_instantiated: production_obligations
            .full_relation_backend_certificate_instantiated,
        p2_sis_extractor_interface_bound: production_obligations.p2_sis_extractor_interface_bound,
        hidden_range_extractor_interface_bound: production_obligations
            .hidden_range_extractor_interface_bound,
        external_coded_sis_review_complete: production_obligations
            .external_coded_sis_review_complete,
        inner_commitment_binding_break_exported: true,
        full_trace_extractable: production_obligations.production_soundness_obligations_discharged,
        full_witness_relation_knowledge: production_obligations
            .production_soundness_obligations_discharged,
        hidden_column_zero_knowledge: production_obligations
            .production_soundness_obligations_discharged,
        masked_query_no_export: true,
        opened_row_component_digest_bound: production_obligations
            .query_opening_component_binding_checked,
        qrom_schedule_bound: true,
        norm_range_soundness: production_obligations.production_soundness_obligations_discharged,
        blinding_noise_bound_soundness: production_obligations
            .production_soundness_obligations_discharged,
        production_soundness_obligations_digest: production_obligations.digest,
        production_soundness_obligations_discharged: production_obligations
            .production_soundness_obligations_discharged,
        role_authentication_material_simulatable: production_obligations
            .production_soundness_obligations_discharged,
        mask_freshness: production_obligations.production_soundness_obligations_discharged,
        no_raw_hidden_openings: true,
        no_public_linear_role_commitments: true,
        fallback_threshold_bytes: PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES,
    };
    verify_path2_transparent_proof_family_capability(&capability)?;
    Ok(capability)
}

pub fn verify_path2_transparent_proof_family_capability(
    capability: &Path2TransparentProofFamilyCapabilityV1,
) -> Result<(), String> {
    if capability.schema != PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_SCHEMA {
        return Err("Path 2 transparent proof-family capability schema mismatch".to_string());
    }
    if capability.profile_id != PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_PROFILE_ID {
        return Err("Path 2 transparent proof-family capability profile mismatch".to_string());
    }
    if capability.family != PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY {
        return Err("Path 2 transparent proof-family capability family mismatch".to_string());
    }
    if capability.relation_layout_digest != path2_transparent_relation_layout_v1_digest()? {
        return Err(
            "Path 2 transparent proof-family capability relation layout mismatch".to_string(),
        );
    }
    let hidden_relation_plan = path2_transparent_hidden_relation_constraint_plan_v1();
    validate_path2_transparent_hidden_relation_constraint_plan_v1(&hidden_relation_plan)?;
    if capability.hidden_relation_constraint_plan_digest != hidden_relation_plan.digest {
        return Err(
            "Path 2 transparent proof-family capability hidden relation plan mismatch".to_string(),
        );
    }
    if capability.proof_friendly_inner_commitment_plan_digest
        != hidden_relation_plan.proof_friendly_inner_commitment_plan_digest
        || capability.proof_friendly_inner_commitment_plan_digest == [0_u8; DIGEST_BYTES]
    {
        return Err(
            "Path 2 transparent proof-family capability proof-friendly inner commitment plan mismatch"
                .to_string(),
        );
    }
    if capability.reference_constraint_check_profile_digest
        != hidden_relation_plan.reference_constraint_check_profile_digest
        || capability.reference_constraint_check_profile_digest == [0_u8; DIGEST_BYTES]
    {
        return Err(
            "Path 2 transparent proof-family capability reference constraint check profile mismatch"
                .to_string(),
        );
    }
    let trace_to_binding_layer = path2_transparent_trace_to_binding_relation_layer_v1();
    validate_path2_transparent_trace_to_binding_relation_layer_v1(&trace_to_binding_layer)?;
    if capability.trace_to_binding_relation_layer_digest != trace_to_binding_layer.digest {
        return Err(
            "Path 2 transparent proof-family capability trace-to-binding layer mismatch"
                .to_string(),
        );
    }
    let current_core_negative_target = path2_transparent_current_core_negative_target_v1();
    validate_path2_transparent_current_core_negative_target_v1(&current_core_negative_target)?;
    if capability.current_core_negative_target_digest != current_core_negative_target.digest {
        return Err(
            "Path 2 transparent proof-family capability current-core negative target mismatch"
                .to_string(),
        );
    }
    let backend_sufficiency_target =
        path2_transparent_full_relation_backend_sufficiency_target_v1();
    validate_path2_transparent_full_relation_backend_sufficiency_target_v1(
        &backend_sufficiency_target,
    )?;
    if capability.backend_sufficiency_target_digest != backend_sufficiency_target.digest {
        return Err(
            "Path 2 transparent proof-family capability backend sufficiency target mismatch"
                .to_string(),
        );
    }
    let full_hidden_relation_proof_contract =
        path2_transparent_full_hidden_relation_proof_contract_v1();
    validate_path2_transparent_full_hidden_relation_proof_contract_v1(
        &full_hidden_relation_proof_contract,
    )?;
    if capability.full_hidden_relation_proof_contract_digest
        != full_hidden_relation_proof_contract.digest
    {
        return Err(
            "Path 2 transparent proof-family capability full hidden relation proof contract mismatch"
                .to_string(),
        );
    }
    let backend_payload_contract =
        path2_transparent_full_hidden_relation_backend_payload_contract_v1();
    validate_path2_transparent_full_hidden_relation_backend_payload_contract_v1(
        &backend_payload_contract,
    )?;
    if capability.backend_payload_contract_digest != backend_payload_contract.digest {
        return Err(
            "Path 2 transparent proof-family capability backend payload contract mismatch"
                .to_string(),
        );
    }
    if capability.backend_acceptance_verifier_digest
        != backend_payload_contract.backend_acceptance_verifier_digest
    {
        return Err(
            "Path 2 transparent proof-family capability backend acceptance verifier mismatch"
                .to_string(),
        );
    }
    if capability.proof_friendly_role_commitment_verifier_digest
        != backend_payload_contract.proof_friendly_role_commitment_verifier_digest
        || capability.proof_friendly_role_commitment_verifier_digest
            != path2_transparent_proof_friendly_role_commitment_verifier_digest_v1()
        || capability.proof_friendly_role_commitment_verifier_digest == [0_u8; DIGEST_BYTES]
    {
        return Err(
            "Path 2 transparent proof-family capability role-commitment verifier mismatch"
                .to_string(),
        );
    }
    if capability.disabled_backend_proof_payload_digest
        != backend_payload_contract.disabled_backend_proof_payload_digest
        || capability.disabled_backend_proof_payload_digest == [0_u8; DIGEST_BYTES]
    {
        return Err(
            "Path 2 transparent proof-family capability disabled backend proof payload mismatch"
                .to_string(),
        );
    }
    if capability.external_coded_sis_review_target_digest
        != path2_external_coded_sis_review_target_digest_v1()
        || capability.external_coded_sis_review_target_digest == [0_u8; DIGEST_BYTES]
    {
        return Err(
            "Path 2 transparent proof-family capability external coded-SIS review target mismatch"
                .to_string(),
        );
    }
    let trace_column_manifest = path2_native_boundary_trace_column_manifest_v1()?;
    if capability.trace_column_manifest_digest
        != path2_native_boundary_trace_column_manifest_v1_digest()?
    {
        return Err(
            "Path 2 transparent proof-family capability trace column manifest mismatch".to_string(),
        );
    }
    if capability.query_schedule_digest != path2_transparent_query_schedule_v1_digest()? {
        return Err(
            "Path 2 transparent proof-family capability query schedule mismatch".to_string(),
        );
    }
    if capability.trace_proof_family_interface_digest
        != path2_native_boundary_trace_proof_family_interface_v1_digest()?
    {
        return Err(
            "Path 2 transparent proof-family capability trace proof interface mismatch".to_string(),
        );
    }
    verify_path2_two_view_column_profile_id(capability.column_profile)?;
    if capability.active_witness_lane_floor != trace_column_manifest.range_account_lane_floor {
        return Err(
            "Path 2 transparent proof-family capability active witness lane floor mismatch"
                .to_string(),
        );
    }
    if capability.active_witness_lane_floor <= PATH2_TRANSPARENT_DESCENT_WITNESS_LANES as u16 {
        return Err("Path 2 transparent proof-family capability is semantic-core-only".to_string());
    }
    if capability.native_boundary_relation_rows != trace_column_manifest.relation_rows_working {
        return Err(
            "Path 2 transparent proof-family capability native relation rows mismatch".to_string(),
        );
    }
    let production_obligations = path2_transparent_production_soundness_obligations_v1();
    validate_path2_transparent_production_soundness_obligations_v1(&production_obligations)?;
    if capability.full_trace_extractable
        != production_obligations.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability full trace extractability mismatch"
                .to_string(),
        );
    }
    if capability.full_witness_relation_knowledge
        != production_obligations.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability full witness relation knowledge mismatch"
                .to_string(),
        );
    }
    if capability.hidden_column_zero_knowledge
        != production_obligations.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability hidden column zero-knowledge mismatch"
                .to_string(),
        );
    }
    if capability.norm_range_soundness
        != production_obligations.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability norm range soundness mismatch".to_string(),
        );
    }
    if capability.blinding_noise_bound_soundness
        != production_obligations.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability blinding noise bound soundness mismatch"
                .to_string(),
        );
    }
    if capability.role_authentication_material_simulatable
        != production_obligations.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability role authentication simulator mismatch"
                .to_string(),
        );
    }
    if capability.mask_freshness
        != production_obligations.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability mask freshness mismatch".to_string(),
        );
    }
    if capability.full_hidden_relation_public_certificate_proof_verified
        && !capability.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability public certificate proof cannot be verified before production obligations are discharged"
                .to_string(),
        );
    }
    for (label, enabled) in [
        ("parent_root_binding", capability.parent_root_binding),
        (
            "typed_role_subcommitments",
            capability.typed_role_subcommitments,
        ),
        (
            "creation_binding_role_handles_bound",
            capability.creation_binding_role_handles_bound,
        ),
        (
            "local_trace_binding_payload_shape_checked",
            capability.local_trace_binding_payload_shape_checked,
        ),
        (
            "local_trace_binding_public_envelope_checked",
            capability.local_trace_binding_public_envelope_checked,
        ),
        (
            "local_trace_binding_check_records_carried",
            capability.local_trace_binding_check_records_carried,
        ),
        (
            "reference_hidden_relation_checks_implemented",
            capability.reference_hidden_relation_checks_implemented,
        ),
        (
            "full_hidden_relation_suite_binding_checked",
            capability.full_hidden_relation_suite_binding_checked,
        ),
        (
            "full_hidden_relation_local_bridge_digest_checked",
            capability.full_hidden_relation_local_bridge_digest_checked,
        ),
        (
            "direct_payload_statement_bridge_checked",
            capability.direct_payload_statement_bridge_checked,
        ),
        (
            "public_view_only_verifier_rejection_only",
            capability.public_view_only_verifier_rejection_only,
        ),
        (
            "account_creation_proof_bytes_endpoint_required",
            capability.account_creation_proof_bytes_endpoint_required,
        ),
        (
            "backend_certificate_payload_only_verifier_rejection_only",
            capability.backend_certificate_payload_only_verifier_rejection_only,
        ),
        (
            "backend_certificate_proof_bundle_endpoint_required",
            capability.backend_certificate_proof_bundle_endpoint_required,
        ),
        (
            "full_hidden_relation_reference_certificate_bridge_verified",
            capability.full_hidden_relation_reference_certificate_bridge_verified,
        ),
        (
            "reference_trace_to_binding_bridge_implemented",
            capability.reference_trace_to_binding_bridge_implemented,
        ),
        (
            "inner_commitment_binding_break_exported",
            capability.inner_commitment_binding_break_exported,
        ),
        (
            "p2_sis_extractor_interface_bound",
            capability.p2_sis_extractor_interface_bound,
        ),
        (
            "proof_payload_contract_bindings_pinned",
            capability.proof_payload_contract_bindings_pinned,
        ),
        (
            "backend_certificate_obligation_set_pinned",
            capability.backend_certificate_obligation_set_pinned,
        ),
        (
            "backend_certificate_acceptance_prerequisites_pinned",
            capability.backend_certificate_acceptance_prerequisites_pinned,
        ),
        (
            "proof_friendly_inner_commitment_bindings_pinned",
            capability.proof_friendly_inner_commitment_bindings_pinned,
        ),
        (
            "full_hidden_relation_constraint_checks_pinned",
            capability.full_hidden_relation_constraint_checks_pinned,
        ),
        (
            "hidden_range_extractor_interface_bound",
            capability.hidden_range_extractor_interface_bound,
        ),
        ("masked_query_no_export", capability.masked_query_no_export),
        (
            "opened_row_component_digest_bound",
            capability.opened_row_component_digest_bound,
        ),
        ("qrom_schedule_bound", capability.qrom_schedule_bound),
        ("no_raw_hidden_openings", capability.no_raw_hidden_openings),
        (
            "no_public_linear_role_commitments",
            capability.no_public_linear_role_commitments,
        ),
    ] {
        if !enabled {
            return Err(format!(
                "Path 2 transparent proof-family capability missing {label}"
            ));
        }
    }
    if capability.fallback_threshold_bytes
        != PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES
    {
        return Err(
            "Path 2 transparent proof-family capability fallback threshold mismatch".to_string(),
        );
    }
    if capability.local_trace_binding_payload_shape_checked
        != production_obligations.local_trace_binding_payload_shape_checked
        || capability.local_trace_binding_public_envelope_checked
            != production_obligations.local_trace_binding_public_envelope_checked
        || capability.local_trace_binding_check_records_carried
            != production_obligations.local_trace_binding_check_records_carried
        || capability.reference_hidden_relation_checks_implemented
            != production_obligations.reference_hidden_relation_checks_implemented
        || capability.full_hidden_relation_suite_binding_checked
            != production_obligations.full_hidden_relation_suite_binding_checked
        || capability.full_hidden_relation_local_bridge_digest_checked
            != production_obligations.full_hidden_relation_local_bridge_digest_checked
        || capability.direct_payload_statement_bridge_checked
            != production_obligations.direct_payload_statement_bridge_checked
        || capability.public_view_only_verifier_rejection_only
            != production_obligations.public_view_only_verifier_rejection_only
        || capability.account_creation_proof_bytes_endpoint_required
            != production_obligations.account_creation_proof_bytes_endpoint_required
        || capability.backend_certificate_payload_only_verifier_rejection_only
            != production_obligations.backend_certificate_payload_only_verifier_rejection_only
        || capability.backend_certificate_proof_bundle_endpoint_required
            != production_obligations.backend_certificate_proof_bundle_endpoint_required
        || capability.full_hidden_relation_reference_certificate_bridge_verified
            != production_obligations.full_hidden_relation_reference_certificate_bridge_verified
        || capability.reference_trace_to_binding_bridge_implemented
            != production_obligations.reference_trace_to_binding_bridge_implemented
        || capability.full_hidden_relation_public_certificate_proof_verified
            != production_obligations.full_hidden_relation_public_certificate_proof_verified
        || capability.backend_certificate_obligation_set_pinned
            != production_obligations.backend_certificate_obligation_set_pinned
        || capability.backend_certificate_acceptance_prerequisites_pinned
            != production_obligations.backend_certificate_acceptance_prerequisites_pinned
        || capability.proof_payload_contract_bindings_pinned
            != production_obligations.proof_payload_contract_bindings_pinned
        || capability.proof_payload_contract_implemented
            != production_obligations.proof_payload_contract_implemented
        || capability.proof_friendly_inner_commitment_bindings_pinned
            != production_obligations.proof_friendly_inner_commitment_bindings_pinned
        || capability.proof_friendly_inner_commitments_implemented
            != production_obligations.proof_friendly_inner_commitments_implemented
        || capability.full_hidden_relation_constraint_checks_pinned
            != production_obligations.full_hidden_relation_constraint_checks_pinned
        || capability.pad_seed_binding_constraint_enforced
            != production_obligations.pad_seed_binding_constraint_enforced
        || capability.prf_mask_derivation_constraint_enforced
            != production_obligations.prf_mask_derivation_constraint_enforced
        || capability.packed_witness_repack_constraint_enforced
            != production_obligations.packed_witness_repack_constraint_enforced
        || capability.role_commitment_consistency_constraint_enforced
            != production_obligations.role_commitment_consistency_constraint_enforced
        || capability.full_hidden_relation_constraints_enforced
            != production_obligations.full_hidden_relation_constraints_enforced
        || capability.trace_to_binding_relation_layer_implemented
            != production_obligations.trace_to_binding_relation_layer_implemented
        || capability.full_relation_backend_certificate_instantiated
            != production_obligations.full_relation_backend_certificate_instantiated
        || capability.p2_sis_extractor_interface_bound
            != production_obligations.p2_sis_extractor_interface_bound
        || capability.hidden_range_extractor_interface_bound
            != production_obligations.hidden_range_extractor_interface_bound
        || capability.external_coded_sis_review_complete
            != production_obligations.external_coded_sis_review_complete
        || capability.opened_row_component_digest_bound
            != production_obligations.query_opening_component_binding_checked
        || capability.proof_friendly_inner_commitment_plan_digest
            != production_obligations.proof_friendly_inner_commitment_plan_digest
        || capability.reference_constraint_check_profile_digest
            != production_obligations.reference_constraint_check_profile_digest
        || capability.backend_payload_contract_digest
            != production_obligations.backend_payload_contract_digest
        || capability.backend_acceptance_verifier_digest
            != production_obligations.backend_acceptance_verifier_digest
        || capability.proof_friendly_role_commitment_verifier_digest
            != production_obligations.proof_friendly_role_commitment_verifier_digest
        || capability.disabled_backend_proof_payload_digest
            != production_obligations.disabled_backend_proof_payload_digest
        || capability.external_coded_sis_review_target_digest
            != production_obligations.external_coded_sis_review_target_digest
    {
        return Err(
            "Path 2 transparent proof-family capability local trace binding status mismatch"
                .to_string(),
        );
    }
    if capability.production_soundness_obligations_digest != production_obligations.digest {
        return Err(
            "Path 2 transparent proof-family capability production obligations digest mismatch"
                .to_string(),
        );
    }
    if capability.production_soundness_obligations_discharged
        != production_obligations.production_soundness_obligations_discharged
    {
        return Err(
            "Path 2 transparent proof-family capability production soundness discharge mismatch"
                .to_string(),
        );
    }
    Ok(())
}

pub fn verify_path2_transparent_proof_family_capability_for_production(
    capability: &Path2TransparentProofFamilyCapabilityV1,
) -> Result<(), String> {
    verify_path2_transparent_proof_family_capability(capability)?;
    if !path2_transparent_descent_production_soundness_obligations_discharged_v1() {
        return Err(PATH2_TRANSPARENT_DESCENT_PRODUCTION_SOUNDNESS_DISABLED_ERROR.to_string());
    }
    Ok(())
}

