pub fn verify_path2_prevalidated_slot_creation_frame_bindings(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
) -> Result<(), String> {
    let slot_leaf_digest = path2_prevalidated_slot_leaf_digest(leaf)?;
    if evidence.slot_leaf_digest != slot_leaf_digest {
        return Err("Path 2 slot leaf digest mismatch".to_string());
    }
    let slot_authorization_digest = path2_slot_authorization_digest(leaf)?;
    if evidence.slot_authorization_digest != slot_authorization_digest {
        return Err("Path 2 slot authorization digest mismatch".to_string());
    }
    if evidence.creation_verifier_version_digest != leaf.verifier_version_digest {
        return Err("Path 2 creation verifier version mismatch".to_string());
    }
    if evidence.hidden_source_statement_digest != leaf.hidden_source_statement_digest {
        return Err("Path 2 hidden-source statement digest mismatch".to_string());
    }
    if evidence.opening_commitment != leaf.opening_commitment {
        return Err("Path 2 opening commitment mismatch".to_string());
    }
    if evidence.pad_seed_digest != leaf.pad_seed_digest {
        return Err("Path 2 pad-seed digest mismatch".to_string());
    }
    if evidence.account_identity_digest != leaf.account_id {
        return Err("Path 2 account id mismatch".to_string());
    }
    if evidence.public_key_identity != leaf.public_key_identity {
        return Err("Path 2 public-key identity mismatch".to_string());
    }
    if evidence.slot_id != leaf.slot_id {
        return Err("Path 2 slot id mismatch".to_string());
    }
    if evidence.state_root_before != leaf.account_state_root_before {
        return Err("Path 2 account state root mismatch".to_string());
    }
    if evidence.lifecycle_anchor != leaf.lifecycle_anchor {
        return Err("Path 2 lifecycle anchor mismatch".to_string());
    }
    if path2_account_creation_evidence_transcript_digest(evidence)?
        != leaf.prevalidation_transcript_digest
    {
        return Err("Path 2 prevalidation transcript digest mismatch".to_string());
    }
    Ok(())
}

pub fn verify_path2_prevalidated_slot_creation_payload_bindings(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: Option<&Path2DirectReplayableRelationCertificateV1>,
) -> Result<(), String> {
    verify_path2_prevalidated_slot_creation_frame_bindings(leaf, evidence)?;
    let certificate =
        certificate.ok_or_else(|| "Path 2 evidence payload unavailable".to_string())?;
    if path2_direct_replayable_relation_certificate_digest(certificate)
        != evidence.evidence_payload_digest
    {
        return Err("Path 2 evidence payload digest mismatch".to_string());
    }
    if certificate.account_id != leaf.account_id {
        return Err("Path 2 certificate account id mismatch".to_string());
    }
    if certificate.public_key_identity != leaf.public_key_identity {
        return Err("Path 2 certificate public-key identity mismatch".to_string());
    }
    if certificate.slot_id != leaf.slot_id {
        return Err("Path 2 certificate slot id mismatch".to_string());
    }
    if certificate.verifier_version_digest != leaf.verifier_version_digest {
        return Err("Path 2 certificate verifier version mismatch".to_string());
    }
    if certificate.account_state_root_before != leaf.account_state_root_before {
        return Err("Path 2 certificate account state root mismatch".to_string());
    }
    if certificate.opening_commitment != leaf.opening_commitment {
        return Err("Path 2 certificate opening commitment mismatch".to_string());
    }
    if certificate.pad_seed_digest != leaf.pad_seed_digest {
        return Err("Path 2 certificate pad-seed digest mismatch".to_string());
    }
    if certificate.hidden_source_statement_digest != leaf.hidden_source_statement_digest {
        return Err("Path 2 certificate hidden-source statement mismatch".to_string());
    }
    if certificate.lifecycle_anchor != leaf.lifecycle_anchor {
        return Err("Path 2 certificate lifecycle anchor mismatch".to_string());
    }
    if certificate.relation_transcript_digest != evidence.relation_transcript_digest {
        return Err("Path 2 certificate relation transcript mismatch".to_string());
    }
    Ok(())
}

fn path2_account_creation_frame_kat_digest(label: &str) -> [u8; DIGEST_BYTES] {
    Sha256::digest(format!("Descender.Path2.AccountCreationFrameKat.v1:{label}:0").as_bytes())
        .into()
}

pub fn path2_account_creation_frame_kat_fixture_v1(
) -> Result<Path2AccountCreationFrameKatFixtureV1, String> {
    let mut leaf = Path2PrevalidatedSlotLeafV1 {
        frame_version: PATH2_PREVALIDATED_SLOT_LEAF_FRAME_VERSION,
        profile_version_digest: path2_account_creation_frame_kat_digest("profile"),
        account_id: path2_account_creation_frame_kat_digest("account"),
        public_key_identity: path2_account_creation_frame_kat_digest("public-key"),
        slot_id: 7,
        verifier_version_digest: path2_account_creation_frame_kat_digest("verifier"),
        account_state_root_before: path2_account_creation_frame_kat_digest("state-root-before"),
        opening_commitment: path2_account_creation_frame_kat_digest("opening-commitment"),
        pad_seed_digest: path2_account_creation_frame_kat_digest("pad-seed-digest"),
        hidden_source_statement_digest: path2_account_creation_frame_kat_digest(
            "hidden-source-statement",
        ),
        prevalidation_transcript_digest: [0_u8; DIGEST_BYTES],
        lifecycle_anchor: path2_account_creation_frame_kat_digest("lifecycle-anchor"),
        live_status_marker: PATH2_PREVALIDATED_SLOT_LIVE_STATUS_MARKER,
    };
    let certificate = Path2DirectReplayableRelationCertificateV1 {
        account_id: leaf.account_id,
        public_key_identity: leaf.public_key_identity,
        slot_id: leaf.slot_id,
        verifier_version_digest: leaf.verifier_version_digest,
        account_state_root_before: leaf.account_state_root_before,
        opening_commitment: leaf.opening_commitment,
        pad_seed_digest: leaf.pad_seed_digest,
        hidden_source_statement_digest: leaf.hidden_source_statement_digest,
        reviewed_active_lane_statement_digest: path2_account_creation_frame_kat_digest(
            "reviewed-active-lane-statement",
        ),
        lifecycle_anchor: leaf.lifecycle_anchor,
        relation_transcript_digest: path2_account_creation_frame_kat_digest("relation-transcript"),
        public_replay_payload_digest: path2_account_creation_frame_kat_digest(
            "public-replay-payload",
        ),
    };
    let mut evidence = Path2AccountCreationEvidenceV1 {
        evidence_domain: PATH2_SLOT_PREVALIDATE_SINGLE_DOMAIN,
        evidence_version: 1,
        evidence_kind: PATH2_EVIDENCE_KIND_DIRECT_REPLAYABLE_RELATION_CERTIFICATE,
        slot_leaf_digest: [0_u8; DIGEST_BYTES],
        slot_authorization_digest: [0_u8; DIGEST_BYTES],
        creation_verifier_version_digest: leaf.verifier_version_digest,
        hidden_source_statement_digest: leaf.hidden_source_statement_digest,
        opening_commitment: leaf.opening_commitment,
        pad_seed_digest: leaf.pad_seed_digest,
        account_identity_digest: leaf.account_id,
        public_key_identity: leaf.public_key_identity,
        slot_id: leaf.slot_id,
        state_root_before: leaf.account_state_root_before,
        lifecycle_anchor: leaf.lifecycle_anchor,
        relation_transcript_digest: certificate.relation_transcript_digest,
        evidence_payload_digest: path2_direct_replayable_relation_certificate_digest(&certificate),
    };
    leaf.prevalidation_transcript_digest =
        path2_account_creation_evidence_transcript_digest(&evidence)?;
    evidence.slot_leaf_digest = path2_prevalidated_slot_leaf_digest(&leaf)?;
    evidence.slot_authorization_digest = path2_slot_authorization_digest(&leaf)?;
    let leaf_digest = evidence.slot_leaf_digest;
    let slot_authorization_digest = evidence.slot_authorization_digest;
    let evidence_transcript_digest = leaf.prevalidation_transcript_digest;
    let certificate_digest = evidence.evidence_payload_digest;
    verify_path2_prevalidated_slot_creation_payload_bindings(&leaf, &evidence, Some(&certificate))?;
    Ok(Path2AccountCreationFrameKatFixtureV1 {
        fixture_id: "Path2AccountCreationFrameKatFixture.v1",
        leaf,
        evidence,
        certificate,
        leaf_digest,
        slot_authorization_digest,
        evidence_transcript_digest,
        certificate_digest,
    })
}

pub fn verify_path2_prevalidated_slot_admission_namespace(
    leaves: &[Path2PrevalidatedSlotLeafV1],
) -> Result<(), String> {
    let mut account_slots = BTreeSet::new();
    let mut pad_seed_digests = BTreeSet::new();
    for leaf in leaves {
        path2_prevalidated_slot_leaf_v1_bytes(leaf)?;
        if !account_slots.insert((leaf.account_id, leaf.slot_id)) {
            return Err("Path 2 duplicate account slot admission".to_string());
        }
        if !pad_seed_digests.insert(leaf.pad_seed_digest) {
            return Err("Path 2 duplicate pad-seed digest admission".to_string());
        }
    }
    Ok(())
}

pub fn verify_path2_prevalidated_slot_consume_once(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    consumed_authorizations: &mut BTreeSet<[u8; DIGEST_BYTES]>,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    let authorization = path2_slot_authorization_digest(leaf)?;
    if !consumed_authorizations.insert(authorization) {
        return Err("Path 2 slot authorization already consumed".to_string());
    }
    Ok(authorization)
}

pub fn verify_path2_prevalidated_slot_creation_relation_replay(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    signature_with_carrier: &ProductionSignature,
    opening: &ProductionReviewedFq12StateAssistedOpening,
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
) -> Result<(), ProductionAccountBindingError> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))
        .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let public_key_identity: [u8; DIGEST_BYTES] = Sha256::digest(public_key.as_bytes()).into();
    if leaf.public_key_identity != public_key_identity {
        return Err(ProductionAccountBindingError::new(
            None,
            "Path 2 relation replay public-key identity mismatch",
        ));
    }
    let reviewed_certificate =
        verify_reviewed_fq12_state_assisted_masked_projection_soundness_certificate(
            public_key,
            message,
            account,
            signature_with_carrier,
            opening,
            statement,
            pad_seed,
        )?;
    let creation_statement =
        path2_creation_hidden_source_statement_v1_from_reviewed(leaf, statement);
    if creation_statement.digest != leaf.hidden_source_statement_digest {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 creation statement digest mismatch",
        ));
    }
    if reviewed_certificate.slot_id as u64 != leaf.slot_id {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 relation replay slot id mismatch",
        ));
    }
    if reviewed_certificate.statement_digest != certificate.reviewed_active_lane_statement_digest {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 relation replay reviewed statement digest mismatch",
        ));
    }
    if reviewed_certificate.opening_commitment != leaf.opening_commitment {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 relation replay opening commitment mismatch",
        ));
    }
    if reviewed_certificate.pad_seed_digest != leaf.pad_seed_digest {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 relation replay pad-seed digest mismatch",
        ));
    }
    Ok(())
}

fn verify_path2_direct_creation_proof_payload_common(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
) -> Result<(), String> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    if binding.schema != PATH2_CREATION_PROOF_BINDING_SCHEMA {
        return Err("Path 2 creation proof binding schema mismatch".to_string());
    }
    if binding.proof_binding_version != 1 {
        return Err("Path 2 creation proof binding version mismatch".to_string());
    }
    if binding.digest != path2_creation_proof_binding_v1_digest(binding) {
        return Err("Path 2 creation proof binding digest mismatch".to_string());
    }
    if binding.account_id != leaf.account_id
        || binding.public_key_identity != leaf.public_key_identity
        || binding.slot_id != leaf.slot_id
        || binding.verifier_version_digest != leaf.verifier_version_digest
        || binding.account_state_root_before != leaf.account_state_root_before
        || binding.lifecycle_anchor != leaf.lifecycle_anchor
        || binding.opening_tuple_commitment != leaf.opening_commitment
        || binding.creation_statement_digest != leaf.hidden_source_statement_digest
    {
        return Err("Path 2 creation proof binding leaf context mismatch".to_string());
    }
    if payload.schema != PATH2_DIRECT_CREATION_PROOF_PAYLOAD_SCHEMA {
        return Err("Path 2 direct creation proof payload schema mismatch".to_string());
    }
    if payload.payload_version != 1 {
        return Err("Path 2 direct creation proof payload version mismatch".to_string());
    }
    if payload.proof_binding_digest != binding.digest {
        return Err("Path 2 direct creation proof binding digest mismatch".to_string());
    }
    if payload.hidden_source_statement_digest != leaf.hidden_source_statement_digest {
        return Err("Path 2 direct creation proof statement mismatch".to_string());
    }
    if payload.relation_transcript_digest != certificate.relation_transcript_digest {
        return Err("Path 2 direct creation proof transcript mismatch".to_string());
    }
    if payload.payload_digest != certificate.public_replay_payload_digest {
        return Err("Path 2 direct creation proof payload digest mismatch".to_string());
    }
    if payload.proof_kind != PATH2_DIRECT_CREATION_PROOF_KIND_TRANSPARENT_DESCENT
        && payload.proof_family_public_binding_digest != [0_u8; DIGEST_BYTES]
    {
        return Err(
            "Path 2 direct creation proof family public binding digest mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn verify_path2_direct_creation_proof_payload_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
) -> Result<(), String> {
    verify_path2_direct_creation_proof_payload_common(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
    )?;
    if payload.proof_kind == PATH2_DIRECT_CREATION_PROOF_KIND_UNINSTANTIATED {
        return Err("Path 2 direct creation proof payload verifier is not implemented".to_string());
    }
    if payload.proof_kind == PATH2_DIRECT_CREATION_PROOF_KIND_TRANSPARENT_DESCENT {
        return Err("Path 2 transparent descent proof verifier is not implemented".to_string());
    }
    if payload.proof_kind == PATH2_DIRECT_CREATION_PROOF_KIND_MASKED_STATE18 {
        return Err(PATH2_MASKED_STATE18_PUBLIC_PROOF_DISABLED_ERROR.to_string());
    }
    Err("Path 2 direct creation proof payload kind is unsupported".to_string())
}

/// Proof-carrying dispatcher for the historical masked-state18 public proof.
///
/// The proof carries `pad_seed` in clear, so this public verifier is intentionally hard-disabled.
/// The internal relation checker remains available only for fixtures and red-team regression tests.
pub fn verify_path2_direct_creation_proof_payload_with_masked_state18_proof_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    proof: &Path2MaskedState18CreationProofV1,
) -> Result<(), String> {
    verify_path2_direct_creation_masked_state18_proof_v1(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
        proof,
    )
}

/// Public verifier for the historical masked-state18 proof. It is hard-disabled because the proof
/// serializes `pad_seed` in clear.
pub fn verify_path2_direct_creation_masked_state18_proof_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    _proof: &Path2MaskedState18CreationProofV1,
) -> Result<(), String> {
    verify_path2_direct_creation_proof_payload_common(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
    )?;
    if payload.proof_kind != PATH2_DIRECT_CREATION_PROOF_KIND_MASKED_STATE18 {
        return Err("Path 2 masked-state18 payload kind mismatch".to_string());
    }
    Err(PATH2_MASKED_STATE18_PUBLIC_PROOF_DISABLED_ERROR.to_string())
}

/// Internal debug verifier for the historical masked-state18 relation.
///
/// Equivalence target: this accepts `(leaf, evidence, certificate, binding, payload, proof)` IFF the
/// harness-replay relation (`verify_path2_prevalidated_slot_creation_relation_replay`) would accept
/// the same creation evidence. It is deliberately not the public verifier because the proof carries
/// `pad_seed` in clear and is non-hiding.
///
/// Retained for masked-state18 negative-control regression tests; normal library
/// builds keep the public verifier hard-disabled, so this debug relation is only
/// called from test modules.
#[allow(dead_code)]
fn verify_path2_direct_creation_masked_state18_proof_debug_relation_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    proof: &Path2MaskedState18CreationProofV1,
) -> Result<(), String> {
    // 1. All frame / leaf-context / certificate-digest / payload-digest bindings (shared with the
    //    bindings-only dispatcher), plus the kind check.
    verify_path2_direct_creation_proof_payload_common(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
    )?;
    if payload.proof_kind != PATH2_DIRECT_CREATION_PROOF_KIND_MASKED_STATE18 {
        return Err("Path 2 masked-state18 payload kind mismatch".to_string());
    }

    // 2. Bind the revealed pad_seed to the leaf's pad_seed_digest. The harness-replay path holds the
    //    pad_seed as a hidden input and binds it the same way; binding it here is the data-availability
    //    step that makes the relation checkable from public data.
    if reviewed_fq12_pad_seed_opening_digest(&proof.pad_seed) != leaf.pad_seed_digest {
        return Err("Path 2 masked-state18 pad-seed digest mismatch".to_string());
    }

    // 3. Replay the HARNESS's own masked-state18 packed-witness opening derivation over the leaf-fixed
    //    packed_witness_commitment. This is byte-for-byte the relation the harness enforces:
    //    - derive masked_projection from the commitment residues,
    //    - subtract the PRF(pad_seed, slot_id) masks to obtain account_projection,
    //    - repack and assert repacked == commitment (fail-closed at the opening function).
    let opening = reviewed_fq12_masked_state18_packed_witness_opening(
        &binding.packed_witness_commitment,
        &proof.pad_seed,
        leaf.slot_id,
    )
    .map_err(|err| format!("Path 2 masked-state18 opening: {err}"))?;

    // 4. The relation-derived account_projection must equal the public claim, per lane.
    if opening.account_projection != proof.account_projection {
        return Err("Path 2 masked-state18 account projection relation mismatch".to_string());
    }

    // 5. Real (non-toy) SHA-256 commitment de-toy: the binding's pad-source commitment binds the
    //    masked_projection lanes and the projection-relation commitment binds the relation-derived
    //    account_projection lanes, both via the real SHA-256/masked_state18 commitment scheme.
    let expected_pad_source = path2_masked_state18_commitment_bytes(
        PATH2_MASKED_STATE18_COMMITMENT_ROLE_PAD_SOURCE,
        &opening.masked_projection,
    )?;
    if binding.pad_source_commitment != expected_pad_source {
        return Err("Path 2 masked-state18 pad-source commitment mismatch".to_string());
    }
    let expected_projection = path2_masked_state18_commitment_bytes(
        PATH2_MASKED_STATE18_COMMITMENT_ROLE_PROJECTION_RELATION,
        &opening.account_projection,
    )?;
    if binding.projection_relation_commitment != expected_projection {
        return Err("Path 2 masked-state18 projection commitment mismatch".to_string());
    }

    // 6. Per-lane mask consistency, asserting the masked_projection (committed in the pad-source role)
    //    and account_projection (committed in the projection-relation role) satisfy the same
    //    masked-projection equation `masked == account + mask (mod q)` the harness pack enforces.
    let masks =
        reviewed_fq12_packed_witness_state18_projection_masks(&proof.pad_seed, leaf.slot_id);
    for lane in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        let recomputed_masked =
            ((opening.account_projection[lane] as u32 + masks[lane] as u32) % Q as u32) as u16;
        if recomputed_masked != opening.masked_projection[lane] {
            return Err("Path 2 masked-state18 masked-projection relation mismatch".to_string());
        }
    }

    Ok(())
}

pub fn verify_path2_direct_creation_transparent_descent_payload_boundary(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    transparent_payload: &Path2TransparentDescentProofPayloadV1,
) -> Result<(), String> {
    verify_path2_direct_creation_transparent_descent_selected_view_bridge(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
        transparent_payload,
    )?;
    Err("Path 2 transparent descent proof verifier is not implemented".to_string())
}

pub(crate) fn verify_path2_direct_creation_transparent_descent_selected_view_bridge(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    transparent_payload: &Path2TransparentDescentProofPayloadV1,
) -> Result<(), String> {
    verify_path2_direct_creation_proof_payload_common(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
    )?;
    if payload.proof_kind != PATH2_DIRECT_CREATION_PROOF_KIND_TRANSPARENT_DESCENT {
        return Err("Path 2 transparent descent payload kind mismatch".to_string());
    }
    if payload.proof_system_id != path2_transparent_descent_proof_system_id() {
        return Err("Path 2 transparent descent proof system mismatch".to_string());
    }
    let interface = path2_native_boundary_trace_proof_family_interface_v1()?;
    if transparent_payload.payload_digest != payload.payload_digest
        || transparent_payload.payload_byte_len != payload.payload_byte_len
    {
        return Err("Path 2 transparent descent payload header mismatch".to_string());
    }
    let view = &transparent_payload.public_view;
    verify_path2_transparent_descent_public_view(view)?;
    let public_view_digest = path2_transparent_descent_public_view_digest(view)?;
    if transparent_payload.public_view_digest == [0_u8; DIGEST_BYTES] {
        return Err("Path 2 transparent descent public view digest is zero".to_string());
    }
    if transparent_payload.public_view_digest != public_view_digest {
        return Err("Path 2 transparent descent public view digest mismatch".to_string());
    }
    if transparent_payload.creation_proof_binding_digest != view.creation_proof_binding_digest
        || transparent_payload.transparent_transcript_digest != view.transparent_transcript_digest
        || transparent_payload.native_role_root_commitment != view.native_role_root_commitment
        || transparent_payload.masked_projection_digest != digest_u16_slice(&view.masked_projection)
        || transparent_payload.trace_binding_context_digest
            != path2_transparent_trace_binding_context_digest_for_public_view(view)
        || transparent_payload.trace_rows != view.trace_rows
        || transparent_payload.query_count != view.query_count
        || transparent_payload.query_index != view.query_index
    {
        return Err("Path 2 transparent descent public view anchor mismatch".to_string());
    }
    for (label, digest) in [
        (
            "transparent transcript digest",
            transparent_payload.transparent_transcript_digest,
        ),
        (
            "creation binding digest",
            transparent_payload.creation_proof_binding_digest,
        ),
        (
            "native role root commitment",
            transparent_payload.native_role_root_commitment,
        ),
        (
            "masked projection digest",
            transparent_payload.masked_projection_digest,
        ),
        (
            "trace binding context digest",
            transparent_payload.trace_binding_context_digest,
        ),
    ] {
        if digest == [0_u8; DIGEST_BYTES] {
            return Err(format!(
                "Path 2 transparent descent public view {label} is zero"
            ));
        }
    }
    verify_path2_two_view_column_profile_id(view.column_profile)?;
    verify_path2_transparent_query_schedule_pair(view.trace_rows, view.query_count)?;
    if view.column_profile != interface.column_profile
        || interface.norm_range_mode != PATH2_NATIVE_BOUNDARY_TRACE_RANGE_HYBRID_BASE128
        || interface.blinding_noise_policy_id
            != PATH2_NATIVE_BOUNDARY_TRACE_BLINDING_NOISE_POLICY_ID
        || !interface.lean_account_admission_adapter_endpoint_present
    {
        return Err("Path 2 transparent descent selected view bridge mismatch".to_string());
    }
    if view.creation_proof_binding_digest != binding.digest {
        return Err("Path 2 transparent descent binding digest mismatch".to_string());
    }
    if view.native_role_root_commitment != binding.native_role_root_commitment {
        return Err("Path 2 transparent descent native role root mismatch".to_string());
    }
    if view.leaf_context_digest
        != path2_prevalidated_slot_leaf_context_digest(leaf, evidence, certificate)?
    {
        return Err("Path 2 transparent descent leaf context mismatch".to_string());
    }
    if view.aggregation_context_digest != binding.aggregation_context_digest {
        return Err("Path 2 transparent descent aggregation context mismatch".to_string());
    }
    path2_transparent_commitment_api_v1(view, binding)?;
    let expected_statement_bridge_digest =
        path2_transparent_direct_payload_statement_bridge_digest_v1(certificate, binding, view)?;
    if transparent_payload.direct_payload_statement_bridge_digest
        != expected_statement_bridge_digest
    {
        return Err(
            "Path 2 transparent descent direct payload statement bridge mismatch".to_string(),
        );
    }
    let expected_payload_digest = path2_transparent_descent_proof_payload_digest(
        view,
        transparent_payload.payload_byte_len,
        &transparent_payload.direct_payload_statement_bridge_digest,
        &transparent_payload.proof_bytes_digest,
        &transparent_payload.full_hidden_relation_subproof_digest,
        &transparent_payload.local_trace_binding_proof_digest,
        &transparent_payload.hidden_relation_witness_check_digest,
        &transparent_payload.trace_origin_witness_check_digest,
        &transparent_payload.proof_friendly_role_commitment_verifier_digest,
        &transparent_payload.query_openings_digest,
        &transparent_payload.merkle_paths_digest,
        &transparent_payload.consistency_messages_digest,
    )?;
    if transparent_payload.payload_digest != expected_payload_digest {
        return Err("Path 2 transparent descent payload digest mismatch".to_string());
    }
    let expected_bridge_digest =
        path2_transparent_descent_public_bridge_binding_digest(transparent_payload)?;
    if payload.proof_family_public_binding_digest != expected_bridge_digest {
        return Err(
            "Path 2 transparent descent proof family public binding digest mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    transparent_payload: &Path2TransparentDescentProofPayloadV1,
    query_opening_manifest: &Path2TransparentQueryOpeningManifestV1,
) -> Result<(), String> {
    match verify_path2_direct_creation_transparent_descent_payload_boundary(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
        transparent_payload,
    ) {
        Err(err) if err == "Path 2 transparent descent proof verifier is not implemented" => {}
        result => return result,
    }
    let view = &transparent_payload.public_view;
    verify_path2_transparent_query_opening_manifest_for_public_view(view, query_opening_manifest)?;
    if path2_transparent_query_opening_manifest_digest(query_opening_manifest)?
        != transparent_payload.query_openings_digest
    {
        return Err(
            "Path 2 transparent descent query opening manifest digest mismatch".to_string(),
        );
    }
    Err("Path 2 transparent descent proof verifier is not implemented".to_string())
}

pub fn verify_path2_direct_creation_transparent_descent_payload_boundary_with_proof_bytes(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    transparent_payload: &Path2TransparentDescentProofPayloadV1,
    query_opening_manifest: &Path2TransparentQueryOpeningManifestV1,
    proof_bytes: &[u8],
) -> Result<(), String> {
    match verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
        transparent_payload,
        query_opening_manifest,
    ) {
        Err(err) if err == "Path 2 transparent descent proof verifier is not implemented" => {}
        result => return result,
    }
    let proof_bytes_digest = path2_transparent_proof_bytes_digest(proof_bytes)?;
    if proof_bytes_digest != transparent_payload.proof_bytes_digest {
        return Err("Path 2 transparent descent proof bytes digest mismatch".to_string());
    }
    if transparent_payload.payload_byte_len != proof_bytes.len() as u64 {
        return Err("Path 2 transparent descent proof bytes length mismatch".to_string());
    }
    let proof_bytes_envelope = decode_path2_transparent_proof_bytes_envelope_v1(proof_bytes)?;
    if proof_bytes_envelope.full_hidden_relation_subproof_digest == [0_u8; DIGEST_BYTES] {
        return Err(
            "Path 2 transparent descent full hidden relation subproof digest is zero".to_string(),
        );
    }
    if proof_bytes_envelope.full_hidden_relation_subproof_digest
        != transparent_payload.full_hidden_relation_subproof_digest
    {
        return Err(
            "Path 2 transparent descent full hidden relation subproof digest mismatch".to_string(),
        );
    }
    if proof_bytes_envelope.local_trace_binding_proof_digest
        != transparent_payload.local_trace_binding_proof_digest
        || proof_bytes_envelope.hidden_relation_witness_check_digest
            != transparent_payload.hidden_relation_witness_check_digest
        || proof_bytes_envelope.trace_origin_witness_check_digest
            != transparent_payload.trace_origin_witness_check_digest
    {
        return Err(
            "Path 2 transparent descent local trace-binding proof digest mismatch".to_string(),
        );
    }
    if proof_bytes_envelope.proof_friendly_role_commitment_verifier_digest
        != transparent_payload.proof_friendly_role_commitment_verifier_digest
    {
        return Err(
            "Path 2 transparent descent proof-friendly role-commitment verifier digest mismatch"
                .to_string(),
        );
    }
    if proof_bytes_envelope.direct_payload_statement_bridge_digest
        != transparent_payload.direct_payload_statement_bridge_digest
    {
        return Err(
            "Path 2 transparent descent direct payload statement bridge mismatch".to_string(),
        );
    }
    let body_start = proof_bytes.len() - proof_bytes_envelope.proof_body_byte_len as usize;
    let suite_body = path2_transparent_zk_decode_proof_suite_body(&proof_bytes[body_start..])?;
    let full_hidden_envelope = decode_path2_transparent_full_hidden_relation_subproof_envelope_v1(
        &suite_body.full_hidden_relation_subproof,
    )?;
    if full_hidden_envelope.direct_payload_statement_bridge_digest
        != transparent_payload.direct_payload_statement_bridge_digest
    {
        return Err(
            "Path 2 transparent descent direct payload statement bridge mismatch".to_string(),
        );
    }
    if full_hidden_envelope.proof_friendly_role_commitment_verifier_digest
        != transparent_payload.proof_friendly_role_commitment_verifier_digest
    {
        return Err(
            "Path 2 transparent descent proof-friendly role-commitment verifier digest mismatch"
                .to_string(),
        );
    }
    let full_hidden_relation_public_inputs =
        path2_transparent_full_hidden_relation_public_inputs_v1(
            leaf,
            evidence,
            certificate,
            binding,
            &transparent_payload.public_view,
            transparent_payload.direct_payload_statement_bridge_digest,
        )?;
    verify_path2_transparent_proof_suite_envelope_with_full_hidden_public_shape_v1(
        &transparent_payload.public_view,
        query_opening_manifest,
        &transparent_payload.merkle_paths_digest,
        &transparent_payload.consistency_messages_digest,
        proof_bytes,
    )?;
    // STEP 6 fail-closed: run the incomplete transparent-descent opening core
    // first, so malformed transcripts fail at their real parse/Merkle/FRI/row
    // check. If that core would accept, require the named full-hidden-relation
    // subproof backend against the canonical public-input statement.
    path2_transparent_descent_verify_zk_opening_debug_incomplete_relation_v1(
        &transparent_payload.public_view,
        query_opening_manifest,
        proof_bytes,
    )?;
    verify_path2_transparent_proof_suite_full_hidden_relation_binding_v1(
        &full_hidden_relation_public_inputs,
        proof_bytes,
    )
}

/// The pinned RAW verifier version the account-creation STARK statement binds
/// in-circuit (`AccountCreationPublic::verifier_version`). The deployed leaf
/// carries only `verifier_version_digest`, so this raw value is the canonical
/// source on BOTH the producer and verify sides — keep them equal.
pub const PATH2_ACCOUNT_STARK_VERIFIER_VERSION: u32 = 1;
pub const PATH2_ACCOUNT_STARK_CREATION_PAYLOAD_SCHEMA: &str =
    "DESCENDER_PATH2_ACCOUNT_STARK_CREATION_PAYLOAD_V1";

/// Self-contained admission payload for the SOUND account-creation ZK-STARK path
/// (the replacement for the transparent-descent / HIGH-2 in-clear-blind backend).
/// Plain data only (NO Plonky3 types) so it can be transported/serialized without
/// the `account-creation-stark-verifier` feature; `account_stark_bundle` is the
/// opaque `descender-account-verifier` `(AccountCreationPublic, Proof)` blob,
/// inspected ONLY under the feature.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Path2AccountStarkCreationPayloadV1 {
    pub leaf_context_digest: [u8; DIGEST_BYTES],
    pub creation_proof_binding_digest: [u8; DIGEST_BYTES],
    /// `= descender_account_verifier::role_root_export_digest(&public.role_root)`
    /// (the named verifier-exporter bridge). Set by the producer; enforced by the
    /// verify boundary against the proven role root.
    pub native_role_root_commitment: [u8; DIGEST_BYTES],
    pub aggregation_context_digest: [u8; DIGEST_BYTES],
    pub slot_id: u64,
    pub masked_projection: [u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
    pub account_stark_bundle: Vec<u8>,
}

pub fn path2_account_stark_creation_payload_v1_frame(
    payload: &Path2AccountStarkCreationPayloadV1,
) -> Result<Vec<u8>, String> {
    if payload.account_stark_bundle.is_empty() {
        return Err("account-creation STARK: payload bundle is empty".to_string());
    }
    let mut masked_projection_bytes =
        Vec::with_capacity(payload.masked_projection.len() * core::mem::size_of::<u16>());
    for lane in payload.masked_projection {
        masked_projection_bytes.extend_from_slice(&lane.to_le_bytes());
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_ACCOUNT_STARK_CREATION_PAYLOAD_SCHEMA.as_bytes(),
    );
    append_u64(&mut frame, b"payload_version", 1);
    append_u64(
        &mut frame,
        b"account_stark_verifier_version",
        PATH2_ACCOUNT_STARK_VERIFIER_VERSION as u64,
    );
    append_frame(
        &mut frame,
        b"leaf_context_digest",
        &payload.leaf_context_digest,
    );
    append_frame(
        &mut frame,
        b"creation_proof_binding_digest",
        &payload.creation_proof_binding_digest,
    );
    append_frame(
        &mut frame,
        b"native_role_root_commitment",
        &payload.native_role_root_commitment,
    );
    append_frame(
        &mut frame,
        b"aggregation_context_digest",
        &payload.aggregation_context_digest,
    );
    append_u64(&mut frame, b"slot_id", payload.slot_id);
    append_u64(
        &mut frame,
        b"masked_projection_lane_count",
        payload.masked_projection.len() as u64,
    );
    append_frame(
        &mut frame,
        b"masked_projection_le",
        &masked_projection_bytes,
    );
    append_frame(
        &mut frame,
        b"account_stark_bundle",
        &payload.account_stark_bundle,
    );
    Ok(frame)
}

pub fn path2_account_stark_creation_payload_v1_digest(
    payload: &Path2AccountStarkCreationPayloadV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(path2_account_stark_creation_payload_v1_frame(payload)?).into())
}

/// Fixed proof-randomness seed for account-STARK payload KAT generation only.
/// Deployment producers must use [`path2_account_stark_prove_creation_v1`].
#[cfg(feature = "account-creation-stark-verifier")]
pub const PATH2_ACCOUNT_STARK_PAYLOAD_KAT_MASK_SEED_V1: u64 = 0x4445_5343_5f4b_4154;

#[cfg(feature = "account-creation-stark-verifier")]
fn path2_account_stark_prove_creation_with_mask_seed_option_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    blinding_seed: &[u8; DIGEST_BYTES],
    proof_mask_seed: Option<u64>,
) -> Result<Path2AccountStarkCreationPayloadV1, String> {
    // Recover the account witness (raw projection + checked-core syndrome) from the
    // deployed opening; its projection masks come from the SAME Poseidon2 PRF the
    // STARK uses in-circuit, so the masked projections will agree.
    let opening = reviewed_fq12_masked_state18_packed_witness_opening(
        &binding.packed_witness_commitment,
        pad_seed,
        leaf.slot_id,
    )?;

    // Commitment blinding nonces for the STARK's OWN C1/C6 commitments (independent
    // of the deployed commitment scheme): derive deterministically from the
    // blinding seed, domain-separated.
    let mut h1 = Sha256::new();
    h1.update(b"DESCENDER_ACCOUNT_STARK_C1_NONCE_V1");
    h1.update(blinding_seed);
    let c1_full: [u8; 32] = h1.finalize().into();
    let mut h6 = Sha256::new();
    h6.update(b"DESCENDER_ACCOUNT_STARK_C6_NONCE_V1");
    h6.update(blinding_seed);
    let c6_full: [u8; 32] = h6.finalize().into();
    let mut c1_nonce = [0u8; 16];
    let mut c6_nonce = [0u8; 16];
    c1_nonce.copy_from_slice(&c1_full[..16]);
    c6_nonce.copy_from_slice(&c6_full[..16]);

    let secrets = descender_account_verifier::AccountCreationSecrets {
        pad_seed: *pad_seed,
        slot_id: leaf.slot_id,
        account_projection: opening.account_projection,
        lifecycle_anchor: leaf.lifecycle_anchor,
        c1_nonce,
        c6_nonce,
        account_id: leaf.account_id,
        verifier_version: PATH2_ACCOUNT_STARK_VERIFIER_VERSION,
        account_state_root: leaf.account_state_root_before,
        syndrome: opening.witness_syndrome,
        checked_core_key_commitment: pack_reviewed_fq12_account_carried_syndrome_digest(
            &opening.witness_syndrome,
        )?,
    };

    let (public, proof) = match proof_mask_seed {
        Some(seed) => descender_account_verifier::prove_account_creation_with_seed(&secrets, seed),
        None => descender_account_verifier::prove_account_creation(&secrets),
    }
    .map_err(|e| format!("account-creation STARK prove failed: {e}"))?;
    let account_stark_bundle = descender_account_verifier::pack_bundle(&public, &proof)
        .map_err(|e| format!("account-creation STARK bundle pack failed: {e}"))?;
    let native_role_root_commitment =
        descender_account_verifier::role_root_export_digest(&public.role_root);

    // The proven masked projection equals the deployed opening's (same Poseidon2
    // masks via the mask-PRF swap + same canonical mod-q reduction); use the
    // already-`u16` deployed value so no Plonky3 field type is handled here. The
    // verify boundary binds this against the proven `public.masked_projection`.
    let masked_projection = opening.masked_projection;

    Ok(Path2AccountStarkCreationPayloadV1 {
        leaf_context_digest: path2_prevalidated_slot_leaf_context_digest(
            leaf,
            evidence,
            certificate,
        )?,
        creation_proof_binding_digest: binding.digest,
        native_role_root_commitment,
        aggregation_context_digest: binding.aggregation_context_digest,
        slot_id: leaf.slot_id,
        masked_projection,
        account_stark_bundle,
    })
}

/// FEATURE-GATED (`account-creation-stark-verifier`) PRODUCER — generates the
/// sound account-creation ZK-STARK proof and packs the admission payload. This is
/// the producer counterpart of
/// [`verify_path2_direct_creation_account_stark_payload_boundary`]; together they
/// replace the transparent-descent full-hidden-relation backend (the HIGH-2 leak
/// path) for the live admission flow. The deployed projection masks and the STARK
/// in-circuit masks are byte-identical (the mask-PRF swap), so the proven
/// `masked_projection` equals the deployed opening's. This deployment producer
/// uses fresh proof randomness through `descender-account-stark`.
#[cfg(feature = "account-creation-stark-verifier")]
pub fn path2_account_stark_prove_creation_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    blinding_seed: &[u8; DIGEST_BYTES],
) -> Result<Path2AccountStarkCreationPayloadV1, String> {
    path2_account_stark_prove_creation_with_mask_seed_option_v1(
        leaf,
        evidence,
        certificate,
        binding,
        pad_seed,
        blinding_seed,
        None,
    )
}

/// FEATURE-GATED deterministic KAT producer. This exists only to give the active
/// account-STARK payload boundary a fixed proof-randomness seed; serialized
/// proof-byte KATs must also run under deterministic proof-of-work witness
/// selection. The checked vector generator does that with a single-thread Rayon
/// pool. This function must not be used as the deployment producer because a
/// fixed mask seed removes proof-randomness freshness.
#[cfg(feature = "account-creation-stark-verifier")]
pub fn path2_account_stark_prove_creation_with_mask_seed_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    blinding_seed: &[u8; DIGEST_BYTES],
    proof_mask_seed: u64,
) -> Result<Path2AccountStarkCreationPayloadV1, String> {
    path2_account_stark_prove_creation_with_mask_seed_option_v1(
        leaf,
        evidence,
        certificate,
        binding,
        pad_seed,
        blinding_seed,
        Some(proof_mask_seed),
    )
}

/// FEATURE-GATED (`account-creation-stark-verifier`) — the SOUND replacement for
/// the transparent-descent full-hidden-relation backend (the HIGH-2 in-clear-blind
/// path the red-team broke). Runs the Plonky3 ZK-STARK relation verifier on the
/// payload's bundle and binds the verified statement to THIS deployed leaf.
///
/// Plonky3 enters the deployed crate ONLY through `descender-account-verifier` and
/// ONLY under this feature; the default signer build never links it.
///
/// Bindings: the payload is tied to this leaf's context digest, the creation-proof
/// binding digest, the aggregation context, and the slot; the STARK statement is
/// then bound (by `descender-account-verifier`) to account_id / slot_id /
/// state_root / lifecycle / verifier_version / masked_projection and — via the
/// named export bridge — the role-root commitment.
#[cfg(feature = "account-creation-stark-verifier")]
pub fn verify_path2_direct_creation_account_stark_payload_boundary(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2AccountStarkCreationPayloadV1,
) -> Result<(), String> {
    // --- standard deployed-frame bindings (parity with the other creation paths) ---
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    if binding.digest != path2_creation_proof_binding_v1_digest(binding) {
        return Err("account-creation STARK: binding digest is noncanonical".to_string());
    }
    if binding.account_id != leaf.account_id
        || binding.public_key_identity != leaf.public_key_identity
        || binding.slot_id != leaf.slot_id
        || binding.verifier_version_digest != leaf.verifier_version_digest
        || binding.account_state_root_before != leaf.account_state_root_before
        || binding.lifecycle_anchor != leaf.lifecycle_anchor
        || binding.opening_tuple_commitment != leaf.opening_commitment
        || binding.creation_statement_digest != leaf.hidden_source_statement_digest
    {
        return Err("account-creation STARK: binding leaf context mismatch".to_string());
    }
    // --- payload ↔ leaf bindings (proof-family-agnostic) ---
    if payload.leaf_context_digest
        != path2_prevalidated_slot_leaf_context_digest(leaf, evidence, certificate)?
    {
        return Err("account-creation STARK: payload leaf context mismatch".to_string());
    }
    if payload.creation_proof_binding_digest != binding.digest {
        return Err("account-creation STARK: creation proof binding digest mismatch".to_string());
    }
    if payload.aggregation_context_digest != binding.aggregation_context_digest {
        return Err("account-creation STARK: aggregation context mismatch".to_string());
    }
    if payload.slot_id != leaf.slot_id {
        return Err("account-creation STARK: slot id mismatch".to_string());
    }
    if path2_account_stark_creation_payload_v1_digest(payload)?
        != certificate.public_replay_payload_digest
    {
        return Err("account-creation STARK: payload digest mismatch".to_string());
    }
    // --- plain anchors (NO Plonky3 types cross this boundary) ---
    let anchors = descender_account_verifier::DeployedCreationAnchors {
        account_id: leaf.account_id,
        slot_id: leaf.slot_id,
        account_state_root: leaf.account_state_root_before,
        lifecycle_anchor: leaf.lifecycle_anchor,
        verifier_version: PATH2_ACCOUNT_STARK_VERIFIER_VERSION,
        masked_projection: payload.masked_projection,
        native_role_root_commitment: payload.native_role_root_commitment,
        // CLASS C / MED-2: pin the proven packed witness to the deployed binding's,
        // tying the creation proof's syndrome + masked_projection to the exact
        // packed witness the spend's checked-core frame consumes.
        packed_witness_commitment: binding.packed_witness_commitment,
    };
    // --- the sound STARK relation verify + statement↔anchor binding ---
    descender_account_verifier::verify_deployed_account_creation(
        &payload.account_stark_bundle,
        &anchors,
    )
    .map_err(|e| format!("account-creation STARK verify failed: {e}"))
}

/// FAIL-CLOSED production gate for the account-creation STARK path. Returns
/// `false` until external review + James's sign-off (the Step #8 gate flip, which
/// is NOT autonomous — see SECURITY_DOSSIER D3). Do NOT flip this unilaterally.
pub const fn path2_account_stark_production_verification_enabled() -> bool {
    false
}

/// FEATURE-GATED production entry for the sound account-creation STARK path:
/// the full boundary verify, then the fail-closed production gate. Mirrors
/// `..._with_proof_bytes_for_production` for the transparent-descent path. While
/// the gate is closed this ALWAYS errs after a successful verify — production stays
/// fail-closed until external review.
#[cfg(feature = "account-creation-stark-verifier")]
pub fn verify_path2_direct_creation_account_stark_payload_boundary_for_production(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2AccountStarkCreationPayloadV1,
) -> Result<(), String> {
    verify_path2_direct_creation_account_stark_payload_boundary(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
    )?;
    if !path2_account_stark_production_verification_enabled() {
        return Err(
            "account-creation STARK production verification is fail-closed (external-review-gated)"
                .to_string(),
        );
    }
    Ok(())
}

