fn path2_account_creation_referenced_obligations_accounted_v1(
    proof_report: &Path2AccountCreationProofBoundaryReportV1,
    obligation_ids: &[&str],
) -> bool {
    !obligation_ids.is_empty()
        && obligation_ids.iter().all(|obligation_id| {
            proof_report.proof_obligation_rows.iter().any(|row| {
                row.obligation_id == *obligation_id
                    && (row.open
                        || (!row.open
                            && row.obligation_id
                                == "creation_proof_obligation_frozen_payload_kats"))
            })
        })
}

fn path2_account_creation_referenced_obligations_have_open_residual_v1(
    proof_report: &Path2AccountCreationProofBoundaryReportV1,
    obligation_ids: &[&str],
) -> bool {
    obligation_ids.iter().any(|obligation_id| {
        proof_report
            .proof_obligation_rows
            .iter()
            .any(|row| row.obligation_id == *obligation_id && row.open)
    })
}

fn path2_account_creation_accepted_requirement_evidence_rows_v1(
    evidence: &Path2AccountCreationAcceptedProofBoundaryEvidenceV1,
    proof_report: &Path2AccountCreationProofBoundaryReportV1,
) -> Vec<Path2AccountCreationAcceptedRequirementEvidenceRowV1> {
    let row = |requirement: &'static str,
               closure_obligation_ids: &'static [&'static str],
               accepted_path_applicable: bool,
               accepted_path_evidence_source: &'static str,
               accepted_path_check: &'static str,
               accepted_path_evidence_present: bool,
               separate_rejection_evidence_required: bool| {
        let coverage = proof_report
            .requirement_coverage_rows
            .iter()
            .find(|row| row.requirement == requirement)
            .expect("accepted proof-boundary requirement coverage row exists");
        Path2AccountCreationAcceptedRequirementEvidenceRowV1 {
            requirement,
            coverage_surface: coverage.coverage_surface,
            vector_evidence_kind: coverage.vector_evidence_kind,
            current_vector_case_ids: coverage.current_vector_case_ids,
            closure_obligation_ids,
            accepted_path_applicable,
            accepted_path_evidence_source,
            accepted_path_check,
            accepted_path_evidence_present,
            boundary_or_audit_evidence_present: coverage.covered_by_current_vectors,
            separate_rejection_evidence_required,
            separate_closure_required:
                path2_account_creation_referenced_obligations_have_open_residual_v1(
                    proof_report,
                    closure_obligation_ids,
                ),
            all_referenced_closure_obligations_still_open:
                path2_account_creation_referenced_obligations_accounted_v1(
                    proof_report,
                    closure_obligation_ids,
                ),
            blocker: coverage.blocker,
        }
    };

    vec![
        row(
            "canonical_leaf_and_evidence_framing",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_FROZEN_KATS,
            true,
            "accepted account-creation verifier boundary and proof-boundary report",
            "verifier_boundary_accepts && proof_boundary_report_validated",
            evidence.verifier_boundary_accepts && evidence.proof_boundary_report_validated,
            false,
        ),
        row(
            "evidence_leaf_binding_equalities",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_FROZEN_KATS,
            true,
            "accepted leaf digest and evidence transcript binding",
            "leaf_transcript_bound_to_evidence && leaf_digest_bound_to_evidence",
            evidence.leaf_transcript_bound_to_evidence && evidence.leaf_digest_bound_to_evidence,
            false,
        ),
        row(
            "certificate_evidence_payload_digest_binding",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_FROZEN_KATS,
            true,
            "accepted replay certificate, evidence envelope, and selected payload digest",
            "payload_digest_bound_to_certificate && evidence_digest_bound_to_certificate",
            evidence.payload_digest_bound_to_certificate
                && evidence.evidence_digest_bound_to_certificate,
            false,
        ),
        row(
            "payload_availability_nonempty_bundle_and_digest_equality",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_FROZEN_KATS,
            true,
            "accepted account-STARK payload frame and non-empty proof bundle",
            "account_stark_bundle_nonempty && payload_digest_bound_to_certificate",
            evidence.account_stark_bundle_nonempty && evidence.payload_digest_bound_to_certificate,
            false,
        ),
        row(
            "payload_context_binding_leaf_proof_aggregation_slot",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_FROZEN_KATS,
            true,
            "accepted payload context, creation binding, aggregation context, and slot id",
            "leaf_context_bound && binding_digest_bound && payload_binding_fields_match_report",
            evidence.leaf_context_bound
                && evidence.binding_digest_bound
                && evidence.payload_binding_fields_match_report,
            false,
        ),
        row(
            "packed_account_stark_bundle_verifies",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_PACKED_STARK,
            true,
            "accepted account-STARK boundary verification result",
            "verifier_boundary_accepts && account_stark_bundle_nonempty",
            evidence.verifier_boundary_accepts && evidence.account_stark_bundle_nonempty,
            false,
        ),
        row(
            "deployed_creation_anchors_match_stark_public_statement",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_PACKED_STARK,
            true,
            "decoded deployed public anchors and payload boundary report",
            "decoded_public_anchors_match_deployed_anchors && deployed_anchor_fields_match_report",
            evidence.decoded_public_anchors_match_deployed_anchors
                && evidence.deployed_anchor_fields_match_report,
            false,
        ),
        row(
            "zero_knowledge_no_export_semantics",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_NO_EXPORT,
            true,
            "accepted public payload no-export audit boundary",
            "!public_payload_exports_private_material && proof_boundary_report_validated",
            !evidence.public_payload_exports_private_material
                && evidence.proof_boundary_report_validated,
            false,
        ),
        row(
            "account_stark_qrom_domain_separation",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_FRI_QROM,
            false,
            "FRI/QROM domain audit corpus and residual theorem ledger",
            "not a happy-path acceptance property; covered by domain audit vectors and residual theorem closure",
            false,
            false,
        ),
        row(
            "deterministic_public_rejection",
            &PATH2_ACCOUNT_CREATION_REQUIREMENT_OBLIGATIONS_FROZEN_KATS,
            false,
            "account-creation public rejection KAT suite",
            "not a happy-path acceptance property; covered by malformed/rebind rejection KAT gates",
            false,
            true,
        ),
    ]
}

#[cfg(feature = "account-creation-stark-verifier")]
fn path2_account_creation_accepted_proof_boundary_evidence_for_fixture_v1(
    fixture: &Path2AccountStarkPayloadKatFixtureV1,
) -> Result<Path2AccountCreationAcceptedProofBoundaryEvidenceV1, String> {
    let proof_boundary_report = path2_account_creation_proof_boundary_report_v1();
    validate_path2_account_creation_proof_boundary_report_v1(&proof_boundary_report)?;
    let sampler_timing_report = path2_account_creation_sampler_timing_report_v1();
    validate_path2_account_creation_sampler_timing_report_v1(&sampler_timing_report)?;
    let no_export_boundary_report = path2_account_creation_no_export_boundary_report_v1();
    validate_path2_account_creation_no_export_boundary_report_v1(&no_export_boundary_report)?;
    let residual_matrix_report = path2_account_stark_residual_matrix_report_v1();
    validate_path2_account_stark_residual_matrix_report_v1(&residual_matrix_report)?;
    let frame_kat_boundary_report = path2_account_creation_frame_kat_boundary_report_v1();
    validate_path2_account_creation_frame_kat_boundary_report_v1(&frame_kat_boundary_report)?;
    let fri_qrom_residual_report = path2_account_stark_fri_qrom_residual_report_v1();
    validate_path2_account_stark_fri_qrom_residual_report_v1(&fri_qrom_residual_report)?;
    let fri_aok_boundary_report = path2_account_stark_fri_aok_boundary_report_v1();
    validate_path2_account_stark_fri_aok_boundary_report_v1(&fri_aok_boundary_report)?;
    let payload_byte_model_report = path2_account_stark_payload_byte_model_report_v1();
    validate_path2_account_stark_payload_byte_model_report_v1(&payload_byte_model_report)?;
    let payload_kat_boundary_report = path2_account_stark_payload_kat_boundary_report_v1();
    validate_path2_account_stark_payload_kat_boundary_report_v1(&payload_kat_boundary_report)?;

    verify_path2_direct_creation_account_stark_payload_boundary(
        &fixture.leaf,
        &fixture.evidence,
        &fixture.certificate,
        &fixture.binding,
        &fixture.payload,
    )?;
    let production_error =
        match verify_path2_direct_creation_account_stark_payload_boundary_for_production(
            &fixture.leaf,
            &fixture.evidence,
            &fixture.certificate,
            &fixture.binding,
            &fixture.payload,
        ) {
            Ok(()) => {
                return Err(
                    "Path 2 accepted proof-boundary evidence production gate unexpectedly opened"
                        .to_string(),
                );
            }
            Err(error) => error,
        };
    if production_error
        != "account-creation STARK production verification is fail-closed (external-review-gated)"
    {
        return Err("Path 2 accepted proof-boundary evidence production gate drift".to_string());
    }

    let leaf_digest = path2_prevalidated_slot_leaf_digest(&fixture.leaf)?;
    let slot_authorization_digest = path2_slot_authorization_digest(&fixture.leaf)?;
    let evidence_transcript_digest =
        path2_account_creation_evidence_transcript_digest(&fixture.evidence)?;
    let certificate_digest =
        path2_direct_replayable_relation_certificate_digest(&fixture.certificate);
    let payload_digest = path2_account_stark_creation_payload_v1_digest(&fixture.payload)?;
    let payload_frame = path2_account_stark_creation_payload_v1_frame(&fixture.payload)?;
    let binding_digest = path2_creation_proof_binding_v1_digest(&fixture.binding);
    let leaf_context_digest = path2_prevalidated_slot_leaf_context_digest(
        &fixture.leaf,
        &fixture.evidence,
        &fixture.certificate,
    )?;
    let decoded_public_anchors =
        descender_account_verifier::decode_deployed_account_creation_public_anchors(
            &fixture.payload.account_stark_bundle,
        )
        .map_err(|error| format!("Path 2 account-STARK public anchor decode failed: {error}"))?;
    let deployed_anchor_digest = path2_account_creation_deployed_anchor_digest(
        &fixture.leaf,
        &fixture.binding,
        &fixture.payload,
    );
    let decoded_public_anchor_digest =
        path2_account_creation_decoded_public_anchor_digest(&decoded_public_anchors);
    let account_stark_bundle_nonempty = !fixture.payload.account_stark_bundle.is_empty();
    let payload_digest_bound_to_certificate =
        fixture.certificate.public_replay_payload_digest == payload_digest;
    let evidence_digest_bound_to_certificate =
        fixture.evidence.evidence_payload_digest == certificate_digest;
    let leaf_transcript_bound_to_evidence =
        fixture.leaf.prevalidation_transcript_digest == evidence_transcript_digest;
    let leaf_digest_bound_to_evidence = fixture.evidence.slot_leaf_digest == leaf_digest;
    let leaf_context_bound = fixture.payload.leaf_context_digest == leaf_context_digest;
    let binding_digest_bound = fixture.binding.digest == binding_digest
        && fixture.payload.creation_proof_binding_digest == binding_digest;
    let payload_binding_fields_match_report = proof_boundary_report.payload_binding_fields
        == PATH2_ACCOUNT_CREATION_PROOF_BOUNDARY_PAYLOAD_BINDING_FIELDS.as_ref()
        && leaf_context_bound
        && binding_digest_bound
        && fixture.payload.aggregation_context_digest == fixture.binding.aggregation_context_digest
        && fixture.payload.slot_id == fixture.leaf.slot_id
        && payload_digest_bound_to_certificate
        && account_stark_bundle_nonempty;
    let deployed_anchor_account_id_bound =
        decoded_public_anchors.account_id == fixture.leaf.account_id;
    let deployed_anchor_slot_id_bound = decoded_public_anchors.slot_id == fixture.leaf.slot_id
        && decoded_public_anchors.slot_id == fixture.payload.slot_id
        && decoded_public_anchors.slot_id == fixture.binding.slot_id;
    let deployed_anchor_state_root_bound = decoded_public_anchors.account_state_root
        == fixture.leaf.account_state_root_before
        && decoded_public_anchors.account_state_root == fixture.binding.account_state_root_before;
    let deployed_anchor_lifecycle_anchor_bound = decoded_public_anchors.lifecycle_anchor
        == fixture.leaf.lifecycle_anchor
        && decoded_public_anchors.lifecycle_anchor == fixture.binding.lifecycle_anchor;
    let deployed_anchor_verifier_version_bound =
        decoded_public_anchors.verifier_version == PATH2_ACCOUNT_STARK_VERIFIER_VERSION;
    let deployed_anchor_masked_projection_bound =
        decoded_public_anchors.masked_projection == fixture.payload.masked_projection;
    let deployed_anchor_role_root_export_bridge_bound = decoded_public_anchors
        .native_role_root_commitment
        == fixture.payload.native_role_root_commitment;
    let deployed_anchor_packed_witness_commitment_bound = decoded_public_anchors
        .packed_witness_commitment
        == fixture.binding.packed_witness_commitment;
    let decoded_public_anchors_match_deployed_anchors = deployed_anchor_account_id_bound
        && deployed_anchor_slot_id_bound
        && deployed_anchor_state_root_bound
        && deployed_anchor_lifecycle_anchor_bound
        && deployed_anchor_verifier_version_bound
        && deployed_anchor_masked_projection_bound
        && deployed_anchor_role_root_export_bridge_bound
        && deployed_anchor_packed_witness_commitment_bound;
    let deployed_anchor_fields_match_report = proof_boundary_report.deployed_anchor_fields
        == PATH2_ACCOUNT_CREATION_PROOF_BOUNDARY_DEPLOYED_ANCHORS.as_ref()
        && decoded_public_anchors_match_deployed_anchors;
    if !payload_binding_fields_match_report
        || !deployed_anchor_fields_match_report
        || !payload_digest_bound_to_certificate
        || !evidence_digest_bound_to_certificate
        || !leaf_transcript_bound_to_evidence
        || !leaf_digest_bound_to_evidence
        || deployed_anchor_digest != decoded_public_anchor_digest
    {
        return Err("Path 2 accepted proof-boundary evidence binding mismatch".to_string());
    }

    let mut evidence = Path2AccountCreationAcceptedProofBoundaryEvidenceV1 {
        digest: [0_u8; DIGEST_BYTES],
        schema: PATH2_ACCOUNT_CREATION_ACCEPTED_PROOF_BOUNDARY_EVIDENCE_SCHEMA,
        proof_boundary_target: proof_boundary_report.proof_boundary_target,
        proof_boundary_conclusion: proof_boundary_report.proof_boundary_conclusion,
        selected_payload_type: proof_boundary_report.selected_payload_type,
        verifier_boundary_endpoint: proof_boundary_report.verifier_boundary_endpoint,
        production_boundary_endpoint: proof_boundary_report.production_boundary_endpoint,
        replay_payload_digest_function: proof_boundary_report.replay_payload_digest_function,
        accepting_requirements: proof_boundary_report.accepting_requirements,
        accepted_requirement_evidence_rows: Vec::new(),
        accepted_requirement_evidence_count: 0,
        accepted_path_applicable_requirement_count: 0,
        accepted_path_requirement_evidence_count: 0,
        boundary_or_audit_requirement_evidence_count: 0,
        separate_closure_required_count: 0,
        every_applicable_accepting_requirement_has_accepted_path_evidence: false,
        every_accepting_requirement_has_boundary_or_audit_evidence: false,
        every_separate_closure_requirement_has_open_obligation: false,
        deterministic_rejection_requirement_deferred_to_rejection_kats: false,
        qrom_requirement_deferred_to_residual_theorem: false,
        account_creation_proof_boundary_report_digest: proof_boundary_report.digest,
        sampler_timing_report_digest: sampler_timing_report.digest,
        no_export_boundary_report_digest: no_export_boundary_report.digest,
        account_stark_residual_matrix_report_digest: residual_matrix_report.digest,
        frame_kat_boundary_report_digest: frame_kat_boundary_report.digest,
        fri_qrom_residual_report_digest: fri_qrom_residual_report.digest,
        fri_aok_boundary_report_digest: fri_aok_boundary_report.digest,
        payload_byte_model_report_digest: payload_byte_model_report.digest,
        payload_kat_boundary_report_digest: payload_kat_boundary_report.digest,
        fixture_id: fixture.fixture_id,
        proof_mask_seed: fixture.proof_mask_seed,
        account_id: fixture.leaf.account_id,
        public_key_identity: fixture.leaf.public_key_identity,
        account_state_root_before: fixture.leaf.account_state_root_before,
        slot_id: fixture.leaf.slot_id,
        prevalidated_slot_leaf_digest: leaf_digest,
        slot_authorization_digest,
        account_creation_evidence_transcript_digest: evidence_transcript_digest,
        direct_replayable_relation_certificate_digest: certificate_digest,
        selected_account_creation_payload_digest: payload_digest,
        creation_proof_binding_digest: binding_digest,
        leaf_context_digest,
        aggregation_context_digest: fixture.payload.aggregation_context_digest,
        native_role_root_commitment: fixture.payload.native_role_root_commitment,
        masked_projection_digest: path2_account_creation_masked_projection_digest(
            &fixture.payload.masked_projection,
        ),
        deployed_anchor_digest,
        payload_frame_digest: Sha256::digest(&payload_frame).into(),
        payload_frame_bytes: payload_frame.len(),
        account_stark_bundle_digest: Sha256::digest(&fixture.payload.account_stark_bundle).into(),
        account_stark_bundle_bytes: fixture.payload.account_stark_bundle.len(),
        decoded_public_anchor_digest,
        verifier_boundary_accepts: true,
        production_gate_fail_closed: true,
        proof_boundary_report_validated: true,
        public_payload_exports_private_material: payload_byte_model_report
            .public_payload_exports_private_material,
        payload_digest_bound_to_certificate,
        evidence_digest_bound_to_certificate,
        leaf_transcript_bound_to_evidence,
        leaf_digest_bound_to_evidence,
        leaf_context_bound,
        binding_digest_bound,
        payload_binding_fields_match_report,
        decoded_public_anchors_match_deployed_anchors,
        deployed_anchor_account_id_bound,
        deployed_anchor_slot_id_bound,
        deployed_anchor_state_root_bound,
        deployed_anchor_lifecycle_anchor_bound,
        deployed_anchor_verifier_version_bound,
        deployed_anchor_masked_projection_bound,
        deployed_anchor_role_root_export_bridge_bound,
        deployed_anchor_packed_witness_commitment_bound,
        deployed_anchor_fields_match_report,
        account_stark_bundle_nonempty,
        proof_family_obligations_still_open: proof_boundary_report
            .proof_obligation_rows
            .iter()
            .any(|row| row.open),
        deployment_ready: false,
    };
    evidence.accepted_requirement_evidence_rows =
        path2_account_creation_accepted_requirement_evidence_rows_v1(
            &evidence,
            &proof_boundary_report,
        );
    evidence.accepted_requirement_evidence_count =
        evidence.accepted_requirement_evidence_rows.len();
    evidence.accepted_path_applicable_requirement_count = evidence
        .accepted_requirement_evidence_rows
        .iter()
        .filter(|row| row.accepted_path_applicable)
        .count();
    evidence.accepted_path_requirement_evidence_count = evidence
        .accepted_requirement_evidence_rows
        .iter()
        .filter(|row| row.accepted_path_applicable && row.accepted_path_evidence_present)
        .count();
    evidence.boundary_or_audit_requirement_evidence_count = evidence
        .accepted_requirement_evidence_rows
        .iter()
        .filter(|row| row.boundary_or_audit_evidence_present)
        .count();
    evidence.separate_closure_required_count = evidence
        .accepted_requirement_evidence_rows
        .iter()
        .filter(|row| row.separate_closure_required)
        .count();
    evidence.every_applicable_accepting_requirement_has_accepted_path_evidence = evidence
        .accepted_requirement_evidence_count
        == PATH2_ACCOUNT_CREATION_PROOF_BOUNDARY_REQUIREMENTS.len()
        && evidence.accepted_path_applicable_requirement_count == 8
        && evidence.accepted_path_requirement_evidence_count == 8
        && evidence
            .accepted_requirement_evidence_rows
            .iter()
            .filter(|row| row.accepted_path_applicable)
            .all(|row| row.accepted_path_evidence_present);
    evidence.every_accepting_requirement_has_boundary_or_audit_evidence = evidence
        .accepted_requirement_evidence_count
        == PATH2_ACCOUNT_CREATION_PROOF_BOUNDARY_REQUIREMENTS.len()
        && evidence.boundary_or_audit_requirement_evidence_count
            == PATH2_ACCOUNT_CREATION_PROOF_BOUNDARY_REQUIREMENTS.len();
    evidence.every_separate_closure_requirement_has_open_obligation = evidence
        .accepted_requirement_evidence_count
        == PATH2_ACCOUNT_CREATION_PROOF_BOUNDARY_REQUIREMENTS.len()
        && evidence.separate_closure_required_count == 4
        && evidence
            .accepted_requirement_evidence_rows
            .iter()
            .filter(|row| row.separate_closure_required)
            .all(|row| row.all_referenced_closure_obligations_still_open);
    evidence.deterministic_rejection_requirement_deferred_to_rejection_kats = evidence
        .accepted_requirement_evidence_rows
        .iter()
        .any(|row| {
            row.requirement == "deterministic_public_rejection"
                && !row.accepted_path_applicable
                && !row.accepted_path_evidence_present
                && row.boundary_or_audit_evidence_present
                && row.separate_rejection_evidence_required
                && row.all_referenced_closure_obligations_still_open
        });
    evidence.qrom_requirement_deferred_to_residual_theorem = evidence
        .accepted_requirement_evidence_rows
        .iter()
        .any(|row| {
            row.requirement == "account_stark_qrom_domain_separation"
                && !row.accepted_path_applicable
                && !row.accepted_path_evidence_present
                && row.boundary_or_audit_evidence_present
                && !row.separate_rejection_evidence_required
                && row.all_referenced_closure_obligations_still_open
        });
    evidence.digest = path2_account_creation_accepted_proof_boundary_evidence_v1_digest(&evidence);
    Ok(evidence)
}

