fn path2_native_checked_core_selected_rust_instantiation_has_forbidden_stubs(
    lean_source: &str,
) -> bool {
    let lean_source = lean_source_without_comments_and_strings_v1(lean_source);
    let selected_source_facts = [
        "selectedRustCheckedCoreEvidenceReport",
        "selectedRustCheckedCoreEvidenceDigest",
        "selectedRustHashByteDomainEvidenceDigest",
        "selectedRustCheckedCoreEvidenceReportVerifiedProof",
        "selectedRustCheckedCoreEvidenceFactsAllTrueProof",
        "selectedRustCheckedCoreAcceptorAccepts",
        "selectedRustProductionCheckedCoreAcceptorAccepts",
        "selectedRustCheckedCoreAcceptorPinnedProof",
        "selectedRustCheckedCoreParserMatchesNative",
        "selectedRustCheckedCoreProofLengthEq",
        "selectedRustCheckedCoreProofCanonical",
        "selectedRustCheckedCoreDecodedProofCommitment",
        "selectedRustCheckedCoreParsedResponseSyndrome",
        "selectedRustCheckedCoreFrameBytes",
        "selectedRustCheckedCoreVerifierHandleEq",
        "selectedRustCheckedCoreParserEquality",
        "selectedRustCheckedCoreHashAndSyndrome",
    ];
    let forbidden_declaration_kinds = ["axiom", "constant", "opaque"];
    let forbidden_declaration_stub = forbidden_declaration_kinds.iter().any(|kind| {
        lean_source
            .match_indices(&format!("\n{kind}"))
            .map(|(index, _)| &lean_source[index..lean_source.len().min(index + 512)])
            .any(|declaration_window| {
                selected_source_facts
                    .iter()
                    .any(|fact| declaration_window.contains(fact))
            })
    });
    let forbidden_variable_stub = lean_source
        .match_indices("\nvariable")
        .map(|(index, _)| &lean_source[index..lean_source.len().min(index + 512)])
        .any(|variable_window| {
            selected_source_facts
                .iter()
                .any(|fact| variable_window.contains(fact))
        });
    let forbidden_vacuous_report_def = [
        "def selectedRustCheckedCoreEvidenceReport : SelectedRustCheckedCoreByteEvidenceReport := {",
        "let selectedRustCheckedCoreEvidenceReport : SelectedRustCheckedCoreByteEvidenceReport :=",
        "def selectedRustCheckedCoreEvidenceReportVerifiedProof := True.intro",
        "def selectedRustCheckedCoreEvidenceFactsAllTrueProof := True.intro",
        "abbrev selectedRustCheckedCoreEvidenceReportVerifiedProof := True.intro",
        "abbrev selectedRustCheckedCoreEvidenceFactsAllTrueProof := True.intro",
        "def selectedRustCheckedCoreAcceptorAccepts := fun _ _ _ _ => False",
        "def selectedRustProductionCheckedCoreAcceptorAccepts := fun _ _ _ _ => False",
        "abbrev selectedRustCheckedCoreAcceptorAccepts := fun _ _ _ _ => False",
        "abbrev selectedRustProductionCheckedCoreAcceptorAccepts := fun _ _ _ _ => False",
    ]
    .iter()
    .any(|marker| lean_source.contains(marker));
    let forbidden_vacuous_report_theorem = [
        "theorem selectedRustCheckedCoreEvidenceReportVerifiedProof",
        "theorem selectedRustCheckedCoreEvidenceFactsAllTrueProof",
    ]
    .iter()
    .any(|marker| {
        lean_source
            .match_indices(marker)
            .map(|(index, _)| &lean_source[index..lean_source.len().min(index + 512)])
            .any(|theorem_window| {
                theorem_window.contains(":= True.intro")
                    || theorem_window.contains(":= by\n  trivial")
                    || theorem_window.contains(":= by trivial")
            })
    });
    forbidden_declaration_stub
        || forbidden_variable_stub
        || forbidden_vacuous_report_def
        || forbidden_vacuous_report_theorem
}

fn path2_native_checked_core_selected_rust_instantiation_present_v1() -> bool {
    let lean_source = include_str!("../../../Descender/Path2CheckedCoreByteBridge.lean");
    path2_native_checked_core_selected_rust_instantiation_present_in_source_v1(lean_source)
}

fn path2_native_checked_core_selected_rust_instantiation_present_in_source_v1(
    lean_source: &str,
) -> bool {
    if path2_native_checked_core_selected_rust_instantiation_has_forbidden_stubs(lean_source) {
        return false;
    }
    let lean_source = lean_source_without_comments_and_strings_v1(lean_source);
    let theorem_name = "selectedRustCheckedCoreByteSource_instantiation_v1";
    let theorem_start_marker = format!("\ntheorem {theorem_name}");

    lean_source
        .match_indices(&theorem_start_marker)
        .any(|(instantiation_start, _)| {
            let instantiation_end = lean_source[instantiation_start..]
                .find("\nend Path2CheckedCoreByteBridge")
                .map(|offset| instantiation_start + offset)
                .unwrap_or(lean_source.len());
            let instantiation_source = &lean_source[instantiation_start..instantiation_end];
            path2_native_checked_core_selected_rust_instantiation_candidate_source_v1(
                instantiation_source,
                theorem_name,
            )
        })
}

fn path2_native_checked_core_selected_rust_instantiation_candidate_source_v1(
    instantiation_source: &str,
    theorem_name: &str,
) -> bool {
    let normalized_instantiation_source =
        instantiation_source.split_whitespace().collect::<String>();
    let contains_normalized = |marker: &str| {
        normalized_instantiation_source.contains(&marker.split_whitespace().collect::<String>())
    };

    let selected_source_facts = [
        "selectedRustCheckedCoreEvidenceReport",
        "selectedRustCheckedCoreEvidenceReportVerifiedProof",
        "selectedRustCheckedCoreEvidenceFactsAllTrueProof",
        "selectedRustHashByteDomainEvidenceDigest",
        "selectedRustCheckedCoreAcceptorAccepts",
        "selectedRustCheckedCoreParserMatchesNative",
        "selectedRustCheckedCoreProofLengthEq",
        "selectedRustCheckedCoreProofCanonical",
        "selectedRustCheckedCoreDecodedProofCommitment",
        "selectedRustCheckedCoreParsedResponseSyndrome",
        "selectedRustCheckedCoreFrameBytes",
        "selectedRustCheckedCoreVerifierHandleEq",
        "selectedRustCheckedCoreParserEquality",
        "selectedRustCheckedCoreHashAndSyndrome",
    ];
    let theorem_header_end = instantiation_source
        .find(":= by")
        .or_else(|| instantiation_source.find(" where"))
        .unwrap_or(instantiation_source.len().min(1024));
    let theorem_header = &instantiation_source[..theorem_header_end];
    let theorem_start_marker = format!("\ntheorem {theorem_name}");
    let Some(theorem_start) = theorem_header.find(&theorem_start_marker) else {
        return false;
    };
    let theorem_name_end = theorem_start + theorem_start_marker.len();
    if theorem_header[theorem_name_end..]
        .chars()
        .next()
        .is_some_and(|next| next.is_ascii_alphanumeric() || next == '_' || next == '\'')
    {
        return false;
    }
    let forbidden_theorem_parameter = selected_source_facts.iter().any(|fact| {
        ["(", "{", "["]
            .iter()
            .any(|binder| theorem_header.contains(&format!("{binder}{fact}")))
    });
    if forbidden_theorem_parameter {
        return false;
    }
    if theorem_header.contains("SelectedRustCheckedCoreByteInstantiationInputs")
        || theorem_header.contains("SelectedRustCheckedCoreByteEvidenceCertificate")
        || theorem_header.contains("Path2NativeCheckedCoreAcceptV1Bridge")
        || theorem_header.contains("Path2NativeCheckedCoreAcceptV1Soundness")
        || theorem_header.contains("SelectedRustCheckedCoreCompositionClosure")
        || theorem_header.contains("NativeAcceptedSpendSoundnessBoundary")
        || theorem_header.contains("NativeFullSignatureSecurityBoundary")
    {
        return false;
    }
    let forbidden_vacuous_evidence_terms = [
        "evidenceReport := {",
        "evidenceReportVerifiedProof := True.intro",
        "evidenceFactsAllTrueProof := True.intro",
        "let selectedRustCheckedCoreEvidenceReport : SelectedRustCheckedCoreByteEvidenceReport :=",
        "let selectedRustCheckedCoreEvidenceReportVerifiedProof := True.intro",
        "let selectedRustCheckedCoreEvidenceFactsAllTrueProof := True.intro",
        "selectedRustCheckedCoreEvidenceCertificate := {",
        "selectedRustCheckedCoreAcceptorAccepts := fun _ _ _ _ => False",
        "selectedRustProductionCheckedCoreAcceptorAccepts := fun _ _ _ _ => False",
        "let selectedRustCheckedCoreAcceptorAccepts := fun _ _ _ _ => False",
        "let selectedRustProductionCheckedCoreAcceptorAccepts := fun _ _ _ _ => False",
    ];
    if forbidden_vacuous_evidence_terms
        .iter()
        .any(|term| instantiation_source.contains(term) || contains_normalized(term))
    {
        return false;
    }

    let instantiation_checks = [
        "selectedRustCheckedCoreByteSource_instantiation_v1",
        "selectedRustCheckedCoreByteSource_valid_or_named_break",
        "SelectedRustCheckedCoreByteSource",
        "Path2NativeCheckedCoreAcceptV1Bridge",
        "Path2NativeCheckedCoreAcceptV1Soundness",
        "let selectedRustCheckedCoreEvidenceCertificate :",
        "SelectedRustCheckedCoreByteEvidenceCertificate",
        "SelectedRustCheckedCoreByteEvidenceCertificate.ofReportAndComponents",
        "selectedRustCheckedCoreEvidenceReport",
        "selectedRustCheckedCoreEvidenceDigest",
        "selectedRustHashByteDomainEvidenceDigest",
        "selectedRustCheckedCoreEvidenceReportVerifiedProof",
        "selectedRustCheckedCoreEvidenceFactsAllTrueProof",
        "selectedRustCheckedCoreAcceptorAccepts",
        "selectedRustProductionCheckedCoreAcceptorAccepts",
        "selectedRustCheckedCoreAcceptorPinnedProof",
        "selectedRustCheckedCoreParserMatchesNative",
        "selectedRustCheckedCoreProofLengthEq",
        "selectedRustCheckedCoreProofCanonical",
        "selectedRustCheckedCoreDecodedProofCommitment",
        "selectedRustCheckedCoreParsedResponseSyndrome",
        "selectedRustCheckedCoreFrameBytes",
        "selectedRustCheckedCoreVerifierHandleEq",
        "selectedRustCheckedCoreParserEquality",
        "selectedRustCheckedCoreHashAndSyndrome",
        "let selectedRustCheckedCoreInputs :",
        "SelectedRustCheckedCoreByteInstantiationInputs",
        "SelectedRustCheckedCoreByteEvidenceCertificate.toInstantiationInputs selectedRustCheckedCoreEvidenceCertificate",
        "selectedRustCheckedCoreByteSource_from_instantiation_inputs_v1 selectedRustCheckedCoreInputs",
        "selectedRustCheckedCoreByteSource_from_instantiation_inputs_valid_or_named_break",
    ];

    instantiation_checks
        .iter()
        .all(|marker| instantiation_source.contains(marker) || contains_normalized(marker))
}

fn path2_native_checked_core_composition_complete_v1() -> bool {
    path2_native_checked_core_byte_bridge_source_present_v1()
        && path2_native_checked_core_selected_rust_instantiation_present_v1()
}

