fn path2_full_signature_execution_source_instantiated_v1() -> bool {
    let full_spend_source = include_str!("../../../Descender/Path2FullSpendConcrete.lean");
    path2_full_signature_execution_source_instantiated_in_source_v1(full_spend_source)
}

fn path2_full_signature_execution_source_instantiated_in_source_v1(
    full_spend_source: &str,
) -> bool {
    let stripped_full_spend_source = lean_source_without_comments_and_strings_v1(full_spend_source);
    let full_spend_source = stripped_full_spend_source.as_str();
    let theorem_name = "concreteFullSignatureExecutionSource_instantiation_v1";
    let forbidden_declaration_terms = [
        "selectedRustFullExecutionEvidenceReport",
        "selectedRustFullExecutionEvidenceDigest",
        "selectedRustFullExecutionSourceVerifiedProof",
        "selectedRustFullExecutionFactsAllTrueProof",
        "selectedRustExecutionSucceeds",
        "selectedRustProductionExecutionSucceeds",
        "selectedRustExecutionPredicatePinnedProof",
        "selectedRustSuccessImpliesVerifierAcceptOrBreak",
    ];
    let forbidden_declaration_kinds = ["axiom", "constant", "opaque"];
    let forbidden_declaration_stub = forbidden_declaration_kinds.iter().any(|kind| {
        full_spend_source
            .match_indices(&format!("\n{kind}"))
            .map(|(index, _)| &full_spend_source[index..full_spend_source.len().min(index + 1024)])
            .any(|declaration_window| {
                forbidden_declaration_terms
                    .iter()
                    .any(|term| declaration_window.contains(term))
            })
    });
    if forbidden_declaration_stub {
        return false;
    }
    let forbidden_variable_stub = full_spend_source
        .match_indices("\nvariable")
        .map(|(index, _)| &full_spend_source[index..full_spend_source.len().min(index + 1024)])
        .any(|variable_window| {
            forbidden_declaration_terms
                .iter()
                .any(|term| variable_window.contains(term))
        });
    if forbidden_variable_stub {
        return false;
    }
    let normalized_full_spend_source = full_spend_source.split_whitespace().collect::<String>();
    let contains_normalized_source = |marker: &str| {
        normalized_full_spend_source.contains(&marker.split_whitespace().collect::<String>())
    };
    let forbidden_vacuous_global_terms = [
        "def selectedRustFullExecutionEvidenceReport := {",
        "def selectedRustFullExecutionEvidenceReport : SelectedRustFullExecutionEvidenceReport :=",
        "def selectedRustFullExecutionEvidenceReport := ⟨",
        "def selectedRustFullExecutionEvidenceDigest := ByteArray.empty",
        "def selectedRustFullExecutionSourceVerifiedProof := True.intro",
        "def selectedRustFullExecutionFactsAllTrueProof := True.intro",
        "def selectedRustExecutionSucceeds := fun _ => False",
        "def selectedRustProductionExecutionSucceeds := fun _ => False",
        "abbrev selectedRustFullExecutionEvidenceReport := {",
        "abbrev selectedRustFullExecutionEvidenceReport : SelectedRustFullExecutionEvidenceReport :=",
        "abbrev selectedRustFullExecutionEvidenceReport := ⟨",
        "abbrev selectedRustFullExecutionEvidenceDigest := ByteArray.empty",
        "abbrev selectedRustFullExecutionSourceVerifiedProof := True.intro",
        "abbrev selectedRustFullExecutionFactsAllTrueProof := True.intro",
        "abbrev selectedRustExecutionSucceeds := fun _ => False",
        "abbrev selectedRustProductionExecutionSucceeds := fun _ => False",
    ];
    if forbidden_vacuous_global_terms
        .iter()
        .any(|term| full_spend_source.contains(term) || contains_normalized_source(term))
    {
        return false;
    }
    let theorem_start_marker = format!("\ntheorem {theorem_name}");
    full_spend_source
        .match_indices(&theorem_start_marker)
        .any(|(instantiation_start, _)| {
            let instantiation_end = full_spend_source[instantiation_start..]
                .find("\nend Path2FullSpendConcrete")
                .map(|offset| instantiation_start + offset)
                .unwrap_or(full_spend_source.len());
            let instantiation_source = &full_spend_source[instantiation_start..instantiation_end];
            path2_full_signature_execution_source_instantiation_candidate_source_v1(
                instantiation_source,
                theorem_name,
            )
        })
}

fn path2_full_signature_execution_source_instantiation_candidate_source_v1(
    instantiation_source: &str,
    theorem_name: &str,
) -> bool {
    let theorem_header_end = instantiation_source
        .find(":= by")
        .or_else(|| instantiation_source.find(" where"))
        .unwrap_or(instantiation_source.len().min(1024));
    let theorem_header = &instantiation_source[..theorem_header_end];
    let theorem_start_marker = format!("\ntheorem {theorem_name}");
    let Some(theorem_start) = theorem_header.find(&theorem_start_marker) else {
        return false;
    };
    let theorem_name_end = theorem_start + theorem_start_marker.len();
    if theorem_header[theorem_name_end..]
        .chars()
        .next()
        .is_some_and(|next| next.is_ascii_alphanumeric() || next == '_' || next == '\'')
    {
        return false;
    }
    let header_has_assumed_term = |term: &str| -> bool {
        let mut depth = 0_usize;
        let mut binder_start = None;
        for (index, ch) in theorem_header.char_indices() {
            match ch {
                '(' | '{' | '[' => {
                    if depth == 0 {
                        binder_start = Some(index);
                    }
                    depth += 1;
                }
                ')' | '}' | ']' if depth > 0 => {
                    depth -= 1;
                    if depth == 0 {
                        if let Some(start) = binder_start {
                            if theorem_header[start..=index].contains(term) {
                                return true;
                            }
                        }
                        binder_start = None;
                    }
                }
                _ => {}
            }
        }
        false
    };
    let forbidden_header_terms = [
        "ConcreteFullSignatureExecutionSource",
        "ConcreteGameConfig",
        "SelectedRustFullExecutionSourceCertificate",
        "SelectedRustFullExecutionEvidenceReport",
        "selectedRustFullExecutionEvidenceReport",
        "selectedRustFullExecutionEvidenceDigest",
        "selectedRustFullExecutionSourceVerifiedProof",
        "selectedRustFullExecutionFactsAllTrueProof",
        "selectedRustExecutionSucceeds",
        "selectedRustProductionExecutionSucceeds",
        "selectedRustExecutionPredicatePinnedProof",
        "selectedRustSuccessImpliesVerifierAcceptOrBreak",
        "NativeFullSignatureSecurityBoundary",
        "NativeAcceptedSpendSoundnessBoundary",
        "SelectedRustAcceptedSpendSoundnessCertificate",
        "Path2FullSpendGame.FullForgeryToAcceptedSpendSoundness",
    ];
    if forbidden_header_terms
        .iter()
        .any(|term| header_has_assumed_term(term))
    {
        return false;
    }
    let forbidden_vacuous_execution_terms = [
        "evidenceReport := {",
        "selectedRustFullExecutionSourceVerifiedProof := True.intro",
        "selectedRustFullExecutionFactsAllTrueProof := True.intro",
        "let selectedRustFullExecutionEvidenceReport : SelectedRustFullExecutionEvidenceReport :=",
        "let selectedRustFullExecutionSourceVerifiedProof := True.intro",
        "let selectedRustFullExecutionFactsAllTrueProof := True.intro",
        "selectedRustFullExecutionCertificate := {",
        "selectedRustExecutionSucceeds := fun _ => False",
        "selectedRustProductionExecutionSucceeds := fun _ => False",
        "let selectedRustExecutionSucceeds := fun _ => False",
        "let selectedRustProductionExecutionSucceeds := fun _ => False",
    ];
    if forbidden_vacuous_execution_terms
        .iter()
        .any(|term| instantiation_source.contains(term))
    {
        return false;
    }

    let instantiation_checks = [
        "concreteFullSignatureExecutionSource_instantiation_v1",
        "let selectedRustFullExecutionCertificate :",
        "SelectedRustFullExecutionSourceCertificate",
        "SelectedRustFullExecutionSourceCertificate.ofReportAndExecutionSource",
        "selectedRustFullExecutionEvidenceReport",
        "selectedRustFullExecutionEvidenceDigest",
        "selectedRustFullExecutionSourceVerifiedProof",
        "selectedRustFullExecutionFactsAllTrueProof",
        "selectedRustExecutionSucceeds",
        "selectedRustProductionExecutionSucceeds",
        "selectedRustExecutionPredicatePinnedProof",
        "selectedRustSuccessImpliesVerifierAcceptOrBreak",
        "let selectedRustFullExecutionSource :",
        "ConcreteFullSignatureExecutionSource",
        "SelectedRustFullExecutionSourceCertificate.toExecutionSource selectedRustFullExecutionCertificate",
        "concrete_fullExecutionAcceptedSpendLift",
        "NativeFullSignatureSecurityBoundary.withConcreteFullExecutionSource",
        "full_signature_with_concrete_full_execution_source_lift",
    ];
    instantiation_checks
        .iter()
        .all(|marker| instantiation_source.contains(marker))
}

