pub fn path2_native_signer_verifier_pipeline_evidence_from_prevalidated_entropy_root_v1(
    prevalidated: Path2NativeSignerPrevalidatedPublicInputV1,
    root: Path2NativeSignerEntropyRootV1,
) -> Result<Path2NativeSignerVerifierPipelineEvidenceV1, String> {
    let output =
        path2_native_honest_constructor_from_prevalidated_entropy_root_v1(prevalidated, root)?;
    let signer_public_output_digest = path2_native_signer_pipeline_public_output_v1_digest(
        &output.constructed.signer_public_output,
    )?;
    let checked_core_proof_digest: [u8; DIGEST_BYTES] =
        Sha256::digest(output.checked_core_proof_bytes).into();
    let checked_core_byte_instantiation_evidence =
        path2_native_checked_core_byte_instantiation_evidence_v1(
            &output.projection_bundle,
            &output.checked_core_proof_bytes,
        )?;
    let checked_core_byte_instantiation_evidence_digest =
        path2_native_checked_core_byte_instantiation_evidence_v1_digest(
            &checked_core_byte_instantiation_evidence,
        )?;
    let verdict = verify_path2_native_deployment_pipeline_v1(
        &output.constructed.signer_public_output.carrier,
        &output.projection_bundle,
        &output.checked_core_proof_bytes,
    );
    if !verdict.checked_core_byte_instantiation_evidence_verified
        || Some(checked_core_byte_instantiation_evidence_digest)
            != verdict.checked_core_byte_instantiation_evidence_digest
    {
        return Err(
            "Path 2 native signer/verifier checked-core evidence was not verified".to_string(),
        );
    }
    let smallest_remaining_productization_gate =
        path2_native_smallest_remaining_deployment_gate_v1(&verdict.deployment_preflight);

    Ok(Path2NativeSignerVerifierPipelineEvidenceV1 {
        schema: PATH2_NATIVE_SIGNER_VERIFIER_PIPELINE_EVIDENCE_SCHEMA,
        prevalidation_accepted: true,
        constructor_succeeded: true,
        signer_public_output_digest,
        carrier_digest: output.constructed.signer_public_output.carrier_digest,
        checked_core_proof_digest,
        checked_core_byte_instantiation_evidence_digest,
        checked_core_byte_instantiation_evidence_verified: verdict
            .checked_core_byte_instantiation_evidence_verified,
        five_source_closure_evidence_digest: verdict.five_source_closure_evidence_digest,
        five_source_closure_evidence_verified: verdict.five_source_closure_evidence_verified,
        five_source_closure_evidence_facts_all_true: verdict
            .five_source_closure_evidence_facts_all_true,
        native_boundary_digest: output.constructed.boundary_meaning.native_boundary_digest,
        verifier_public_boundary_accepted: verdict.public_boundary_accepted,
        verifier_production_accepted: verdict.production_accepted,
        verifier_rejection_code: verdict.rejection_code,
        smallest_remaining_productization_gate,
        deployment_blockers: verdict.deployment_preflight.internal_blockers,
        explicit_non_claims: [
            "no production acceptance claim while deployment preflight remains blocked",
            "no constant-time claim for private signing or keygen",
            "no target-chain storage lifecycle hardening claim",
        ],
    })
}

