pub fn path2_native_signer_execution_report_v1_digest(
    report: &Path2NativeSignerExecutionReportV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(path2_native_signer_execution_report_v1_frame(report)?).into())
}

pub fn path2_native_signer_execution_report_v1_frame(
    report: &Path2NativeSignerExecutionReportV1,
) -> Result<Vec<u8>, String> {
    let deployment_preflight_digest =
        path2_native_deployment_preflight_v1_digest(&report.deployment_preflight)?;
    let mut frame = Vec::new();
    append_frame(&mut frame, b"schema", report.schema.as_bytes());
    append_u64(
        &mut frame,
        b"constructor_succeeded",
        u64::from(report.constructor_succeeded),
    );
    append_u64(
        &mut frame,
        b"public_boundary_accepted",
        u64::from(report.public_boundary_accepted),
    );
    append_u64(
        &mut frame,
        b"production_accepted",
        u64::from(report.production_accepted),
    );
    append_u64(
        &mut frame,
        b"rejection_code_present",
        u64::from(report.rejection_code.is_some()),
    );
    if let Some(code) = report.rejection_code {
        append_frame(&mut frame, b"rejection_code", code.as_bytes());
    }
    append_u64(
        &mut frame,
        b"signer_public_output_digest_present",
        u64::from(report.signer_public_output_digest.is_some()),
    );
    if let Some(digest) = report.signer_public_output_digest {
        append_frame(&mut frame, b"signer_public_output_digest", &digest);
    }
    append_u64(
        &mut frame,
        b"carrier_digest_present",
        u64::from(report.carrier_digest.is_some()),
    );
    if let Some(digest) = report.carrier_digest {
        append_frame(&mut frame, b"carrier_digest", &digest);
    }
    append_u64(
        &mut frame,
        b"native_boundary_digest_present",
        u64::from(report.native_boundary_digest.is_some()),
    );
    if let Some(digest) = report.native_boundary_digest {
        append_frame(&mut frame, b"native_boundary_digest", &digest);
    }
    append_u64(
        &mut frame,
        b"checked_core_proof_digest_present",
        u64::from(report.checked_core_proof_digest.is_some()),
    );
    if let Some(digest) = report.checked_core_proof_digest {
        append_frame(&mut frame, b"checked_core_proof_digest", &digest);
    }
    append_frame(
        &mut frame,
        b"cleanup_policy",
        report.cleanup_policy.as_bytes(),
    );
    append_u64(
        &mut frame,
        b"entropy_q_fixed_attempts",
        report.entropy_q_fixed_attempts as u64,
    );
    append_frame(
        &mut frame,
        b"deployment_preflight_digest",
        &deployment_preflight_digest,
    );
    Ok(frame)
}

pub fn path2_native_signer_constant_time_stage_labels_v1(
) -> [&'static str; PATH2_NATIVE_SIGNER_CT_STAGE_COUNT] {
    [
        "deployment_preflight_snapshot",
        "entropy_root_acquisition",
        "secret_derivation_schedule",
        "commitment_derivation",
        "private_fiber_binding_check",
        "checked_core_proof_generation",
        "public_boundary_verification",
        "public_report_sanitization",
    ]
}

fn path2_native_signer_rejection_code_is_public_v1(code: Option<&str>) -> bool {
    match code {
        Some(code) => {
            code.starts_with("reject_active_native_")
                && !code.contains("root")
                && !code.contains("nonce")
                && !code.contains("seed")
                && !code.contains("syndrome")
                && !code.contains("unsupported")
        }
        None => true,
    }
}

fn path2_native_public_report_excludes_private_material_v1(rendered: &str) -> bool {
    [
        "AuthorizationLocal",
        "private_signing",
        "private_trapdoor",
        "raw_pad_seed",
        "pad_seed",
        "pad_source",
        "opening_tuple",
        "opening_commitment",
        "opening_preimage",
        "unmasked_projection",
        "account_projection",
        "gauge",
        "randomizer",
        "blinding",
        "transparent_query_opening",
        "range_witness",
        "digit_witness",
        "carrier_transcript_binding",
        "projection_carrier",
        "checked_core_signature_or_proof_bytes",
        "root_entropy",
        "account_nonce",
        "authorization_local_seed",
        "proof_randomizer_syndrome",
        "unsupported authorization",
    ]
    .iter()
    .all(|needle| !rendered.contains(needle))
}

pub fn path2_native_signer_constant_time_stage_report_from_reports_v1(
    success_report: &Path2NativeSignerExecutionReportV1,
    rejection_report: &Path2NativeSignerExecutionReportV1,
) -> Result<Path2NativeSignerConstantTimeStageReportV1, String> {
    let stage_labels = path2_native_signer_constant_time_stage_labels_v1();
    let success_execution_report_digest =
        path2_native_signer_execution_report_v1_digest(success_report)?;
    let rejection_execution_report_digest =
        path2_native_signer_execution_report_v1_digest(rejection_report)?;
    let rejection_codes_public_only =
        path2_native_signer_rejection_code_is_public_v1(success_report.rejection_code)
            && path2_native_signer_rejection_code_is_public_v1(rejection_report.rejection_code);

    Ok(Path2NativeSignerConstantTimeStageReportV1 {
        schema: PATH2_NATIVE_SIGNER_CONSTANT_TIME_STAGE_REPORT_SCHEMA,
        audit_complete: false,
        fixed_public_schedule_required: true,
        current_implementation_claims_constant_time: false,
        stage_count: PATH2_NATIVE_SIGNER_CT_STAGE_COUNT as u8,
        stage_labels,
        success_execution_report_digest,
        rejection_execution_report_digest,
        success_rejection_same_stage_shape: success_report.schema
            == PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA
            && rejection_report.schema == PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA
            && stage_labels == path2_native_signer_constant_time_stage_labels_v1(),
        rejection_codes_public_only,
        cleanup_policy: "constant public stage schedule required; current report proves only sanitized public reporting",
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        deployment_preflight: path2_native_deployment_preflight_v1(),
    })
}

pub fn path2_native_signer_constant_time_stage_report_v1_digest(
    report: &Path2NativeSignerConstantTimeStageReportV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(
        Sha256::digest(path2_native_signer_constant_time_stage_report_v1_frame(
            report,
        )?)
        .into(),
    )
}

pub fn path2_native_signer_constant_time_stage_report_v1_frame(
    report: &Path2NativeSignerConstantTimeStageReportV1,
) -> Result<Vec<u8>, String> {
    let deployment_preflight_digest =
        path2_native_deployment_preflight_v1_digest(&report.deployment_preflight)?;
    let mut frame = Vec::new();
    append_frame(&mut frame, b"schema", report.schema.as_bytes());
    append_u64(
        &mut frame,
        b"audit_complete",
        u64::from(report.audit_complete),
    );
    append_u64(
        &mut frame,
        b"fixed_public_schedule_required",
        u64::from(report.fixed_public_schedule_required),
    );
    append_u64(
        &mut frame,
        b"current_implementation_claims_constant_time",
        u64::from(report.current_implementation_claims_constant_time),
    );
    append_u64(&mut frame, b"stage_count", report.stage_count as u64);
    for label in &report.stage_labels {
        append_frame(&mut frame, b"stage_label", label.as_bytes());
    }
    append_frame(
        &mut frame,
        b"success_execution_report_digest",
        &report.success_execution_report_digest,
    );
    append_frame(
        &mut frame,
        b"rejection_execution_report_digest",
        &report.rejection_execution_report_digest,
    );
    append_u64(
        &mut frame,
        b"success_rejection_same_stage_shape",
        u64::from(report.success_rejection_same_stage_shape),
    );
    append_u64(
        &mut frame,
        b"rejection_codes_public_only",
        u64::from(report.rejection_codes_public_only),
    );
    append_frame(
        &mut frame,
        b"cleanup_policy",
        report.cleanup_policy.as_bytes(),
    );
    append_frame(&mut frame, b"blocker", report.blocker.as_bytes());
    append_frame(
        &mut frame,
        b"deployment_preflight_digest",
        &deployment_preflight_digest,
    );
    Ok(frame)
}

fn path2_native_signer_entropy_q_source_window_v1() -> &'static str {
    let source = include_str!("production_reference.rs");
    let start = source
        .find("fn path2_native_signer_entropy_q_v1(")
        .expect("Path 2 native signer q sampler source start marker missing");
    let end = source[start..]
        .find("pub fn path2_native_secret_material_from_entropy_root_v1(")
        .expect("Path 2 native signer q sampler source end marker missing")
        + start;
    &source[start..end]
}

pub fn path2_native_signer_ct_source_audit_v1() -> Path2NativeSignerCtSourceAuditV1 {
    let source_window = path2_native_signer_entropy_q_source_window_v1();
    let no_runtime_modulo_or_division_tokens =
        !source_window.contains('%') && !source_window.contains('/');
    Path2NativeSignerCtSourceAuditV1 {
        schema: PATH2_NATIVE_SIGNER_CT_SOURCE_AUDIT_SCHEMA,
        audited_function: "path2_native_signer_entropy_q_v1",
        source_shape_audit_complete: true,
        backend_audit_complete: false,
        fixed_attempt_loop_present: source_window
            .contains("0_u16..PATH2_NATIVE_SIGNER_ENTROPY_Q_FIXED_ATTEMPTS"),
        deterministic_fallback_present: source_window.contains("fallback")
            && source_window.contains("Ok((selected & found_mask) | (fallback & !found_mask))"),
        mask_select_present: source_window.contains("valid_mask")
            && source_window.contains("take_mask")
            && source_window.contains("selected = (selected & !take_mask) | (reduced & take_mask)"),
        no_runtime_modulo_or_division_tokens,
        no_sampler_exhaustion_error: !source_window.contains("sampler exhausted")
            && !source_window.contains("return Err")
            && !source_window.contains("Err("),
        fixed_digest_byte_loads_only: source_window.contains("digest[0]")
            && source_window.contains("digest[1]")
            && !source_window.contains("digest[idx]")
            && !source_window.contains("digest[lane]")
            && !source_window.contains("digest[attempt"),
        source_window_digest: Sha256::digest(source_window.as_bytes()).into(),
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        explicit_non_claims: [
            "source-shape audit is not compiler assembly audit",
            "source-shape audit is not microarchitectural timing evidence",
            "source-shape audit is limited to signer entropy q sampler",
        ],
    }
}

pub fn path2_native_signer_ct_source_audit_v1_digest(
    report: &Path2NativeSignerCtSourceAuditV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(path2_native_signer_ct_source_audit_v1_frame(report)).into())
}

pub fn path2_native_signer_ct_source_audit_v1_frame(
    report: &Path2NativeSignerCtSourceAuditV1,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(&mut frame, b"schema", report.schema.as_bytes());
    append_frame(
        &mut frame,
        b"audited_function",
        report.audited_function.as_bytes(),
    );
    append_u64(
        &mut frame,
        b"source_shape_audit_complete",
        u64::from(report.source_shape_audit_complete),
    );
    append_u64(
        &mut frame,
        b"backend_audit_complete",
        u64::from(report.backend_audit_complete),
    );
    append_u64(
        &mut frame,
        b"fixed_attempt_loop_present",
        u64::from(report.fixed_attempt_loop_present),
    );
    append_u64(
        &mut frame,
        b"deterministic_fallback_present",
        u64::from(report.deterministic_fallback_present),
    );
    append_u64(
        &mut frame,
        b"mask_select_present",
        u64::from(report.mask_select_present),
    );
    append_u64(
        &mut frame,
        b"no_runtime_modulo_or_division_tokens",
        u64::from(report.no_runtime_modulo_or_division_tokens),
    );
    append_u64(
        &mut frame,
        b"no_sampler_exhaustion_error",
        u64::from(report.no_sampler_exhaustion_error),
    );
    append_u64(
        &mut frame,
        b"fixed_digest_byte_loads_only",
        u64::from(report.fixed_digest_byte_loads_only),
    );
    append_frame(
        &mut frame,
        b"source_window_digest",
        &report.source_window_digest,
    );
    append_frame(&mut frame, b"blocker", report.blocker.as_bytes());
    for non_claim in &report.explicit_non_claims {
        append_frame(&mut frame, b"explicit_non_claim", non_claim.as_bytes());
    }
    frame
}

fn path2_native_signer_execution_report_has_no_private_digests_v1(
    report: &Path2NativeSignerExecutionReportV1,
) -> bool {
    report.signer_public_output_digest.is_none()
        && report.carrier_digest.is_none()
        && report.native_boundary_digest.is_none()
        && report.checked_core_proof_digest.is_none()
}

pub fn path2_native_signer_rejection_cleanup_audit_v1(
    success_report: &Path2NativeSignerExecutionReportV1,
    constructor_rejection_report: &Path2NativeSignerExecutionReportV1,
    entropy_rejection_report: &Path2NativeSignerExecutionReportV1,
) -> Result<Path2NativeSignerRejectionCleanupAuditV1, String> {
    let success_report_digest = path2_native_signer_execution_report_v1_digest(success_report)?;
    let constructor_rejection_report_digest =
        path2_native_signer_execution_report_v1_digest(constructor_rejection_report)?;
    let entropy_rejection_report_digest =
        path2_native_signer_execution_report_v1_digest(entropy_rejection_report)?;
    let all_rejection_digests_absent =
        path2_native_signer_execution_report_has_no_private_digests_v1(
            constructor_rejection_report,
        ) && path2_native_signer_execution_report_has_no_private_digests_v1(
            entropy_rejection_report,
        );
    let all_rejection_codes_public_only =
        path2_native_signer_rejection_code_is_public_v1(success_report.rejection_code)
            && path2_native_signer_rejection_code_is_public_v1(
                constructor_rejection_report.rejection_code,
            )
            && path2_native_signer_rejection_code_is_public_v1(
                entropy_rejection_report.rejection_code,
            );
    let success_rendered = serde_json::to_string(success_report)
        .map_err(|err| format!("encode signer success cleanup report: {err}"))?;
    let constructor_rendered = serde_json::to_string(constructor_rejection_report)
        .map_err(|err| format!("encode signer constructor rejection cleanup report: {err}"))?;
    let entropy_rendered = serde_json::to_string(entropy_rejection_report)
        .map_err(|err| format!("encode signer entropy rejection cleanup report: {err}"))?;
    let all_reports_private_material_absent =
        path2_native_public_report_excludes_private_material_v1(&success_rendered)
            && path2_native_public_report_excludes_private_material_v1(&constructor_rendered)
            && path2_native_public_report_excludes_private_material_v1(&entropy_rendered);
    let public_error_surface_complete = success_report.schema
        == PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA
        && constructor_rejection_report.schema == PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA
        && entropy_rejection_report.schema == PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA
        && constructor_rejection_report.rejection_code
            == Some("reject_active_native_signer_constructor_failed")
        && entropy_rejection_report.rejection_code
            == Some("reject_active_native_signer_entropy_failed")
        && all_rejection_digests_absent
        && all_rejection_codes_public_only
        && all_reports_private_material_absent;

    Ok(Path2NativeSignerRejectionCleanupAuditV1 {
        schema: PATH2_NATIVE_SIGNER_REJECTION_CLEANUP_AUDIT_SCHEMA,
        audit_complete: false,
        public_error_surface_complete,
        cleanup_zeroization_claim_complete: false,
        success_report_digest,
        constructor_rejection_report_digest,
        entropy_rejection_report_digest,
        constructor_rejection_code: constructor_rejection_report.rejection_code,
        entropy_rejection_code: entropy_rejection_report.rejection_code,
        all_rejection_digests_absent,
        all_rejection_codes_public_only,
        all_reports_private_material_absent,
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        deployment_preflight: path2_native_deployment_preflight_v1(),
        explicit_non_claims: [
            "public report cleanup is not whole-signer timing evidence",
            "public report cleanup is not allocator memory inspection",
            "public report cleanup is not operating-system entropy validation",
        ],
    })
}

pub fn path2_native_signer_rejection_cleanup_audit_v1_digest(
    report: &Path2NativeSignerRejectionCleanupAuditV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(
        Sha256::digest(path2_native_signer_rejection_cleanup_audit_v1_frame(
            report,
        )?)
        .into(),
    )
}

pub fn path2_native_signer_rejection_cleanup_audit_v1_frame(
    report: &Path2NativeSignerRejectionCleanupAuditV1,
) -> Result<Vec<u8>, String> {
    let deployment_preflight_digest =
        path2_native_deployment_preflight_v1_digest(&report.deployment_preflight)?;
    let mut frame = Vec::new();
    append_frame(&mut frame, b"schema", report.schema.as_bytes());
    append_u64(
        &mut frame,
        b"audit_complete",
        u64::from(report.audit_complete),
    );
    append_u64(
        &mut frame,
        b"public_error_surface_complete",
        u64::from(report.public_error_surface_complete),
    );
    append_u64(
        &mut frame,
        b"cleanup_zeroization_claim_complete",
        u64::from(report.cleanup_zeroization_claim_complete),
    );
    append_frame(
        &mut frame,
        b"success_report_digest",
        &report.success_report_digest,
    );
    append_frame(
        &mut frame,
        b"constructor_rejection_report_digest",
        &report.constructor_rejection_report_digest,
    );
    append_frame(
        &mut frame,
        b"entropy_rejection_report_digest",
        &report.entropy_rejection_report_digest,
    );
    append_u64(
        &mut frame,
        b"constructor_rejection_code_present",
        u64::from(report.constructor_rejection_code.is_some()),
    );
    if let Some(code) = report.constructor_rejection_code {
        append_frame(&mut frame, b"constructor_rejection_code", code.as_bytes());
    }
    append_u64(
        &mut frame,
        b"entropy_rejection_code_present",
        u64::from(report.entropy_rejection_code.is_some()),
    );
    if let Some(code) = report.entropy_rejection_code {
        append_frame(&mut frame, b"entropy_rejection_code", code.as_bytes());
    }
    append_u64(
        &mut frame,
        b"all_rejection_digests_absent",
        u64::from(report.all_rejection_digests_absent),
    );
    append_u64(
        &mut frame,
        b"all_rejection_codes_public_only",
        u64::from(report.all_rejection_codes_public_only),
    );
    append_u64(
        &mut frame,
        b"all_reports_private_material_absent",
        u64::from(report.all_reports_private_material_absent),
    );
    append_frame(&mut frame, b"blocker", report.blocker.as_bytes());
    append_frame(
        &mut frame,
        b"deployment_preflight_digest",
        &deployment_preflight_digest,
    );
    for non_claim in &report.explicit_non_claims {
        append_frame(&mut frame, b"explicit_non_claim", non_claim.as_bytes());
    }
    Ok(frame)
}

