fn path2_native_private_fiber_cleanup_source_window_v1() -> &'static str {
    let source = include_str!("production_reference.rs");
    let start = source
        .find("fn path2_native_private_fiber_from_secret_material_v1(")
        .expect("Path 2 native private fiber cleanup source start marker missing");
    let end = source[start..]
        .find("pub fn path2_native_checked_core_proof_from_bundle_v1(")
        .expect("Path 2 native private fiber cleanup source end marker missing")
        + start;
    &source[start..end]
}

fn path2_native_zeroize_source_window_v1() -> &'static str {
    let source = include_str!("production_reference.rs");
    let start = source
        .find("#[inline(never)]\nfn path2_native_zeroize_bytes_v1(")
        .expect("Path 2 native zeroize source start marker missing");
    let end = source[start..]
        .find("impl Drop for Path2NativeSignerEntropyRootV1")
        .expect("Path 2 native zeroize source end marker missing")
        + start;
    &source[start..end]
}

pub fn path2_native_signer_runtime_cleanup_audit_v1() -> Path2NativeSignerRuntimeCleanupAuditV1 {
    let entropy_source = path2_native_signer_os_entropy_source_window_v1();
    let derivation_source = path2_native_secret_material_derivation_source_window_v1();
    let private_fiber_source = path2_native_private_fiber_cleanup_source_window_v1();
    let zeroize_source = path2_native_zeroize_source_window_v1();
    let cleanup_source = [
        zeroize_source.as_bytes(),
        entropy_source.as_bytes(),
        derivation_source.as_bytes(),
        private_fiber_source.as_bytes(),
    ]
    .concat();
    let owned_root_drop_present = entropy_source
        .contains("impl Drop for Path2NativeSignerEntropyRootV1")
        || include_str!("production_reference.rs")
            .contains("impl Drop for Path2NativeSignerEntropyRootV1");
    let owned_material_drop_present = include_str!("production_reference.rs")
        .contains("impl Drop for Path2NativeHonestConstructorSecretMaterialV1");
    let root_explicit_success_zeroize_present = derivation_source.contains("root.zeroize();");
    let root_failure_zeroize_present = entropy_source.matches("root.zeroize();").count() >= 2;
    let seed_component_zeroize_present =
        include_str!("production_reference.rs").contains("path2_native_zeroize_bytes_v1(seed);");
    let signer_digest_source = path2_native_signer_entropy_digest_source_window_v1();
    let constructor_digest_source = path2_native_secret_component_digest_source_window_v1();
    let signer_digest_uses_fixed_frame = signer_digest_source
        .contains("Path2NativeSignerDigestFrameV1::new()")
        && !signer_digest_source.contains("let mut frame = Vec::new();");
    let constructor_digest_uses_fixed_frame = constructor_digest_source
        .contains("Path2NativeSignerDigestFrameV1::new()")
        && !constructor_digest_source.contains("let mut frame = Vec::new();");
    let signer_digest_fixed_frame_zeroize_present =
        signer_digest_source.contains("frame.zeroize();");
    let constructor_digest_fixed_frame_zeroize_present =
        constructor_digest_source.contains("frame.zeroize();");
    let private_fiber_success_zeroize_present =
        private_fiber_source.contains("secret.zeroize();\n    Ok(private_fiber)");
    let private_fiber_error_zeroize_present = private_fiber_source
        .contains("secret.zeroize();\n                return Err(err);")
        && private_fiber_source.contains("secret.zeroize();\n        return Err(");
    let volatile_byte_zeroize_present = zeroize_source.contains("fn path2_native_zeroize_bytes_v1")
        && zeroize_source.contains("ptr::write_volatile(byte, 0)");
    let volatile_word_zeroize_present = zeroize_source.contains("fn path2_native_zeroize_u16s_v1")
        && zeroize_source.contains("ptr::write_volatile(word, 0)");
    let volatile_fixed_frame_zeroize_present = zeroize_source
        .contains("fn path2_native_zeroize_signer_digest_frame_v1")
        && zeroize_source.contains("ptr::write_volatile(byte, 0)");
    let compiler_fence_present = zeroize_source
        .matches("compiler_fence(Ordering::SeqCst);")
        .count()
        >= 3;
    let entropy_failure_report = path2_native_signer_execution_failure_report_v1(
        "reject_active_native_signer_entropy_failed",
    );
    let constructor_failure_report = path2_native_signer_execution_failure_report_v1(
        "reject_active_native_signer_constructor_failed",
    );
    let public_failure_reports_digest_only =
        path2_native_signer_execution_report_has_no_private_digests_v1(&entropy_failure_report)
            && path2_native_signer_execution_report_has_no_private_digests_v1(
                &constructor_failure_report,
            );
    let source_cleanup_complete = owned_root_drop_present
        && owned_material_drop_present
        && root_explicit_success_zeroize_present
        && root_failure_zeroize_present
        && seed_component_zeroize_present
        && signer_digest_uses_fixed_frame
        && constructor_digest_uses_fixed_frame
        && signer_digest_fixed_frame_zeroize_present
        && constructor_digest_fixed_frame_zeroize_present
        && private_fiber_success_zeroize_present
        && private_fiber_error_zeroize_present
        && volatile_byte_zeroize_present
        && volatile_word_zeroize_present
        && volatile_fixed_frame_zeroize_present
        && compiler_fence_present
        && public_failure_reports_digest_only;

    Path2NativeSignerRuntimeCleanupAuditV1 {
        schema: PATH2_NATIVE_SIGNER_RUNTIME_CLEANUP_AUDIT_SCHEMA,
        audit_complete: false,
        source_cleanup_complete,
        allocator_memory_inspection_complete: false,
        owned_root_drop_present,
        owned_material_drop_present,
        root_explicit_success_zeroize_present,
        root_failure_zeroize_present,
        seed_component_zeroize_present,
        signer_digest_uses_fixed_frame,
        constructor_digest_uses_fixed_frame,
        signer_digest_fixed_frame_zeroize_present,
        constructor_digest_fixed_frame_zeroize_present,
        private_fiber_success_zeroize_present,
        private_fiber_error_zeroize_present,
        volatile_byte_zeroize_present,
        volatile_word_zeroize_present,
        volatile_fixed_frame_zeroize_present,
        compiler_fence_present,
        public_failure_reports_digest_only,
        cleanup_source_digest: Sha256::digest(cleanup_source).into(),
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        explicit_non_claims: [
            "source cleanup audit is not allocator memory inspection",
            "source cleanup audit is not compiler dead-store-elimination proof",
            "source cleanup audit is not whole-signer timing evidence",
        ],
    }
}

