fn path2_native_function_source_window_v1(function_name: &str, next_marker: &str) -> &'static str {
    let source = include_str!("production_reference.rs");
    let start_marker = format!("\npub fn {function_name}(");
    let start = source
        .find(&start_marker)
        .unwrap_or_else(|| panic!("Path 2 native source start marker missing: {start_marker}"));
    let end = source[start..]
        .find(next_marker)
        .unwrap_or_else(|| panic!("Path 2 native source end marker missing: {next_marker}"))
        + start;
    &source[start..end]
}

pub fn path2_native_signer_production_routing_audit_v1() -> Path2NativeSignerProductionRoutingAuditV1
{
    let public_input_source = path2_native_function_source_window_v1(
        "path2_native_signer_execution_report_from_public_input_os_entropy_v1",
        "pub fn path2_native_signer_execution_report_from_os_entropy_v1(",
    );
    let prevalidated_os_source = path2_native_function_source_window_v1(
        "path2_native_signer_execution_report_from_prevalidated_os_entropy_v1",
        "pub fn path2_native_signer_execution_report_from_public_input_os_entropy_v1(",
    );
    let prevalidated_private_source = path2_native_function_source_window_v1(
        "path2_native_signer_execution_report_from_prevalidated_entropy_root_v1",
        "pub fn path2_native_signer_execution_report_from_prevalidated_os_entropy_v1(",
    );
    let production_public_input_entrypoint_present = public_input_source
        .contains("path2_native_signer_execution_report_from_public_input_os_entropy_v1");
    let production_public_input_entrypoint_prevalidates_first = public_input_source
        .contains("path2_native_signer_prevalidated_public_input_v1(bundle)")
        && public_input_source
            .contains("path2_native_signer_execution_report_from_prevalidated_os_entropy_v1");
    let production_public_input_entrypoint_avoids_direct_entropy =
        !public_input_source.contains("path2_native_signer_entropy_root_from_os_v1");
    let prevalidated_os_entrypoint_acquires_entropy =
        prevalidated_os_source.contains("path2_native_signer_entropy_root_from_os_v1()");
    let prevalidated_private_entrypoint_requires_wrapper = prevalidated_private_source
        .contains("prevalidated: Path2NativeSignerPrevalidatedPublicInputV1")
        && prevalidated_private_source
            .contains("path2_native_honest_constructor_from_prevalidated_entropy_root_v1");
    let invalid_public_input_rejected_before_entropy =
        production_public_input_entrypoint_prevalidates_first
            && production_public_input_entrypoint_avoids_direct_entropy;
    let full_source = include_str!("production_reference.rs");
    let legacy_direct_entrypoints_retained_for_negative_controls = full_source
        .contains("pub fn path2_native_signer_execution_report_from_entropy_root_v1(")
        && full_source.contains("constructor_rejection_total_ns");
    let source_routing_complete = production_public_input_entrypoint_present
        && production_public_input_entrypoint_prevalidates_first
        && production_public_input_entrypoint_avoids_direct_entropy
        && prevalidated_os_entrypoint_acquires_entropy
        && prevalidated_private_entrypoint_requires_wrapper
        && invalid_public_input_rejected_before_entropy;

    Path2NativeSignerProductionRoutingAuditV1 {
        schema: PATH2_NATIVE_SIGNER_PRODUCTION_ROUTING_AUDIT_SCHEMA,
        audit_complete: false,
        source_routing_complete,
        production_public_input_entrypoint_present,
        production_public_input_entrypoint_prevalidates_first,
        production_public_input_entrypoint_avoids_direct_entropy,
        prevalidated_os_entrypoint_acquires_entropy,
        prevalidated_private_entrypoint_requires_wrapper,
        invalid_public_input_rejected_before_entropy,
        legacy_direct_entrypoints_retained_for_negative_controls,
        public_input_entrypoint_source_digest: Sha256::digest(public_input_source.as_bytes())
            .into(),
        prevalidated_os_entrypoint_source_digest: Sha256::digest(prevalidated_os_source.as_bytes())
            .into(),
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        explicit_non_claims: [
            "production routing audit is source-level entrypoint evidence only",
            "production routing audit is not whole-signer timing evidence",
            "legacy direct entrypoints remain available for tests and negative controls",
        ],
    }
}

