pub fn path2_native_signer_ct_evidence_ledger_v1() -> Path2NativeSignerCtEvidenceLedgerV1 {
    let q_sampler_source = path2_native_signer_ct_source_audit_v1();
    let sha256_boundary = path2_native_signer_sha256_boundary_audit_v1();
    let sha256_schedule = path2_native_signer_sha256_call_schedule_audit_v1();
    let runtime_cleanup = path2_native_signer_runtime_cleanup_audit_v1();
    let production_routing = path2_native_signer_production_routing_audit_v1();
    let backend_scripts = path2_native_signer_ct_backend_script_bundle_v1();

    let q_sampler_release_backend_script_pinned = backend_scripts
        .contains("path2_native_signer_entropy_q_v1")
        && backend_scripts.contains("digest_call_count");
    let sha256_dependency_backend_script_pinned = backend_scripts.contains("sha2_version")
        && backend_scripts.contains("sha2_asm_dependency_present=0");
    let sha256_source_backend_script_pinned = backend_scripts
        .contains("force_soft_feature_enabled")
        && backend_scripts.contains("runtime_x86_dispatch_selected=0")
        && backend_scripts.contains("constant_time_claim_complete=0");
    let sha256_release_backend_script_pinned = backend_scripts
        .contains("force_soft_release_backend_selected")
        && backend_scripts.contains("public_cpufeature_dispatch_present=0")
        && backend_scripts.contains("sha256rnds2_count=0");
    let sha256_soft_ct_shape_script_pinned = backend_scripts
        .contains("Descender.Path2.NativeSignerSha256SoftCtShapeAudit.v1")
        && backend_scripts.contains("assembly_conditional_branches")
        && backend_scripts.contains("assembly_variable_shifts=0")
        && backend_scripts.contains("assembly_allocator_mem_sha_ni_dispatch_markers=0");
    let private_sha256_ct_shape_script_pinned = backend_scripts
        .contains("Descender.Path2.NativeSignerPrivateSha256CtShapeAudit.v1")
        && backend_scripts.contains("source_fixed_round_loop_present=1")
        && backend_scripts.contains("assembly_public_loop_conditional_branches")
        && backend_scripts.contains("assembly_public_length_memroutine_calls=0")
        && backend_scripts.contains("assembly_zeroize_calls=3")
        && backend_scripts.contains("assembly_allocator_sha_ni_dispatch_markers=0");
    let sha256_private_hash_lifetime_audit_pinned = backend_scripts
        .contains("Descender.Path2.NativeSignerSha256InternalStateLifetimeAudit.v1")
        && backend_scripts.contains("active_private_sha256_path=1")
        && backend_scripts.contains("upstream_private_sha256_digest_calls=0")
        && backend_scripts.contains("private_sha256_workspace_zeroize_present=1")
        && backend_scripts.contains("private_sha256_schedule_zeroize_present=1")
        && backend_scripts.contains("private_sha256_state_zeroize_present=1")
        && backend_scripts.contains("internal_state_lifetime_source_cleanup_complete=1")
        && backend_scripts.contains("release_digest_output_written_before_internal_cleanup=1")
        && backend_scripts.contains("release_internal_stack_lifetime_claim_complete=1")
        && backend_scripts.contains("release_residual_register_lifetime_claim_complete=0");
    let register_residual_audit_script_pinned = backend_scripts
        .contains("Descender.Path2.NativeSignerRegisterResidualAudit.v1")
        && backend_scripts.contains("private_sha_output_before_cleanup=1")
        && backend_scripts.contains("entropy_wrapper_local_digest_zeroized_after_output_copy=1")
        && backend_scripts.contains("secret_wrapper_seed_and_local_digest_zeroized=1")
        && backend_scripts.contains("wrapper_xmm_digest_copy_registers_observed=1")
        && backend_scripts.contains("general_register_scrub_complete=0")
        && backend_scripts.contains("simd_register_scrub_complete=0")
        && backend_scripts.contains("register_residual_lifetime_claim_complete=0");
    let register_scrub_policy_script_pinned = backend_scripts
        .contains("Descender.Path2.NativeSignerRegisterScrubPolicy.v1")
        && backend_scripts.contains("target_toolchain_policy_required=1")
        && backend_scripts.contains("accepted_closure_option_1")
        && backend_scripts.contains("accepted_closure_option_2")
        && backend_scripts.contains("accepted_closure_option_3")
        && backend_scripts.contains("register_scrub_policy_complete=0");
    let target_host_timing_campaign_script_pinned = backend_scripts
        .contains("Descender.Path2.NativeSignerTargetHostTimingCampaign.v1")
        && backend_scripts.contains("target_host_bundle_archived=1")
        && backend_scripts.contains("microarchitectural_timing_claim_complete=0")
        && backend_scripts.contains("register_scrub_policy_output_sha256")
        && backend_scripts.contains("timing_stability_output_sha256");
    let target_host_campaign_promotion_gate_script_pinned = backend_scripts
        .contains("Descender.Path2.NativeSignerTargetHostCampaignPromotionGate.v1")
        && backend_scripts.contains("PATH2_NATIVE_SIGNER_PROMOTION_MIN_TIMING_ITERS")
        && backend_scripts.contains("target_host_campaign_thresholds_met=1")
        && backend_scripts.contains("target_host_artifact_hashes_verified=1")
        && backend_scripts.contains("release_promotion_claim_complete=0")
        && backend_scripts.contains("constant_time_claim_complete=0");
    let digest_frame_release_backend_script_pinned = backend_scripts
        .contains("path2_native_signer_entropy_digest_v1")
        && backend_scripts.contains("path2_native_digest_secret_component_v1")
        && backend_scripts.contains("fixed_frame_zeroize_calls")
        && backend_scripts.contains("entropy_local_digest_zeroize_calls")
        && backend_scripts.contains("secret_seed_and_local_digest_zeroize_calls");
    let zeroize_release_backend_script_pinned = backend_scripts
        .contains("path2_native_zeroize_signer_digest_frame_v1")
        && backend_scripts.contains("digest_frame_loop_bound_bytes");
    let production_routing_release_backend_script_pinned = backend_scripts
        .contains("path2_native_signer_execution_report_from_public_input_os_entropy_v1")
        && backend_scripts.contains("public_entropy_calls");
    let prevalidated_timing_stability_script_pinned = backend_scripts
        .contains("path2_native_signer_prevalidated_timing_probe.sh")
        && backend_scripts.contains("max_ratio_micros");
    let ct_evidence_bundle_script_pinned = backend_scripts
        .contains(PATH2_NATIVE_SIGNER_CT_EVIDENCE_BUNDLE_SCHEMA)
        && backend_scripts.contains("bundle_payload_sha256")
        && backend_scripts.contains("environment_manifest_sha256")
        && backend_scripts.contains("target_host_execution_claim_complete=0")
        && backend_scripts.contains("constant_time_claim_complete=0");
    let ct_evidence_bundle_preserves_outputs_when_requested = backend_scripts
        .contains("PATH2_NATIVE_SIGNER_CT_EVIDENCE_OUT_DIR")
        && backend_scripts.contains("audit_output_path")
        && backend_scripts.contains("environment_manifest_path")
        && backend_scripts.contains("manifest_path");
    let source_evidence_complete = q_sampler_source.source_shape_audit_complete
        && sha256_boundary.source_boundary_complete
        && sha256_schedule.source_schedule_complete
        && runtime_cleanup.source_cleanup_complete
        && production_routing.source_routing_complete;
    let backend_evidence_scripts_pinned = q_sampler_release_backend_script_pinned
        && sha256_dependency_backend_script_pinned
        && sha256_source_backend_script_pinned
        && sha256_release_backend_script_pinned
        && sha256_soft_ct_shape_script_pinned
        && private_sha256_ct_shape_script_pinned
        && sha256_private_hash_lifetime_audit_pinned
        && register_residual_audit_script_pinned
        && register_scrub_policy_script_pinned
        && target_host_timing_campaign_script_pinned
        && target_host_campaign_promotion_gate_script_pinned
        && digest_frame_release_backend_script_pinned
        && zeroize_release_backend_script_pinned
        && production_routing_release_backend_script_pinned
        && prevalidated_timing_stability_script_pinned
        && ct_evidence_bundle_script_pinned
        && ct_evidence_bundle_preserves_outputs_when_requested;

    Path2NativeSignerCtEvidenceLedgerV1 {
        schema: PATH2_NATIVE_SIGNER_CT_EVIDENCE_LEDGER_SCHEMA,
        ledger_complete: false,
        source_evidence_complete,
        backend_evidence_scripts_pinned,
        q_sampler_source_shape_complete: q_sampler_source.source_shape_audit_complete,
        q_sampler_release_backend_script_pinned,
        sha256_boundary_source_complete: sha256_boundary.source_boundary_complete,
        sha256_call_schedule_source_complete: sha256_schedule.source_schedule_complete,
        sha256_dependency_backend_script_pinned,
        sha256_source_backend_script_pinned,
        sha256_release_backend_script_pinned,
        sha256_soft_ct_shape_script_pinned,
        private_sha256_ct_shape_script_pinned,
        sha256_private_hash_lifetime_audit_pinned,
        register_residual_audit_script_pinned,
        register_scrub_policy_script_pinned,
        target_host_timing_campaign_script_pinned,
        target_host_campaign_promotion_gate_script_pinned,
        digest_frame_release_backend_script_pinned,
        zeroize_release_backend_script_pinned,
        runtime_cleanup_source_complete: runtime_cleanup.source_cleanup_complete,
        production_routing_source_complete: production_routing.source_routing_complete,
        production_routing_release_backend_script_pinned,
        prevalidated_timing_stability_script_pinned,
        ct_evidence_bundle_script_pinned,
        ct_evidence_bundle_preserves_outputs_when_requested,
        timing_evidence_is_smoke_only: true,
        sha256_backend_constant_time_claim_complete: false,
        whole_signer_microarchitectural_timing_complete: false,
        register_and_internal_hash_state_lifetime_complete: false,
        target_host_evidence_bundle_execution_complete: false,
        constant_time_audit_complete: false,
        backend_script_bundle_digest: Sha256::digest(backend_scripts.as_bytes()).into(),
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        remaining_blockers: [
            "prove private SHA-256 backend constant-time and release residual-lifetime assumptions",
            "complete whole-signer microarchitectural timing campaign beyond smoke evidence",
            "close register, spill, and post-cleanup residual lifetime evidence",
            "promote release backend audit outputs into reproducible deployment artifacts",
        ],
        explicit_non_claims: [
            "script pinning is not proof that release audits were executed on a target host",
            "timing-stability smoke evidence is not a distributional leakage proof",
            "constant-time deployment blocker remains active",
        ],
    }
}

