#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductionRejectionReportFields {
    pub proof_model: &'static str,
    pub expected_signature_bytes: usize,
    pub slot_id: Option<u32>,
    pub claimed_challenge: Option<[u8; CHALLENGE_BYTES]>,
    pub reason: String,
}

pub fn rejection_report_fields(
    signature: &ProductionSignature,
    rejection: ProductionVerificationRejection,
) -> ProductionRejectionReportFields {
    let claimed_challenge = signature
        .as_bytes()
        .get(SLOT_ID_BYTES..SLOT_ID_BYTES + CHALLENGE_BYTES)
        .and_then(|bytes| bytes.try_into().ok());
    ProductionRejectionReportFields {
        proof_model: PRODUCTION_REFERENCE_FACADE_PROOF_MODEL,
        expected_signature_bytes: LINEAR_SIGMA_TARGET_TRANSACTION_SIGNATURE_BYTES,
        slot_id: rejection.slot_id(),
        claimed_challenge,
        reason: rejection.into_reason(),
    }
}

