pub fn validate_public_key_bytes(public_key: &[u8]) -> Result<(), String> {
    if public_key.len() != PK_BYTES {
        return Err(format!(
            "public key has {} bytes, expected {PK_BYTES}",
            public_key.len()
        ));
    }
    unpack_q_elements(&public_key[PK_SEED_BYTES..], VIEW_COORDS).map(|_| ())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ProductionAccountCommitment {
    bytes: [u8; REVIEWED_ACCOUNT_LINK_BYTES],
}

impl ProductionAccountCommitment {
    pub fn new(
        witness_commitment: [u8; DIGEST_BYTES],
        randomizer_commitment: [u8; DIGEST_BYTES],
    ) -> Self {
        let mut bytes = [0_u8; REVIEWED_ACCOUNT_LINK_BYTES];
        bytes[..DIGEST_BYTES].copy_from_slice(&witness_commitment);
        bytes[DIGEST_BYTES..2 * DIGEST_BYTES].copy_from_slice(&randomizer_commitment);
        bytes[2 * DIGEST_BYTES..].copy_from_slice(&reviewed_response_link_code());
        Self { bytes }
    }

    pub fn from_bytes(bytes: [u8; REVIEWED_ACCOUNT_LINK_BYTES]) -> Result<Self, String> {
        let commitment = Self { bytes };
        commitment.validate()?;
        Ok(commitment)
    }

    pub fn from_bytes_unchecked_for_test(bytes: [u8; REVIEWED_ACCOUNT_LINK_BYTES]) -> Self {
        Self { bytes }
    }

    pub fn as_bytes(&self) -> &[u8; REVIEWED_ACCOUNT_LINK_BYTES] {
        &self.bytes
    }

    pub fn witness_commitment(&self) -> [u8; DIGEST_BYTES] {
        self.bytes[..DIGEST_BYTES].try_into().unwrap()
    }

    pub fn randomizer_commitment(&self) -> [u8; DIGEST_BYTES] {
        self.bytes[DIGEST_BYTES..2 * DIGEST_BYTES]
            .try_into()
            .unwrap()
    }

    pub fn response_link_code(&self) -> [u8; REVIEWED_ACCOUNT_RESPONSE_LINK_CODE_BYTES] {
        self.bytes[2 * DIGEST_BYTES..].try_into().unwrap()
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.response_link_code() != reviewed_response_link_code() {
            return Err("account response-link code mismatch".to_string());
        }
        if unpack_q_syndrome_digest(&self.witness_commitment()).is_none() {
            return Err("account witness commitment is not canonical".to_string());
        }
        if unpack_q_syndrome_digest(&self.randomizer_commitment()).is_none() {
            return Err("account randomizer commitment is not canonical".to_string());
        }
        Ok(())
    }
}

pub fn validate_reviewed_fq12_state_assisted_account_commitment(
    commitment: &ProductionAccountCommitment,
) -> Result<(), String> {
    if commitment.response_link_code() != reviewed_response_link_code() {
        return Err("account response-link code mismatch".to_string());
    }
    if unpack_reviewed_fq12_account_carried_syndrome_digest(&commitment.witness_commitment())
        .is_err()
        && unpack_reviewed_fq12_packed_witness_state18(&commitment.witness_commitment()).is_err()
    {
        return Err("account witness commitment is not canonical".to_string());
    }
    if unpack_reviewed_fq12_account_carried_syndrome_digest(&commitment.randomizer_commitment())
        .is_err()
    {
        return Err("account randomizer commitment is not canonical".to_string());
    }
    Ok(())
}

pub fn reviewed_response_link_code() -> [u8; REVIEWED_ACCOUNT_RESPONSE_LINK_CODE_BYTES] {
    // Two little-endian u16 coordinates: [0, 3].
    [0, 0, 3, 0]
}

