#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductionAccountState {
    slots: Vec<ProductionAccountSlot>,
}

impl ProductionAccountState {
    pub fn new(slots: Vec<ProductionAccountSlot>) -> Result<Self, String> {
        for (idx, slot) in slots.iter().enumerate() {
            if slot.slot_id() as usize != idx {
                return Err("account slots must be sorted by slot id".to_string());
            }
            slot.commitment().validate()?;
        }
        Ok(Self { slots })
    }

    pub fn slots(&self) -> &[ProductionAccountSlot] {
        &self.slots
    }

    pub fn len(&self) -> usize {
        self.slots.len()
    }

    pub fn is_empty(&self) -> bool {
        self.slots.is_empty()
    }

    pub fn get_slot(&self, slot_id: u32) -> Option<&ProductionAccountSlot> {
        self.slots.get(slot_id as usize)
    }

    pub fn checked_slot_records(&self) -> Result<Vec<ProductionAccountSlotRecord>, String> {
        let mut records = Vec::with_capacity(self.slots.len());
        for (idx, slot) in self.slots.iter().enumerate() {
            if slot.slot_id() as usize != idx {
                return Err("account slots must be sorted by slot id".to_string());
            }
            slot.commitment().validate()?;
            records.push(ProductionAccountSlotRecord {
                slot_id: slot.slot_id(),
                witness_commitment: slot.commitment().witness_commitment(),
                randomizer_commitment: slot.commitment().randomizer_commitment(),
                unused: slot.is_unused(),
            });
        }
        Ok(records)
    }

    pub fn project_checked_slot_records<R, F>(&self, project: F) -> Result<R, String>
    where
        F: FnOnce(&[ProductionAccountSlotRecord]) -> Result<R, String>,
    {
        let records = self.checked_slot_records()?;
        project(&records)
    }

    pub fn mark_consumed(&mut self, slot_id: u32) -> Result<(), String> {
        let slot = self
            .slots
            .get_mut(slot_id as usize)
            .ok_or_else(|| "slot id is out of range".to_string())?;
        slot.mark_consumed();
        Ok(())
    }

    pub fn replace_slot_commitment_for_test(
        &mut self,
        slot_id: u32,
        commitment: ProductionAccountCommitment,
    ) -> Result<(), String> {
        let slot = self
            .slots
            .get_mut(slot_id as usize)
            .ok_or_else(|| "slot id is out of range".to_string())?;
        slot.replace_commitment_for_test(commitment);
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductionSignature {
    bytes: Vec<u8>,
}

impl ProductionSignature {
    pub fn new(bytes: Vec<u8>) -> Self {
        Self { bytes }
    }

    pub fn as_bytes(&self) -> &[u8] {
        &self.bytes
    }

    pub fn len(&self) -> usize {
        self.bytes.len()
    }

    pub fn is_empty(&self) -> bool {
        self.bytes.is_empty()
    }

    pub fn decode(&self) -> Result<ProductionSignatureParts, String> {
        decode_production_signature(self.as_bytes())
    }

    pub fn decode_reviewed_account_carried(
        &self,
    ) -> Result<ProductionReviewedAccountCarriedSignatureParts, String> {
        decode_reviewed_account_carried_signature(self.as_bytes())
    }

    pub fn decode_reviewed_fq12_account_carried(
        &self,
    ) -> Result<ProductionReviewedFq12AccountCarriedSignatureParts, String> {
        decode_reviewed_fq12_account_carried_signature(self.as_bytes())
    }

    pub fn decode_reviewed_fq12_account_carried_with_hidden_source_proof(
        &self,
    ) -> Result<ProductionReviewedFq12AccountCarriedWithHiddenSourceProof, String> {
        decode_reviewed_fq12_account_carried_with_hidden_source_proof(self.as_bytes())
    }

    pub fn decode_reviewed_fq12_account_carried_with_fallback_projection(
        &self,
    ) -> Result<ProductionReviewedFq12AccountCarriedWithFallbackProjection, String> {
        decode_reviewed_fq12_account_carried_with_fallback_projection(self.as_bytes())
    }
}

pub fn account_state_from_slot_seeds<I>(
    seeds: I,
    randomizer_commitment: [u8; DIGEST_BYTES],
) -> Result<ProductionAccountState, String>
where
    I: IntoIterator<Item = ProductionAccountSlotSeed>,
{
    let slots = seeds
        .into_iter()
        .enumerate()
        .map(|(slot_id, seed)| {
            ProductionAccountSlot::with_used_state(
                slot_id as u32,
                ProductionAccountCommitment::new(seed.witness_commitment, randomizer_commitment),
                seed.unused,
            )
        })
        .collect();
    ProductionAccountState::new(slots)
}

pub fn reviewed_fq12_state_assisted_account_state_from_slot_records<I>(
    records: I,
) -> Result<ProductionReviewedFq12StateAssistedAccountState, String>
where
    I: IntoIterator<Item = ProductionReviewedFq12StateAssistedAccountSlotRecord>,
{
    let slots = records
        .into_iter()
        .map(|record| {
            ProductionReviewedFq12StateAssistedAccountSlot::with_used_state(
                record.slot_id,
                ProductionAccountCommitment::new(
                    record.witness_commitment,
                    record.randomizer_commitment,
                ),
                record.hidden_source_opening_commitment,
                record.restore_anchor_digest,
                record.pad_seed_digest,
                record.unused,
            )
        })
        .collect();
    ProductionReviewedFq12StateAssistedAccountState::new(slots)
}

pub fn hidden_source_fallback_projection_account_state_from_slot_frames<I>(
    seeds: I,
) -> Result<ProductionReviewedFq12StateAssistedAccountState, String>
where
    I: IntoIterator<Item = HiddenSourceFallbackProjectionAccountSlotFrameSeed>,
{
    // Archival constructor for the older direct expanded-opening state model.
    // The selected deployment path commits the state-assisted opening tuple.
    let slots = seeds
        .into_iter()
        .enumerate()
        .map(|(slot_id, seed)| {
            let account_witness_opening =
                decode_hidden_source_fallback_account_witness_opening_frame(
                    &seed.account_witness_opening_frame,
                )?;
            let hidden_source_opening_commitment =
                hidden_source_fallback_expanded_account_opening_commitment(
                    &account_witness_opening,
                )?;
            let slot = ProductionReviewedFq12StateAssistedAccountSlot::with_used_state(
                slot_id as u32,
                ProductionAccountCommitment::new(
                    seed.witness_commitment,
                    seed.randomizer_commitment,
                ),
                hidden_source_opening_commitment,
                seed.restore_anchor_digest,
                seed.pad_seed_digest,
                seed.unused,
            );
            verify_hidden_source_fallback_expanded_opening_state_slot_frame(
                &slot,
                &seed.account_witness_opening_frame,
            )?;
            Ok(slot)
        })
        .collect::<Result<Vec<_>, String>>()?;
    ProductionReviewedFq12StateAssistedAccountState::new(slots)
}

pub fn encode_production_signature(
    slot_id: u32,
    challenge_bytes: &[u8; CHALLENGE_BYTES],
    responses: &ProductionCompactResponses,
    openings: &ProductionLocalOpenings,
    proof: &ProductionLinearSigmaTargetProof,
) -> Result<ProductionSignature, String> {
    decode_challenge(challenge_bytes)?;
    let encoded_responses = encode_responses(responses)?;
    let encoded_openings = encode_openings(openings)?;
    let encoded_proof = encode_linear_sigma_target_proof(proof);
    let mut bytes = Vec::with_capacity(LINEAR_SIGMA_TARGET_TRANSACTION_SIGNATURE_BYTES);
    bytes.extend_from_slice(&slot_id.to_le_bytes());
    bytes.extend_from_slice(challenge_bytes);
    bytes.extend_from_slice(&encoded_responses);
    bytes.extend_from_slice(&encoded_openings);
    bytes.extend_from_slice(&encoded_proof);
    Ok(ProductionSignature::new(bytes))
}

