pub fn sign_with_secret_key<ReferenceKeypair, F>(
    secret_key: &ProductionSecretKey<ReferenceKeypair>,
    account_slot: &ProductionAccountSlot,
    build_signature: F,
) -> Result<ProductionSignature, String>
where
    F: FnOnce(&ReferenceKeypair, u32, [u8; DIGEST_BYTES]) -> Result<ProductionSignature, String>,
{
    sign_with_account_binding(account_slot, |slot_id, witness_commitment| {
        build_signature(secret_key.reference_keypair(), slot_id, witness_commitment)
    })
}

