#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductionSelectedProjectionTargetChainKvDb<Kv> {
    kv: Kv,
}

impl<Kv> ProductionSelectedProjectionTargetChainKvDb<Kv> {
    pub fn new(kv: Kv) -> Self {
        Self { kv }
    }

    pub fn kv(&self) -> &Kv {
        &self.kv
    }

    pub fn kv_mut(&mut self) -> &mut Kv {
        &mut self.kv
    }

    pub fn into_kv(self) -> Kv {
        self.kv
    }

    pub fn lifecycle_key(public_key: &ProductionPublicKey) -> Vec<u8> {
        Self::key(public_key, b"lifecycle")
    }

    pub fn spent_slots_key(public_key: &ProductionPublicKey) -> Vec<u8> {
        Self::key(public_key, b"spent_slots")
    }

    pub fn trusted_anchor_key(public_key: &ProductionPublicKey) -> Vec<u8> {
        Self::key(public_key, b"trusted_anchor")
    }

    fn key(public_key: &ProductionPublicKey, suffix: &[u8]) -> Vec<u8> {
        let public_key_hash =
            ProductionInMemorySelectedProjectionTargetChainDb::public_key_hash(public_key);
        let mut key = Vec::with_capacity(
            PRODUCTION_TARGET_CHAIN_KV_NAMESPACE.len() + 1 + DIGEST_BYTES + 1 + suffix.len(),
        );
        key.extend_from_slice(PRODUCTION_TARGET_CHAIN_KV_NAMESPACE.as_bytes());
        key.push(0);
        key.extend_from_slice(&public_key_hash);
        key.push(0);
        key.extend_from_slice(suffix);
        key
    }
}

impl<Kv> ProductionSelectedProjectionTargetChainKvDb<Kv>
where
    Kv: ProductionTargetChainTransactionalKv,
{
    pub fn initialize_account_state(
        &mut self,
        public_key: &ProductionPublicKey,
        lifecycle_snapshot: ProductionReviewedFq12StateAssistedLifecycleSnapshot,
        trusted_anchor: ProductionTrustedRestoreAnchorRecord,
    ) -> Result<(), ProductionLifecycleError> {
        if trusted_anchor.public_key_sha256
            != ProductionInMemorySelectedProjectionTargetChainDb::public_key_hash(public_key)
        {
            return Err(ProductionLifecycleError::new(
                None,
                "trusted restore anchor public key mismatch",
            ));
        }
        if trusted_anchor.minimum_snapshot_sequence > lifecycle_snapshot.snapshot_sequence {
            return Err(ProductionLifecycleError::new(
                None,
                "trusted restore anchor is newer than initialized lifecycle snapshot",
            ));
        }
        self.kv.commit_batch(vec![
            ProductionTargetChainKvWrite {
                key: Self::lifecycle_key(public_key),
                value: encode_target_chain_kv_lifecycle_value(lifecycle_snapshot)?,
            },
            ProductionTargetChainKvWrite {
                key: Self::spent_slots_key(public_key),
                value: encode_target_chain_kv_spent_slots_value(Vec::new())?,
            },
            ProductionTargetChainKvWrite {
                key: Self::trusted_anchor_key(public_key),
                value: encode_target_chain_kv_trusted_anchor_value(trusted_anchor)?,
            },
        ])
    }

    fn load_lifecycle_snapshot(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<
        Option<ProductionReviewedFq12StateAssistedLifecycleSnapshot>,
        ProductionLifecycleError,
    > {
        self.kv
            .get(&Self::lifecycle_key(public_key))?
            .map(|bytes| decode_target_chain_kv_lifecycle_value(&bytes))
            .transpose()
    }

    fn load_spent_slot_records(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<Vec<ProductionSpentSlotRecord>, ProductionLifecycleError> {
        self.kv
            .get(&Self::spent_slots_key(public_key))?
            .map(|bytes| decode_target_chain_kv_spent_slots_value(&bytes))
            .transpose()
            .map(|records| records.unwrap_or_default())
    }

    fn load_trusted_anchor(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<Option<ProductionTrustedRestoreAnchorRecord>, ProductionLifecycleError> {
        self.kv
            .get(&Self::trusted_anchor_key(public_key))?
            .map(|bytes| decode_target_chain_kv_trusted_anchor_value(&bytes))
            .transpose()
    }
}

impl<Kv> ProductionSelectedProjectionTargetChainDb
    for ProductionSelectedProjectionTargetChainKvDb<Kv>
where
    Kv: ProductionTargetChainTransactionalKv,
{
    fn load_selected_projection_lifecycle_snapshot(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<
        Option<ProductionReviewedFq12StateAssistedLifecycleSnapshot>,
        ProductionLifecycleError,
    > {
        self.load_lifecycle_snapshot(public_key)
    }

    fn load_selected_projection_spent_slot_records(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<Vec<ProductionSpentSlotRecord>, ProductionLifecycleError> {
        self.load_spent_slot_records(public_key)
    }

    fn load_selected_projection_trusted_anchor(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<Option<ProductionTrustedRestoreAnchorRecord>, ProductionLifecycleError> {
        self.load_trusted_anchor(public_key)
    }

    fn commit_selected_projection_transition(
        &mut self,
        public_key: &ProductionPublicKey,
        transition: ProductionSelectedProjectionConsensusTransition,
        trusted_anchor: ProductionTrustedRestoreAnchorRecord,
    ) -> Result<(), ProductionLifecycleError> {
        let existing_snapshot = self.load_lifecycle_snapshot(public_key)?;
        let existing_anchor = self.load_trusted_anchor(public_key)?;
        validate_selected_projection_target_chain_commit(
            existing_snapshot.as_ref(),
            existing_anchor.as_ref(),
            public_key,
            &transition,
            &trusted_anchor,
        )?;
        self.kv.commit_batch(vec![
            ProductionTargetChainKvWrite {
                key: Self::lifecycle_key(public_key),
                value: encode_target_chain_kv_lifecycle_value(transition.next_lifecycle_snapshot)?,
            },
            ProductionTargetChainKvWrite {
                key: Self::spent_slots_key(public_key),
                value: encode_target_chain_kv_spent_slots_value(
                    transition.next_spent_slot_records,
                )?,
            },
            ProductionTargetChainKvWrite {
                key: Self::trusted_anchor_key(public_key),
                value: encode_target_chain_kv_trusted_anchor_value(trusted_anchor)?,
            },
        ])
    }
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ProductionInMemoryTransactionalKv {
    entries: BTreeMap<Vec<u8>, Vec<u8>>,
    fail_next_commit: bool,
}

impl ProductionInMemoryTransactionalKv {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn raw_get(&self, key: &[u8]) -> Option<&[u8]> {
        self.entries.get(key).map(Vec::as_slice)
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn fail_next_commit(&mut self) {
        self.fail_next_commit = true;
    }
}

impl ProductionTargetChainTransactionalKv for ProductionInMemoryTransactionalKv {
    fn get(&self, key: &[u8]) -> Result<Option<Vec<u8>>, ProductionLifecycleError> {
        Ok(self.entries.get(key).cloned())
    }

    fn commit_batch(
        &mut self,
        writes: Vec<ProductionTargetChainKvWrite>,
    ) -> Result<(), ProductionLifecycleError> {
        if self.fail_next_commit {
            self.fail_next_commit = false;
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain kv transaction failed",
            ));
        }
        for write in writes {
            self.entries.insert(write.key, write.value);
        }
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
struct ProductionFileBackedTransactionalKvEntry {
    key: Vec<u8>,
    value: Vec<u8>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
struct ProductionFileBackedTransactionalKvStoreFile {
    schema: String,
    entries: Vec<ProductionFileBackedTransactionalKvEntry>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductionFileBackedTransactionalKv {
    path: PathBuf,
}

#[derive(Debug)]
pub struct ProductionFileBackedTransactionalKvLock {
    path: PathBuf,
    _file: File,
}

impl ProductionFileBackedTransactionalKvLock {
    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl Drop for ProductionFileBackedTransactionalKvLock {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

impl ProductionFileBackedTransactionalKv {
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self { path: path.into() }
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    pub fn lock_path(&self) -> PathBuf {
        let mut file_name = self
            .path
            .file_name()
            .map(|name| name.to_os_string())
            .unwrap_or_else(|| "target_chain_kv".into());
        file_name.push(".lock");
        self.path.with_file_name(file_name)
    }

    pub fn tmp_path(&self) -> PathBuf {
        let mut file_name = self
            .path
            .file_name()
            .map(|name| name.to_os_string())
            .unwrap_or_else(|| "target_chain_kv".into());
        file_name.push(".tmp");
        self.path.with_file_name(file_name)
    }

    pub fn try_lock(
        &self,
    ) -> Result<ProductionFileBackedTransactionalKvLock, ProductionLifecycleError> {
        let lock_path = self.lock_path();
        if let Some(parent) = lock_path
            .parent()
            .filter(|path| !path.as_os_str().is_empty())
        {
            fs::create_dir_all(parent).map_err(|err| {
                self.io_error_for_path("create file-backed target-chain kv lock dir", parent, err)
            })?;
        }
        let mut file = match OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&lock_path)
        {
            Ok(file) => file,
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {
                return Err(ProductionLifecycleError::new(
                    None,
                    "file-backed target-chain kv store is locked",
                ));
            }
            Err(err) => {
                return Err(self.io_error_for_path(
                    "create file-backed target-chain kv lock",
                    &lock_path,
                    err,
                ));
            }
        };
        writeln!(file, "pid={}", std::process::id()).map_err(|err| {
            self.io_error_for_path("write file-backed target-chain kv lock", &lock_path, err)
        })?;
        file.sync_all().map_err(|err| {
            self.io_error_for_path("sync file-backed target-chain kv lock", &lock_path, err)
        })?;
        Ok(ProductionFileBackedTransactionalKvLock {
            path: lock_path,
            _file: file,
        })
    }

    fn load_entries(&self) -> Result<BTreeMap<Vec<u8>, Vec<u8>>, ProductionLifecycleError> {
        let bytes = match fs::read(&self.path) {
            Ok(bytes) => bytes,
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => {
                return Ok(BTreeMap::new());
            }
            Err(err) => return Err(self.io_error("read file-backed target-chain kv", err)),
        };
        let file: ProductionFileBackedTransactionalKvStoreFile = serde_json::from_slice(&bytes)
            .map_err(|err| {
                ProductionLifecycleError::new(
                    None,
                    format!(
                        "decode file-backed target-chain kv {}: {err}",
                        self.path.display()
                    ),
                )
            })?;
        if file.schema != PRODUCTION_FILE_BACKED_TRANSACTIONAL_KV_SCHEMA {
            return Err(ProductionLifecycleError::new(
                None,
                "file-backed target-chain kv schema mismatch",
            ));
        }
        let mut entries = BTreeMap::new();
        for entry in file.entries {
            if entries.insert(entry.key, entry.value).is_some() {
                return Err(ProductionLifecycleError::new(
                    None,
                    "duplicate file-backed target-chain kv key",
                ));
            }
        }
        Ok(entries)
    }

    fn save_entries(
        &self,
        entries: BTreeMap<Vec<u8>, Vec<u8>>,
    ) -> Result<(), ProductionLifecycleError> {
        let file = ProductionFileBackedTransactionalKvStoreFile {
            schema: PRODUCTION_FILE_BACKED_TRANSACTIONAL_KV_SCHEMA.to_string(),
            entries: entries
                .into_iter()
                .map(|(key, value)| ProductionFileBackedTransactionalKvEntry { key, value })
                .collect(),
        };
        let mut bytes = serde_json::to_vec_pretty(&file).map_err(|err| {
            ProductionLifecycleError::new(
                None,
                format!("encode file-backed target-chain kv: {err}"),
            )
        })?;
        bytes.push(b'\n');
        self.atomic_write(&bytes)
    }

    fn atomic_write(&self, bytes: &[u8]) -> Result<(), ProductionLifecycleError> {
        if let Some(parent) = self
            .path
            .parent()
            .filter(|path| !path.as_os_str().is_empty())
        {
            fs::create_dir_all(parent).map_err(|err| {
                self.io_error_for_path("create file-backed target-chain kv dir", parent, err)
            })?;
        }
        let tmp_path = self.tmp_path();
        let mut file = File::create(&tmp_path).map_err(|err| {
            self.io_error_for_path("create temp file-backed target-chain kv", &tmp_path, err)
        })?;
        file.write_all(bytes).map_err(|err| {
            self.io_error_for_path("write temp file-backed target-chain kv", &tmp_path, err)
        })?;
        file.sync_all().map_err(|err| {
            self.io_error_for_path("sync temp file-backed target-chain kv", &tmp_path, err)
        })?;
        drop(file);
        fs::rename(&tmp_path, &self.path)
            .map_err(|err| self.io_error("commit file-backed target-chain kv", err))?;
        Ok(())
    }

    fn io_error(&self, action: &str, err: std::io::Error) -> ProductionLifecycleError {
        self.io_error_for_path(action, &self.path, err)
    }

    fn io_error_for_path(
        &self,
        action: &str,
        path: &Path,
        err: std::io::Error,
    ) -> ProductionLifecycleError {
        ProductionLifecycleError::new(None, format!("{action} {}: {err}", path.display()))
    }
}

impl ProductionTargetChainTransactionalKv for ProductionFileBackedTransactionalKv {
    fn get(&self, key: &[u8]) -> Result<Option<Vec<u8>>, ProductionLifecycleError> {
        Ok(self.load_entries()?.get(key).cloned())
    }

    fn commit_batch(
        &mut self,
        writes: Vec<ProductionTargetChainKvWrite>,
    ) -> Result<(), ProductionLifecycleError> {
        let _lock = self.try_lock()?;
        let mut entries = self.load_entries()?;
        for write in writes {
            entries.insert(write.key, write.value);
        }
        self.save_entries(entries)
    }
}

fn encode_target_chain_kv_lifecycle_value(
    snapshot: ProductionReviewedFq12StateAssistedLifecycleSnapshot,
) -> Result<Vec<u8>, ProductionLifecycleError> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PRODUCTION_TARGET_CHAIN_KV_LIFECYCLE_SCHEMA.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"snapshot",
        &production_lifecycle_snapshot_frame(&snapshot),
    );
    Ok(frame)
}

fn decode_target_chain_kv_lifecycle_value(
    bytes: &[u8],
) -> Result<ProductionReviewedFq12StateAssistedLifecycleSnapshot, ProductionLifecycleError> {
    if bytes.first() != Some(&b'{') {
        let mut reader = ProductionKvFrameReader::new(bytes);
        let schema = reader.read_utf8(b"schema")?;
        if schema != PRODUCTION_TARGET_CHAIN_KV_LIFECYCLE_SCHEMA {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain lifecycle schema mismatch",
            ));
        }
        let snapshot = decode_production_lifecycle_snapshot_frame(reader.read_frame(b"snapshot")?)?;
        reader.finish()?;
        return Ok(snapshot);
    }
    let value: ProductionTargetChainKvLifecycleValue =
        serde_json::from_slice(bytes).map_err(|err| {
            ProductionLifecycleError::new(
                None,
                format!("decode target-chain lifecycle value: {err}"),
            )
        })?;
    if value.schema != PRODUCTION_TARGET_CHAIN_KV_LIFECYCLE_SCHEMA {
        return Err(ProductionLifecycleError::new(
            None,
            "target-chain lifecycle schema mismatch",
        ));
    }
    Ok(value.snapshot)
}

fn encode_target_chain_kv_spent_slots_value(
    records: Vec<ProductionSpentSlotRecord>,
) -> Result<Vec<u8>, ProductionLifecycleError> {
    let records = ProductionSpentSlotLedger::from_records(records)?.to_records();
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PRODUCTION_TARGET_CHAIN_KV_SPENT_SCHEMA.as_bytes(),
    );
    append_u64(&mut frame, b"record_count", records.len() as u64);
    for record in &records {
        append_frame(
            &mut frame,
            b"spent_slot_record",
            &production_spent_slot_record_frame(record),
        );
    }
    Ok(frame)
}

fn decode_target_chain_kv_spent_slots_value(
    bytes: &[u8],
) -> Result<Vec<ProductionSpentSlotRecord>, ProductionLifecycleError> {
    if bytes.first() != Some(&b'{') {
        let mut reader = ProductionKvFrameReader::new(bytes);
        let schema = reader.read_utf8(b"schema")?;
        if schema != PRODUCTION_TARGET_CHAIN_KV_SPENT_SCHEMA {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain spent slots schema mismatch",
            ));
        }
        let record_count = reader.read_usize(b"record_count")?;
        let mut records = Vec::with_capacity(record_count);
        for _ in 0..record_count {
            records.push(decode_production_spent_slot_record_frame(
                reader.read_frame(b"spent_slot_record")?,
            )?);
        }
        reader.finish()?;
        return ProductionSpentSlotLedger::from_records(records).map(|ledger| ledger.to_records());
    }
    let value: ProductionTargetChainKvSpentSlotsValue =
        serde_json::from_slice(bytes).map_err(|err| {
            ProductionLifecycleError::new(
                None,
                format!("decode target-chain spent slots value: {err}"),
            )
        })?;
    if value.schema != PRODUCTION_TARGET_CHAIN_KV_SPENT_SCHEMA {
        return Err(ProductionLifecycleError::new(
            None,
            "target-chain spent slots schema mismatch",
        ));
    }
    ProductionSpentSlotLedger::from_records(value.records).map(|ledger| ledger.to_records())
}

