struct ProductionKvFrameReader<'a> {
    bytes: &'a [u8],
    offset: usize,
}

impl<'a> ProductionKvFrameReader<'a> {
    fn new(bytes: &'a [u8]) -> Self {
        Self { bytes, offset: 0 }
    }

    fn read_frame(&mut self, expected_label: &[u8]) -> Result<&'a [u8], ProductionLifecycleError> {
        let label_len = self.read_u16_len("target-chain kv label length")?;
        let label = self.read_bytes(label_len, "target-chain kv label")?;
        if label != expected_label {
            return Err(ProductionLifecycleError::new(
                None,
                format!(
                    "target-chain kv frame label mismatch: expected {}, got {}",
                    String::from_utf8_lossy(expected_label),
                    String::from_utf8_lossy(label)
                ),
            ));
        }
        let data_len = self.read_u64_len("target-chain kv data length")?;
        self.read_bytes(data_len, "target-chain kv frame data")
    }

    fn read_u64(&mut self, label: &[u8]) -> Result<u64, ProductionLifecycleError> {
        let bytes = self.read_frame(label)?;
        if bytes.len() != 8 {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain kv u64 field length mismatch",
            ));
        }
        Ok(u64::from_le_bytes(bytes.try_into().unwrap()))
    }

    fn read_u32(&mut self, label: &[u8]) -> Result<u32, ProductionLifecycleError> {
        let value = self.read_u64(label)?;
        u32::try_from(value).map_err(|_| {
            ProductionLifecycleError::new(None, "target-chain kv u32 field out of range")
        })
    }

    fn read_usize(&mut self, label: &[u8]) -> Result<usize, ProductionLifecycleError> {
        let value = self.read_u64(label)?;
        usize::try_from(value).map_err(|_| {
            ProductionLifecycleError::new(None, "target-chain kv usize field out of range")
        })
    }

    fn read_bool(&mut self, label: &[u8]) -> Result<bool, ProductionLifecycleError> {
        match self.read_u64(label)? {
            0 => Ok(false),
            1 => Ok(true),
            _ => Err(ProductionLifecycleError::new(
                None,
                "target-chain kv bool field must be 0 or 1",
            )),
        }
    }

    fn read_digest(
        &mut self,
        label: &[u8],
    ) -> Result<[u8; DIGEST_BYTES], ProductionLifecycleError> {
        let bytes = self.read_frame(label)?;
        bytes.try_into().map_err(|_| {
            ProductionLifecycleError::new(None, "target-chain kv digest field length mismatch")
        })
    }

    fn read_utf8(&mut self, label: &[u8]) -> Result<String, ProductionLifecycleError> {
        std::str::from_utf8(self.read_frame(label)?)
            .map(|value| value.to_string())
            .map_err(|err| {
                ProductionLifecycleError::new(
                    None,
                    format!("target-chain kv utf8 field mismatch: {err}"),
                )
            })
    }

    fn finish(&self) -> Result<(), ProductionLifecycleError> {
        if self.offset == self.bytes.len() {
            Ok(())
        } else {
            Err(ProductionLifecycleError::new(
                None,
                "target-chain kv frame has trailing bytes",
            ))
        }
    }

    fn read_u16_len(&mut self, context: &str) -> Result<usize, ProductionLifecycleError> {
        let bytes = self.read_bytes(2, context)?;
        Ok(u16::from_le_bytes(bytes.try_into().unwrap()) as usize)
    }

    fn read_u64_len(&mut self, context: &str) -> Result<usize, ProductionLifecycleError> {
        let bytes = self.read_bytes(8, context)?;
        let value = u64::from_le_bytes(bytes.try_into().unwrap());
        usize::try_from(value).map_err(|_| {
            ProductionLifecycleError::new(None, "target-chain kv frame length out of range")
        })
    }

    fn read_bytes(
        &mut self,
        len: usize,
        context: &str,
    ) -> Result<&'a [u8], ProductionLifecycleError> {
        let end = self.offset.checked_add(len).ok_or_else(|| {
            ProductionLifecycleError::new(None, "target-chain kv frame length overflow")
        })?;
        if end > self.bytes.len() {
            return Err(ProductionLifecycleError::new(
                None,
                format!("truncated {context}"),
            ));
        }
        let out = &self.bytes[self.offset..end];
        self.offset = end;
        Ok(out)
    }
}

fn production_lifecycle_snapshot_frame(
    snapshot: &ProductionReviewedFq12StateAssistedLifecycleSnapshot,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_u64(&mut frame, b"snapshot_sequence", snapshot.snapshot_sequence);
    append_u64(
        &mut frame,
        b"next_reservation_epoch",
        snapshot.next_reservation_epoch,
    );
    append_u64(
        &mut frame,
        b"account_slot_count",
        snapshot.account_slots.len() as u64,
    );
    for slot in &snapshot.account_slots {
        append_frame(
            &mut frame,
            b"account_slot",
            &production_account_slot_record_frame(slot),
        );
    }
    append_u64(
        &mut frame,
        b"active_reservation_count",
        snapshot.active_reservations.len() as u64,
    );
    for reservation in &snapshot.active_reservations {
        append_frame(
            &mut frame,
            b"active_reservation",
            &production_slot_reservation_frame(reservation),
        );
    }
    frame
}

fn decode_production_lifecycle_snapshot_frame(
    bytes: &[u8],
) -> Result<ProductionReviewedFq12StateAssistedLifecycleSnapshot, ProductionLifecycleError> {
    let mut reader = ProductionKvFrameReader::new(bytes);
    let snapshot_sequence = reader.read_u64(b"snapshot_sequence")?;
    let next_reservation_epoch = reader.read_u64(b"next_reservation_epoch")?;
    let account_slot_count = reader.read_usize(b"account_slot_count")?;
    let mut account_slots = Vec::with_capacity(account_slot_count);
    for _ in 0..account_slot_count {
        account_slots.push(decode_production_account_slot_record_frame(
            reader.read_frame(b"account_slot")?,
        )?);
    }
    let active_reservation_count = reader.read_usize(b"active_reservation_count")?;
    let mut active_reservations = Vec::with_capacity(active_reservation_count);
    for _ in 0..active_reservation_count {
        active_reservations.push(decode_production_slot_reservation_frame(
            reader.read_frame(b"active_reservation")?,
        )?);
    }
    reader.finish()?;
    Ok(ProductionReviewedFq12StateAssistedLifecycleSnapshot {
        account_slots,
        active_reservations,
        next_reservation_epoch,
        snapshot_sequence,
    })
}

fn production_account_slot_record_frame(
    slot: &ProductionReviewedFq12StateAssistedAccountSlotRecord,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_u64(&mut frame, b"slot_id", slot.slot_id as u64);
    append_frame(&mut frame, b"witness_commitment", &slot.witness_commitment);
    append_frame(
        &mut frame,
        b"randomizer_commitment",
        &slot.randomizer_commitment,
    );
    append_frame(
        &mut frame,
        b"hidden_source_opening_commitment",
        &slot.hidden_source_opening_commitment,
    );
    append_frame(
        &mut frame,
        b"restore_anchor_digest",
        &slot.restore_anchor_digest,
    );
    append_frame(&mut frame, b"pad_seed_digest", &slot.pad_seed_digest);
    append_u64(&mut frame, b"unused", u64::from(slot.unused));
    frame
}

fn decode_production_account_slot_record_frame(
    bytes: &[u8],
) -> Result<ProductionReviewedFq12StateAssistedAccountSlotRecord, ProductionLifecycleError> {
    let mut reader = ProductionKvFrameReader::new(bytes);
    let slot = ProductionReviewedFq12StateAssistedAccountSlotRecord {
        slot_id: reader.read_u32(b"slot_id")?,
        witness_commitment: reader.read_digest(b"witness_commitment")?,
        randomizer_commitment: reader.read_digest(b"randomizer_commitment")?,
        hidden_source_opening_commitment: reader
            .read_digest(b"hidden_source_opening_commitment")?,
        restore_anchor_digest: reader.read_digest(b"restore_anchor_digest")?,
        pad_seed_digest: reader.read_digest(b"pad_seed_digest")?,
        unused: reader.read_bool(b"unused")?,
    };
    reader.finish()?;
    Ok(slot)
}

fn production_slot_reservation_frame(reservation: &ProductionSlotReservation) -> Vec<u8> {
    let mut frame = Vec::new();
    append_u64(&mut frame, b"slot_id", reservation.slot_id as u64);
    append_u64(&mut frame, b"epoch", reservation.epoch);
    frame
}

fn decode_production_slot_reservation_frame(
    bytes: &[u8],
) -> Result<ProductionSlotReservation, ProductionLifecycleError> {
    let mut reader = ProductionKvFrameReader::new(bytes);
    let reservation = ProductionSlotReservation {
        slot_id: reader.read_u32(b"slot_id")?,
        epoch: reader.read_u64(b"epoch")?,
    };
    reader.finish()?;
    Ok(reservation)
}

fn production_spent_slot_record_frame(record: &ProductionSpentSlotRecord) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"public_key_sha256",
        &record.key.public_key_sha256,
    );
    append_u64(&mut frame, b"slot_id", record.key.slot_id as u64);
    append_u64(&mut frame, b"snapshot_sequence", record.snapshot_sequence);
    append_frame(&mut frame, b"source", record.source.as_bytes());
    append_u64(
        &mut frame,
        b"pad_seed_digest_present",
        u64::from(record.pad_seed_digest.is_some()),
    );
    if let Some(pad_seed_digest) = record.pad_seed_digest {
        append_frame(&mut frame, b"pad_seed_digest", &pad_seed_digest);
    }
    frame
}

fn decode_production_spent_slot_record_frame(
    bytes: &[u8],
) -> Result<ProductionSpentSlotRecord, ProductionLifecycleError> {
    let mut reader = ProductionKvFrameReader::new(bytes);
    let key = ProductionSpentSlotKey {
        public_key_sha256: reader.read_digest(b"public_key_sha256")?,
        slot_id: reader.read_u32(b"slot_id")?,
    };
    let snapshot_sequence = reader.read_u64(b"snapshot_sequence")?;
    let source = reader.read_utf8(b"source")?;
    let pad_seed_digest = if reader.read_bool(b"pad_seed_digest_present")? {
        Some(reader.read_digest(b"pad_seed_digest")?)
    } else {
        None
    };
    reader.finish()?;
    Ok(ProductionSpentSlotRecord {
        key,
        snapshot_sequence,
        source,
        pad_seed_digest,
    })
}

fn production_trusted_restore_anchor_record_frame(
    record: &ProductionTrustedRestoreAnchorRecord,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(&mut frame, b"public_key_sha256", &record.public_key_sha256);
    append_u64(
        &mut frame,
        b"minimum_snapshot_sequence",
        record.minimum_snapshot_sequence,
    );
    append_frame(&mut frame, b"placement", record.placement.as_bytes());
    frame
}

fn decode_production_trusted_restore_anchor_record_frame(
    bytes: &[u8],
) -> Result<ProductionTrustedRestoreAnchorRecord, ProductionLifecycleError> {
    let mut reader = ProductionKvFrameReader::new(bytes);
    let record = ProductionTrustedRestoreAnchorRecord {
        public_key_sha256: reader.read_digest(b"public_key_sha256")?,
        minimum_snapshot_sequence: reader.read_u64(b"minimum_snapshot_sequence")?,
        placement: reader.read_utf8(b"placement")?,
    };
    reader.finish()?;
    Ok(record)
}

fn current_unix_nanos() -> Result<u64, ProductionLifecycleError> {
    let duration = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(|err| ProductionLifecycleError::new(None, format!("system clock error: {err}")))?;
    u64::try_from(duration.as_nanos())
        .map_err(|_| ProductionLifecycleError::new(None, "system clock nanoseconds overflow"))
}

pub fn challenge_hash_frame(
    public_key: &[u8],
    message: &[u8],
    slot_id: u32,
    digest: &[u8; DIGEST_BYTES],
    proof_commitment: &[u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES],
) -> Vec<u8> {
    let mut frame = challenge_hash_frame_prefix(public_key, message, slot_id, digest);
    append_frame(&mut frame, b"proof_commitment", proof_commitment);
    frame
}

pub fn legacy_stateful_challenge_hash_frame(
    public_key: &[u8],
    message: &[u8],
    slot_id: u32,
    digest: &[u8; DIGEST_BYTES],
) -> Vec<u8> {
    challenge_hash_frame_prefix(public_key, message, slot_id, digest)
}

/// ARCHIVED SHA-256 Fiat–Shamir challenge body. Retained ONLY as the historical
/// SHA-era anchor for the archived KAT / equivalence audit trail — it is NO LONGER
/// on any production FS path (the full spend FS — transaction, authorization, and
/// relation challenges — was re-hosted to Poseidon2 on 2026-06-18). Do NOT route a
/// new FS caller here: that would silently re-introduce SHA-based Fiat–Shamir.
#[deprecated(note = "not on the FS path; Poseidon2 re-host 2026-06-18. SHA-era anchor only.")]
pub fn hash_frame_to_challenge_bytes_sha256_legacy(frame: &[u8]) -> [u8; CHALLENGE_BYTES] {
    let digest = Sha256::digest(frame);
    let mut out = [0_u8; CHALLENGE_BYTES];
    out.copy_from_slice(&digest[..CHALLENGE_BYTES]);
    out[ALGEBRAIC_CHALLENGE_BYTES - 1] &= ALGEBRAIC_CHALLENGE_LAST_BYTE_MASK;
    out
}

/// Domain separator for the checked-core RELATION Fiat–Shamir challenge under Poseidon2.
pub const PATH2_CHECKED_CORE_FS_POSEIDON2_DOMAIN: &str =
    "Descender.Path2.checked_core.fiat_shamir.poseidon2.v1";

/// Domain separator for the main LINEAR_SIGMA TRANSACTION Fiat–Shamir challenge under Poseidon2.
pub const PATH2_TXN_FS_POSEIDON2_DOMAIN: &str =
    "Descender.Path2.transaction.fiat_shamir.poseidon2.v1";

/// Domain separator for the checked-core AUTHORIZATION Fiat–Shamir challenge under Poseidon2.
pub const PATH2_AUTH_FS_POSEIDON2_DOMAIN: &str =
    "Descender.Path2.checked_core.authorization.fiat_shamir.poseidon2.v1";

/// Poseidon2 (KoalaBear) Fiat–Shamir challenge derivation, domain-separated. This is
/// the unified spend-FS sponge body (recursion-friendly, Plonky3-free via the shared
/// `descender-mask-prf` Poseidon2 sponge). Preserves the 31-byte algebraic+hardening
/// layout and last-byte mask, so downstream challenge parsing is unchanged; only the
/// VALUES differ from the archived SHA-256 body. Each FS context (relation, transaction,
/// authorization) passes its own domain tag so the three sponges can never collide. The
/// FS soundness assumption is SHA-256-as-RO -> Poseidon2-sponge-as-RO (the named-standard
/// A_poseidon2_* assumption already carried for the mask PRF + relation frame).
pub fn hash_frame_to_challenge_bytes_poseidon2_with_domain(
    domain: &[u8],
    frame: &[u8],
) -> [u8; CHALLENGE_BYTES] {
    let mut out = descender_mask_prf::poseidon2_hash_bytes::<CHALLENGE_BYTES>(domain, frame);
    out[ALGEBRAIC_CHALLENGE_BYTES - 1] &= ALGEBRAIC_CHALLENGE_LAST_BYTE_MASK;
    out
}

/// Relation-domain Poseidon2 Fiat–Shamir challenge — thin wrapper over
/// [`hash_frame_to_challenge_bytes_poseidon2_with_domain`] pinned to the CHECKED-CORE
/// relation domain (back-compat for the relation-frame callers re-hosted 2026-06-18).
pub fn hash_frame_to_challenge_bytes_poseidon2(frame: &[u8]) -> [u8; CHALLENGE_BYTES] {
    hash_frame_to_challenge_bytes_poseidon2_with_domain(
        PATH2_CHECKED_CORE_FS_POSEIDON2_DOMAIN.as_bytes(),
        frame,
    )
}

pub fn challenge_bytes(
    public_key: &[u8],
    message: &[u8],
    slot_id: u32,
    digest: &[u8; DIGEST_BYTES],
    proof_commitment: &[u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES],
) -> [u8; CHALLENGE_BYTES] {
    hash_frame_to_challenge_bytes_poseidon2_with_domain(
        PATH2_TXN_FS_POSEIDON2_DOMAIN.as_bytes(),
        &challenge_hash_frame(public_key, message, slot_id, digest, proof_commitment),
    )
}

pub fn path2_checked_core_authorization_challenge_frame(
    public_key: &[u8],
    message: &[u8],
    account_id: &[u8; DIGEST_BYTES],
    account_state_root: &[u8; DIGEST_BYTES],
    slot_id: u32,
    witness_commitment: &[u8; DIGEST_BYTES],
    slot_authorization_digest: &[u8; DIGEST_BYTES],
    proof_commitment: &[u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES],
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        PATH2_SLOT_CONSUME_SINGLE_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_pivot", LOCAL_PIVOT as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(&mut frame, b"repetitions", REPS as u64);
    append_u64(&mut frame, b"slot_id", slot_id as u64);
    append_frame(&mut frame, b"public_key", public_key);
    append_frame(&mut frame, b"message", message);
    append_frame(&mut frame, b"account_id", account_id);
    append_frame(&mut frame, b"account_state_root", account_state_root);
    append_frame(&mut frame, b"witness_commitment", witness_commitment);
    append_frame(
        &mut frame,
        b"slot_authorization_digest",
        slot_authorization_digest,
    );
    append_frame(&mut frame, b"proof_commitment", proof_commitment);
    frame
}

pub fn path2_checked_core_authorization_challenge_bytes(
    public_key: &[u8],
    message: &[u8],
    account_id: &[u8; DIGEST_BYTES],
    account_state_root: &[u8; DIGEST_BYTES],
    slot_id: u32,
    witness_commitment: &[u8; DIGEST_BYTES],
    slot_authorization_digest: &[u8; DIGEST_BYTES],
    proof_commitment: &[u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES],
) -> [u8; CHALLENGE_BYTES] {
    hash_frame_to_challenge_bytes_poseidon2_with_domain(
        PATH2_AUTH_FS_POSEIDON2_DOMAIN.as_bytes(),
        &path2_checked_core_authorization_challenge_frame(
            public_key,
            message,
            account_id,
            account_state_root,
            slot_id,
            witness_commitment,
            slot_authorization_digest,
            proof_commitment,
        ),
    )
}

pub fn require_path2_checked_core_authorization_challenge_binding(
    public_key: &[u8],
    message: &[u8],
    account_id: &[u8; DIGEST_BYTES],
    account_state_root: &[u8; DIGEST_BYTES],
    slot_id: u32,
    witness_commitment: &[u8; DIGEST_BYTES],
    slot_authorization_digest: &[u8; DIGEST_BYTES],
    signature: &ProductionSignature,
) -> Result<(), ProductionAccountBindingError> {
    if signature.as_bytes().len() != REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES {
        return Err(ProductionAccountBindingError::new(
            Some(slot_id),
            format!(
                "Path 2 checked-core signature has {} bytes, expected {REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES}",
                signature.as_bytes().len()
            ),
        ));
    }
    let parts = decode_reviewed_fq12_account_carried_signature(signature.as_bytes())
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    let expected = path2_checked_core_authorization_challenge_bytes(
        public_key,
        message,
        account_id,
        account_state_root,
        slot_id,
        witness_commitment,
        slot_authorization_digest,
        &parts.proof.proof_commitment,
    );
    let claimed = &signature.as_bytes()[SLOT_ID_BYTES..SLOT_ID_BYTES + CHALLENGE_BYTES];
    if claimed != expected {
        return Err(ProductionAccountBindingError::new(
            Some(slot_id),
            "Path 2 checked-core authorization challenge mismatch",
        ));
    }
    Ok(())
}

pub fn verify_path2_checked_core_authorization(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    account_id: &[u8; DIGEST_BYTES],
    account_state_root: &[u8; DIGEST_BYTES],
    slot_authorization_digest: &[u8; DIGEST_BYTES],
    signature: &ProductionSignature,
) -> Result<ProductionReviewedFq12AccountCarriedSignatureParts, ProductionAccountBindingError> {
    let parts = decode_reviewed_fq12_account_carried_signature(signature.as_bytes())
        .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let slot = account.get_slot(parts.slot_id).ok_or_else(|| {
        ProductionAccountBindingError::new(Some(parts.slot_id), "slot id is out of range")
    })?;
    if !slot.is_unused() {
        return Err(ProductionAccountBindingError::new(
            Some(parts.slot_id),
            "slot is already consumed",
        ));
    }
    validate_reviewed_fq12_state_assisted_account_commitment(slot.commitment())
        .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    unpack_reviewed_fq12_account_carried_syndrome_digest(&parts.proof.proof_commitment)
        .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    if parts.proof.proof_commitment != slot.commitment().randomizer_commitment() {
        return Err(ProductionAccountBindingError::new(
            Some(parts.slot_id),
            "account randomizer commitment mismatch",
        ));
    }
    require_path2_checked_core_authorization_challenge_binding(
        public_key.as_bytes(),
        message,
        account_id,
        account_state_root,
        parts.slot_id,
        &slot.commitment().witness_commitment(),
        slot_authorization_digest,
        signature,
    )?;
    let actual =
        reviewed_fq12_account_carried_response_syndrome(&parts.proof.masked_quotient_response)
            .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    let challenge: [u8; CHALLENGE_BYTES] = signature.as_bytes()
        [SLOT_ID_BYTES..SLOT_ID_BYTES + CHALLENGE_BYTES]
        .try_into()
        .expect("decoded Fq12 account-carried signature has fixed challenge slice");
    let expected = reviewed_fq12_state_assisted_expected_response_syndrome(
        &challenge,
        &slot.commitment().witness_commitment(),
        &parts.proof.proof_commitment,
    )
    .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    if actual != expected {
        return Err(ProductionAccountBindingError::new(
            Some(parts.slot_id),
            "reviewed Fq12 account-carried sigma equation mismatch",
        ));
    }
    verify_public_local_fiber_consistency(public_key, &parts.challenge, &parts.responses)
        .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    verify_public_pad_opening_consistency(
        public_key,
        &parts.challenge,
        &parts.responses,
        &parts.openings,
    )
    .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    Ok(parts)
}

pub fn verify_path2_direct_single_slot_spend_authorization(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    signature: &ProductionSignature,
    admitted_state_authorizations: &BTreeSet<(
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
    )>,
    consumed_authorizations: &mut BTreeSet<[u8; DIGEST_BYTES]>,
) -> Result<ProductionReviewedFq12AccountCarriedSignatureParts, ProductionAccountBindingError> {
    let public_key_identity: [u8; DIGEST_BYTES] = Sha256::digest(public_key.as_bytes()).into();
    if leaf.public_key_identity != public_key_identity {
        return Err(ProductionAccountBindingError::new(
            None,
            "Path 2 public-key identity mismatch",
        ));
    }
    let authorization = validate_path2_direct_slot_authorization_state_namespace(
        leaf,
        evidence,
        certificate,
        admitted_state_authorizations,
    )
    .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let parts = verify_path2_checked_core_authorization(
        public_key,
        message,
        account,
        &leaf.account_id,
        &leaf.account_state_root_before,
        &authorization,
        signature,
    )?;
    if u64::from(parts.slot_id) != leaf.slot_id {
        return Err(ProductionAccountBindingError::new(
            Some(parts.slot_id),
            "Path 2 checked-core slot id does not match prevalidated leaf",
        ));
    }
    let consumed_authorization = verify_path2_prevalidated_slot_consume_once(
        leaf,
        evidence,
        certificate,
        consumed_authorizations,
    )
    .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    if consumed_authorization != authorization {
        return Err(ProductionAccountBindingError::new(
            Some(parts.slot_id),
            "Path 2 consumed authorization mismatch",
        ));
    }
    Ok(parts)
}

pub fn verify_path2_direct_single_slot_spend_authorization_public_result_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    signature: &ProductionSignature,
    admitted_state_authorizations: &BTreeSet<(
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
    )>,
    consumed_authorizations: &mut BTreeSet<[u8; DIGEST_BYTES]>,
) -> Path2DirectSpendPublicResultV1 {
    let consumed_before = consumed_authorizations.clone();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        verify_path2_direct_single_slot_spend_authorization(
            leaf,
            evidence,
            certificate,
            public_key,
            message,
            account,
            signature,
            admitted_state_authorizations,
            consumed_authorizations,
        )
    }));
    match result {
        Ok(Ok(parts)) => Path2DirectSpendPublicResultV1::accepted_spend(parts.slot_id),
        Ok(Err(err)) => {
            *consumed_authorizations = consumed_before;
            Path2DirectSpendPublicResultV1::rejected(
                path2_direct_account_binding_public_result_class(&err),
            )
        }
        Err(_) => {
            *consumed_authorizations = consumed_before;
            Path2DirectSpendPublicResultV1::rejected(
                Path2PublicResultClassV1::InternalErrorFailClosed,
            )
        }
    }
}

pub fn path2_direct_admission_namespace_record_digest(
    account_id: &[u8; DIGEST_BYTES],
    account_state_root_before: &[u8; DIGEST_BYTES],
    slot_authorization_digest: &[u8; DIGEST_BYTES],
) -> [u8; DIGEST_BYTES] {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        b"Descender.Path2.DirectAdmissionNamespaceRecord.v1",
    );
    append_frame(&mut frame, b"account_id", account_id);
    append_frame(
        &mut frame,
        b"account_state_root_before",
        account_state_root_before,
    );
    append_frame(
        &mut frame,
        b"slot_authorization_digest",
        slot_authorization_digest,
    );
    Sha256::digest(frame).into()
}

pub fn path2_direct_consume_once_authorization_set_digest(
    consumed_authorizations: &BTreeSet<[u8; DIGEST_BYTES]>,
) -> [u8; DIGEST_BYTES] {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        b"Descender.Path2.DirectConsumeOnceAuthorizationSet.v1",
    );
    append_u64(
        &mut frame,
        b"authorization_count",
        consumed_authorizations.len() as u64,
    );
    for authorization in consumed_authorizations {
        append_frame(&mut frame, b"slot_authorization_digest", authorization);
    }
    Sha256::digest(frame).into()
}

fn path2_direct_referenced_obligations_still_open_v1(obligation_ids: &[&str]) -> bool {
    !obligation_ids.is_empty()
        && obligation_ids.iter().all(|obligation_id| {
            PATH2_DIRECT_THEOREM_OBLIGATION_ROWS
                .iter()
                .any(|row| row.obligation_id == *obligation_id && row.open)
        })
}

fn path2_direct_referenced_obligations_open_or_imported_v1(obligation_ids: &[&str]) -> bool {
    !obligation_ids.is_empty()
        && obligation_ids.iter().all(|obligation_id| {
            PATH2_DIRECT_THEOREM_OBLIGATION_ROWS.iter().any(|row| {
                row.obligation_id == *obligation_id
                    && (row.open
                        || (*obligation_id == "direct_obligation_consume_once"
                            && row.acceptance_hypothesis
                                == "lifecycle_transition_consumes_authorization_once")
                        || (*obligation_id == "direct_obligation_checked_core_frame_binding"
                            && row.acceptance_hypothesis
                                == "checked_core_challenge_binds_public_spend_context")
                        || (*obligation_id == "direct_obligation_slot_authorization_digest"
                            && row.acceptance_hypothesis
                                == "slot_authorization_digest_matches_canonical_leaf"))
            })
        })
}

fn path2_direct_referenced_obligations_closed_by_import_v1(obligation_ids: &[&str]) -> bool {
    !obligation_ids.is_empty()
        && obligation_ids.iter().all(|obligation_id| {
            PATH2_DIRECT_THEOREM_OBLIGATION_ROWS.iter().any(|row| {
                row.obligation_id == *obligation_id
                    && !row.open
                    && ((*obligation_id == "direct_obligation_consume_once"
                        && row.acceptance_hypothesis
                            == "lifecycle_transition_consumes_authorization_once")
                        || (*obligation_id == "direct_obligation_checked_core_frame_binding"
                            && row.acceptance_hypothesis
                                == "checked_core_challenge_binds_public_spend_context")
                        || (*obligation_id == "direct_obligation_slot_authorization_digest"
                            && row.acceptance_hypothesis
                                == "slot_authorization_digest_matches_canonical_leaf"))
            })
        })
}

fn path2_direct_accepted_tuple_field_evidence_rows_v1(
    evidence: &Path2DirectAcceptedSpendTupleEvidenceV1,
) -> Vec<Path2DirectAcceptedTupleFieldEvidenceRowV1> {
    let nonzero = |digest: &[u8; DIGEST_BYTES]| *digest != [0_u8; DIGEST_BYTES];
    let row = |accepted_tuple_field: &'static str,
               direct_obligation_ids: &'static [&'static str],
               accepted_path_evidence_source: &'static str,
               accepted_path_check: &'static str,
               accepted_path_evidence_present: bool,
               imported_boundary_report: &'static str| {
        Path2DirectAcceptedTupleFieldEvidenceRowV1 {
            accepted_tuple_field,
            direct_obligation_ids,
            accepted_path_evidence_source,
            accepted_path_check,
            accepted_path_evidence_present,
            imported_boundary_report,
            separate_closure_required: !path2_direct_referenced_obligations_closed_by_import_v1(
                direct_obligation_ids,
            ),
            all_referenced_direct_obligations_still_open:
                path2_direct_referenced_obligations_still_open_v1(direct_obligation_ids),
            all_referenced_direct_obligations_open_or_imported:
                path2_direct_referenced_obligations_open_or_imported_v1(direct_obligation_ids),
            closed_by_imported_boundary: path2_direct_referenced_obligations_closed_by_import_v1(
                direct_obligation_ids,
            ),
            blocker: PRODUCTION_DEPLOYMENT_BLOCKER_DIRECT_THEOREM_COMPOSITION,
        }
    };

    vec![
        row(
            "public_key_or_public_key_identity",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_PUBLIC_KEY,
            "accepted tuple public-key identity digest",
            "public_key_identity digest present",
            nonzero(&evidence.public_key_identity),
            "",
        ),
        row(
            "message_or_message_digest",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_MESSAGE,
            "accepted tuple message digest",
            "message_digest present",
            nonzero(&evidence.message_digest),
            "",
        ),
        row(
            "account_id",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_ACCOUNT_ID,
            "accepted tuple account id",
            "account_id present",
            nonzero(&evidence.account_id),
            "",
        ),
        row(
            "account_state_root_before_spend",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_ACCOUNT_STATE,
            "accepted tuple account state root before spend",
            "account_state_root_before present",
            nonzero(&evidence.account_state_root_before),
            "",
        ),
        row(
            "slot_id",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_SLOT_ID,
            "accepted tuple slot id and public result accepted slot id",
            "slot_id == accepted_slot_id",
            evidence.slot_id == u64::from(evidence.accepted_slot_id),
            "",
        ),
        row(
            "checked_core_signature_body",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_CHECKED_CORE,
            "checked-core signature, challenge, proof commitment, and QROM/action boundary digest",
            "checked-core digests present && public_result_accepts_same_slot",
            nonzero(&evidence.checked_core_signature_digest)
                && nonzero(&evidence.checked_core_challenge_digest)
                && nonzero(&evidence.checked_core_proof_commitment_digest)
                && nonzero(&evidence.direct_qrom_action_boundary_report_digest)
                && evidence.public_result_accepts_same_slot,
            "Path2DirectQromActionBoundaryReportV1",
        ),
        row(
            "prevalidated_slot_leaf_v1",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_LEAF,
            "accepted tuple prevalidated slot leaf digest",
            "prevalidated_slot_leaf_digest present",
            nonzero(&evidence.prevalidated_slot_leaf_digest),
            "",
        ),
        row(
            "account_creation_evidence_v1",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_EVIDENCE,
            "accepted tuple account-creation evidence transcript and proof-boundary digest",
            "account_creation_evidence_transcript_digest present && account_creation_proof_boundary_report_digest present",
            nonzero(&evidence.account_creation_evidence_transcript_digest)
                && nonzero(&evidence.account_creation_proof_boundary_report_digest),
            "Path2AccountCreationProofBoundaryReportV1",
        ),
        row(
            "selected_account_creation_proof_payload",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_CREATION_PAYLOAD,
            "accepted tuple selected account-creation payload digest and proof-boundary digest",
            "selected_account_creation_payload_digest present && account_creation_proof_boundary_report_digest present",
            nonzero(&evidence.selected_account_creation_payload_digest)
                && nonzero(&evidence.account_creation_proof_boundary_report_digest),
            "Path2AccountCreationProofBoundaryReportV1",
        ),
        row(
            "direct_admission_namespace_record",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_ADMISSION_NAMESPACE,
            "accepted tuple direct admission namespace record and membership flag",
            "direct_admission_namespace_record_digest recomputes && state_namespace_record_present",
            evidence.direct_admission_namespace_record_digest
                == path2_direct_admission_namespace_record_digest(
                    &evidence.account_id,
                    &evidence.account_state_root_before,
                    &evidence.slot_authorization_digest,
                )
                && evidence.state_namespace_record_present,
            "",
        ),
        row(
            "consume_once_state_before_and_after_spend",
            &PATH2_DIRECT_TUPLE_FIELD_OBLIGATIONS_CONSUME_ONCE,
            "accepted tuple consume-once before/after state digests and insertion flags",
            "consume_once_state_before_digest != consume_once_state_after_digest && consumed flags",
            evidence.consume_once_state_before_digest != evidence.consume_once_state_after_digest
                && evidence.consumed_authorization_absent_before
                && evidence.consumed_authorization_present_after
                && evidence.consume_once_inserted_exactly_one_authorization,
            "Path2DirectLifecycleBoundaryReportV1",
        ),
    ]
}

pub fn path2_direct_accepted_spend_tuple_evidence_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    signature: &ProductionSignature,
    admitted_state_authorizations: &BTreeSet<(
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
    )>,
    consumed_before: &BTreeSet<[u8; DIGEST_BYTES]>,
    consumed_after: &BTreeSet<[u8; DIGEST_BYTES]>,
    accepted_parts: &ProductionReviewedFq12AccountCarriedSignatureParts,
) -> Result<Path2DirectAcceptedSpendTupleEvidenceV1, ProductionAccountBindingError> {
    let public_key_identity: [u8; DIGEST_BYTES] = Sha256::digest(public_key.as_bytes()).into();
    if leaf.public_key_identity != public_key_identity {
        return Err(ProductionAccountBindingError::new(
            None,
            "Path 2 accepted tuple public-key identity mismatch",
        ));
    }
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))
        .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let slot_authorization_digest = path2_slot_authorization_digest(leaf)
        .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let namespace_record = (
        leaf.account_id,
        leaf.account_state_root_before,
        slot_authorization_digest,
    );
    let state_namespace_record_present = admitted_state_authorizations.contains(&namespace_record);
    if !state_namespace_record_present {
        return Err(ProductionAccountBindingError::new(
            None,
            "Path 2 accepted tuple state namespace record missing",
        ));
    }
    let checked_core_parts = verify_path2_checked_core_authorization(
        public_key,
        message,
        account,
        &leaf.account_id,
        &leaf.account_state_root_before,
        &slot_authorization_digest,
        signature,
    )?;
    if checked_core_parts != *accepted_parts {
        return Err(ProductionAccountBindingError::new(
            Some(accepted_parts.slot_id),
            "Path 2 accepted tuple checked-core parts mismatch",
        ));
    }
    if u64::from(accepted_parts.slot_id) != leaf.slot_id {
        return Err(ProductionAccountBindingError::new(
            Some(accepted_parts.slot_id),
            "Path 2 accepted tuple slot id mismatch",
        ));
    }

    let consumed_authorization_absent_before =
        !consumed_before.contains(&slot_authorization_digest);
    let consumed_authorization_present_after = consumed_after.contains(&slot_authorization_digest);
    let mut expected_after = consumed_before.clone();
    expected_after.insert(slot_authorization_digest);
    let consume_once_inserted_exactly_one_authorization =
        consumed_authorization_absent_before && expected_after == *consumed_after;
    if !consume_once_inserted_exactly_one_authorization {
        return Err(ProductionAccountBindingError::new(
            Some(accepted_parts.slot_id),
            "Path 2 accepted tuple consume-once transition mismatch",
        ));
    }

    let mut public_result_consumed = consumed_before.clone();
    let public_result = verify_path2_direct_single_slot_spend_authorization_public_result_v1(
        leaf,
        evidence,
        certificate,
        public_key,
        message,
        account,
        signature,
        admitted_state_authorizations,
        &mut public_result_consumed,
    );
    let public_result_accepts_same_slot = public_result.result_class
        == Path2PublicResultClassV1::AcceptSpendSlot
        && public_result.accepted_slot_id == Some(accepted_parts.slot_id)
        && public_result_consumed == *consumed_after;
    if !public_result_accepts_same_slot {
        return Err(ProductionAccountBindingError::new(
            Some(accepted_parts.slot_id),
            "Path 2 accepted tuple public result mismatch",
        ));
    }

    let leaf_digest = path2_prevalidated_slot_leaf_digest(leaf)
        .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let evidence_transcript_digest = path2_account_creation_evidence_transcript_digest(evidence)
        .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let direct_qrom_action_boundary_report = path2_direct_qrom_action_boundary_report_v1();
    let direct_lifecycle_boundary_report = path2_direct_lifecycle_boundary_report_v1();
    let account_creation_proof_boundary_report = path2_account_creation_proof_boundary_report_v1();
    let signature_bytes = signature.as_bytes();
    let challenge_bytes = &signature_bytes[SLOT_ID_BYTES..SLOT_ID_BYTES + CHALLENGE_BYTES];
    let tuple_fields_match_theorem_boundary = PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.len()
        == 11
        && PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS
            .contains(&"public_key_or_public_key_identity")
        && PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.contains(&"message_or_message_digest")
        && PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS
            .contains(&"direct_admission_namespace_record")
        && PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS
            .contains(&"consume_once_state_before_and_after_spend");
    if !tuple_fields_match_theorem_boundary {
        return Err(ProductionAccountBindingError::new(
            Some(accepted_parts.slot_id),
            "Path 2 accepted tuple theorem-field boundary mismatch",
        ));
    }

    let mut tuple_evidence = Path2DirectAcceptedSpendTupleEvidenceV1 {
        digest: [0_u8; DIGEST_BYTES],
        schema: PATH2_DIRECT_ACCEPTED_SPEND_TUPLE_EVIDENCE_SCHEMA,
        theorem_target: PATH2_DIRECT_THEOREM_TARGET,
        theorem_conclusion: PATH2_DIRECT_THEOREM_CONCLUSION,
        accepted_tuple_fields: &PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS,
        acceptance_hypotheses: &PATH2_DIRECT_THEOREM_ACCEPTANCE_HYPOTHESES,
        accepted_tuple_field_evidence_rows: Vec::new(),
        accepted_tuple_field_evidence_count: 0,
        accepted_tuple_field_evidence_present_count: 0,
        accepted_tuple_field_open_obligation_count: 0,
        accepted_tuple_field_imported_closure_count: 0,
        every_accepted_tuple_field_has_evidence: false,
        every_accepted_tuple_field_has_open_direct_obligation: false,
        every_accepted_tuple_field_has_open_or_imported_direct_obligation: false,
        direct_qrom_action_boundary_report_digest: direct_qrom_action_boundary_report.digest,
        direct_lifecycle_boundary_report_digest: direct_lifecycle_boundary_report.digest,
        account_creation_proof_boundary_report_digest: account_creation_proof_boundary_report
            .digest,
        public_key_identity,
        message_digest: Sha256::digest(message).into(),
        account_id: leaf.account_id,
        account_state_root_before: leaf.account_state_root_before,
        slot_id: leaf.slot_id,
        accepted_slot_id: accepted_parts.slot_id,
        checked_core_signature_digest: Sha256::digest(signature.as_bytes()).into(),
        checked_core_challenge_digest: Sha256::digest(challenge_bytes).into(),
        checked_core_proof_commitment_digest: Sha256::digest(accepted_parts.proof.proof_commitment)
            .into(),
        prevalidated_slot_leaf_digest: leaf_digest,
        account_creation_evidence_transcript_digest: evidence_transcript_digest,
        selected_account_creation_payload_digest: certificate.public_replay_payload_digest,
        direct_admission_namespace_record_digest: path2_direct_admission_namespace_record_digest(
            &leaf.account_id,
            &leaf.account_state_root_before,
            &slot_authorization_digest,
        ),
        slot_authorization_digest,
        consume_once_state_before_digest: path2_direct_consume_once_authorization_set_digest(
            consumed_before,
        ),
        consume_once_state_after_digest: path2_direct_consume_once_authorization_set_digest(
            consumed_after,
        ),
        public_result_class_name: public_result.result_class_name,
        state_namespace_record_present,
        consumed_authorization_absent_before,
        consumed_authorization_present_after,
        consume_once_inserted_exactly_one_authorization,
        public_result_accepts_same_slot,
        tuple_fields_match_theorem_boundary,
    };
    tuple_evidence.accepted_tuple_field_evidence_rows =
        path2_direct_accepted_tuple_field_evidence_rows_v1(&tuple_evidence);
    tuple_evidence.accepted_tuple_field_evidence_count =
        tuple_evidence.accepted_tuple_field_evidence_rows.len();
    tuple_evidence.accepted_tuple_field_evidence_present_count = tuple_evidence
        .accepted_tuple_field_evidence_rows
        .iter()
        .filter(|row| row.accepted_path_evidence_present)
        .count();
    tuple_evidence.accepted_tuple_field_open_obligation_count = tuple_evidence
        .accepted_tuple_field_evidence_rows
        .iter()
        .filter(|row| row.all_referenced_direct_obligations_still_open)
        .count();
    tuple_evidence.accepted_tuple_field_imported_closure_count = tuple_evidence
        .accepted_tuple_field_evidence_rows
        .iter()
        .filter(|row| row.closed_by_imported_boundary)
        .count();
    tuple_evidence.every_accepted_tuple_field_has_evidence = tuple_evidence
        .accepted_tuple_field_evidence_count
        == PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.len()
        && tuple_evidence.accepted_tuple_field_evidence_present_count
            == PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.len()
        && PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS
            .iter()
            .zip(tuple_evidence.accepted_tuple_field_evidence_rows.iter())
            .all(|(field, row)| {
                row.accepted_tuple_field == *field && row.accepted_path_evidence_present
            });
    tuple_evidence.every_accepted_tuple_field_has_open_direct_obligation = tuple_evidence
        .accepted_tuple_field_evidence_count
        == PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.len()
        && tuple_evidence.accepted_tuple_field_open_obligation_count
            == PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.len()
        && tuple_evidence
            .accepted_tuple_field_evidence_rows
            .iter()
            .all(|row| {
                row.separate_closure_required
                    && row.all_referenced_direct_obligations_still_open
                    && row.blocker == PRODUCTION_DEPLOYMENT_BLOCKER_DIRECT_THEOREM_COMPOSITION
            });
    tuple_evidence.every_accepted_tuple_field_has_open_or_imported_direct_obligation =
        tuple_evidence.accepted_tuple_field_evidence_count
            == PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.len()
            && tuple_evidence
                .accepted_tuple_field_evidence_rows
                .iter()
                .all(|row| row.all_referenced_direct_obligations_open_or_imported);
    tuple_evidence.digest = path2_direct_accepted_spend_tuple_evidence_v1_digest(&tuple_evidence);
    Ok(tuple_evidence)
}

pub fn verify_path2_direct_single_slot_spend_authorization_with_tuple_evidence_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    signature: &ProductionSignature,
    admitted_state_authorizations: &BTreeSet<(
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
    )>,
    consumed_authorizations: &mut BTreeSet<[u8; DIGEST_BYTES]>,
) -> Result<Path2DirectAcceptedSpendTupleEvidenceV1, ProductionAccountBindingError> {
    let consumed_before = consumed_authorizations.clone();
    let parts = verify_path2_direct_single_slot_spend_authorization(
        leaf,
        evidence,
        certificate,
        public_key,
        message,
        account,
        signature,
        admitted_state_authorizations,
        consumed_authorizations,
    )?;
    let consumed_after = consumed_authorizations.clone();
    path2_direct_accepted_spend_tuple_evidence_v1(
        leaf,
        evidence,
        certificate,
        public_key,
        message,
        account,
        signature,
        admitted_state_authorizations,
        &consumed_before,
        &consumed_after,
        &parts,
    )
}

#[cfg(feature = "account-creation-stark-verifier")]
struct Path2DirectAcceptedSpendTupleKatContextV1 {
    direct_report: Path2DirectTheoremBoundaryReportV1,
    qrom_report: Path2DirectQromActionBoundaryReportV1,
    lifecycle_report: Path2DirectLifecycleBoundaryReportV1,
    proof_report: Path2AccountCreationProofBoundaryReportV1,
    stark_fixture: Path2AccountStarkPayloadKatFixtureV1,
    creation_evidence: Path2AccountCreationAcceptedProofBoundaryEvidenceV1,
    authorization: [u8; DIGEST_BYTES],
    consumed: BTreeSet<[u8; DIGEST_BYTES]>,
    tuple_evidence: Path2DirectAcceptedSpendTupleEvidenceV1,
    replay_rejected_by_consume_once: bool,
}

#[cfg(feature = "account-creation-stark-verifier")]
fn path2_direct_accepted_spend_tuple_kat_context_v1(
) -> Result<Path2DirectAcceptedSpendTupleKatContextV1, String> {
    let direct_report = path2_direct_theorem_boundary_report_v1();
    validate_path2_direct_theorem_boundary_report_v1(&direct_report)?;
    let qrom_report = path2_direct_qrom_action_boundary_report_v1();
    validate_path2_direct_qrom_action_boundary_report_v1(&qrom_report)?;
    let lifecycle_report = path2_direct_lifecycle_boundary_report_v1();
    validate_path2_direct_lifecycle_boundary_report_v1(&lifecycle_report)?;
    let proof_report = path2_account_creation_proof_boundary_report_v1();
    validate_path2_account_creation_proof_boundary_report_v1(&proof_report)?;
    let (reviewed_fixture, stark_fixture) =
        path2_account_stark_payload_kat_fixture_with_reviewed_v1()?;
    let creation_evidence =
        path2_account_creation_accepted_proof_boundary_evidence_for_fixture_v1(&stark_fixture)?;

    verify_path2_direct_creation_account_stark_payload_boundary(
        &stark_fixture.leaf,
        &stark_fixture.evidence,
        &stark_fixture.certificate,
        &stark_fixture.binding,
        &stark_fixture.payload,
    )?;

    let authorization = path2_slot_authorization_digest(&stark_fixture.leaf)?;
    let mut admitted_state_authorizations = BTreeSet::new();
    admitted_state_authorizations.insert((
        stark_fixture.leaf.account_id,
        stark_fixture.leaf.account_state_root_before,
        authorization,
    ));
    let responses = ProductionCompactResponses {
        active_free: [[0_i16; LOCAL_FREE]; REPS],
    };
    let signature = sign_path2_reviewed_fq12_authorization_checked_core(
        &reviewed_fixture.public_key,
        reviewed_fixture.message,
        &reviewed_fixture.account,
        &stark_fixture.leaf.account_id,
        &stark_fixture.leaf.account_state_root_before,
        &authorization,
        stark_fixture.leaf.slot_id as u32,
        &reviewed_fixture.pad_seed,
        &responses,
    )
    .map_err(|err| err.reason().to_string())?;
    let mut consumed = BTreeSet::new();
    let tuple_evidence =
        verify_path2_direct_single_slot_spend_authorization_with_tuple_evidence_v1(
            &stark_fixture.leaf,
            &stark_fixture.evidence,
            &stark_fixture.certificate,
            &reviewed_fixture.public_key,
            reviewed_fixture.message,
            &reviewed_fixture.account,
            &signature,
            &admitted_state_authorizations,
            &mut consumed,
        )
        .map_err(|err| err.reason().to_string())?;
    let tuple_digest = path2_direct_accepted_spend_tuple_evidence_v1_digest(&tuple_evidence);
    if tuple_digest != tuple_evidence.digest {
        return Err("Path 2 direct accepted spend tuple KAT digest mismatch".to_string());
    }
    if tuple_evidence.public_result_class_name != PATH2_PUBLIC_RESULT_ACCEPT_SPEND_SLOT
        || !tuple_evidence.state_namespace_record_present
        || !tuple_evidence.consumed_authorization_absent_before
        || !tuple_evidence.consumed_authorization_present_after
        || !tuple_evidence.consume_once_inserted_exactly_one_authorization
        || !tuple_evidence.public_result_accepts_same_slot
        || !tuple_evidence.tuple_fields_match_theorem_boundary
    {
        return Err("Path 2 direct accepted spend tuple KAT lost acceptance flags".to_string());
    }
    let replay_rejected_by_consume_once =
        match verify_path2_direct_single_slot_spend_authorization_with_tuple_evidence_v1(
            &stark_fixture.leaf,
            &stark_fixture.evidence,
            &stark_fixture.certificate,
            &reviewed_fixture.public_key,
            reviewed_fixture.message,
            &reviewed_fixture.account,
            &signature,
            &admitted_state_authorizations,
            &mut consumed,
        ) {
            Ok(_) => false,
            Err(err) => err.reason() == "Path 2 slot authorization already consumed",
        };
    if !replay_rejected_by_consume_once {
        return Err(
            "Path 2 direct accepted spend tuple KAT replay was not consume-once rejected"
                .to_string(),
        );
    }

    Ok(Path2DirectAcceptedSpendTupleKatContextV1 {
        direct_report,
        qrom_report,
        lifecycle_report,
        proof_report,
        stark_fixture,
        creation_evidence,
        authorization,
        consumed,
        tuple_evidence,
        replay_rejected_by_consume_once,
    })
}

#[cfg(feature = "account-creation-stark-verifier")]
fn path2_direct_accepted_spend_tuple_kat_evidence_unpooled_v1(
) -> Result<Path2DirectAcceptedSpendTupleKatEvidenceV1, String> {
    let context = path2_direct_accepted_spend_tuple_kat_context_v1()?;
    Ok(Path2DirectAcceptedSpendTupleKatEvidenceV1 {
        account_creation_fixture_id: context.stark_fixture.fixture_id,
        proof_mask_seed: context.stark_fixture.proof_mask_seed,
        evidence: context.tuple_evidence,
        replay_rejected_by_consume_once: context.replay_rejected_by_consume_once,
    })
}

#[cfg(feature = "account-creation-stark-verifier")]
pub fn path2_direct_accepted_spend_tuple_kat_evidence_v1(
) -> Result<Path2DirectAcceptedSpendTupleKatEvidenceV1, String> {
    let pool = rayon::ThreadPoolBuilder::new()
        .num_threads(1)
        .build()
        .map_err(|err| format!("failed to build deterministic single-thread KAT pool: {err}"))?;
    pool.install(path2_direct_accepted_spend_tuple_kat_evidence_unpooled_v1)
}

fn path2_direct_obligation_still_open_for_hypothesis_v1(
    direct_report: &Path2DirectTheoremBoundaryReportV1,
    direct_obligation_id: &str,
    acceptance_hypothesis: &str,
) -> bool {
    direct_report.obligation_rows.iter().any(|row| {
        row.obligation_id == direct_obligation_id
            && row.acceptance_hypothesis == acceptance_hypothesis
            && row.open
    })
}

fn path2_direct_accepted_composition_hypothesis_evidence_rows_v1(
    evidence: &Path2DirectAcceptedCompositionEvidenceV1,
    direct_report: &Path2DirectTheoremBoundaryReportV1,
) -> Vec<Path2DirectAcceptedCompositionHypothesisEvidenceRowV1> {
    let row = |acceptance_hypothesis: &'static str,
               direct_obligation_id: &'static str,
               accepted_path_evidence_source: &'static str,
               accepted_path_check: &'static str,
               accepted_path_evidence_present: bool,
               separate_rejection_evidence_required: bool| {
        Path2DirectAcceptedCompositionHypothesisEvidenceRowV1 {
            acceptance_hypothesis,
            direct_obligation_id,
            accepted_path_evidence_source,
            accepted_path_check,
            accepted_path_evidence_present,
            separate_rejection_evidence_required,
            theorem_obligation_still_open: path2_direct_obligation_still_open_for_hypothesis_v1(
                direct_report,
                direct_obligation_id,
                acceptance_hypothesis,
            ),
            closed_by_imported_boundary: path2_direct_referenced_obligations_closed_by_import_v1(
                &[direct_obligation_id],
            ),
        }
    };

    vec![
        row(
            "leaf_is_canonical_and_live",
            "direct_obligation_leaf_canonical_live",
            "accepted composition leaf digest and direct verifier accepted tuple",
            "creation_evidence_matches_direct_tuple && direct_spend_tuple_accepts",
            evidence.creation_evidence_matches_direct_tuple && evidence.direct_spend_tuple_accepts,
            false,
        ),
        row(
            "evidence_envelope_matches_leaf_bindings",
            "direct_obligation_evidence_leaf_bindings",
            "accepted account-creation proof-boundary evidence and direct tuple digest",
            "creation_evidence_matches_direct_tuple && proof_boundary_digest_matches_direct_theorem",
            evidence.creation_evidence_matches_direct_tuple
                && evidence.proof_boundary_digest_matches_direct_theorem,
            false,
        ),
        row(
            "slot_authorization_digest_matches_canonical_leaf",
            "direct_obligation_slot_authorization_digest",
            "accepted tuple slot_authorization_digest and admission namespace digest",
            "direct_admission_namespace_matches_authorization && direct_spend_tuple_accepts",
            evidence.direct_admission_namespace_matches_authorization
                && evidence.direct_spend_tuple_accepts,
            false,
        ),
        row(
            "selected_creation_verifier_accepted_before_spend_challenge",
            "direct_obligation_creation_before_challenge",
            "accepted composition orders account-creation boundary acceptance before direct spend tuple verification",
            "verifier_boundary_accepts_creation && direct_spend_tuple_accepts",
            evidence.verifier_boundary_accepts_creation && evidence.direct_spend_tuple_accepts,
            false,
        ),
        row(
            "direct_admission_namespace_contains_exact_tuple",
            "direct_obligation_admission_namespace",
            "direct admission namespace record digest",
            "direct_admission_namespace_matches_authorization",
            evidence.direct_admission_namespace_matches_authorization,
            false,
        ),
        row(
            "checked_core_challenge_binds_public_spend_context",
            "direct_obligation_checked_core_frame_binding",
            "direct spend tuple digest and public result wrapper acceptance",
            "direct_spend_tuple_accepts && public_result_accepts_same_slot",
            evidence.direct_spend_tuple_accepts && evidence.public_result_accepts_same_slot,
            false,
        ),
        row(
            "checked_core_verification_accepts_poseidon2_and_fq12_action",
            "direct_obligation_checked_core_acceptance",
            "accepted direct spend tuple and QROM/action boundary digest",
            "direct_spend_tuple_accepts && qrom_action_digest_matches_direct_theorem",
            evidence.direct_spend_tuple_accepts
                && evidence.qrom_action_digest_matches_direct_theorem,
            false,
        ),
        row(
            "lifecycle_transition_consumes_authorization_once",
            "direct_obligation_consume_once",
            "consume-once before/after state digests",
            "consume_once_transition_matches_tuple && lifecycle_digest_matches_direct_theorem",
            evidence.consume_once_transition_matches_tuple
                && evidence.lifecycle_digest_matches_direct_theorem,
            false,
        ),
        row(
            "rejection_is_deterministic_public_and_state_preserving",
            "direct_obligation_public_rejection",
            "direct public rejection KAT suite",
            "not a happy-path composition property; covered by direct rejection KAT gates",
            false,
            true,
        ),
    ]
}

#[cfg(feature = "account-creation-stark-verifier")]
fn path2_direct_accepted_composition_evidence_unpooled_v1(
) -> Result<Path2DirectAcceptedCompositionEvidenceV1, String> {
    let Path2DirectAcceptedSpendTupleKatContextV1 {
        direct_report,
        qrom_report,
        lifecycle_report,
        proof_report,
        stark_fixture,
        creation_evidence,
        authorization,
        consumed,
        tuple_evidence,
        ..
    } = path2_direct_accepted_spend_tuple_kat_context_v1()?;

    let creation_evidence_matches_direct_tuple = creation_evidence.account_id
        == tuple_evidence.account_id
        && creation_evidence.public_key_identity == tuple_evidence.public_key_identity
        && creation_evidence.account_state_root_before == tuple_evidence.account_state_root_before
        && creation_evidence.slot_id == tuple_evidence.slot_id
        && creation_evidence.prevalidated_slot_leaf_digest
            == tuple_evidence.prevalidated_slot_leaf_digest
        && creation_evidence.account_creation_evidence_transcript_digest
            == tuple_evidence.account_creation_evidence_transcript_digest
        && creation_evidence.selected_account_creation_payload_digest
            == tuple_evidence.selected_account_creation_payload_digest
        && creation_evidence.slot_authorization_digest == tuple_evidence.slot_authorization_digest;
    let proof_boundary_digest_matches_direct_theorem = direct_report
        .account_creation_proof_boundary_report_digest
        == proof_report.digest
        && tuple_evidence.account_creation_proof_boundary_report_digest == proof_report.digest
        && creation_evidence.account_creation_proof_boundary_report_digest == proof_report.digest;
    let qrom_action_digest_matches_direct_theorem =
        direct_report.direct_qrom_action_boundary_report_digest == qrom_report.digest
            && tuple_evidence.direct_qrom_action_boundary_report_digest == qrom_report.digest;
    let lifecycle_digest_matches_direct_theorem =
        direct_report.direct_lifecycle_boundary_report_digest == lifecycle_report.digest
            && tuple_evidence.direct_lifecycle_boundary_report_digest == lifecycle_report.digest;
    let direct_admission_namespace_matches_authorization = tuple_evidence
        .direct_admission_namespace_record_digest
        == path2_direct_admission_namespace_record_digest(
            &stark_fixture.leaf.account_id,
            &stark_fixture.leaf.account_state_root_before,
            &authorization,
        );
    let consume_once_transition_matches_tuple = tuple_evidence.consume_once_state_after_digest
        == path2_direct_consume_once_authorization_set_digest(&consumed)
        && tuple_evidence.consumed_authorization_absent_before
        && tuple_evidence.consumed_authorization_present_after
        && tuple_evidence.consume_once_inserted_exactly_one_authorization;
    let direct_spend_tuple_accepts =
        tuple_evidence.public_result_class_name == PATH2_PUBLIC_RESULT_ACCEPT_SPEND_SLOT;
    let public_result_accepts_same_slot = tuple_evidence.public_result_accepts_same_slot;
    let direct_theorem_obligations_still_open =
        direct_report.obligation_rows.iter().any(|row| row.open);

    if !creation_evidence_matches_direct_tuple
        || !proof_boundary_digest_matches_direct_theorem
        || !qrom_action_digest_matches_direct_theorem
        || !lifecycle_digest_matches_direct_theorem
        || !direct_admission_namespace_matches_authorization
        || !consume_once_transition_matches_tuple
        || !creation_evidence.verifier_boundary_accepts
        || !direct_spend_tuple_accepts
        || !public_result_accepts_same_slot
        || !direct_theorem_obligations_still_open
        || !creation_evidence.proof_family_obligations_still_open
    {
        return Err("Path 2 direct accepted composition evidence boundary mismatch".to_string());
    }

    let mut evidence = Path2DirectAcceptedCompositionEvidenceV1 {
        digest: [0_u8; DIGEST_BYTES],
        schema: PATH2_DIRECT_ACCEPTED_COMPOSITION_EVIDENCE_SCHEMA,
        theorem_target: PATH2_DIRECT_THEOREM_TARGET,
        theorem_conclusion: PATH2_DIRECT_THEOREM_CONCLUSION,
        direct_theorem_boundary_report_digest: direct_report.digest,
        direct_accepted_spend_tuple_evidence_digest: tuple_evidence.digest,
        account_creation_accepted_proof_boundary_evidence_digest: creation_evidence.digest,
        direct_qrom_action_boundary_report_digest: qrom_report.digest,
        direct_lifecycle_boundary_report_digest: lifecycle_report.digest,
        account_creation_proof_boundary_report_digest: proof_report.digest,
        account_creation_fixture_id: stark_fixture.fixture_id,
        proof_mask_seed: stark_fixture.proof_mask_seed,
        public_key_identity: tuple_evidence.public_key_identity,
        message_digest: tuple_evidence.message_digest,
        account_id: tuple_evidence.account_id,
        account_state_root_before: tuple_evidence.account_state_root_before,
        slot_id: tuple_evidence.slot_id,
        prevalidated_slot_leaf_digest: tuple_evidence.prevalidated_slot_leaf_digest,
        account_creation_evidence_transcript_digest: tuple_evidence
            .account_creation_evidence_transcript_digest,
        selected_account_creation_payload_digest: tuple_evidence
            .selected_account_creation_payload_digest,
        slot_authorization_digest: tuple_evidence.slot_authorization_digest,
        direct_admission_namespace_record_digest: tuple_evidence
            .direct_admission_namespace_record_digest,
        consume_once_state_before_digest: tuple_evidence.consume_once_state_before_digest,
        consume_once_state_after_digest: tuple_evidence.consume_once_state_after_digest,
        creation_evidence_matches_direct_tuple,
        proof_boundary_digest_matches_direct_theorem,
        qrom_action_digest_matches_direct_theorem,
        lifecycle_digest_matches_direct_theorem,
        direct_admission_namespace_matches_authorization,
        consume_once_transition_matches_tuple,
        verifier_boundary_accepts_creation: creation_evidence.verifier_boundary_accepts,
        direct_spend_tuple_accepts,
        public_result_accepts_same_slot,
        accepted_hypothesis_evidence_rows: Vec::new(),
        accepted_hypothesis_evidence_count: 0,
        positive_acceptance_hypothesis_evidence_count: 0,
        every_positive_acceptance_hypothesis_has_accepted_path_evidence: false,
        public_rejection_hypothesis_deferred_to_rejection_kats: false,
        direct_theorem_obligations_still_open,
        proof_family_obligations_still_open: creation_evidence.proof_family_obligations_still_open,
        composition_theorem_instantiated: false,
        account_creation_proof_boundary_verified: false,
        deployment_ready: false,
    };
    evidence.accepted_hypothesis_evidence_rows =
        path2_direct_accepted_composition_hypothesis_evidence_rows_v1(&evidence, &direct_report);
    evidence.accepted_hypothesis_evidence_count = evidence.accepted_hypothesis_evidence_rows.len();
    evidence.positive_acceptance_hypothesis_evidence_count = evidence
        .accepted_hypothesis_evidence_rows
        .iter()
        .filter(|row| {
            row.accepted_path_evidence_present && !row.separate_rejection_evidence_required
        })
        .count();
    evidence.every_positive_acceptance_hypothesis_has_accepted_path_evidence = evidence
        .accepted_hypothesis_evidence_count
        == PATH2_DIRECT_THEOREM_ACCEPTANCE_HYPOTHESES.len()
        && evidence.positive_acceptance_hypothesis_evidence_count == 8
        && evidence
            .accepted_hypothesis_evidence_rows
            .iter()
            .filter(|row| !row.separate_rejection_evidence_required)
            .all(|row| {
                row.accepted_path_evidence_present
                    && (row.theorem_obligation_still_open || row.closed_by_imported_boundary)
            });
    evidence.public_rejection_hypothesis_deferred_to_rejection_kats = evidence
        .accepted_hypothesis_evidence_rows
        .iter()
        .any(|row| {
            row.acceptance_hypothesis == "rejection_is_deterministic_public_and_state_preserving"
                && row.direct_obligation_id == "direct_obligation_public_rejection"
                && !row.accepted_path_evidence_present
                && row.separate_rejection_evidence_required
                && row.theorem_obligation_still_open
        });
    evidence.digest = path2_direct_accepted_composition_evidence_v1_digest(&evidence);
    Ok(evidence)
}

#[cfg(feature = "account-creation-stark-verifier")]
pub fn path2_direct_accepted_composition_evidence_v1(
) -> Result<Path2DirectAcceptedCompositionEvidenceV1, String> {
    let pool = rayon::ThreadPoolBuilder::new()
        .num_threads(1)
        .build()
        .map_err(|err| format!("failed to build deterministic single-thread KAT pool: {err}"))?;
    pool.install(path2_direct_accepted_composition_evidence_unpooled_v1)
}

pub fn validate_path2_account_creation_accepted_proof_boundary_evidence_v1(
    evidence: &Path2AccountCreationAcceptedProofBoundaryEvidenceV1,
) -> Result<(), String> {
    if path2_account_creation_accepted_proof_boundary_evidence_v1_digest(evidence)
        != evidence.digest
    {
        return Err(
            "Path 2 account-creation accepted proof-boundary evidence digest mismatch".to_string(),
        );
    }

    let proof_boundary_report = path2_account_creation_proof_boundary_report_v1();
    validate_path2_account_creation_proof_boundary_report_v1(&proof_boundary_report)?;
    let sampler_timing_report = path2_account_creation_sampler_timing_report_v1();
    validate_path2_account_creation_sampler_timing_report_v1(&sampler_timing_report)?;
    let no_export_boundary_report = path2_account_creation_no_export_boundary_report_v1();
    validate_path2_account_creation_no_export_boundary_report_v1(&no_export_boundary_report)?;
    let residual_matrix_report = path2_account_stark_residual_matrix_report_v1();
    validate_path2_account_stark_residual_matrix_report_v1(&residual_matrix_report)?;
    let frame_kat_boundary_report = path2_account_creation_frame_kat_boundary_report_v1();
    validate_path2_account_creation_frame_kat_boundary_report_v1(&frame_kat_boundary_report)?;
    let fri_qrom_residual_report = path2_account_stark_fri_qrom_residual_report_v1();
    validate_path2_account_stark_fri_qrom_residual_report_v1(&fri_qrom_residual_report)?;
    let fri_aok_boundary_report = path2_account_stark_fri_aok_boundary_report_v1();
    validate_path2_account_stark_fri_aok_boundary_report_v1(&fri_aok_boundary_report)?;
    let payload_byte_model_report = path2_account_stark_payload_byte_model_report_v1();
    validate_path2_account_stark_payload_byte_model_report_v1(&payload_byte_model_report)?;
    let payload_kat_boundary_report = path2_account_stark_payload_kat_boundary_report_v1();
    validate_path2_account_stark_payload_kat_boundary_report_v1(&payload_kat_boundary_report)?;

    if evidence.schema != PATH2_ACCOUNT_CREATION_ACCEPTED_PROOF_BOUNDARY_EVIDENCE_SCHEMA
        || evidence.proof_boundary_target != proof_boundary_report.proof_boundary_target
        || evidence.proof_boundary_conclusion != proof_boundary_report.proof_boundary_conclusion
        || evidence.selected_payload_type != proof_boundary_report.selected_payload_type
        || evidence.verifier_boundary_endpoint != proof_boundary_report.verifier_boundary_endpoint
        || evidence.production_boundary_endpoint
            != proof_boundary_report.production_boundary_endpoint
        || evidence.replay_payload_digest_function
            != proof_boundary_report.replay_payload_digest_function
        || evidence.accepting_requirements != proof_boundary_report.accepting_requirements
        || evidence.account_creation_proof_boundary_report_digest != proof_boundary_report.digest
        || evidence.sampler_timing_report_digest != sampler_timing_report.digest
        || evidence.no_export_boundary_report_digest != no_export_boundary_report.digest
        || evidence.account_stark_residual_matrix_report_digest != residual_matrix_report.digest
        || evidence.frame_kat_boundary_report_digest != frame_kat_boundary_report.digest
        || evidence.fri_qrom_residual_report_digest != fri_qrom_residual_report.digest
        || evidence.fri_aok_boundary_report_digest != fri_aok_boundary_report.digest
        || evidence.payload_byte_model_report_digest != payload_byte_model_report.digest
        || evidence.payload_kat_boundary_report_digest != payload_kat_boundary_report.digest
    {
        return Err(
            "Path 2 account-creation accepted proof-boundary evidence authority mismatch"
                .to_string(),
        );
    }

    if evidence.fixture_id != "Path2AccountStarkPayloadKatFixture.v1"
        || evidence.payload_frame_bytes <= evidence.account_stark_bundle_bytes
        || evidence.account_stark_bundle_bytes == 0
        || evidence.decoded_public_anchor_digest != evidence.deployed_anchor_digest
    {
        return Err(
            "Path 2 account-creation accepted proof-boundary evidence fixture binding mismatch"
                .to_string(),
        );
    }

    #[cfg(feature = "account-creation-stark-verifier")]
    {
        let fixture = path2_account_stark_payload_kat_fixture_deterministic_v1()?;
        let payload_frame = path2_account_stark_creation_payload_v1_frame(&fixture.payload)?;
        let payload_digest = path2_account_stark_creation_payload_v1_digest(&fixture.payload)?;
        let decoded_public_anchors =
            descender_account_verifier::decode_deployed_account_creation_public_anchors(
                &fixture.payload.account_stark_bundle,
            )
            .map_err(|error| {
                format!("Path 2 account-STARK public anchor decode failed: {error}")
            })?;
        let deployed_anchor_digest = path2_account_creation_deployed_anchor_digest(
            &fixture.leaf,
            &fixture.binding,
            &fixture.payload,
        );
        let decoded_public_anchor_digest =
            path2_account_creation_decoded_public_anchor_digest(&decoded_public_anchors);
        let payload_frame_digest: [u8; DIGEST_BYTES] = Sha256::digest(&payload_frame).into();
        let account_stark_bundle_digest: [u8; DIGEST_BYTES] =
            Sha256::digest(&fixture.payload.account_stark_bundle).into();
        if evidence.fixture_id != fixture.fixture_id
            || evidence.proof_mask_seed != fixture.proof_mask_seed
            || evidence.account_id != fixture.leaf.account_id
            || evidence.public_key_identity != fixture.leaf.public_key_identity
            || evidence.account_state_root_before != fixture.leaf.account_state_root_before
            || evidence.slot_id != fixture.leaf.slot_id
            || evidence.prevalidated_slot_leaf_digest
                != path2_prevalidated_slot_leaf_digest(&fixture.leaf)?
            || evidence.slot_authorization_digest != path2_slot_authorization_digest(&fixture.leaf)?
            || evidence.account_creation_evidence_transcript_digest
                != path2_account_creation_evidence_transcript_digest(&fixture.evidence)?
            || evidence.direct_replayable_relation_certificate_digest
                != path2_direct_replayable_relation_certificate_digest(&fixture.certificate)
            || evidence.selected_account_creation_payload_digest != payload_digest
            || evidence.creation_proof_binding_digest
                != path2_creation_proof_binding_v1_digest(&fixture.binding)
            || evidence.leaf_context_digest
                != path2_prevalidated_slot_leaf_context_digest(
                    &fixture.leaf,
                    &fixture.evidence,
                    &fixture.certificate,
                )?
            || evidence.aggregation_context_digest != fixture.payload.aggregation_context_digest
            || evidence.native_role_root_commitment != fixture.payload.native_role_root_commitment
            || evidence.masked_projection_digest
                != path2_account_creation_masked_projection_digest(
                    &fixture.payload.masked_projection,
                )
            || evidence.deployed_anchor_digest != deployed_anchor_digest
            || evidence.payload_frame_digest != payload_frame_digest
            || evidence.payload_frame_bytes != payload_frame.len()
            || evidence.account_stark_bundle_digest != account_stark_bundle_digest
            || evidence.account_stark_bundle_bytes != fixture.payload.account_stark_bundle.len()
            || evidence.decoded_public_anchor_digest != decoded_public_anchor_digest
        {
            return Err(
                "Path 2 account-creation accepted proof-boundary evidence fixture binding mismatch"
                    .to_string(),
            );
        }
    }

    let expected_requirement_rows = path2_account_creation_accepted_requirement_evidence_rows_v1(
        evidence,
        &proof_boundary_report,
    );
    if evidence.accepted_requirement_evidence_rows != expected_requirement_rows
        || evidence.accepted_requirement_evidence_count
            != PATH2_ACCOUNT_CREATION_PROOF_BOUNDARY_REQUIREMENTS.len()
        || evidence.accepted_requirement_evidence_count
            != evidence.accepted_requirement_evidence_rows.len()
        || evidence.accepted_path_applicable_requirement_count != 8
        || evidence.accepted_path_requirement_evidence_count != 8
        || evidence.boundary_or_audit_requirement_evidence_count
            != PATH2_ACCOUNT_CREATION_PROOF_BOUNDARY_REQUIREMENTS.len()
        || evidence.separate_closure_required_count != 4
        || !evidence.every_applicable_accepting_requirement_has_accepted_path_evidence
        || !evidence.every_accepting_requirement_has_boundary_or_audit_evidence
        || !evidence.every_separate_closure_requirement_has_open_obligation
        || !evidence.deterministic_rejection_requirement_deferred_to_rejection_kats
        || !evidence.qrom_requirement_deferred_to_residual_theorem
    {
        return Err(
            "Path 2 account-creation accepted proof-boundary evidence lost requirement evidence rows"
                .to_string(),
        );
    }

    let required_true = [
        (
            "verifier_boundary_accepts",
            evidence.verifier_boundary_accepts,
        ),
        (
            "production_gate_fail_closed",
            evidence.production_gate_fail_closed,
        ),
        (
            "proof_boundary_report_validated",
            evidence.proof_boundary_report_validated,
        ),
        (
            "payload_digest_bound_to_certificate",
            evidence.payload_digest_bound_to_certificate,
        ),
        (
            "evidence_digest_bound_to_certificate",
            evidence.evidence_digest_bound_to_certificate,
        ),
        (
            "leaf_transcript_bound_to_evidence",
            evidence.leaf_transcript_bound_to_evidence,
        ),
        (
            "leaf_digest_bound_to_evidence",
            evidence.leaf_digest_bound_to_evidence,
        ),
        ("leaf_context_bound", evidence.leaf_context_bound),
        ("binding_digest_bound", evidence.binding_digest_bound),
        (
            "payload_binding_fields_match_report",
            evidence.payload_binding_fields_match_report,
        ),
        (
            "decoded_public_anchors_match_deployed_anchors",
            evidence.decoded_public_anchors_match_deployed_anchors,
        ),
        (
            "deployed_anchor_account_id_bound",
            evidence.deployed_anchor_account_id_bound,
        ),
        (
            "deployed_anchor_slot_id_bound",
            evidence.deployed_anchor_slot_id_bound,
        ),
        (
            "deployed_anchor_state_root_bound",
            evidence.deployed_anchor_state_root_bound,
        ),
        (
            "deployed_anchor_lifecycle_anchor_bound",
            evidence.deployed_anchor_lifecycle_anchor_bound,
        ),
        (
            "deployed_anchor_verifier_version_bound",
            evidence.deployed_anchor_verifier_version_bound,
        ),
        (
            "deployed_anchor_masked_projection_bound",
            evidence.deployed_anchor_masked_projection_bound,
        ),
        (
            "deployed_anchor_role_root_export_bridge_bound",
            evidence.deployed_anchor_role_root_export_bridge_bound,
        ),
        (
            "deployed_anchor_packed_witness_commitment_bound",
            evidence.deployed_anchor_packed_witness_commitment_bound,
        ),
        (
            "deployed_anchor_fields_match_report",
            evidence.deployed_anchor_fields_match_report,
        ),
        (
            "account_stark_bundle_nonempty",
            evidence.account_stark_bundle_nonempty,
        ),
        (
            "proof_family_obligations_still_open",
            evidence.proof_family_obligations_still_open,
        ),
    ];
    if let Some((name, _)) = required_true.iter().find(|(_, value)| !*value) {
        return Err(format!(
            "Path 2 account-creation accepted proof-boundary evidence lost required flag {name}"
        ));
    }
    if evidence.public_payload_exports_private_material || evidence.deployment_ready {
        return Err(
            "Path 2 account-creation accepted proof-boundary evidence unexpectedly changes closure status"
                .to_string(),
        );
    }
    Ok(())
}

pub fn validate_path2_direct_accepted_spend_tuple_evidence_v1(
    evidence: &Path2DirectAcceptedSpendTupleEvidenceV1,
) -> Result<(), String> {
    if path2_direct_accepted_spend_tuple_evidence_v1_digest(evidence) != evidence.digest {
        return Err("Path 2 direct accepted spend tuple evidence digest mismatch".to_string());
    }

    let qrom_report = path2_direct_qrom_action_boundary_report_v1();
    validate_path2_direct_qrom_action_boundary_report_v1(&qrom_report)?;
    let lifecycle_report = path2_direct_lifecycle_boundary_report_v1();
    validate_path2_direct_lifecycle_boundary_report_v1(&lifecycle_report)?;
    let proof_report = path2_account_creation_proof_boundary_report_v1();
    validate_path2_account_creation_proof_boundary_report_v1(&proof_report)?;

    if evidence.schema != PATH2_DIRECT_ACCEPTED_SPEND_TUPLE_EVIDENCE_SCHEMA
        || evidence.theorem_target != PATH2_DIRECT_THEOREM_TARGET
        || evidence.theorem_conclusion != PATH2_DIRECT_THEOREM_CONCLUSION
        || evidence.accepted_tuple_fields != PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.as_ref()
        || evidence.acceptance_hypotheses != PATH2_DIRECT_THEOREM_ACCEPTANCE_HYPOTHESES.as_ref()
        || evidence.direct_qrom_action_boundary_report_digest != qrom_report.digest
        || evidence.direct_lifecycle_boundary_report_digest != lifecycle_report.digest
        || evidence.account_creation_proof_boundary_report_digest != proof_report.digest
    {
        return Err("Path 2 direct accepted spend tuple evidence authority mismatch".to_string());
    }

    if evidence.accepted_slot_id as u64 != evidence.slot_id
        || evidence.public_result_class_name != PATH2_PUBLIC_RESULT_ACCEPT_SPEND_SLOT
        || evidence.direct_admission_namespace_record_digest
            != path2_direct_admission_namespace_record_digest(
                &evidence.account_id,
                &evidence.account_state_root_before,
                &evidence.slot_authorization_digest,
            )
        || evidence.consume_once_state_before_digest == evidence.consume_once_state_after_digest
    {
        return Err("Path 2 direct accepted spend tuple evidence binding mismatch".to_string());
    }

    let required_true = [
        (
            "state_namespace_record_present",
            evidence.state_namespace_record_present,
        ),
        (
            "consumed_authorization_absent_before",
            evidence.consumed_authorization_absent_before,
        ),
        (
            "consumed_authorization_present_after",
            evidence.consumed_authorization_present_after,
        ),
        (
            "consume_once_inserted_exactly_one_authorization",
            evidence.consume_once_inserted_exactly_one_authorization,
        ),
        (
            "public_result_accepts_same_slot",
            evidence.public_result_accepts_same_slot,
        ),
        (
            "tuple_fields_match_theorem_boundary",
            evidence.tuple_fields_match_theorem_boundary,
        ),
        (
            "every_accepted_tuple_field_has_evidence",
            evidence.every_accepted_tuple_field_has_evidence,
        ),
        (
            "every_accepted_tuple_field_has_open_or_imported_direct_obligation",
            evidence.every_accepted_tuple_field_has_open_or_imported_direct_obligation,
        ),
    ];
    if let Some((name, _)) = required_true.iter().find(|(_, value)| !*value) {
        return Err(format!(
            "Path 2 direct accepted spend tuple evidence lost required flag {name}"
        ));
    }

    let expected_field_rows = path2_direct_accepted_tuple_field_evidence_rows_v1(evidence);
    if evidence.accepted_tuple_field_evidence_rows != expected_field_rows
        || evidence.accepted_tuple_field_evidence_count
            != PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.len()
        || evidence.accepted_tuple_field_evidence_count
            != evidence.accepted_tuple_field_evidence_rows.len()
        || evidence.accepted_tuple_field_evidence_present_count
            != PATH2_DIRECT_THEOREM_ACCEPTED_TUPLE_FIELDS.len()
        || evidence.accepted_tuple_field_open_obligation_count != 6
        || evidence.accepted_tuple_field_imported_closure_count != 2
        || !evidence.every_accepted_tuple_field_has_evidence
        || evidence.every_accepted_tuple_field_has_open_direct_obligation
        || !evidence.every_accepted_tuple_field_has_open_or_imported_direct_obligation
        || !evidence
            .accepted_tuple_field_evidence_rows
            .iter()
            .all(|row| row.all_referenced_direct_obligations_open_or_imported)
    {
        return Err(
            "Path 2 direct accepted spend tuple evidence lost field evidence rows".to_string(),
        );
    }
    Ok(())
}

#[cfg(feature = "account-creation-stark-verifier")]
pub fn validate_path2_direct_accepted_spend_tuple_kat_evidence_v1(
    kat: &Path2DirectAcceptedSpendTupleKatEvidenceV1,
) -> Result<(), String> {
    validate_path2_direct_accepted_spend_tuple_evidence_v1(&kat.evidence)?;
    if kat.account_creation_fixture_id != "Path2AccountStarkPayloadKatFixture.v1"
        || kat.proof_mask_seed != PATH2_ACCOUNT_STARK_PAYLOAD_KAT_MASK_SEED_V1
        || !kat.replay_rejected_by_consume_once
    {
        return Err(
            "Path 2 direct accepted spend tuple KAT evidence lost deterministic replay binding"
                .to_string(),
        );
    }
    if kat != &path2_direct_accepted_spend_tuple_kat_evidence_v1()? {
        return Err(
            "Path 2 direct accepted spend tuple KAT evidence fixture binding mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn validate_path2_direct_accepted_composition_evidence_v1(
    evidence: &Path2DirectAcceptedCompositionEvidenceV1,
) -> Result<(), String> {
    if path2_direct_accepted_composition_evidence_v1_digest(evidence) != evidence.digest {
        return Err("Path 2 direct accepted composition evidence digest mismatch".to_string());
    }

    let direct_report = path2_direct_theorem_boundary_report_v1();
    validate_path2_direct_theorem_boundary_report_v1(&direct_report)?;
    let qrom_report = path2_direct_qrom_action_boundary_report_v1();
    validate_path2_direct_qrom_action_boundary_report_v1(&qrom_report)?;
    let lifecycle_report = path2_direct_lifecycle_boundary_report_v1();
    validate_path2_direct_lifecycle_boundary_report_v1(&lifecycle_report)?;
    let proof_report = path2_account_creation_proof_boundary_report_v1();
    validate_path2_account_creation_proof_boundary_report_v1(&proof_report)?;

    if evidence.schema != PATH2_DIRECT_ACCEPTED_COMPOSITION_EVIDENCE_SCHEMA
        || evidence.theorem_target != PATH2_DIRECT_THEOREM_TARGET
        || evidence.theorem_conclusion != PATH2_DIRECT_THEOREM_CONCLUSION
        || evidence.direct_theorem_boundary_report_digest != direct_report.digest
        || evidence.direct_qrom_action_boundary_report_digest != qrom_report.digest
        || evidence.direct_lifecycle_boundary_report_digest != lifecycle_report.digest
        || evidence.account_creation_proof_boundary_report_digest != proof_report.digest
        || evidence.direct_accepted_spend_tuple_evidence_digest == [0_u8; DIGEST_BYTES]
        || evidence.account_creation_accepted_proof_boundary_evidence_digest == [0_u8; DIGEST_BYTES]
    {
        return Err("Path 2 direct accepted composition evidence authority mismatch".to_string());
    }

    let direct_obligations_still_open = direct_report.obligation_rows.iter().any(|row| row.open);
    let proof_family_obligations_still_open = proof_report
        .proof_obligation_rows
        .iter()
        .any(|row| row.open);
    if evidence.direct_theorem_obligations_still_open != direct_obligations_still_open
        || evidence.proof_family_obligations_still_open != proof_family_obligations_still_open
    {
        return Err(
            "Path 2 direct accepted composition evidence open-obligation binding mismatch"
                .to_string(),
        );
    }
    if evidence.direct_admission_namespace_record_digest
        != path2_direct_admission_namespace_record_digest(
            &evidence.account_id,
            &evidence.account_state_root_before,
            &evidence.slot_authorization_digest,
        )
        || evidence.consume_once_state_before_digest == evidence.consume_once_state_after_digest
    {
        return Err("Path 2 direct accepted composition evidence binding mismatch".to_string());
    }
    let expected_hypothesis_rows =
        path2_direct_accepted_composition_hypothesis_evidence_rows_v1(evidence, &direct_report);
    if evidence.accepted_hypothesis_evidence_rows != expected_hypothesis_rows
        || evidence.accepted_hypothesis_evidence_count
            != PATH2_DIRECT_THEOREM_ACCEPTANCE_HYPOTHESES.len()
        || evidence.accepted_hypothesis_evidence_count
            != evidence.accepted_hypothesis_evidence_rows.len()
        || evidence.positive_acceptance_hypothesis_evidence_count != 8
        || !evidence.every_positive_acceptance_hypothesis_has_accepted_path_evidence
        || !evidence.public_rejection_hypothesis_deferred_to_rejection_kats
    {
        return Err(
            "Path 2 direct accepted composition evidence lost hypothesis evidence rows".to_string(),
        );
    }

    let required_true = [
        (
            "creation_evidence_matches_direct_tuple",
            evidence.creation_evidence_matches_direct_tuple,
        ),
        (
            "proof_boundary_digest_matches_direct_theorem",
            evidence.proof_boundary_digest_matches_direct_theorem,
        ),
        (
            "qrom_action_digest_matches_direct_theorem",
            evidence.qrom_action_digest_matches_direct_theorem,
        ),
        (
            "lifecycle_digest_matches_direct_theorem",
            evidence.lifecycle_digest_matches_direct_theorem,
        ),
        (
            "direct_admission_namespace_matches_authorization",
            evidence.direct_admission_namespace_matches_authorization,
        ),
        (
            "consume_once_transition_matches_tuple",
            evidence.consume_once_transition_matches_tuple,
        ),
        (
            "verifier_boundary_accepts_creation",
            evidence.verifier_boundary_accepts_creation,
        ),
        (
            "direct_spend_tuple_accepts",
            evidence.direct_spend_tuple_accepts,
        ),
        (
            "public_result_accepts_same_slot",
            evidence.public_result_accepts_same_slot,
        ),
        (
            "every_positive_acceptance_hypothesis_has_accepted_path_evidence",
            evidence.every_positive_acceptance_hypothesis_has_accepted_path_evidence,
        ),
        (
            "public_rejection_hypothesis_deferred_to_rejection_kats",
            evidence.public_rejection_hypothesis_deferred_to_rejection_kats,
        ),
        (
            "direct_theorem_obligations_still_open",
            evidence.direct_theorem_obligations_still_open,
        ),
        (
            "proof_family_obligations_still_open",
            evidence.proof_family_obligations_still_open,
        ),
    ];
    if let Some((name, _)) = required_true.iter().find(|(_, value)| !*value) {
        return Err(format!(
            "Path 2 direct accepted composition evidence lost required flag {name}"
        ));
    }
    if evidence.composition_theorem_instantiated
        || evidence.account_creation_proof_boundary_verified
        || evidence.deployment_ready
    {
        return Err(
            "Path 2 direct accepted composition evidence unexpectedly changes closure status"
                .to_string(),
        );
    }
    #[cfg(feature = "account-creation-stark-verifier")]
    {
        if evidence != &path2_direct_accepted_composition_evidence_v1()? {
            return Err(
                "Path 2 direct accepted composition evidence fixture binding mismatch".to_string(),
            );
        }
    }
    Ok(())
}

pub fn sign_path2_reviewed_fq12_authorization_checked_core(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    account_id: &[u8; DIGEST_BYTES],
    account_state_root: &[u8; DIGEST_BYTES],
    slot_authorization_digest: &[u8; DIGEST_BYTES],
    slot_id: u32,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    responses: &ProductionCompactResponses,
) -> Result<ProductionSignature, ProductionAccountBindingError> {
    let slot = account.get_slot(slot_id).ok_or_else(|| {
        ProductionAccountBindingError::new(Some(slot_id), "slot id is out of range")
    })?;
    if !slot.is_unused() {
        return Err(ProductionAccountBindingError::new(
            Some(slot_id),
            "slot is already consumed",
        ));
    }
    validate_reviewed_fq12_state_assisted_account_commitment(slot.commitment())
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    let witness_commitment = slot.commitment().witness_commitment();
    let proof_commitment = slot.commitment().randomizer_commitment();
    unpack_reviewed_fq12_account_carried_syndrome_digest(&proof_commitment)
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    let challenge = path2_checked_core_authorization_challenge_bytes(
        public_key.as_bytes(),
        message,
        account_id,
        account_state_root,
        slot_id,
        &witness_commitment,
        slot_authorization_digest,
        &proof_commitment,
    );
    let decoded_challenge = decode_challenge(&challenge)
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    let expected_response_syndrome = reviewed_fq12_state_assisted_expected_response_syndrome(
        &challenge,
        &witness_commitment,
        &proof_commitment,
    )
    .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    let public_view = decode_public_view(public_key.as_bytes())
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    let mut openings = ProductionLocalOpenings {
        active_free: [[0_u16; LOCAL_FREE]; REPS],
    };
    for rep in 0..REPS {
        let pad =
            reviewed_fq12_pad_residues_from_seed(pad_seed, decoded_challenge.active_block[rep]);
        let mask_view = reconstructed_mask_view(&public_view, &decoded_challenge, responses, rep)
            .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
        for coord in 0..LOCAL_FREE {
            openings.active_free[rep][coord] = add_mod(pad[coord], mask_view[coord]);
        }
    }
    let proof = ProductionReviewedFq12AccountCarriedProof {
        proof_commitment,
        masked_quotient_response: encode_reviewed_fq12_account_carried_masked_response(
            &reviewed_fq12_masked_response_for_response_syndrome(&expected_response_syndrome)
                .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?,
        )
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?,
    };
    let signature = encode_reviewed_fq12_account_carried_signature(
        slot_id, &challenge, responses, &openings, &proof,
    )
    .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    verify_path2_checked_core_authorization(
        public_key,
        message,
        account,
        account_id,
        account_state_root,
        slot_authorization_digest,
        &signature,
    )?;
    Ok(signature)
}

fn challenge_hash_frame_prefix(
    public_key: &[u8],
    message: &[u8],
    slot_id: u32,
    digest: &[u8; DIGEST_BYTES],
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(&mut frame, b"domain", CHALLENGE_HASH_DOMAIN.as_bytes());
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_pivot", LOCAL_PIVOT as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(&mut frame, b"repetitions", REPS as u64);
    append_u64(&mut frame, b"slot_id", slot_id as u64);
    append_frame(&mut frame, b"public_key", public_key);
    append_frame(&mut frame, b"message", message);
    append_frame(&mut frame, b"slot_digest", digest);
    frame
}

fn public_pad_opening_statement_frame(
    consistency: &ProductionPublicPadOpeningConsistency,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        REVIEWED_FQ12_PAD_OPENING_VIEW_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(&mut frame, b"repetitions", REPS as u64);
    let mut observed_bitmap = 0_u16;
    for (block, &observed) in consistency.observed_blocks.iter().enumerate() {
        if observed {
            observed_bitmap |= 1_u16 << block;
        }
    }
    append_frame(
        &mut frame,
        b"observed_bitmap",
        &observed_bitmap.to_le_bytes(),
    );
    for block in 0..GROUPS {
        if consistency.observed_blocks[block] {
            append_u64(&mut frame, b"block", block as u64);
            for coord in 0..LOCAL_FREE {
                append_frame(
                    &mut frame,
                    b"pad",
                    &consistency.block_pads[block][coord].to_le_bytes(),
                );
            }
        }
    }
    frame
}

pub fn reviewed_fq12_state_assisted_opening_commitment_frame(
    opening: &ProductionReviewedFq12StateAssistedOpening,
) -> Vec<u8> {
    let mut frame = Vec::with_capacity(REVIEWED_FQ12_STATE_ASSISTED_OPENING_FRAME_BYTES);
    frame.extend_from_slice(REVIEWED_FQ12_STATE_ASSISTED_OPENING_DOMAIN.as_bytes());
    frame.extend_from_slice(REVIEWED_FQ12_STATE_ASSISTED_OPENING_PROFILE.as_bytes());
    frame.extend_from_slice(&opening.slot_id.to_le_bytes());
    frame.extend_from_slice(&opening.account_witness_commitment);
    frame.extend_from_slice(&opening.account_randomizer_commitment);
    frame.extend_from_slice(&opening.restore_anchor_digest);
    frame.extend_from_slice(&opening.witness_opening_digest);
    frame.extend_from_slice(&opening.pad_seed_digest);
    frame.extend_from_slice(&opening.carrier_handle_secret_digest);
    debug_assert_eq!(
        frame.len(),
        REVIEWED_FQ12_STATE_ASSISTED_OPENING_FRAME_BYTES
    );
    frame
}

pub fn reviewed_fq12_state_assisted_opening_commitment_digest(
    opening: &ProductionReviewedFq12StateAssistedOpening,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_state_assisted_opening_commitment_frame(
        opening,
    ))
    .into()
}

pub fn reviewed_fq12_state_assisted_carrier_handle_frame(
    carrier: &ProductionReviewedFq12StateAssistedCarrierHandle,
) -> Vec<u8> {
    let mut frame = Vec::with_capacity(REVIEWED_FQ12_STATE_ASSISTED_CARRIER_FRAME_BYTES);
    frame.extend_from_slice(REVIEWED_FQ12_STATE_ASSISTED_CARRIER_DOMAIN.as_bytes());
    frame.extend_from_slice(&carrier.hidden_source_opening_commitment);
    frame.extend_from_slice(&carrier.proof_transcript_digest);
    frame.extend_from_slice(&carrier.signature_digest);
    frame.extend_from_slice(&carrier.public_key_digest);
    frame.extend_from_slice(&carrier.message_digest);
    frame.extend_from_slice(&carrier.slot_id.to_le_bytes());
    frame.extend_from_slice(&carrier.carrier_handle_secret_digest);
    debug_assert_eq!(
        frame.len(),
        REVIEWED_FQ12_STATE_ASSISTED_CARRIER_FRAME_BYTES
    );
    frame
}

pub fn reviewed_fq12_state_assisted_carrier_handle_digest(
    carrier: &ProductionReviewedFq12StateAssistedCarrierHandle,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_state_assisted_carrier_handle_frame(carrier)).into()
}

pub fn verify_reviewed_fq12_state_assisted_carrier_handle(
    carrier: &ProductionReviewedFq12StateAssistedCarrierHandle,
    proof: &ProductionReviewedFq12HiddenSourceProof,
) -> Result<[u8; DIGEST_BYTES], String> {
    let digest = reviewed_fq12_state_assisted_carrier_handle_digest(carrier);
    if proof.as_bytes() != &digest {
        return Err(PRODUCTION_HIDDEN_SOURCE_PROOF_FAILURE_REASON.to_string());
    }
    Ok(digest)
}

pub fn reviewed_fq12_state_assisted_ro_pok_transcript_frame(
    input: &ProductionReviewedFq12StateAssistedRoPokPublicInput,
) -> Result<Vec<u8>, String> {
    let statement_frame_len: u32 = input
        .statement_frame
        .len()
        .try_into()
        .map_err(|_| "state-assisted RO-PoK statement frame exceeds u32 length".to_string())?;
    let mut frame = Vec::with_capacity(
        REVIEWED_FQ12_STATE_ASSISTED_RO_POK_DOMAIN.len()
            + REVIEWED_FQ12_STATE_ASSISTED_RO_POK_PROFILE.len()
            + size_of::<u32>()
            + input.statement_frame.len()
            + REVIEWED_FQ12_STATE_ASSISTED_RO_POK_FIXED_BYTES,
    );
    frame.extend_from_slice(REVIEWED_FQ12_STATE_ASSISTED_RO_POK_DOMAIN.as_bytes());
    frame.extend_from_slice(REVIEWED_FQ12_STATE_ASSISTED_RO_POK_PROFILE.as_bytes());
    frame.extend_from_slice(&statement_frame_len.to_le_bytes());
    frame.extend_from_slice(&input.statement_frame);
    frame.extend_from_slice(&input.opening_commitment);
    frame.extend_from_slice(&input.proof_transcript_digest);
    frame.extend_from_slice(&input.carrier);
    Ok(frame)
}

pub fn reviewed_fq12_state_assisted_ro_pok_transcript_digest(
    input: &ProductionReviewedFq12StateAssistedRoPokPublicInput,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(reviewed_fq12_state_assisted_ro_pok_transcript_frame(input)?).into())
}

pub fn verify_reviewed_fq12_state_assisted_ro_pok(
    _input: &ProductionReviewedFq12StateAssistedRoPokPublicInput,
) -> Result<(), String> {
    Err(PRODUCTION_HIDDEN_SOURCE_PROOF_FAILURE_REASON.to_string())
}

fn reviewed_fq12_hidden_source_statement_from_public(
    public_key: &ProductionPublicKey,
    message: &[u8],
    slot_id: u32,
    commitment: &ProductionAccountCommitment,
    signature: &ProductionSignature,
    pad_opening_statement: ProductionPublicPadOpeningStatement,
) -> ProductionReviewedFq12HiddenSourceStatement {
    let mut statement = ProductionReviewedFq12HiddenSourceStatement {
        digest: [0_u8; DIGEST_BYTES],
        slot_id,
        witness_commitment: commitment.witness_commitment(),
        randomizer_commitment: commitment.randomizer_commitment(),
        public_key_digest: Sha256::digest(public_key.as_bytes()).into(),
        message_digest: Sha256::digest(message).into(),
        signature_digest: Sha256::digest(signature.as_bytes()).into(),
        pad_opening_statement,
    };
    statement.digest = reviewed_fq12_hidden_source_statement_digest(&statement);
    statement
}

fn reviewed_fq12_hidden_source_statement_frame(
    statement: &ProductionReviewedFq12HiddenSourceStatement,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        REVIEWED_FQ12_HIDDEN_SOURCE_STATEMENT_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_pivot", LOCAL_PIVOT as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(&mut frame, b"repetitions", REPS as u64);
    append_u64(&mut frame, b"slot_id", statement.slot_id as u64);
    append_frame(
        &mut frame,
        b"witness_commitment",
        &statement.witness_commitment,
    );
    append_frame(
        &mut frame,
        b"randomizer_commitment",
        &statement.randomizer_commitment,
    );
    append_frame(
        &mut frame,
        b"public_key_digest",
        &statement.public_key_digest,
    );
    append_frame(&mut frame, b"message_digest", &statement.message_digest);
    append_frame(&mut frame, b"signature_digest", &statement.signature_digest);
    append_frame(
        &mut frame,
        b"pad_opening_statement_digest",
        &statement.pad_opening_statement.digest,
    );
    append_u64(
        &mut frame,
        b"pad_observed_block_count",
        statement.pad_opening_statement.observed_block_count as u64,
    );
    let mut observed_bitmap = 0_u16;
    for (block, &observed) in statement
        .pad_opening_statement
        .observed_blocks
        .iter()
        .enumerate()
    {
        if observed {
            observed_bitmap |= 1_u16 << block;
        }
    }
    append_frame(
        &mut frame,
        b"pad_observed_bitmap",
        &observed_bitmap.to_le_bytes(),
    );
    frame
}

fn reviewed_fq12_hidden_source_proof_transcript_frame(
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    proof: &ProductionReviewedFq12HiddenSourceProof,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_pivot", LOCAL_PIVOT as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(&mut frame, b"repetitions", REPS as u64);
    append_u64(
        &mut frame,
        b"proof_bytes",
        REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_BYTES as u64,
    );
    let statement_digest = reviewed_fq12_hidden_source_statement_digest(statement);
    append_frame(
        &mut frame,
        b"hidden_source_statement_digest",
        &statement_digest,
    );
    append_frame(&mut frame, b"hidden_source_proof", proof.as_bytes());
    frame
}

fn reviewed_fq12_deployment_blocker_report_frame(
    report: &ProductionReviewedFq12DeploymentBlockerReport,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        REVIEWED_FQ12_DEPLOYMENT_BLOCKER_REPORT_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_pivot", LOCAL_PIVOT as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(&mut frame, b"repetitions", REPS as u64);
    append_frame(&mut frame, b"blocker", report.blocker.as_bytes());
    let statement_digest = reviewed_fq12_hidden_source_statement_digest(&report.context.statement);
    let transcript = reviewed_fq12_hidden_source_proof_transcript(
        &report.context.statement,
        &report.context.proof,
    );
    append_frame(
        &mut frame,
        b"hidden_source_statement_digest",
        &statement_digest,
    );
    append_frame(
        &mut frame,
        b"hidden_source_transcript_digest",
        &transcript.digest,
    );
    append_frame(
        &mut frame,
        b"hidden_source_transcript_statement_digest",
        &transcript.statement_digest,
    );
    append_u64(&mut frame, b"proof_bytes", transcript.proof_bytes as u64);
    append_frame(
        &mut frame,
        b"hidden_source_proof",
        report.context.proof.as_bytes(),
    );
    frame
}

