pub fn unpack_reviewed_account_carried_masked_response(
    bytes: &[u8; REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES],
) -> Result<[u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES], String> {
    if any_bits_set_le(
        bytes,
        REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BITS,
        REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_SLACK_BITS,
    ) {
        return Err("reviewed masked response is not canonical: high bits are set".to_string());
    }
    let mut out = [0_u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES];
    for (idx, value) in out.iter_mut().enumerate() {
        let decoded = read_bits_le(bytes, idx * FIELD_BITS, FIELD_BITS);
        if decoded >= Q as u32 {
            return Err(format!(
                "reviewed masked response residue {idx} is non-canonical: {decoded}"
            ));
        }
        *value = decoded as u16;
    }
    Ok(out)
}

