    fn lean_byte_array_digest_after_marker(
        source: &str,
        marker: &str,
        context: &str,
    ) -> [u8; DIGEST_BYTES] {
        let byte_array_start = source
            .find(marker)
            .unwrap_or_else(|| panic!("missing ByteArray literal for {context}"))
            + marker.len();
        let byte_array_end = source[byte_array_start..]
            .find(']')
            .unwrap_or_else(|| panic!("unterminated ByteArray literal for {context}"))
            + byte_array_start;
        let byte_values: Vec<u8> = source[byte_array_start..byte_array_end]
            .split(',')
            .filter_map(|part| {
                let part = part.trim();
                if part.is_empty() {
                    None
                } else {
                    Some(
                        part.parse::<u8>()
                            .unwrap_or_else(|err| panic!("invalid byte in {context}: {err}")),
                    )
                }
            })
            .collect();
        byte_values
            .try_into()
            .unwrap_or_else(|bytes: Vec<u8>| panic!("{context} has {} bytes", bytes.len()))
    }

    #[test]
    fn account_commitment_layout_validates() {
        let witness = pack_q_syndrome_digest(&[1_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let randomizer = pack_q_syndrome_digest(&[7_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let commitment = ProductionAccountCommitment::new(witness, randomizer);
        assert_eq!(commitment.as_bytes().len(), REVIEWED_ACCOUNT_LINK_BYTES);
        assert_eq!(commitment.witness_commitment(), witness);
        assert_eq!(commitment.randomizer_commitment(), randomizer);
        assert_eq!(
            commitment.response_link_code(),
            reviewed_response_link_code()
        );
        assert!(commitment.validate().is_ok());
    }

    #[test]
    fn public_key_validation_rejects_bad_length_and_noncanonical_coordinate() {
        let key = vec![0_u8; PK_BYTES];
        assert!(ProductionPublicKey::new(key).is_ok());

        assert_eq!(
            ProductionPublicKey::new(vec![0_u8; PK_BYTES - 1]).unwrap_err(),
            format!("public key has {} bytes, expected {PK_BYTES}", PK_BYTES - 1)
        );

        let mut bad_key = vec![0_u8; PK_BYTES];
        let q = Q;
        for i in 0..FIELD_BITS {
            let bit = i;
            bad_key[PK_SEED_BYTES + bit / 8] |= (((q as u32 >> i) & 1) as u8) << (bit % 8);
        }
        assert_eq!(
            ProductionPublicKey::new(bad_key).unwrap_err(),
            format!("non-canonical q-coordinate at index 0: {Q}")
        );
    }

    #[test]
    fn production_keypair_wrapper_keeps_validated_public_account_boundary() {
        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let witness = pack_q_syndrome_digest(&[1_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let randomizer = pack_q_syndrome_digest(&[2_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let slot =
            ProductionAccountSlot::new(0, ProductionAccountCommitment::new(witness, randomizer));
        let account = ProductionAccountState::new(vec![slot]).unwrap();
        let secret_key = ProductionSecretKey::new("reference-secret");
        let keypair = ProductionKeypair::new(public_key, secret_key, account);

        assert_eq!(keypair.public_key.len(), PK_BYTES);
        assert_eq!(keypair.secret_key.reference_keypair(), &"reference-secret");
        assert_eq!(keypair.account.len(), 1);
    }

    #[test]
    fn account_commitment_rejects_bad_code_and_noncanonical_digest() {
        let witness = pack_q_syndrome_digest(&[1_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let randomizer = pack_q_syndrome_digest(&[7_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let commitment = ProductionAccountCommitment::new(witness, randomizer);

        let mut bad_code = *commitment.as_bytes();
        bad_code[2 * DIGEST_BYTES] ^= 1;
        assert_eq!(
            ProductionAccountCommitment::from_bytes(bad_code).unwrap_err(),
            "account response-link code mismatch"
        );

        let mut bad_digest = *commitment.as_bytes();
        bad_digest[SIS_FULL_RESPONSE_SYNDROME_PACKED_BITS / 8] |=
            1 << (SIS_FULL_RESPONSE_SYNDROME_PACKED_BITS % 8);
        assert_eq!(
            ProductionAccountCommitment::from_bytes(bad_digest).unwrap_err(),
            "account witness commitment is not canonical"
        );
    }

    #[test]
    fn account_state_requires_sorted_valid_slots_and_consumes() {
        let witness = pack_q_syndrome_digest(&[1_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let randomizer = pack_q_syndrome_digest(&[7_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let commitment = ProductionAccountCommitment::new(witness, randomizer);
        let mut account =
            ProductionAccountState::new(vec![ProductionAccountSlot::new(0, commitment)]).unwrap();
        assert_eq!(account.len(), 1);
        assert!(account.get_slot(0).unwrap().is_unused());
        let records = account.checked_slot_records().unwrap();
        assert_eq!(records.len(), 1);
        assert_eq!(records[0].slot_id, 0);
        assert_eq!(records[0].witness_commitment, witness);
        assert_eq!(records[0].randomizer_commitment, randomizer);
        assert!(records[0].unused);
        let projected = account
            .project_checked_slot_records(|records| {
                Ok(records
                    .iter()
                    .map(|record| (record.slot_id, record.witness_commitment, record.unused))
                    .collect::<Vec<_>>())
            })
            .unwrap();
        assert_eq!(projected, vec![(0, witness, true)]);

        account.mark_consumed(0).unwrap();
        assert!(!account.get_slot(0).unwrap().is_unused());

        assert_eq!(
            ProductionAccountState::new(vec![ProductionAccountSlot::new(1, commitment)])
                .unwrap_err(),
            "account slots must be sorted by slot id"
        );
    }

    #[test]
    fn account_state_from_slot_seeds_assigns_sorted_ids_and_validates_commitments() {
        let witness0 = pack_q_syndrome_digest(&[1_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let witness1 = pack_q_syndrome_digest(&[2_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let randomizer = pack_q_syndrome_digest(&[7_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let account = account_state_from_slot_seeds(
            [
                ProductionAccountSlotSeed {
                    witness_commitment: witness0,
                    unused: true,
                },
                ProductionAccountSlotSeed {
                    witness_commitment: witness1,
                    unused: false,
                },
            ],
            randomizer,
        )
        .unwrap();

        let records = account.checked_slot_records().unwrap();
        assert_eq!(records[0].slot_id, 0);
        assert_eq!(records[0].witness_commitment, witness0);
        assert!(records[0].unused);
        assert_eq!(records[1].slot_id, 1);
        assert_eq!(records[1].witness_commitment, witness1);
        assert!(!records[1].unused);
    }

    #[test]
    fn production_signature_codec_splits_and_rejects_noncanonical_payloads() {
        let mut signature = vec![0_u8; LINEAR_SIGMA_TARGET_TRANSACTION_SIGNATURE_BYTES];
        let response_start = SLOT_ID_BYTES + CHALLENGE_BYTES;
        let opening_start = response_start + ACTIVE_RESPONSE_BYTES;
        let proof_start = opening_start + LOCAL_OPENING_BYTES;
        signature[response_start..opening_start].fill(RESPONSE_BOUND as u8);

        let decoded = decode_production_signature(&signature).unwrap();
        assert_eq!(decoded.slot_id, 0);
        assert_eq!(decoded.challenge.active_block, [0_usize; REPS]);
        assert_eq!(decoded.challenge.sign, [1_i8; REPS]);
        assert_eq!(decoded.responses.active_free, [[0_i16; LOCAL_FREE]; REPS]);
        assert_eq!(decoded.openings.active_free, [[0_u16; LOCAL_FREE]; REPS]);
        assert_eq!(
            decoded.proof.proof_commitment,
            [0_u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES]
        );
        assert_eq!(
            proof_start + LINEAR_SIGMA_TARGET_PROOF_BYTES,
            signature.len()
        );

        let mut bad_challenge = signature.clone();
        bad_challenge[SLOT_ID_BYTES + ALGEBRAIC_CHALLENGE_BYTES - 1] = 0x80;
        assert_eq!(
            decode_production_signature(&bad_challenge).unwrap_err(),
            "challenge is not canonical: high bits are set"
        );

        let mut bad_response = signature.clone();
        bad_response[response_start] = (2 * RESPONSE_BOUND) as u8 + 1;
        assert!(decode_production_signature(&bad_response)
            .unwrap_err()
            .contains("active response coordinate 0 in round 0 is non-canonical"));

        let mut bad_opening = signature;
        bad_opening[opening_start..opening_start + 2].copy_from_slice(&Q.to_le_bytes());
        assert_eq!(
            decode_production_signature(&bad_opening).unwrap_err(),
            format!("opening coordinate 0 in round 0 is non-canonical: {Q}")
        );
    }

    #[test]
    fn production_signature_encoder_roundtrips_and_rejects_bad_fields() {
        let mut challenge_bytes = [0_u8; CHALLENGE_BYTES];
        challenge_bytes[0] = 2;
        let responses = ProductionCompactResponses {
            active_free: [[0_i16; LOCAL_FREE]; REPS],
        };
        let openings = ProductionLocalOpenings {
            active_free: [[1_u16; LOCAL_FREE]; REPS],
        };
        let proof = ProductionLinearSigmaTargetProof {
            proof_commitment: [3_u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES],
            masked_witness_response: [4_u8; LINEAR_SIGMA_MASKED_WITNESS_BYTES],
        };
        let signature =
            encode_production_signature(7, &challenge_bytes, &responses, &openings, &proof)
                .unwrap();
        let decoded = signature.decode().unwrap();
        assert_eq!(decoded.slot_id, 7);
        assert_eq!(decoded.challenge.active_block[0], 2);
        assert_eq!(decoded.responses, responses);
        assert_eq!(decoded.openings, openings);
        assert_eq!(decoded.proof, proof);

        let mut bad_responses = responses;
        bad_responses.active_free[0][0] = RESPONSE_BOUND + 1;
        assert_eq!(
            encode_responses(&bad_responses).unwrap_err(),
            "active response coordinate 0 in round 0 is out of bound: 49"
        );

        let mut bad_openings = openings;
        bad_openings.active_free[0][0] = Q;
        assert_eq!(
            encode_openings(&bad_openings).unwrap_err(),
            format!("opening coordinate 0 in round 0 is non-canonical: {Q}")
        );
    }

    #[test]
    fn reviewed_account_carried_signature_codec_is_256_bytes() {
        let mut challenge_bytes = [0_u8; CHALLENGE_BYTES];
        challenge_bytes[0] = 2;
        let responses = ProductionCompactResponses {
            active_free: [[0_i16; LOCAL_FREE]; REPS],
        };
        let openings = ProductionLocalOpenings {
            active_free: [[1_u16; LOCAL_FREE]; REPS],
        };
        let masked_quotient_response = encode_reviewed_account_carried_masked_response(
            &[5_u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES],
        )
        .unwrap();
        let proof = ProductionReviewedAccountCarriedProof {
            proof_commitment: [3_u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES],
            masked_quotient_response,
        };
        let signature = encode_reviewed_account_carried_signature(
            7,
            &challenge_bytes,
            &responses,
            &openings,
            &proof,
        )
        .unwrap();
        assert_eq!(signature.len(), REVIEWED_TARGET_TRANSACTION_SIGNATURE_BYTES);
        assert_eq!(signature.len(), 260);
        assert_eq!(REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES, 37);
        assert_eq!(REVIEWED_ACCOUNT_CARRIED_PROOF_BYTES, 69);

        let decoded = signature.decode_reviewed_account_carried().unwrap();
        assert_eq!(decoded.slot_id, 7);
        assert_eq!(decoded.challenge.active_block[0], 2);
        assert_eq!(decoded.responses, responses);
        assert_eq!(decoded.openings, openings);
        assert_eq!(decoded.proof, proof);
        assert_eq!(
            unpack_reviewed_account_carried_masked_response(
                &decoded.proof.masked_quotient_response
            )
            .unwrap(),
            [5_u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES]
        );

        let mut noncanonical = signature.as_bytes().to_vec();
        let last = noncanonical.last_mut().unwrap();
        *last |= 0xc0;
        assert_eq!(
            decode_reviewed_account_carried_signature(&noncanonical).unwrap_err(),
            "reviewed masked response is not canonical: high bits are set"
        );
    }

    #[test]
    fn reviewed_account_carried_quotient_map_packs_strict_10_residue_digest() {
        let residues = core::array::from_fn(|idx| (idx as u16 * 17 + 5) % Q);
        let masked = encode_reviewed_account_carried_masked_response(&residues).unwrap();
        let syndrome = reviewed_account_carried_response_syndrome(&masked).unwrap();
        let digest = reviewed_account_carried_response_syndrome_digest(&masked).unwrap();
        assert_eq!(
            unpack_reviewed_account_carried_syndrome_digest(&digest).unwrap(),
            syndrome
        );
        assert_eq!(
            any_bits_set_le(
                &digest,
                REVIEWED_ACCOUNT_CARRIED_SYNDROME_PACKED_BITS,
                REVIEWED_ACCOUNT_CARRIED_SYNDROME_SLACK_BITS
            ),
            false
        );
        assert!(syndrome.iter().all(|&value| value < Q));

        let mut noncanonical_digest = digest;
        noncanonical_digest[REVIEWED_ACCOUNT_CARRIED_SYNDROME_PACKED_BITS / 8] |=
            1 << (REVIEWED_ACCOUNT_CARRIED_SYNDROME_PACKED_BITS % 8);
        assert_eq!(
            unpack_reviewed_account_carried_syndrome_digest(&noncanonical_digest).unwrap_err(),
            "reviewed account-carried syndrome digest is not canonical: high bits are set"
        );
    }

