    /// CROSS-CHECK KAT (deployed-mask-prf-swap regression gate).
    ///
    /// After the swap, the deployed signer mask fn
    /// `reviewed_fq12_packed_witness_state18_projection_masks` IS
    /// `descender_mask_prf::projection_masks` by construction, so this is
    /// trivially true today — but it LOCKS that equality so any future drift
    /// (e.g. someone re-pointing the deployed fn at the SHA legacy path, or the
    /// shared PRF changing) is caught here. It also records a frozen GOLDEN
    /// vector for the shared Poseidon2 mask PRF.
    #[test]
    fn reviewed_fq12_projection_masks_match_shared_prf_crosscheck() {
        // (1) deployed fn == shared crate fn for several (pad_seed, slot) inputs.
        let cases: &[([u8; REVIEWED_FQ12_PAD_SEED_BYTES], u64)] = &[
            ([0xA5; REVIEWED_FQ12_PAD_SEED_BYTES], 7),
            ([0x00; REVIEWED_FQ12_PAD_SEED_BYTES], 0),
            ([0xFF; REVIEWED_FQ12_PAD_SEED_BYTES], u64::MAX),
            (core::array::from_fn(|i| (i as u8).wrapping_mul(31)), 12289),
            (
                core::array::from_fn(|i| (i as u8).wrapping_mul(17).wrapping_add(3)),
                1,
            ),
        ];
        for (pad_seed, slot_id) in cases {
            let deployed =
                reviewed_fq12_packed_witness_state18_projection_masks(pad_seed, *slot_id);
            let shared = descender_mask_prf::projection_masks(pad_seed, *slot_id);
            assert_eq!(
                deployed, shared,
                "deployed mask fn drifted from shared descender_mask_prf::projection_masks \
                 for slot {slot_id}"
            );
            for &m in deployed.iter() {
                assert!(m < Q, "mask {m} is non-canonical (>= q={Q})");
            }
        }

        // (2) FROZEN GOLDEN vector: pad_seed = [0xA5; 32], slot = 7.
        // Recorded from descender_mask_prf::projection_masks (Poseidon2 over
        // KoalaBear, wide-then-reduce to q12289) at the swap. If this line ever
        // has to change, the deployed mask PRF changed — treat as a deliberate,
        // reviewed event (it invalidates every previously-issued masked witness).
        let golden = reviewed_fq12_packed_witness_state18_projection_masks(
            &[0xA5; REVIEWED_FQ12_PAD_SEED_BYTES],
            7,
        );
        assert_eq!(
            golden,
            [6434_u16, 9538, 8382, 4631, 1382, 8618],
            "deployed projection-mask golden vector changed (pad=[0xA5;32], slot=7)"
        );
    }

    fn sample_account_and_signature() -> (ProductionAccountState, ProductionSignature) {
        let witness = pack_q_syndrome_digest(&[1_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let randomizer = pack_q_syndrome_digest(&[7_u16; SIS_FULL_RESPONSE_PUBLIC_ROWS]);
        let commitment = ProductionAccountCommitment::new(witness, randomizer);
        let account =
            ProductionAccountState::new(vec![ProductionAccountSlot::new(0, commitment)]).unwrap();
        let challenge_bytes = [0_u8; CHALLENGE_BYTES];
        let responses = ProductionCompactResponses {
            active_free: [[0_i16; LOCAL_FREE]; REPS],
        };
        let openings = ProductionLocalOpenings {
            active_free: [[1_u16; LOCAL_FREE]; REPS],
        };
        let proof = ProductionLinearSigmaTargetProof {
            proof_commitment: randomizer,
            masked_witness_response: [4_u8; LINEAR_SIGMA_MASKED_WITNESS_BYTES],
        };
        let signature =
            encode_production_signature(0, &challenge_bytes, &responses, &openings, &proof)
                .unwrap();
        (account, signature)
    }

    fn temp_json_path(prefix: &str) -> PathBuf {
        std::env::temp_dir().join(format!(
            "{prefix}-{}-{}.json",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ))
    }

    fn assert_serialized_public_state_excludes_secret_sentinels(serialized: &str) {
        for forbidden in [
            "DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE",
            "reference-secret",
            "reference_keypair",
            "secret_key",
            "ProductionSecretKey",
            "hidden_witness",
            "randomizer_preimage",
            "active_pad",
            "sampler_randomness",
            "masked_witness_response",
        ] {
            assert!(
                !serialized.contains(forbidden),
                "serialized public state leaked forbidden marker {forbidden}"
            );
        }
    }

    fn assert_public_report_excludes_secret_sentinels(report: impl std::fmt::Debug) {
        let rendered = format!("{report:?}");
        assert_serialized_public_state_excludes_secret_sentinels(&rendered);
    }

    fn test_digest(label: &str) -> [u8; DIGEST_BYTES] {
        Sha256::digest(format!("Descender.test_vector.v1:{label}:0").as_bytes()).into()
    }

    fn repeated_digest(byte: u8) -> [u8; DIGEST_BYTES] {
        [byte; DIGEST_BYTES]
    }

    fn path2_transparent_query_opening_manifest_fixture_for_public_view(
        public_view: &Path2TransparentDescentPublicViewV1,
    ) -> Path2TransparentQueryOpeningManifestV1 {
        let mut records = Vec::new();
        let profile = path2_two_view_column_profile_v1();
        for query_index in 0..public_view.query_count {
            let row_index = path2_transparent_query_row_index(public_view, query_index).unwrap();
            for entry in profile.entries {
                let hidden_role = path2_two_view_entry_is_hidden_or_private(&entry);
                let mut record = Path2TransparentQueryOpeningRecordV1 {
                    query_index,
                    role_id: entry.role_id,
                    column_set_id: entry.masked_column_set_id,
                    row_index,
                    visibility_class: if hidden_role {
                        PATH2_TWO_VIEW_VISIBILITY_MASKED_PUBLIC
                    } else {
                        entry.visibility_class
                    },
                    mask_domain_id: if hidden_role {
                        path2_transparent_query_opening_expected_mask_domain_id(query_index, &entry)
                            .unwrap()
                    } else {
                        0
                    },
                    mask_domain_digest: [0_u8; DIGEST_BYTES],
                    component_digest: [0_u8; DIGEST_BYTES],
                };
                record.mask_domain_digest =
                    path2_transparent_query_opening_mask_domain_digest(public_view, &record)
                        .unwrap();
                record.component_digest =
                    path2_transparent_query_opening_component_digest(public_view, &record).unwrap();
                records.push(record);
            }
        }
        path2_transparent_query_opening_manifest_v1(public_view, records).unwrap()
    }

    fn contains_window(haystack: &[u8], needle: &[u8]) -> bool {
        haystack
            .windows(needle.len())
            .any(|window| window == needle)
    }

