    #[test]
    fn path2_native_checked_core_frame_v1_golden_vector_and_roundtrip() {
        let frame = path2_native_checked_core_frame_fixture();
        let bytes = path2_native_checked_core_frame_v1_bytes(&frame).unwrap();
        assert_eq!(bytes.len(), PATH2_NATIVE_CHECKED_CORE_FRAME_BYTES);
        assert_eq!(
            &bytes[..PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.len()],
            PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.as_bytes()
        );

        let mut offset = PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.len();
        assert_eq!(
            u16::from_le_bytes([bytes[offset], bytes[offset + 1]]),
            PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION
        );
        offset += 2;
        assert_eq!(
            u16::from_le_bytes([bytes[offset], bytes[offset + 1]]),
            PATH2_NATIVE_CHECKED_CORE_PARAMETER_SET_Q12289
        );
        offset += 2;
        assert_eq!(
            u16::from_le_bytes([bytes[offset], bytes[offset + 1]]),
            PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12
        );
        offset += 2;

        for (label, expected) in [
            ("account_creation_domain_digest", repeated_digest(0x11)),
            ("spend_verifier_domain_digest", repeated_digest(0x12)),
            ("chain_or_application_domain_digest", repeated_digest(0x13)),
            ("fork_or_epoch_scope_digest", repeated_digest(0x14)),
        ] {
            assert_eq!(&bytes[offset..offset + DIGEST_BYTES], &expected, "{label}");
            offset += DIGEST_BYTES;
        }
        assert_eq!(bytes[offset], PATH2_NATIVE_AGGREGATION_MODE_DIRECT);
        offset += 1;
        for (label, expected) in [
            ("native_boundary_digest", repeated_digest(0x21)),
            ("p_account_digest", repeated_digest(0x22)),
            ("p_spend_digest", repeated_digest(0x23)),
            ("p_lifecycle_digest", repeated_digest(0x24)),
            ("p_transcript_digest", repeated_digest(0x25)),
            ("p_state_digest", repeated_digest(0x26)),
            ("message_digest", repeated_digest(0x31)),
            ("current_state_digest", repeated_digest(0x32)),
            ("proof_commitment", repeated_digest(0x51)),
        ] {
            assert_eq!(&bytes[offset..offset + DIGEST_BYTES], &expected, "{label}");
            offset += DIGEST_BYTES;
        }
        assert_eq!(offset, PATH2_NATIVE_CHECKED_CORE_FRAME_BYTES);
        assert_eq!(
            decode_path2_native_checked_core_frame_v1(&bytes).unwrap(),
            frame
        );
        assert_eq!(
            path2_native_checked_core_frame_v1_challenge(&frame).unwrap(),
            hash_frame_to_challenge_bytes_poseidon2(&bytes)
        );
    }

    #[test]
    fn path2_native_checked_core_frame_v1_mutations_change_challenge() {
        let base = path2_native_checked_core_frame_fixture();
        let base_challenge = path2_native_checked_core_frame_v1_challenge(&base).unwrap();

        let mut mutated_frames = Vec::new();
        let mut frame = base;
        frame.account_creation_domain_digest[0] ^= 1;
        mutated_frames.push(("account_creation_domain_digest", frame));
        let mut frame = base;
        frame.spend_verifier_domain_digest[0] ^= 1;
        mutated_frames.push(("spend_verifier_domain_digest", frame));
        let mut frame = base;
        frame.chain_or_application_domain_digest[0] ^= 1;
        mutated_frames.push(("chain_or_application_domain_digest", frame));
        let mut frame = base;
        frame.fork_or_epoch_scope_digest[0] ^= 1;
        mutated_frames.push(("fork_or_epoch_scope_digest", frame));
        let mut frame = base;
        frame.aggregation_mode = PATH2_NATIVE_AGGREGATION_MODE_AGGREGATE_COMPATIBLE;
        mutated_frames.push(("aggregation_mode", frame));
        let mut frame = base;
        frame.native_boundary_digest[0] ^= 1;
        mutated_frames.push(("native_boundary_digest", frame));
        let mut frame = base;
        frame.p_account_digest[0] ^= 1;
        mutated_frames.push(("p_account_digest", frame));
        let mut frame = base;
        frame.p_spend_digest[0] ^= 1;
        mutated_frames.push(("p_spend_digest", frame));
        let mut frame = base;
        frame.p_lifecycle_digest[0] ^= 1;
        mutated_frames.push(("p_lifecycle_digest", frame));
        let mut frame = base;
        frame.p_transcript_digest[0] ^= 1;
        mutated_frames.push(("p_transcript_digest", frame));
        let mut frame = base;
        frame.p_state_digest[0] ^= 1;
        mutated_frames.push(("p_state_digest", frame));
        let mut frame = base;
        frame.message_digest[0] ^= 1;
        mutated_frames.push(("message_digest", frame));
        let mut frame = base;
        frame.current_state_digest[0] ^= 1;
        mutated_frames.push(("current_state_digest", frame));
        let mut frame = base;
        frame.proof_commitment[0] ^= 1;
        mutated_frames.push(("proof_commitment", frame));

        for (label, frame) in mutated_frames {
            assert_ne!(
                path2_native_checked_core_frame_v1_challenge(&frame).unwrap(),
                base_challenge,
                "{label}"
            );
        }
    }

    #[test]
    fn path2_native_checked_core_frame_v1_rejects_invalid_context() {
        let base = path2_native_checked_core_frame_fixture();
        let mut frame = base;
        frame.native_boundary_version += 1;
        assert!(validate_path2_native_checked_core_frame_v1(&frame)
            .unwrap_err()
            .contains("version mismatch"));

        let mut frame = base;
        frame.parameter_set_id += 1;
        assert!(validate_path2_native_checked_core_frame_v1(&frame)
            .unwrap_err()
            .contains("parameter set mismatch"));

        let mut frame = base;
        frame.verifier_family_id += 1;
        assert!(validate_path2_native_checked_core_frame_v1(&frame)
            .unwrap_err()
            .contains("verifier family mismatch"));

        let mut frame = base;
        frame.aggregation_mode = 2;
        assert!(validate_path2_native_checked_core_frame_v1(&frame)
            .unwrap_err()
            .contains("reserved"));

        let mut bytes = path2_native_checked_core_frame_v1_bytes(&base).unwrap();
        bytes[0] ^= 1;
        assert_eq!(
            decode_path2_native_checked_core_frame_v1(&bytes).unwrap_err(),
            "Path 2 native checked-core frame domain mismatch"
        );
    }

    #[test]
    fn path2_native_checked_core_frame_v1_excludes_legacy_private_handles() {
        let frame = path2_native_checked_core_frame_fixture();
        let bytes = path2_native_checked_core_frame_v1_bytes(&frame).unwrap();
        for (label, sentinel) in [
            ("opening_commitment", repeated_digest(0xa1)),
            ("pad_seed_digest", repeated_digest(0xa2)),
            ("hidden_source_statement_digest", repeated_digest(0xa3)),
            ("fallback_carrier_lane_bytes", repeated_digest(0xa4)),
        ] {
            assert!(
                !contains_window(&bytes, &sentinel),
                "native checked-core frame includes legacy private handle {label}"
            );
        }
    }

    fn assert_no_active_native_private_material(rendered: &str) {
        for forbidden in [
            "AuthorizationLocal",
            "private_signing",
            "private_trapdoor",
            "raw_pad_seed",
            "pad_seed",
            "pad_source",
            "opening_tuple",
            "opening_commitment",
            "opening_preimage",
            "unmasked_projection",
            "account_projection",
            "gauge",
            "randomizer",
            "blinding",
            "transparent_query_opening",
            "range_witness",
            "digit_witness",
            "carrier_transcript_binding",
            "projection_carrier",
            "checked_core_signature_or_proof_bytes",
        ] {
            assert!(
                !rendered.contains(forbidden),
                "active native public view leaked forbidden marker {forbidden}: {rendered}"
            );
        }
    }

    #[test]
    fn public_native_account_view_v1_serializes_only_allowlisted_fields() {
        let view = public_native_account_view_v1(
            PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION,
            PATH2_NATIVE_CHECKED_CORE_PARAMETER_SET_Q12289,
            PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12,
            PATH2_NATIVE_AGGREGATION_MODE_DIRECT,
            repeated_digest(0x21),
            repeated_digest(0x20),
            repeated_digest(0x22),
            repeated_digest(0x23),
            repeated_digest(0x24),
            repeated_digest(0x25),
            repeated_digest(0x26),
            1,
            repeated_digest(0x32),
            repeated_digest(0x40),
        )
        .unwrap();
        assert_eq!(view.schema, PATH2_PUBLIC_NATIVE_ACCOUNT_VIEW_SCHEMA);
        assert_eq!(view.native_boundary_digest, repeated_digest(0x21));
        assert_eq!(view.p_context_digest, repeated_digest(0x20));

        let serialized = public_native_account_view_v1_json(&view).unwrap();
        assert!(serialized.contains(PATH2_PUBLIC_NATIVE_ACCOUNT_VIEW_SCHEMA));
        for expected_field in [
            "native_boundary_version",
            "parameter_set_id",
            "verifier_family_id",
            "aggregation_mode",
            "native_boundary_digest",
            "p_context_digest",
            "p_account_digest",
            "p_spend_digest",
            "p_lifecycle_digest",
            "p_transcript_digest",
            "p_state_digest",
            "public_lifecycle_marker",
            "public_state_root",
            "obstruction_flags_digest",
        ] {
            assert!(
                serialized.contains(expected_field),
                "active native account view omitted allowlisted field {expected_field}: {serialized}"
            );
        }
        assert_no_active_native_private_material(&serialized);

        assert!(public_native_account_view_v1(
            PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION + 1,
            PATH2_NATIVE_CHECKED_CORE_PARAMETER_SET_Q12289,
            PATH2_NATIVE_CHECKED_CORE_VERIFIER_FAMILY_FQ12,
            PATH2_NATIVE_AGGREGATION_MODE_DIRECT,
            repeated_digest(0x21),
            repeated_digest(0x20),
            repeated_digest(0x22),
            repeated_digest(0x23),
            repeated_digest(0x24),
            repeated_digest(0x25),
            repeated_digest(0x26),
            1,
            repeated_digest(0x32),
            repeated_digest(0x40),
        )
        .unwrap_err()
        .contains("version mismatch"));
    }

    #[test]
    fn public_native_spend_view_v1_serializes_digest_only_proof_surface() {
        let frame = path2_native_checked_core_frame_fixture();
        let proof_bytes = native_checked_core_proof_fixture();
        let view = public_native_spend_view_v1(&frame, &proof_bytes).unwrap();
        assert_eq!(view.schema, PATH2_PUBLIC_NATIVE_SPEND_VIEW_SCHEMA);
        assert_eq!(view.native_boundary_digest, frame.native_boundary_digest);
        assert_eq!(view.message_digest, frame.message_digest);
        assert_eq!(view.current_state_digest, frame.current_state_digest);
        assert_eq!(view.proof_commitment, frame.proof_commitment);
        assert_eq!(
            view.checked_core_frame_digest,
            path2_native_checked_core_frame_v1_digest(&frame).unwrap()
        );
        let expected_proof_digest: [u8; DIGEST_BYTES] = Sha256::digest(proof_bytes).into();
        assert_eq!(view.checked_core_proof_bytes_digest, expected_proof_digest);
        assert_eq!(
            view.checked_core_proof_byte_len,
            PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES as u64
        );

        let serialized = public_native_spend_view_v1_json(&view).unwrap();
        assert!(serialized.contains(PATH2_PUBLIC_NATIVE_SPEND_VIEW_SCHEMA));
        assert!(serialized.contains("checked_core_frame_digest"));
        assert!(serialized.contains("checked_core_proof_bytes_digest"));
        assert!(serialized.contains("checked_core_proof_byte_len"));
        assert_no_active_native_private_material(&serialized);
        assert!(
            !serialized.contains("161,161,161,161"),
            "active native spend view serialized raw proof bytes: {serialized}"
        );

        let mut mutated_proof = proof_bytes;
        mutated_proof[0] ^= 1;
        let mutated_view = public_native_spend_view_v1(&frame, &mutated_proof).unwrap();
        assert_ne!(
            mutated_view.checked_core_proof_bytes_digest,
            view.checked_core_proof_bytes_digest
        );

        let mut bad_frame = frame;
        bad_frame.aggregation_mode = 9;
        assert!(public_native_spend_view_v1(&bad_frame, &proof_bytes)
            .unwrap_err()
            .contains("reserved"));

        let bad_len_proof = [0xa1_u8; PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES + 1];
        assert!(public_native_spend_view_v1(&frame, &bad_len_proof)
            .unwrap_err()
            .contains("checked-core proof has"));
    }

    #[test]
    fn path2_native_no_export_serializer_evidence_reports_component_facts() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = native_checked_core_proof_fixture();
        let spend_view =
            public_native_spend_view_v1(&path2_native_checked_core_frame_fixture(), &proof_bytes)
                .unwrap();
        let accept_output = public_native_spend_view_v1_json(&spend_view).unwrap();

        let da_digest = path2_native_projection_preimage_da_digest_v1(&bundle).unwrap();
        let assembly = assemble_path2_native_boundary_v1(&bundle, &proof_bytes).unwrap();
        let mut carrier = path2_native_consensus_carrier_v1_from_assembly(&assembly, da_digest);
        carrier.p_spend_digest[0] ^= 1;
        let rejected = verify_path2_native_deployment_pipeline_v1(&carrier, &bundle, &proof_bytes);
        assert!(!rejected.public_boundary_accepted);
        assert!(!rejected.production_accepted);
        let reject_output = serde_json::to_string(&rejected).unwrap();

        let storage_scope = path2_native_storage_lifecycle_hardening_scope_v1();
        let storage_output = serde_json::to_string(&storage_scope).unwrap();

        let evidence = path2_native_no_export_serializer_evidence_v1(
            &accept_output,
            &reject_output,
            &storage_output,
        );
        assert_eq!(
            evidence.schema,
            PATH2_NATIVE_NO_EXPORT_SERIALIZER_EVIDENCE_SCHEMA
        );
        assert!(evidence.schema_matches);
        assert!(evidence.report_digest_verified);
        assert!(evidence.active_output_tags_pinned);
        assert!(evidence.public_output_policy_pinned);
        assert!(evidence.accept_serializer_bound);
        assert!(evidence.reject_serializer_bound);
        assert!(evidence.storage_serializer_bound);
        assert!(evidence.denylist_exclusion_checked);
        assert!(evidence.serializer_negative_controls_passed);
        assert!(path2_native_no_export_serializer_evidence_all_facts_true(
            &evidence
        ));
        assert_ne!(
            path2_native_no_export_serializer_evidence_v1_digest(&evidence).unwrap(),
            [0_u8; DIGEST_BYTES]
        );
        assert_eq!(
            verify_path2_native_no_export_serializer_evidence_v1(
                &accept_output,
                &reject_output,
                &storage_output,
                &evidence,
            )
            .unwrap(),
            path2_native_no_export_serializer_evidence_v1_digest(&evidence).unwrap()
        );

        let evidence_frame = path2_native_no_export_serializer_evidence_v1_frame(&evidence);
        let expected_frame_digest: [u8; DIGEST_BYTES] = Sha256::digest(&evidence_frame).into();
        assert_eq!(
            path2_native_no_export_serializer_evidence_v1_digest(&evidence).unwrap(),
            expected_frame_digest
        );

        let mut tampered_digest_evidence = evidence;
        tampered_digest_evidence.accept_output_digest[0] ^= 1;
        assert_eq!(
            verify_path2_native_no_export_serializer_evidence_v1(
                &accept_output,
                &reject_output,
                &storage_output,
                &tampered_digest_evidence,
            )
            .unwrap_err(),
            "Path 2 native no-export serializer evidence mismatch"
        );

        let mut untrue_fact_evidence = evidence;
        untrue_fact_evidence.denylist_exclusion_checked = false;
        assert!(!path2_native_no_export_serializer_evidence_all_facts_true(
            &untrue_fact_evidence
        ));
        assert_eq!(
            verify_path2_native_no_export_serializer_evidence_v1(
                &accept_output,
                &reject_output,
                &storage_output,
                &untrue_fact_evidence,
            )
            .unwrap_err(),
            "Path 2 native no-export serializer evidence mismatch"
        );

        let private_accept_output = format!("{accept_output} raw_pad_seed");
        let private_evidence = path2_native_no_export_serializer_evidence_v1(
            &private_accept_output,
            &reject_output,
            &storage_output,
        );
        assert!(!private_evidence.denylist_exclusion_checked);
        assert!(!path2_native_no_export_serializer_evidence_all_facts_true(
            &private_evidence
        ));

        let rendered = serde_json::to_string(&evidence).unwrap();
        assert!(rendered.contains(PATH2_NATIVE_NO_EXPORT_SERIALIZER_EVIDENCE_SCHEMA));
        assert_no_active_native_private_material(&rendered);
    }

    #[test]
    fn path2_native_accepted_spend_numeric_evidence_stays_fail_closed_until_priced() {
        let evidence = path2_native_accepted_spend_numeric_evidence_v1();
        assert_eq!(
            evidence.schema,
            PATH2_NATIVE_ACCEPTED_SPEND_NUMERIC_EVIDENCE_SCHEMA
        );
        assert!(evidence.schema_matches);
        assert!(evidence.report_digest_verified);
        assert!(evidence.numeric_evidence_digests_verified);
        for digest in [
            evidence.finite_trace_support_digest,
            evidence.active_outcome_carrier_digest,
            evidence.accepted_spend_event_semantics_digest,
            evidence.active_break_family_digest,
            evidence.named_break_events_digest,
            evidence.accepted_spend_union_bound_pricing_digest,
            evidence.accepted_spend_priced_bound_digest,
        ] {
            assert_ne!(digest, [0_u8; DIGEST_BYTES]);
        }
        assert!(!evidence.accepted_spend_numeric_bound_priced);
        assert!(evidence.finite_trace_support_priced);
        assert!(evidence.active_outcome_carrier_pinned);
        assert!(evidence.accepted_spend_event_pinned);
        assert!(evidence.active_break_family_pinned);
        assert!(evidence.named_break_events_pinned);
        assert!(evidence.accepted_spend_union_bound_priced);
        assert!(!evidence.accepted_spend_event_bound_priced);
        assert!(!evidence.named_break_event_bounds_priced);
        assert!(!evidence.break_pricing_budget_meets_priced_bound);
        assert_eq!(evidence.target_security_bits, 128);
        assert_eq!(evidence.selected_multi_target_horizon_log2, 32);
        assert_eq!(evidence.qrom_quadratic_loss_bits_at_deployment_bound, 32);
        assert_eq!(evidence.transcript_term_bits_after_qrom_loss, 182);
        assert_eq!(evidence.accepted_spend_priced_bound_security_bits, 128);
        assert!(evidence.accepted_spend_numeric_budget_meets_target);
        assert!(evidence.hidden_source_closure_ready);
        assert!(evidence.checked_core_closure_ready);
        assert!(evidence.lifecycle_replay_closure_ready);
        assert!(evidence.no_export_closure_ready);
        assert!(path2_native_accepted_spend_numeric_evidence_report_verified_v1(&evidence));
        assert!(!path2_native_accepted_spend_numeric_evidence_all_facts_true(&evidence));
        let missing_pricing =
            path2_native_accepted_spend_numeric_missing_pricing_obligations_v1(&evidence);
        assert_eq!(
            missing_pricing.as_slice(),
            PATH2_NATIVE_ACCEPTED_SPEND_NUMERIC_CURRENT_MISSING_PRICING_OBLIGATIONS.as_slice()
        );
        assert_ne!(
            path2_native_accepted_spend_numeric_evidence_v1_digest(&evidence).unwrap(),
            [0_u8; DIGEST_BYTES]
        );

        let evidence_frame = path2_native_accepted_spend_numeric_evidence_v1_frame(&evidence);
        let expected_frame_digest: [u8; DIGEST_BYTES] = Sha256::digest(&evidence_frame).into();
        assert_eq!(
            path2_native_accepted_spend_numeric_evidence_v1_digest(&evidence).unwrap(),
            expected_frame_digest
        );
        assert_eq!(
            verify_path2_native_accepted_spend_numeric_evidence_v1(&evidence).unwrap(),
            path2_native_accepted_spend_numeric_evidence_v1_digest(&evidence).unwrap()
        );

        let mut forged_ready = evidence;
        forged_ready.accepted_spend_numeric_bound_priced = true;
        forged_ready.finite_trace_support_priced = true;
        forged_ready.active_outcome_carrier_pinned = true;
        forged_ready.accepted_spend_event_pinned = true;
        forged_ready.active_break_family_pinned = true;
        forged_ready.named_break_events_pinned = true;
        forged_ready.accepted_spend_union_bound_priced = true;
        forged_ready.accepted_spend_event_bound_priced = true;
        forged_ready.named_break_event_bounds_priced = true;
        forged_ready.break_pricing_budget_meets_priced_bound = true;
        forged_ready.accepted_spend_priced_bound_security_bits = evidence.target_security_bits;
        forged_ready.accepted_spend_numeric_budget_meets_target = true;
        assert!(
            path2_native_accepted_spend_numeric_missing_pricing_obligations_v1(&forged_ready)
                .is_empty()
        );
        assert!(!path2_native_accepted_spend_numeric_evidence_all_facts_true(&forged_ready));
        assert_eq!(
            verify_path2_native_accepted_spend_numeric_evidence_v1(&forged_ready).unwrap_err(),
            "Path 2 native accepted-spend numeric evidence mismatch"
        );

        let mut forged_over_transcript = forged_ready;
        forged_over_transcript.accepted_spend_priced_bound_security_bits =
            evidence.transcript_term_bits_after_qrom_loss;
        assert_eq!(
            path2_native_accepted_spend_numeric_missing_pricing_obligations_v1(
                &forged_over_transcript
            ),
            vec!["accepted_spend_priced_bound_security_within_transcript"]
        );

        let mut tampered_digest = evidence;
        tampered_digest.accepted_spend_priced_bound_digest[0] ^= 1;
        assert!(!path2_native_accepted_spend_numeric_evidence_report_verified_v1(&tampered_digest));
        assert_eq!(
            verify_path2_native_accepted_spend_numeric_evidence_v1(&tampered_digest).unwrap_err(),
            "Path 2 native accepted-spend numeric evidence mismatch"
        );
        let mut unverified_digests = evidence;
        unverified_digests.numeric_evidence_digests_verified = false;
        assert!(
            !path2_native_accepted_spend_numeric_evidence_report_verified_v1(&unverified_digests)
        );
        assert_eq!(
            verify_path2_native_accepted_spend_numeric_evidence_v1(&unverified_digests)
                .unwrap_err(),
            "Path 2 native accepted-spend numeric evidence mismatch"
        );

        let rendered = serde_json::to_string(&evidence).unwrap();
        assert!(rendered.contains(PATH2_NATIVE_ACCEPTED_SPEND_NUMERIC_EVIDENCE_SCHEMA));
        assert!(!rendered.contains("\"accepted_spend_numeric_bound_priced\":true"));
        assert!(!rendered.contains("\"accepted_spend_event_bound_priced\":true"));
        assert!(!rendered.contains("\"named_break_event_bounds_priced\":true"));
        assert!(!rendered.contains("\"break_pricing_budget_meets_priced_bound\":true"));
        assert!(rendered.contains("\"accepted_spend_event_pinned\":true"));
        assert!(rendered.contains("\"accepted_spend_union_bound_priced\":true"));
        assert!(rendered.contains("\"accepted_spend_numeric_budget_meets_target\":true"));
        assert_no_active_native_private_material(&rendered);
    }

    #[test]
    fn path2_native_full_signature_reduction_evidence_stays_fail_closed_until_instantiated() {
        let evidence = path2_native_full_signature_reduction_evidence_v1();
        assert_eq!(
            evidence.schema,
            PATH2_NATIVE_FULL_SIGNATURE_REDUCTION_EVIDENCE_SCHEMA
        );
        assert!(evidence.schema_matches);
        assert!(evidence.report_digest_verified);
        assert!(evidence.reduction_evidence_digests_verified);
        for digest in [
            evidence.production_signature_probability_digest,
            evidence.signature_accepted_spend_link_digest,
            evidence.full_execution_source_digest,
            evidence.active_hash_boundary_digest,
            evidence.query_budget_pricing_digest,
            evidence.multi_target_pricing_digest,
            evidence.verifier_game_binding_digest,
        ] {
            assert_ne!(digest, [0_u8; DIGEST_BYTES]);
        }
        assert!(!evidence.production_signature_probability_pinned);
        assert!(!evidence.signature_success_matches_accepted_spend_game);
        assert!(!evidence.accepted_spend_probability_linked);
        assert!(evidence.full_execution_source_consumed);
        assert!(evidence.active_hash_boundary_consumed);
        assert!(evidence.all_active_query_symbols_priced);
        assert!(evidence.multi_target_horizon_priced);
        assert!(evidence.verifier_game_matches_production_execution);
        assert!(path2_native_full_signature_reduction_evidence_report_verified_v1(&evidence));
        assert!(!path2_native_full_signature_reduction_evidence_all_facts_true(&evidence));
        let missing_production =
            path2_native_full_signature_reduction_missing_production_obligations_v1(&evidence);
        assert_eq!(
            missing_production.as_slice(),
            PATH2_NATIVE_FULL_SIGNATURE_REDUCTION_CURRENT_MISSING_PRODUCTION_OBLIGATIONS.as_slice()
        );

        let evidence_frame = path2_native_full_signature_reduction_evidence_v1_frame(&evidence);
        let expected_frame_digest: [u8; DIGEST_BYTES] = Sha256::digest(&evidence_frame).into();
        assert_eq!(
            path2_native_full_signature_reduction_evidence_v1_digest(&evidence).unwrap(),
            expected_frame_digest
        );
        assert_eq!(
            verify_path2_native_full_signature_reduction_evidence_v1(&evidence).unwrap(),
            path2_native_full_signature_reduction_evidence_v1_digest(&evidence).unwrap()
        );

        let mut forged_ready = evidence;
        forged_ready.production_signature_probability_pinned = true;
        forged_ready.signature_success_matches_accepted_spend_game = true;
        forged_ready.accepted_spend_probability_linked = true;
        forged_ready.full_execution_source_consumed = true;
        forged_ready.active_hash_boundary_consumed = true;
        forged_ready.all_active_query_symbols_priced = true;
        forged_ready.multi_target_horizon_priced = true;
        forged_ready.verifier_game_matches_production_execution = true;
        assert!(
            path2_native_full_signature_reduction_missing_production_obligations_v1(&forged_ready)
                .is_empty()
        );
        assert!(!path2_native_full_signature_reduction_evidence_all_facts_true(&forged_ready));
        assert_eq!(
            verify_path2_native_full_signature_reduction_evidence_v1(&forged_ready).unwrap_err(),
            "Path 2 native full-signature reduction evidence mismatch"
        );

        let mut tampered_digest = evidence;
        tampered_digest.signature_accepted_spend_link_digest[0] ^= 1;
        assert!(
            !path2_native_full_signature_reduction_evidence_report_verified_v1(&tampered_digest)
        );
        assert_eq!(
            verify_path2_native_full_signature_reduction_evidence_v1(&tampered_digest).unwrap_err(),
            "Path 2 native full-signature reduction evidence mismatch"
        );

        let mut unverified_digests = evidence;
        unverified_digests.reduction_evidence_digests_verified = false;
        assert!(
            !path2_native_full_signature_reduction_evidence_report_verified_v1(&unverified_digests)
        );
        assert_eq!(
            verify_path2_native_full_signature_reduction_evidence_v1(&unverified_digests)
                .unwrap_err(),
            "Path 2 native full-signature reduction evidence mismatch"
        );

        let rendered = serde_json::to_string(&evidence).unwrap();
        assert!(rendered.contains(PATH2_NATIVE_FULL_SIGNATURE_REDUCTION_EVIDENCE_SCHEMA));
        assert!(!rendered.contains("\"production_signature_probability_pinned\":true"));
        assert!(rendered.contains("\"full_execution_source_consumed\":true"));
        assert!(rendered.contains("\"active_hash_boundary_consumed\":true"));
        assert!(rendered.contains("\"all_active_query_symbols_priced\":true"));
        assert!(rendered.contains("\"multi_target_horizon_priced\":true"));
        assert!(rendered.contains("\"verifier_game_matches_production_execution\":true"));
        assert_no_active_native_private_material(&rendered);
    }

