    #[test]
    fn path2_native_boundary_assembly_derives_one_consistent_public_surface() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = native_checked_core_proof_fixture();
        let assembly = assemble_path2_native_boundary_v1(&bundle, &proof_bytes).unwrap();

        assert_eq!(
            assembly.p_context_digest,
            path2_native_context_projection_v1_digest(&bundle.context).unwrap()
        );
        assert_eq!(
            assembly.p_account_digest,
            path2_native_account_projection_v1_digest(&bundle.account)
        );
        assert_eq!(
            assembly.p_spend_digest,
            path2_native_spend_projection_v1_digest(&bundle.spend).unwrap()
        );
        assert_eq!(
            assembly.p_lifecycle_digest,
            path2_native_lifecycle_projection_v1_digest(&bundle.lifecycle)
        );
        assert_eq!(
            assembly.p_state_digest,
            path2_native_state_projection_v1_digest(&bundle.state)
        );
        assert_eq!(
            assembly.native_boundary_digest,
            path2_native_boundary_v1_digest(
                &assembly.p_context_digest,
                &assembly.p_account_digest,
                &assembly.p_spend_digest,
                &assembly.p_lifecycle_digest,
                &assembly.p_state_digest,
            )
        );
        assert_eq!(
            assembly.p_transcript_digest,
            path2_native_transcript_projection_v1_digest(&assembly.transcript_projection).unwrap()
        );
        assert_eq!(
            assembly.checked_core_frame.native_boundary_digest,
            assembly.native_boundary_digest
        );
        assert_eq!(
            assembly.checked_core_frame.p_transcript_digest,
            assembly.p_transcript_digest
        );
        assert_eq!(
            assembly.account_view.native_boundary_digest,
            assembly.native_boundary_digest
        );
        assert_eq!(
            assembly.spend_view.checked_core_frame_digest,
            path2_native_checked_core_frame_v1_digest(&assembly.checked_core_frame).unwrap()
        );
        let expected_proof_digest: [u8; DIGEST_BYTES] = Sha256::digest(proof_bytes).into();
        assert_eq!(
            assembly.spend_view.checked_core_proof_bytes_digest,
            expected_proof_digest
        );
    }

    #[test]
    fn path2_native_boundary_assembly_rejects_independent_digest_inputs() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = native_checked_core_proof_fixture();
        let assembly = assemble_path2_native_boundary_v1(&bundle, &proof_bytes).unwrap();

        let mut mutated = bundle;
        mutated.account.account_id[0] ^= 1;
        let mutated_assembly = assemble_path2_native_boundary_v1(&mutated, &proof_bytes).unwrap();
        assert_ne!(mutated_assembly.p_account_digest, assembly.p_account_digest);
        assert_ne!(
            mutated_assembly.native_boundary_digest,
            assembly.native_boundary_digest
        );
        assert_ne!(
            mutated_assembly.checked_core_frame.p_account_digest,
            assembly.checked_core_frame.p_account_digest
        );
        assert_ne!(
            mutated_assembly.spend_view.checked_core_frame_digest,
            assembly.spend_view.checked_core_frame_digest
        );

        let mut bad = bundle;
        bad.spend.public_key_identity[0] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native assembly public-key identity mismatch"
        );

        let mut bad = bundle;
        bad.account.public_key_identity[0] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native assembly public-key identity mismatch"
        );

        let mut bad = bundle;
        bad.spend.aggregation_mode = PATH2_NATIVE_AGGREGATION_MODE_AGGREGATE_COMPATIBLE;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native assembly aggregation mode mismatch"
        );

        let mut bad = bundle;
        bad.spend.spend_domain_separator_digest[0] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native assembly spend domain mismatch"
        );

        let mut bad = bundle;
        bad.spend.allowed_state_transition_class_digest[0] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native assembly spend-state transition mismatch"
        );

        let mut bad = bundle;
        bad.state.live_state_requirement ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native assembly lifecycle-state live marker mismatch"
        );

        let mut bad = bundle;
        bad.obstruction_flags_digest[0] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native assembly obstruction flags are not cleared"
        );

        let mut bad = bundle;
        bad.spend.allowed_authorization_local_mode =
            PATH2_NATIVE_AUTHORIZATION_LOCAL_MODE_DIRECT + 1;
        assert!(assemble_path2_native_boundary_v1(&bad, &proof_bytes)
            .unwrap_err()
            .contains("authorization-local mode mismatch"));

        let mut bad = bundle;
        bad.spend.spend_authorization_class_digest[0] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native spend projection authorization class digest mismatch"
        );

        let mut bad = bundle;
        bad.spend.checked_core_verifier_handle_digest[0] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native assembly public-key identity is not bound to checked-core verifier handle"
        );

        let mut bad_proof = proof_bytes;
        bad_proof[LINEAR_SIGMA_PROOF_COMMITMENT_BYTES] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bundle, &bad_proof).unwrap_err(),
            "Path 2 native checked-core sigma equation mismatch"
        );

        let mut bad = bundle;
        bad.proof_commitment[0] ^= 1;
        assert_eq!(
            assemble_path2_native_boundary_v1(&bad, &proof_bytes).unwrap_err(),
            "Path 2 native checked-core proof commitment mismatch"
        );
    }

    #[test]
    fn path2_active_native_domains_and_public_schemas_are_unique() {
        let domains = [
            PATH2_NATIVE_PROJECTION_CONTEXT_DOMAIN,
            PATH2_NATIVE_PUBLIC_KEY_IDENTITY_DOMAIN,
            PATH2_NATIVE_AUTHORIZATION_CLASS_DOMAIN,
            PATH2_NATIVE_PROJECTION_ACCOUNT_DOMAIN,
            PATH2_NATIVE_PROJECTION_SPEND_DOMAIN,
            PATH2_NATIVE_PROJECTION_LIFECYCLE_DOMAIN,
            PATH2_NATIVE_PROJECTION_STATE_DOMAIN,
            PATH2_NATIVE_PROJECTION_TRANSCRIPT_DOMAIN,
            PATH2_NATIVE_BOUNDARY_DOMAIN,
            PATH2_NATIVE_NO_OBSTRUCTION_FLAGS_DOMAIN,
            PATH2_NATIVE_PROJECTION_PREIMAGE_DA_DOMAIN,
            PATH2_NATIVE_CONSENSUS_CARRIER_DOMAIN,
            PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN,
        ];
        for (idx, domain) in domains.iter().enumerate() {
            assert!(
                domain.starts_with("Descender.Path2."),
                "active native domain lacks Path2 namespace: {domain}"
            );
            assert!(
                domain.ends_with(".v1"),
                "active native domain lacks explicit v1 suffix: {domain}"
            );
            for other in domains.iter().skip(idx + 1) {
                assert_ne!(domain, other, "duplicate active native domain {domain}");
            }
        }

        let schemas = [
            PATH2_PUBLIC_NATIVE_ACCOUNT_VIEW_SCHEMA,
            PATH2_PUBLIC_NATIVE_SPEND_VIEW_SCHEMA,
        ];
        for (idx, schema) in schemas.iter().enumerate() {
            assert!(
                schema.starts_with("DESCENDER_PATH2_PUBLIC_NATIVE_"),
                "active native public schema lacks public-native namespace: {schema}"
            );
            assert!(
                schema.ends_with("_V1"),
                "active native public schema lacks explicit V1 suffix: {schema}"
            );
            for other in schemas.iter().skip(idx + 1) {
                assert_ne!(
                    schema, other,
                    "duplicate active native public schema {schema}"
                );
            }
        }

        for domain in domains {
            for schema in schemas {
                assert_ne!(
                    domain, schema,
                    "active native domain collides with public schema {domain}"
                );
            }
        }
    }

    #[test]
    fn production_domain_schema_registry_is_globally_disjoint() {
        let registry = production_registered_domain_schema_constants();
        assert!(
            registry.len() >= 80,
            "production registry is missing expected domain/schema surfaces"
        );
        let mut by_value = BTreeMap::new();
        for (label, value) in &registry {
            assert!(!label.is_empty(), "empty registry label for {value}");
            assert!(!value.is_empty(), "empty registry value for {label}");
            assert!(
                value.as_bytes().iter().all(|byte| byte.is_ascii_graphic()),
                "registry value contains whitespace/control bytes: {label}={value}"
            );
            assert!(
                value.contains(".v") || value.contains("_V"),
                "registry value lacks explicit version marker: {label}={value}"
            );
            assert!(
                by_value.insert(*value, *label).is_none(),
                "duplicate production domain/schema value: {value}"
            );
        }

        for required in [
            "PATH2_NATIVE_PROJECTION_CONTEXT_DOMAIN",
            "PATH2_NATIVE_PUBLIC_KEY_IDENTITY_DOMAIN",
            "PATH2_NATIVE_AUTHORIZATION_CLASS_DOMAIN",
            "PATH2_NATIVE_PROJECTION_ACCOUNT_DOMAIN",
            "PATH2_NATIVE_PROJECTION_SPEND_DOMAIN",
            "PATH2_NATIVE_PROJECTION_LIFECYCLE_DOMAIN",
            "PATH2_NATIVE_PROJECTION_STATE_DOMAIN",
            "PATH2_NATIVE_PROJECTION_TRANSCRIPT_DOMAIN",
            "PATH2_NATIVE_BOUNDARY_DOMAIN",
            "PATH2_NATIVE_NO_OBSTRUCTION_FLAGS_DOMAIN",
            "PATH2_NATIVE_PROJECTION_PREIMAGE_DA_DOMAIN",
            "PATH2_NATIVE_CONSENSUS_CARRIER_DOMAIN",
            "PATH2_NATIVE_CONSENSUS_PREFLIGHT_REPORT_SCHEMA",
            "PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA",
            "PATH2_NATIVE_SIGNER_CONSTANT_TIME_STAGE_REPORT_SCHEMA",
            "PATH2_NATIVE_SIGNER_CT_SOURCE_AUDIT_SCHEMA",
            "PATH2_NATIVE_SIGNER_REJECTION_CLEANUP_AUDIT_SCHEMA",
            "PATH2_NATIVE_SIGNER_SHA256_BOUNDARY_AUDIT_SCHEMA",
            "PATH2_NATIVE_SIGNER_SHA256_CALL_SCHEDULE_AUDIT_SCHEMA",
            "PATH2_NATIVE_SIGNER_OS_ENTROPY_BOUNDARY_AUDIT_SCHEMA",
            "PATH2_NATIVE_SIGNER_RUNTIME_CLEANUP_AUDIT_SCHEMA",
            "PATH2_NATIVE_SIGNER_TIMING_PROBE_SCHEMA",
            "PATH2_NATIVE_SIGNER_PREVALIDATED_PUBLIC_INPUT_SCHEMA",
            "PATH2_NATIVE_SIGNER_PREVALIDATED_TIMING_PROBE_SCHEMA",
            "PATH2_NATIVE_SIGNER_PRODUCTION_ROUTING_AUDIT_SCHEMA",
            "PATH2_NATIVE_SIGNER_CT_EVIDENCE_LEDGER_SCHEMA",
            "PATH2_NATIVE_SIGNER_CT_EVIDENCE_BUNDLE_SCHEMA",
            "PATH2_NATIVE_HONEST_CONSTRUCTOR_SCOPE_SCHEMA",
            "PATH2_NATIVE_SIGNER_KEYGEN_PRODUCTIZATION_SCOPE_SCHEMA",
            "PATH2_NATIVE_SIGNER_ENTROPY_DERIVATION_DOMAIN",
            "PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN",
            "PATH2_NATIVE_STORAGE_LIFECYCLE_HARDENING_SCOPE_SCHEMA",
            "PATH2_NATIVE_BOUNDARY_TRACE_COLUMN_MANIFEST_SCHEMA",
            "PATH2_NATIVE_BOUNDARY_TRACE_PROOF_FAMILY_INTERFACE_SCHEMA",
            "PATH2_PUBLIC_NATIVE_ACCOUNT_VIEW_SCHEMA",
            "PATH2_PUBLIC_NATIVE_SPEND_VIEW_SCHEMA",
            "PATH2_NATIVE_ACCEPTED_SPEND_NUMERIC_EVIDENCE_SCHEMA",
            "PATH2_NATIVE_FULL_SIGNATURE_REDUCTION_EVIDENCE_SCHEMA",
            "REVIEWED_FQ12_STATE_ASSISTED_CARRIER_DOMAIN",
            "HIDDEN_SOURCE_FALLBACK_CHECKED_CORE_TRANSCRIPT_FRAME_DOMAIN",
            "PRODUCTION_DEPLOYMENT_PREFLIGHT_CERTIFICATE_DOMAIN",
        ] {
            assert!(
                registry.iter().any(|(label, _)| *label == required),
                "production registry missing {required}"
            );
        }

        let active_native_values: Vec<_> = registry
            .iter()
            .filter(|(label, _)| {
                label.starts_with("PATH2_NATIVE_") || label.starts_with("PATH2_PUBLIC_NATIVE_")
            })
            .map(|(_, value)| *value)
            .collect();
        assert_eq!(active_native_values.len(), 40);
        for active in active_native_values {
            for (label, value) in &registry {
                if label.starts_with("PATH2_NATIVE_") || label.starts_with("PATH2_PUBLIC_NATIVE_") {
                    continue;
                }
                assert_ne!(
                    active, *value,
                    "active native registry value collides with non-native {label}"
                );
            }
        }
    }

    #[test]
    fn path2_native_consensus_carrier_v1_is_canonical_hybrid_surface() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = native_checked_core_proof_fixture();
        let assembly = assemble_path2_native_boundary_v1(&bundle, &proof_bytes).unwrap();
        let da_digest = path2_native_projection_preimage_da_digest_v1(&bundle).unwrap();
        let carrier = path2_native_consensus_carrier_v1_from_assembly(&assembly, da_digest);
        assert_eq!(
            carrier.carrier_version,
            PATH2_NATIVE_CONSENSUS_CARRIER_VERSION
        );
        assert_eq!(
            carrier.native_boundary_digest,
            assembly.native_boundary_digest
        );
        assert_eq!(carrier.p_context_digest, assembly.p_context_digest);
        assert_eq!(carrier.p_account_digest, assembly.p_account_digest);
        assert_eq!(carrier.p_spend_digest, assembly.p_spend_digest);
        assert_eq!(carrier.p_lifecycle_digest, assembly.p_lifecycle_digest);
        assert_eq!(carrier.p_state_digest, assembly.p_state_digest);
        assert_eq!(carrier.p_transcript_digest, assembly.p_transcript_digest);
        assert_eq!(carrier.projection_preimage_da_digest, da_digest);

        let bytes = path2_native_consensus_carrier_v1_bytes(&carrier).unwrap();
        assert_eq!(bytes.len(), PATH2_NATIVE_CONSENSUS_CARRIER_BYTES);
        assert_eq!(
            &bytes[..PATH2_NATIVE_CONSENSUS_CARRIER_DOMAIN.len()],
            PATH2_NATIVE_CONSENSUS_CARRIER_DOMAIN.as_bytes()
        );
        assert_eq!(
            decode_path2_native_consensus_carrier_v1(&bytes).unwrap(),
            carrier
        );
        let expected_carrier_digest: [u8; DIGEST_BYTES] = Sha256::digest(&bytes).into();
        assert_eq!(
            path2_native_consensus_carrier_v1_digest(&carrier).unwrap(),
            expected_carrier_digest
        );
        assert_eq!(PATH2_NATIVE_CONSENSUS_CARRIER_BODY_BYTES, 330);

        let rendered = serde_json::to_string(&carrier).unwrap();
        assert_no_active_native_private_material(&rendered);
        assert!(!rendered.contains("message_digest"));
        assert!(!rendered.contains("proof_commitment"));
        assert!(!rendered.contains("checked_core_proof"));
    }

    #[test]
    fn path2_native_consensus_carrier_v1_rejects_bad_context_and_mutates() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = native_checked_core_proof_fixture();
        let assembly = assemble_path2_native_boundary_v1(&bundle, &proof_bytes).unwrap();
        let da_digest = path2_native_projection_preimage_da_digest_v1(&bundle).unwrap();
        let carrier = path2_native_consensus_carrier_v1_from_assembly(&assembly, da_digest);
        let digest = path2_native_consensus_carrier_v1_digest(&carrier).unwrap();

        let mut mutated = carrier;
        mutated.p_account_digest[0] ^= 1;
        assert_ne!(
            path2_native_consensus_carrier_v1_digest(&mutated).unwrap(),
            digest
        );

        let mut bad = carrier;
        bad.carrier_version += 1;
        assert!(validate_path2_native_consensus_carrier_v1(&bad)
            .unwrap_err()
            .contains("carrier version mismatch"));

        let mut bad = carrier;
        bad.aggregation_mode = 9;
        assert!(validate_path2_native_consensus_carrier_v1(&bad)
            .unwrap_err()
            .contains("reserved"));

        let mut bytes = path2_native_consensus_carrier_v1_bytes(&carrier).unwrap();
        bytes[0] ^= 1;
        assert_eq!(
            decode_path2_native_consensus_carrier_v1(&bytes).unwrap_err(),
            "Path 2 native consensus carrier domain mismatch"
        );
    }

