        let leaf_context_digest =
            path2_prevalidated_slot_leaf_context_digest(&leaf, &evidence, &certificate).unwrap();
        let mut old_leaf_context_frame = Vec::new();
        append_frame(
            &mut old_leaf_context_frame,
            b"domain",
            PATH2_TRANSPARENT_PUBLIC_VIEW_SCHEMA.as_bytes(),
        );
        append_frame(&mut old_leaf_context_frame, b"account_id", &leaf.account_id);
        append_frame(
            &mut old_leaf_context_frame,
            b"public_key_identity",
            &leaf.public_key_identity,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"slot_id",
            &leaf.slot_id.to_le_bytes(),
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"verifier_version_digest",
            &leaf.verifier_version_digest,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"account_state_root_before",
            &leaf.account_state_root_before,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"lifecycle_anchor",
            &leaf.lifecycle_anchor,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"live_status_marker",
            &[leaf.live_status_marker],
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"hidden_source_statement_digest",
            &leaf.hidden_source_statement_digest,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"relation_transcript_digest",
            &certificate.relation_transcript_digest,
        );
        let old_leaf_context_digest: [u8; DIGEST_BYTES] =
            Sha256::digest(old_leaf_context_frame).into();
        assert_ne!(leaf_context_digest, old_leaf_context_digest);
        let matrix_domain_transcript_digest = path2_descent_sis_matrix_transcript_digest(
            PATH2_DESCENT_SIS_ROLE_TRANSCRIPT_COMMITMENT,
            64,
        )
        .unwrap();
        let public_view = path2_transparent_descent_public_view_v1(
            path2_transparent_descent_proof_system_id(),
            256,
            16,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            leaf_context_digest,
            binding.digest,
            leaf.slot_id,
            leaf.hidden_source_statement_digest,
            binding.native_role_root_commitment,
            matrix_domain_transcript_digest,
            masked_projection,
            binding.aggregation_context_digest,
            test_digest("path2-transparent-trace-root"),
            test_digest("path2-transparent-constraint-root"),
            3,
        )
        .unwrap();
        let public_view_digest =
            path2_transparent_descent_public_view_digest(&public_view).unwrap();
        assert_ne!(public_view_digest, [0_u8; DIGEST_BYTES]);
        let commitment_api = path2_transparent_commitment_api_v1(&public_view, &binding).unwrap();
        assert_eq!(
            commitment_api.schema,
            PATH2_TRANSPARENT_COMMITMENT_API_SCHEMA
        );
        assert_eq!(commitment_api.creation_proof_binding_digest, binding.digest);
        assert_eq!(
            commitment_api.native_role_root_commitment,
            binding.native_role_root_commitment
        );
        assert_eq!(
            commitment_api.role_handles[0].role_id,
            PATH2_TWO_VIEW_ROLE_PACKED_WITNESS
        );
        assert_eq!(
            commitment_api.role_handles[0].role_handle,
            binding.packed_witness_commitment
        );
        assert_eq!(
            commitment_api.role_handles[1].role_id,
            PATH2_TWO_VIEW_ROLE_RANDOMIZER
        );
        assert_eq!(
            commitment_api.role_handles[1].role_handle,
            binding.randomizer_commitment
        );
        assert_eq!(
            commitment_api.role_handles[2].role_id,
            PATH2_TWO_VIEW_ROLE_PAD_SOURCE
        );
        assert_eq!(
            commitment_api.role_handles[2].role_handle,
            binding.pad_source_commitment
        );
        assert_eq!(
            commitment_api.role_handles[3].role_id,
            PATH2_TWO_VIEW_ROLE_PROJECTION_RELATION
        );
        assert_eq!(
            commitment_api.role_handles[3].role_handle,
            binding.projection_relation_commitment
        );
        assert_eq!(
            commitment_api.role_handles[4].role_id,
            PATH2_TWO_VIEW_ROLE_OPENING_TUPLE
        );
        assert_eq!(
            commitment_api.role_handles[4].role_handle,
            binding.opening_tuple_commitment
        );
        assert_eq!(
            commitment_api.role_handles[5].role_id,
            PATH2_TWO_VIEW_ROLE_BLINDING
        );
        assert_eq!(
            commitment_api.role_handles[5].role_handle,
            binding.gauge_commitment
        );
        assert_ne!(
            path2_transparent_commitment_api_v1_digest(&commitment_api, &public_view, &binding)
                .unwrap(),
            [0_u8; DIGEST_BYTES]
        );
        let mut wrong_public_view_role_root = public_view;
        wrong_public_view_role_root.native_role_root_commitment[0] ^= 1;
        wrong_public_view_role_root.transparent_transcript_digest =
            path2_transparent_descent_transcript_digest(
                &wrong_public_view_role_root.proof_system_id,
                wrong_public_view_role_root.trace_rows,
                wrong_public_view_role_root.query_count,
                wrong_public_view_role_root.column_profile,
                &wrong_public_view_role_root.leaf_context_digest,
                &wrong_public_view_role_root.creation_proof_binding_digest,
                wrong_public_view_role_root.slot_id,
                &wrong_public_view_role_root.hidden_source_statement_digest,
                &wrong_public_view_role_root.native_role_root_commitment,
                &wrong_public_view_role_root.matrix_domain_transcript_digest,
                &wrong_public_view_role_root.masked_projection,
                &wrong_public_view_role_root.aggregation_context_digest,
                &wrong_public_view_role_root.trace_commitment_root,
                &wrong_public_view_role_root.constraint_commitment_root,
                wrong_public_view_role_root.query_index,
            )
            .unwrap();
        assert_eq!(
            path2_transparent_commitment_api_v1(&wrong_public_view_role_root, &binding)
                .unwrap_err(),
            "Path 2 transparent commitment API context mismatch"
        );
        let mut unauthenticated_role = commitment_api;
        unauthenticated_role.role_handles[0].authenticated_under_parent_root = false;
        assert_eq!(
            verify_path2_transparent_commitment_api(&unauthenticated_role, &public_view, &binding,)
                .unwrap_err(),
            "Path 2 transparent commitment API role handle is not parent-authenticated"
        );
        let mut duplicate_role = commitment_api;
        duplicate_role.role_handles[1].role_id = duplicate_role.role_handles[0].role_id;
        assert_eq!(
            verify_path2_transparent_commitment_api(&duplicate_role, &public_view, &binding)
                .unwrap_err(),
            "Path 2 transparent commitment API duplicate role handle"
        );
        macro_rules! assert_commitment_api_role_handle_mismatch {
            ($index:expr) => {{
                let mut wrong_role_handle = commitment_api;
                wrong_role_handle.role_handles[$index].role_handle[0] ^= 1;
                assert_eq!(
                    verify_path2_transparent_commitment_api(
                        &wrong_role_handle,
                        &public_view,
                        &binding,
                    )
                    .unwrap_err(),
                    "Path 2 transparent commitment API role handle mismatch"
                );
            }};
        }
        assert_commitment_api_role_handle_mismatch!(0);
        assert_commitment_api_role_handle_mismatch!(1);
        assert_commitment_api_role_handle_mismatch!(2);
        assert_commitment_api_role_handle_mismatch!(3);
        assert_commitment_api_role_handle_mismatch!(4);
        assert_commitment_api_role_handle_mismatch!(5);
        let rebound_masked_projection = [43_u16, 47, 53, 59, 61, 67];
        let mut rebound_packed_binding = binding;
        rebound_packed_binding.packed_witness_commitment =
            pack_reviewed_fq12_packed_witness_state18_from_parts(
                &[0_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS],
                &rebound_masked_projection,
            )
            .unwrap();
        rebound_packed_binding.native_role_root_commitment =
            path2_creation_native_role_root_commitment_v1(
                &rebound_packed_binding.packed_witness_commitment,
                &rebound_packed_binding.randomizer_commitment,
                &rebound_packed_binding.pad_source_commitment,
                &rebound_packed_binding.opening_tuple_commitment,
                &rebound_packed_binding.projection_relation_commitment,
                &rebound_packed_binding.gauge_commitment,
            );
        rebound_packed_binding.digest =
            path2_creation_proof_binding_v1_digest(&rebound_packed_binding);
        let rebound_packed_view = path2_transparent_descent_public_view_v1(
            path2_transparent_descent_proof_system_id(),
            256,
            16,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            leaf_context_digest,
            rebound_packed_binding.digest,
            leaf.slot_id,
            leaf.hidden_source_statement_digest,
            rebound_packed_binding.native_role_root_commitment,
            matrix_domain_transcript_digest,
            masked_projection,
            rebound_packed_binding.aggregation_context_digest,
            test_digest("path2-transparent-trace-root"),
            test_digest("path2-transparent-constraint-root"),
            3,
        )
        .unwrap();
        assert_eq!(
            path2_transparent_commitment_api_v1(&rebound_packed_view, &rebound_packed_binding)
                .unwrap_err(),
            "Path 2 transparent commitment API packed witness masked projection mismatch"
        );
        let mut rebound_pad_source_binding = binding;
