    #[test]
    fn path2_native_checked_core_accept_pins_canonical_proof_bytes_before_acceptance() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = path2_native_checked_core_proof_from_bundle_v1(&bundle).unwrap();
        let (_, checked_core_frame) = path2_native_derive_boundary_frame_v1(&bundle).unwrap();

        assert_eq!(proof_bytes.len(), PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES);
        assert!(path2_native_checked_core_accept_v1(
            &checked_core_frame,
            &bundle.spend.checked_core_verifier_handle_digest,
            &proof_bytes,
        )
        .is_ok());

        let short_proof = &proof_bytes[..PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES - 1];
        assert!(path2_native_checked_core_accept_v1(
            &checked_core_frame,
            &bundle.spend.checked_core_verifier_handle_digest,
            short_proof,
        )
        .unwrap_err()
        .contains("Path 2 native checked-core proof has"));

        let mut noncanonical_proof = proof_bytes;
        noncanonical_proof[PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES - 1] |= 0xc0;
        assert_eq!(
            path2_native_checked_core_accept_v1(
                &checked_core_frame,
                &bundle.spend.checked_core_verifier_handle_digest,
                &noncanonical_proof,
            )
            .unwrap_err(),
            "Path 2 native checked-core proof decode: reviewed Fq12 masked response is not canonical: high bits are set"
        );

        let mut commitment_mismatch_proof = proof_bytes;
        commitment_mismatch_proof[0] ^= 1;
        assert_eq!(
            path2_native_checked_core_accept_v1(
                &checked_core_frame,
                &bundle.spend.checked_core_verifier_handle_digest,
                &commitment_mismatch_proof,
            )
            .unwrap_err(),
            "Path 2 native checked-core proof commitment mismatch"
        );
    }

    #[test]
    fn path2_native_checked_core_byte_instantiation_evidence_reports_component_facts() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = path2_native_checked_core_proof_from_bundle_v1(&bundle).unwrap();
        let evidence =
            path2_native_checked_core_byte_instantiation_evidence_v1(&bundle, &proof_bytes)
                .unwrap();

        assert_eq!(
            evidence.schema,
            PATH2_NATIVE_CHECKED_CORE_BYTE_INSTANTIATION_EVIDENCE_SCHEMA
        );
        assert!(evidence.accepted);
        assert!(evidence.checked_core_acceptor_accepts);
        assert!(evidence.parser_matches_native_handle);
        assert!(evidence.proof_length_eq);
        assert!(evidence.proof_canonical);
        assert!(evidence.decoded_proof_commitment_eq);
        assert!(evidence.parsed_response_syndrome_eq);
        assert!(evidence.frame_bytes_eq);
        assert!(evidence.verifier_handle_eq);
        assert!(evidence.parser_equality);
        assert!(evidence.hash_and_syndrome_eq);
        assert!(evidence.short_proof_rejected);
        assert!(evidence.noncanonical_proof_rejected);
        assert!(evidence.commitment_mismatch_rejected);
        assert!(evidence.verifier_handle_mismatch_rejected);
        let hash_byte_domain_evidence = path2_native_hash_byte_domain_evidence_v1();
        let hash_byte_domain_evidence_digest =
            verify_path2_native_hash_byte_domain_evidence_v1(&hash_byte_domain_evidence).unwrap();
        assert_eq!(
            evidence.hash_byte_domain_evidence_digest,
            hash_byte_domain_evidence_digest
        );
        assert!(evidence.hash_byte_domain_evidence_verified);
        assert!(evidence.hash_byte_domain_evidence_facts_all_true);
        assert!(evidence.checked_core_frame_domain_matches_hash_evidence);
        assert!(evidence.checked_core_frame_bytes_use_hash_domain_prefix);
        assert!(evidence.checked_core_challenge_uses_hash_domain_frame);
        assert!(evidence.checked_core_frame_digest_matches_hash_domain_frame);
        assert_eq!(
            evidence.proof_byte_len as usize,
            PATH2_NATIVE_CHECKED_CORE_PROOF_BYTES
        );
        assert_ne!(evidence.checked_core_frame_digest, [0_u8; DIGEST_BYTES]);
        let (_, checked_core_frame) = path2_native_derive_boundary_frame_v1(&bundle).unwrap();
        let checked_core_frame_bytes =
            path2_native_checked_core_frame_v1_bytes(&checked_core_frame).unwrap();
        assert!(checked_core_frame_bytes.starts_with(
            hash_byte_domain_evidence
                .checked_core_frame_domain
                .as_bytes()
        ));
        assert_eq!(
            evidence.checked_core_challenge,
            hash_frame_to_challenge_bytes_poseidon2(&checked_core_frame_bytes)
        );
        let checked_core_frame_digest: [u8; DIGEST_BYTES] =
            Sha256::digest(&checked_core_frame_bytes).into();
        assert_eq!(
            evidence.checked_core_frame_digest,
            checked_core_frame_digest
        );
        assert_ne!(
            evidence.checked_core_proof_bytes_digest,
            [0_u8; DIGEST_BYTES]
        );
        let expected_proof_digest: [u8; DIGEST_BYTES] = Sha256::digest(proof_bytes).into();
        assert_eq!(
            evidence.checked_core_proof_bytes_digest,
            expected_proof_digest
        );
        assert_eq!(
            evidence.checked_core_verifier_handle_digest,
            bundle.spend.checked_core_verifier_handle_digest
        );
        assert_ne!(
            path2_native_checked_core_byte_instantiation_evidence_v1_digest(&evidence).unwrap(),
            [0_u8; DIGEST_BYTES]
        );
        let evidence_frame =
            path2_native_checked_core_byte_instantiation_evidence_v1_frame(&evidence);
        assert!(!evidence_frame.is_empty());
        let evidence_frame_digest: [u8; DIGEST_BYTES] = Sha256::digest(&evidence_frame).into();
        assert_eq!(
            path2_native_checked_core_byte_instantiation_evidence_v1_digest(&evidence).unwrap(),
            evidence_frame_digest
        );
        assert!(path2_native_checked_core_byte_instantiation_evidence_all_facts_true(&evidence));
        assert_eq!(
            verify_path2_native_checked_core_byte_instantiation_evidence_v1(
                &bundle,
                &proof_bytes,
                &evidence,
            )
            .unwrap(),
            path2_native_checked_core_byte_instantiation_evidence_v1_digest(&evidence).unwrap()
        );

        let mut unbound_bundle = bundle;
        unbound_bundle.account.public_key_identity[0] ^= 1;
        let unbound_proof_bytes =
            path2_native_checked_core_proof_from_bundle_v1(&unbound_bundle).unwrap();
        let untrue_fact_evidence = path2_native_checked_core_byte_instantiation_evidence_v1(
            &unbound_bundle,
            &unbound_proof_bytes,
        )
        .unwrap();
        assert!(!untrue_fact_evidence.verifier_handle_eq);
        assert!(
            !path2_native_checked_core_byte_instantiation_evidence_all_facts_true(
                &untrue_fact_evidence
            )
        );
        assert_eq!(
            verify_path2_native_checked_core_byte_instantiation_evidence_v1(
                &unbound_bundle,
                &unbound_proof_bytes,
                &untrue_fact_evidence,
            )
            .unwrap_err(),
            "Path 2 native checked-core byte evidence has an unsatisfied component fact"
        );

        let mut tampered_digest_evidence = evidence;
        tampered_digest_evidence.checked_core_proof_bytes_digest[0] ^= 1;
        assert_eq!(
            verify_path2_native_checked_core_byte_instantiation_evidence_v1(
                &bundle,
                &proof_bytes,
                &tampered_digest_evidence,
            )
            .unwrap_err(),
            "Path 2 native checked-core byte evidence mismatch"
        );

        let mut tampered_hash_domain_evidence = evidence;
        tampered_hash_domain_evidence.hash_byte_domain_evidence_digest[0] ^= 1;
        assert_eq!(
            verify_path2_native_checked_core_byte_instantiation_evidence_v1(
                &bundle,
                &proof_bytes,
                &tampered_hash_domain_evidence,
            )
            .unwrap_err(),
            "Path 2 native checked-core byte evidence mismatch"
        );

        let mut tampered_bool_evidence = evidence;
        tampered_bool_evidence.hash_and_syndrome_eq = false;
        assert_eq!(
            verify_path2_native_checked_core_byte_instantiation_evidence_v1(
                &bundle,
                &proof_bytes,
                &tampered_bool_evidence,
            )
            .unwrap_err(),
            "Path 2 native checked-core byte evidence mismatch"
        );

        let rendered = serde_json::to_string(&evidence).unwrap();
        assert!(rendered.contains(PATH2_NATIVE_CHECKED_CORE_BYTE_INSTANTIATION_EVIDENCE_SCHEMA));
        assert_no_active_native_private_material(&rendered);
        assert!(!rendered.contains("masked_quotient_response"));
        assert!(!rendered.contains("proof_randomizer_syndrome"));
    }

