    #[test]
    fn path2_native_signer_rejection_cleanup_audit_pins_public_failure_surface() {
        let success_report = path2_native_signer_execution_report_from_entropy_root_v1(
            native_projection_bundle_fixture(),
            native_entropy_root_fixture("cleanup-success"),
        );
        let mut rejection_bundle = native_projection_bundle_fixture();
        rejection_bundle.spend.allowed_authorization_local_mode = 99;
        let constructor_rejection_report =
            path2_native_signer_execution_report_from_entropy_root_v1(
                rejection_bundle,
                native_entropy_root_fixture("cleanup-constructor-reject"),
            );
        let entropy_rejection_report = path2_native_signer_execution_failure_report_v1(
            "reject_active_native_signer_entropy_failed",
        );

        let audit = path2_native_signer_rejection_cleanup_audit_v1(
            &success_report,
            &constructor_rejection_report,
            &entropy_rejection_report,
        )
        .unwrap();

        assert_eq!(
            audit.schema,
            PATH2_NATIVE_SIGNER_REJECTION_CLEANUP_AUDIT_SCHEMA
        );
        assert!(!audit.audit_complete);
        assert!(audit.public_error_surface_complete);
        assert!(!audit.cleanup_zeroization_claim_complete);
        assert!(audit.all_rejection_digests_absent);
        assert!(audit.all_rejection_codes_public_only);
        assert!(audit.all_reports_private_material_absent);
        assert_eq!(
            audit.constructor_rejection_code,
            Some("reject_active_native_signer_constructor_failed")
        );
        assert_eq!(
            audit.entropy_rejection_code,
            Some("reject_active_native_signer_entropy_failed")
        );
        assert_ne!(audit.success_report_digest, [0_u8; DIGEST_BYTES]);
        assert_ne!(
            audit.success_report_digest,
            audit.constructor_rejection_report_digest
        );
        assert_ne!(
            audit.constructor_rejection_report_digest,
            audit.entropy_rejection_report_digest
        );
        assert_ne!(
            path2_native_signer_rejection_cleanup_audit_v1_digest(&audit).unwrap(),
            [0_u8; DIGEST_BYTES]
        );
        let audit_frame = path2_native_signer_rejection_cleanup_audit_v1_frame(&audit).unwrap();
        assert!(!audit_frame.is_empty());
        let audit_frame_digest: [u8; DIGEST_BYTES] = Sha256::digest(&audit_frame).into();
        assert_eq!(
            path2_native_signer_rejection_cleanup_audit_v1_digest(&audit).unwrap(),
            audit_frame_digest
        );
        assert_eq!(audit.blocker, PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME);

        let rendered = serde_json::to_string(&audit).unwrap();
        assert!(rendered.contains(PATH2_NATIVE_SIGNER_REJECTION_CLEANUP_AUDIT_SCHEMA));
        assert_no_active_native_private_material(&rendered);
        assert!(!rendered.contains("root_entropy"));
        assert!(!rendered.contains("account_nonce"));
        assert!(!rendered.contains("authorization_local_seed"));
        assert!(!rendered.contains("proof_randomizer_syndrome"));
        assert!(!rendered.contains("unsupported authorization"));
    }

    fn path2_native_signer_timing_probe_fixture(iterations: u32) -> Path2NativeSignerTimingProbeV1 {
        let mut success_total_ns = 0_u128;
        let mut constructor_rejection_total_ns = 0_u128;
        let mut last_success_report = None;
        let mut last_rejection_report = None;

        for idx in 0..iterations {
            let started = Instant::now();
            let success_report = path2_native_signer_execution_report_from_entropy_root_v1(
                native_projection_bundle_fixture(),
                native_entropy_root_fixture(&format!("timing-success-{idx}")),
            );
            success_total_ns += started.elapsed().as_nanos();
            last_success_report = Some(success_report);

            let mut rejection_bundle = native_projection_bundle_fixture();
            rejection_bundle.spend.allowed_authorization_local_mode = 99;
            let started = Instant::now();
            let rejection_report = path2_native_signer_execution_report_from_entropy_root_v1(
                rejection_bundle,
                native_entropy_root_fixture(&format!("timing-rejection-{idx}")),
            );
            constructor_rejection_total_ns += started.elapsed().as_nanos();
            last_rejection_report = Some(rejection_report);
        }

        let success_report = last_success_report.expect("timing probe success report missing");
        let rejection_report =
            last_rejection_report.expect("timing probe rejection report missing");
        let success_avg_ns = success_total_ns / iterations as u128;
        let constructor_rejection_avg_ns = constructor_rejection_total_ns / iterations as u128;
        let min_avg = success_avg_ns.min(constructor_rejection_avg_ns).max(1);
        let max_avg = success_avg_ns.max(constructor_rejection_avg_ns);
        let public_reports_sanitized = path2_native_public_report_excludes_private_material_v1(
            &serde_json::to_string(&success_report).unwrap(),
        ) && path2_native_public_report_excludes_private_material_v1(
            &serde_json::to_string(&rejection_report).unwrap(),
        )
            && path2_native_signer_execution_report_has_no_private_digests_v1(&rejection_report);

        Path2NativeSignerTimingProbeV1 {
            schema: PATH2_NATIVE_SIGNER_TIMING_PROBE_SCHEMA,
            iterations,
            success_total_ns,
            constructor_rejection_total_ns,
            success_avg_ns,
            constructor_rejection_avg_ns,
            max_to_min_avg_ratio_micros: (max_avg * 1_000_000) / min_avg,
            success_report_digest: path2_native_signer_execution_report_v1_digest(&success_report)
                .unwrap(),
            constructor_rejection_report_digest: path2_native_signer_execution_report_v1_digest(
                &rejection_report,
            )
            .unwrap(),
            public_reports_sanitized,
            timing_claim_complete: false,
            blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
            explicit_non_claims: [
                "timing probe is wall-clock smoke evidence only",
                "timing probe is not microarchitectural leakage proof",
                "timing probe does not complete signer constant-time audit",
            ],
        }
    }

