    #[test]
    fn path2_direct_authorization_requires_exact_admitted_leaf() {
        let (leaf, evidence, certificate) = path2_creation_frame_binding_fixture();
        let authorization = path2_slot_authorization_digest(&leaf).unwrap();
        let mut admitted = BTreeSet::new();

        assert_eq!(
            validate_path2_direct_slot_authorization_admission(
                &leaf,
                &evidence,
                &certificate,
                &admitted,
            )
            .unwrap_err(),
            "Path 2 slot authorization was not admitted"
        );

        admitted.insert(authorization);
        assert_eq!(
            validate_path2_direct_slot_authorization_admission(
                &leaf,
                &evidence,
                &certificate,
                &admitted,
            )
            .unwrap(),
            authorization
        );

        let (mut sibling_leaf, mut sibling_evidence, mut sibling_certificate) =
            path2_creation_frame_binding_fixture();
        sibling_leaf.slot_id += 1;
        sibling_evidence.slot_id = sibling_leaf.slot_id;
        sibling_certificate.slot_id = sibling_leaf.slot_id;
        sibling_evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&sibling_certificate);
        sibling_leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&sibling_evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&sibling_leaf, &mut sibling_evidence);
        assert_eq!(
            validate_path2_direct_slot_authorization_admission(
                &sibling_leaf,
                &sibling_evidence,
                &sibling_certificate,
                &admitted,
            )
            .unwrap_err(),
            "Path 2 slot authorization was not admitted"
        );
    }

