    fn path2_signature_with_authorization_challenge(
        signature: &ProductionSignature,
        public_key: &ProductionPublicKey,
        message: &[u8],
        leaf: &Path2PrevalidatedSlotLeafV1,
        witness_commitment: &[u8; DIGEST_BYTES],
    ) -> ProductionSignature {
        let parts = decode_reviewed_fq12_account_carried_signature(signature.as_bytes()).unwrap();
        let authorization = path2_slot_authorization_digest(leaf).unwrap();
        let challenge = path2_checked_core_authorization_challenge_bytes(
            public_key.as_bytes(),
            message,
            &leaf.account_id,
            &leaf.account_state_root_before,
            leaf.slot_id as u32,
            witness_commitment,
            &authorization,
            &parts.proof.proof_commitment,
        );
        let mut bytes = signature.as_bytes().to_vec();
        bytes[SLOT_ID_BYTES..SLOT_ID_BYTES + CHALLENGE_BYTES].copy_from_slice(&challenge);
        ProductionSignature::new(bytes)
    }

    #[test]
    fn path2_checked_core_authorization_challenge_binds_slot_authorization() {
        let (fixture, leaf, _evidence, _certificate) = path2_creation_relation_replay_fixture();
        let witness_commitment = fixture
            .account
            .get_slot(leaf.slot_id as u32)
            .unwrap()
            .commitment()
            .witness_commitment();
        let signature = path2_signature_with_authorization_challenge(
            &fixture.signature,
            &fixture.public_key,
            fixture.message,
            &leaf,
            &witness_commitment,
        );
        let authorization = path2_slot_authorization_digest(&leaf).unwrap();
        require_path2_checked_core_authorization_challenge_binding(
            fixture.public_key.as_bytes(),
            fixture.message,
            &leaf.account_id,
            &leaf.account_state_root_before,
            leaf.slot_id as u32,
            &witness_commitment,
            &authorization,
            &signature,
        )
        .unwrap();

        let mut wrong_authorization = authorization;
        wrong_authorization[0] ^= 1;
        assert_eq!(
            require_path2_checked_core_authorization_challenge_binding(
                fixture.public_key.as_bytes(),
                fixture.message,
                &leaf.account_id,
                &leaf.account_state_root_before,
                leaf.slot_id as u32,
                &witness_commitment,
                &wrong_authorization,
                &signature,
            )
            .unwrap_err()
            .reason(),
            "Path 2 checked-core authorization challenge mismatch"
        );

        let mut wrong_state_root = leaf.account_state_root_before;
        wrong_state_root[0] ^= 1;
        assert_eq!(
            require_path2_checked_core_authorization_challenge_binding(
                fixture.public_key.as_bytes(),
                fixture.message,
                &leaf.account_id,
                &wrong_state_root,
                leaf.slot_id as u32,
                &witness_commitment,
                &authorization,
                &signature,
            )
            .unwrap_err()
            .reason(),
            "Path 2 checked-core authorization challenge mismatch"
        );

        assert_ne!(
            challenge_bytes(
                fixture.public_key.as_bytes(),
                fixture.message,
                leaf.slot_id as u32,
                &witness_commitment,
                &decode_reviewed_fq12_account_carried_signature(fixture.signature.as_bytes())
                    .unwrap()
                    .proof
                    .proof_commitment,
            ),
            path2_checked_core_authorization_challenge_bytes(
                fixture.public_key.as_bytes(),
                fixture.message,
                &leaf.account_id,
                &leaf.account_state_root_before,
                leaf.slot_id as u32,
                &witness_commitment,
                &authorization,
                &decode_reviewed_fq12_account_carried_signature(fixture.signature.as_bytes())
                    .unwrap()
                    .proof
                    .proof_commitment,
            )
        );
    }

