    #[test]
    fn path2_direct_single_slot_spend_rejections_preserve_consume_once_state() {
        let (fixture, leaf, evidence, certificate) = path2_creation_relation_replay_fixture();
        let authorization = path2_slot_authorization_digest(&leaf).unwrap();
        let mut admitted_state_authorizations = BTreeSet::new();
        admitted_state_authorizations.insert((
            leaf.account_id,
            leaf.account_state_root_before,
            authorization,
        ));
        let responses = ProductionCompactResponses {
            active_free: [[0_i16; LOCAL_FREE]; REPS],
        };
        let signature = sign_path2_reviewed_fq12_authorization_checked_core(
            &fixture.public_key,
            fixture.message,
            &fixture.account,
            &leaf.account_id,
            &leaf.account_state_root_before,
            &authorization,
            leaf.slot_id as u32,
            &fixture.pad_seed,
            &responses,
        )
        .unwrap();

        let assert_rejects_without_consuming =
            |label: &str,
             leaf: &Path2PrevalidatedSlotLeafV1,
             evidence: &Path2AccountCreationEvidenceV1,
             certificate: &Path2DirectReplayableRelationCertificateV1,
             message: &[u8],
             signature: &ProductionSignature,
             admitted_state_authorizations: &BTreeSet<(
                [u8; DIGEST_BYTES],
                [u8; DIGEST_BYTES],
                [u8; DIGEST_BYTES],
            )>,
             expected: &str,
             expected_class: Path2PublicResultClassV1| {
                let mut consumed = BTreeSet::new();
                let err = verify_path2_direct_single_slot_spend_authorization(
                    leaf,
                    evidence,
                    certificate,
                    &fixture.public_key,
                    message,
                    &fixture.account,
                    signature,
                    admitted_state_authorizations,
                    &mut consumed,
                )
                .unwrap_err();
                assert_eq!(err.reason(), expected, "{label}");
                assert_eq!(
                    path2_direct_account_binding_public_result_class(&err),
                    expected_class,
                    "{label}"
                );
                assert!(
                    consumed.is_empty(),
                    "direct rejection {label} mutated consume-once state"
                );
            };

        let mut wrong_public_key_leaf = leaf;
        wrong_public_key_leaf.public_key_identity[0] ^= 1;
        assert_rejects_without_consuming(
            "public_key_identity_mismatch",
            &wrong_public_key_leaf,
            &evidence,
            &certificate,
            fixture.message,
            &signature,
            &admitted_state_authorizations,
            "Path 2 public-key identity mismatch",
            Path2PublicResultClassV1::RejectBindingMismatch,
        );

        assert_rejects_without_consuming(
            "missing_state_namespace_admission",
            &leaf,
            &evidence,
            &certificate,
            fixture.message,
            &signature,
            &BTreeSet::new(),
            "Path 2 slot authorization was not admitted in state namespace",
            Path2PublicResultClassV1::RejectCreationEvidence,
        );

        assert_rejects_without_consuming(
            "malformed_checked_core_signature",
            &leaf,
            &evidence,
            &certificate,
            fixture.message,
            &ProductionSignature::new(vec![0_u8; 7]),
            &admitted_state_authorizations,
            "reviewed Fq12 account-carried signature has 7 bytes, expected 262",
            Path2PublicResultClassV1::RejectMalformedPublicInput,
        );

        assert_rejects_without_consuming(
            "checked_core_message_rebinding",
            &leaf,
            &evidence,
            &certificate,
            b"path2-wrong-message",
            &signature,
            &admitted_state_authorizations,
            "Path 2 checked-core authorization challenge mismatch",
            Path2PublicResultClassV1::RejectCheckedCore,
        );

        let (mut rebound_leaf, mut rebound_evidence, mut rebound_certificate) =
            (leaf, evidence, certificate);
        rebound_leaf.slot_id += 1;
        rebound_evidence.slot_id = rebound_leaf.slot_id;
        rebound_certificate.slot_id = rebound_leaf.slot_id;
        rebound_evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&rebound_certificate);
        rebound_leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&rebound_evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&rebound_leaf, &mut rebound_evidence);
        let rebound_authorization = path2_slot_authorization_digest(&rebound_leaf).unwrap();
        let mut rebound_admitted_state_authorizations = BTreeSet::new();
        rebound_admitted_state_authorizations.insert((
            rebound_leaf.account_id,
            rebound_leaf.account_state_root_before,
            rebound_authorization,
        ));
        let rebound_signature = sign_path2_reviewed_fq12_authorization_checked_core(
            &fixture.public_key,
            fixture.message,
            &fixture.account,
            &rebound_leaf.account_id,
            &rebound_leaf.account_state_root_before,
            &rebound_authorization,
            0,
            &fixture.pad_seed,
            &responses,
        )
        .unwrap();
        assert_rejects_without_consuming(
            "checked_core_slot_leaf_rebinding",
            &rebound_leaf,
            &rebound_evidence,
            &rebound_certificate,
            fixture.message,
            &rebound_signature,
            &rebound_admitted_state_authorizations,
            "Path 2 checked-core slot id does not match prevalidated leaf",
            Path2PublicResultClassV1::RejectBindingMismatch,
        );

        let mut consumed = BTreeSet::new();
        consumed.insert(authorization);
        let before = consumed.clone();
        let err = verify_path2_direct_single_slot_spend_authorization(
            &leaf,
            &evidence,
            &certificate,
            &fixture.public_key,
            fixture.message,
            &fixture.account,
            &signature,
            &admitted_state_authorizations,
            &mut consumed,
        )
        .unwrap_err();
        assert_eq!(err.reason(), "Path 2 slot authorization already consumed");
        assert_eq!(
            path2_direct_account_binding_public_result_class(&err),
            Path2PublicResultClassV1::RejectLifecycleState
        );
        assert_eq!(
            consumed, before,
            "already-consumed rejection changed consume-once state"
        );
    }

    #[test]
    fn path2_direct_single_slot_spend_malformed_signature_kats_are_panic_free() {
        let (fixture, leaf, evidence, certificate) = path2_creation_relation_replay_fixture();
        let authorization = path2_slot_authorization_digest(&leaf).unwrap();
        let mut admitted_state_authorizations = BTreeSet::new();
        admitted_state_authorizations.insert((
            leaf.account_id,
            leaf.account_state_root_before,
            authorization,
        ));
        let responses = ProductionCompactResponses {
            active_free: [[0_i16; LOCAL_FREE]; REPS],
        };
        let signature = sign_path2_reviewed_fq12_authorization_checked_core(
            &fixture.public_key,
            fixture.message,
            &fixture.account,
            &leaf.account_id,
            &leaf.account_state_root_before,
            &authorization,
            leaf.slot_id as u32,
            &fixture.pad_seed,
            &responses,
        )
        .unwrap();
        let valid_bytes = signature.as_bytes();
        let response_start = SLOT_ID_BYTES + CHALLENGE_BYTES;
        let opening_start = response_start + ACTIVE_RESPONSE_BYTES;

        let mut one_short = valid_bytes.to_vec();
        one_short.pop();
        let mut one_long = valid_bytes.to_vec();
        one_long.push(0);
        let mut bad_challenge = valid_bytes.to_vec();
        bad_challenge[SLOT_ID_BYTES + ALGEBRAIC_CHALLENGE_BYTES - 1] |= 0x80;
        let mut bad_response = valid_bytes.to_vec();
        bad_response[response_start] = (2 * RESPONSE_BOUND) as u8 + 1;
        let mut bad_opening = valid_bytes.to_vec();
        bad_opening[opening_start..opening_start + 2].copy_from_slice(&Q.to_le_bytes());
        let mut bad_masked_response = valid_bytes.to_vec();
        *bad_masked_response.last_mut().unwrap() |= 0xf0;

        let cases = [
            (
                "empty_signature",
                ProductionSignature::new(Vec::new()),
                "reviewed Fq12 account-carried signature has 0 bytes, expected 262".to_string(),
            ),
            (
                "slot_id_only_signature",
                ProductionSignature::new(vec![0_u8; SLOT_ID_BYTES]),
                "reviewed Fq12 account-carried signature has 4 bytes, expected 262".to_string(),
            ),
            (
                "one_byte_short_signature",
                ProductionSignature::new(one_short),
                "reviewed Fq12 account-carried signature has 261 bytes, expected 262".to_string(),
            ),
            (
                "one_byte_long_signature",
                ProductionSignature::new(one_long),
                "reviewed Fq12 account-carried signature has 263 bytes, expected 262".to_string(),
            ),
            (
                "noncanonical_challenge",
                ProductionSignature::new(bad_challenge),
                "challenge is not canonical: high bits are set".to_string(),
            ),
            (
                "noncanonical_response",
                ProductionSignature::new(bad_response),
                "active response coordinate 0 in round 0 is non-canonical: 97".to_string(),
            ),
            (
                "noncanonical_opening",
                ProductionSignature::new(bad_opening),
                format!("opening coordinate 0 in round 0 is non-canonical: {Q}"),
            ),
            (
                "noncanonical_fq12_masked_response",
                ProductionSignature::new(bad_masked_response),
                "reviewed Fq12 masked response is not canonical: high bits are set".to_string(),
            ),
        ];

        for (label, malformed_signature, expected_reason) in cases {
            let mut consumed = BTreeSet::new();
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                verify_path2_direct_single_slot_spend_authorization(
                    &leaf,
                    &evidence,
                    &certificate,
                    &fixture.public_key,
                    fixture.message,
                    &fixture.account,
                    &malformed_signature,
                    &admitted_state_authorizations,
                    &mut consumed,
                )
            }));
            let err = result
                .unwrap_or_else(|_| panic!("malformed signature case {label} panicked"))
                .unwrap_err();
            assert_eq!(err.reason(), expected_reason, "{label}");
            assert_eq!(
                path2_direct_account_binding_public_result_class(&err),
                Path2PublicResultClassV1::RejectMalformedPublicInput,
                "{label}"
            );
            assert!(
                consumed.is_empty(),
                "malformed signature case {label} mutated consume-once state"
            );
        }
    }

