    #[test]
    fn path2_creation_statement_must_not_be_signature_dependent() {
        let (fixture, leaf, _evidence, _certificate) = path2_creation_relation_replay_fixture();
        assert_ne!(
            fixture.statement.digest, leaf.hidden_source_statement_digest,
            "Path 2 leaf must bind the non-circular creation statement, not the reviewed Fq12 spend statement"
        );
        let creation_statement =
            path2_creation_hidden_source_statement_v1_from_reviewed(&leaf, &fixture.statement);
        assert_eq!(
            creation_statement.digest,
            leaf.hidden_source_statement_digest
        );

        let mut signature_rebound = fixture.statement;
        signature_rebound.signature_digest[0] ^= 1;
        signature_rebound.digest = reviewed_fq12_hidden_source_statement_digest(&signature_rebound);
        assert_ne!(signature_rebound.digest, fixture.statement.digest);
        assert_ne!(
            signature_rebound.digest, leaf.hidden_source_statement_digest,
            "legacy reviewed Fq12 statement rebinding must not become the Path 2 creation digest"
        );
        assert_eq!(
            path2_creation_hidden_source_statement_v1_from_reviewed(&leaf, &signature_rebound)
                .digest,
            leaf.hidden_source_statement_digest
        );

        let mut message_rebound = fixture.statement;
        message_rebound.message_digest[0] ^= 1;
        message_rebound.digest = reviewed_fq12_hidden_source_statement_digest(&message_rebound);
        assert_ne!(message_rebound.digest, fixture.statement.digest);
        assert_ne!(
            message_rebound.digest, leaf.hidden_source_statement_digest,
            "legacy reviewed Fq12 message rebinding must not become the Path 2 creation digest"
        );
        assert_eq!(
            path2_creation_hidden_source_statement_v1_from_reviewed(&leaf, &message_rebound).digest,
            leaf.hidden_source_statement_digest
        );
    }

    #[test]
    fn path2_creation_hidden_source_statement_v1_is_canonical_and_non_circular() {
        let (fixture, leaf, _evidence, _certificate) = path2_creation_relation_replay_fixture();
        let statement =
            path2_creation_hidden_source_statement_v1_from_reviewed(&leaf, &fixture.statement);
        let frame = path2_creation_hidden_source_statement_v1_frame(&statement);

        assert_eq!(
            statement.frame_version,
            PATH2_CREATION_HIDDEN_SOURCE_STATEMENT_FRAME_VERSION
        );
        assert_eq!(
            statement.digest,
            path2_creation_hidden_source_statement_v1_digest(&statement)
        );
        assert!(frame
            .windows(PATH2_CREATION_HIDDEN_SOURCE_STATEMENT_DOMAIN.len())
            .any(|window| window == PATH2_CREATION_HIDDEN_SOURCE_STATEMENT_DOMAIN.as_bytes()));
        assert!(!frame
            .windows(b"message_digest".len())
            .any(|window| window == b"message_digest"));
        assert!(!frame
            .windows(b"signature_digest".len())
            .any(|window| window == b"signature_digest"));

        let mut signature_rebound = fixture.statement;
        signature_rebound.signature_digest[0] ^= 1;
        signature_rebound.digest = reviewed_fq12_hidden_source_statement_digest(&signature_rebound);
        assert_eq!(
            statement.digest,
            path2_creation_hidden_source_statement_v1_from_reviewed(&leaf, &signature_rebound)
                .digest
        );

        let mut message_rebound = fixture.statement;
        message_rebound.message_digest[0] ^= 1;
        message_rebound.digest = reviewed_fq12_hidden_source_statement_digest(&message_rebound);
        assert_eq!(
            statement.digest,
            path2_creation_hidden_source_statement_v1_from_reviewed(&leaf, &message_rebound).digest
        );

        let mut pad_rebound = fixture.statement;
        pad_rebound.pad_opening_statement.digest[0] ^= 1;
        assert_ne!(
            statement.digest,
            path2_creation_hidden_source_statement_v1_from_reviewed(&leaf, &pad_rebound).digest
        );
    }

