    struct MaskedProjectionFixture {
        slot: ProductionReviewedFq12StateAssistedAccountSlot,
        opening: ProductionReviewedFq12StateAssistedOpening,
        statement: ProductionReviewedFq12HiddenSourceStatement,
        pad_seed: [u8; REVIEWED_FQ12_PAD_SEED_BYTES],
        carrier: HiddenSourceFallbackProjectionCarrier,
    }

    fn masked_projection_fixture() -> MaskedProjectionFixture {
        let slot_id = 0_u64;
        let pad_seed = [0x42_u8; REVIEWED_FQ12_PAD_SEED_BYTES];
        let mut account_projection = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
        for (idx, value) in account_projection.iter_mut().enumerate() {
            *value = (idx as u16) + 1;
        }
        let witness_syndrome = [0_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS];
        let witness_commitment = reviewed_fq12_pack_masked_witness_state18_from_parts(
            &witness_syndrome,
            &account_projection,
            &pad_seed,
            slot_id,
        )
        .unwrap();
        let randomizer_commitment = pack_reviewed_fq12_account_carried_syndrome_digest(
            &[0_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS],
        )
        .unwrap();
        let account_witness_opening = HiddenSourceFallbackProjectionAccountWitnessOpening {
            selected_source_values: account_projection,
        };
        let account_witness_opening_frame =
            encode_hidden_source_fallback_account_witness_opening_frame(&account_witness_opening)
                .unwrap();
        let mut opening = ProductionReviewedFq12StateAssistedOpening {
            slot_id,
            account_witness_commitment: witness_commitment,
            account_randomizer_commitment: randomizer_commitment,
            restore_anchor_digest: test_digest("masked-projection-restore-anchor"),
            witness_opening_digest: reviewed_fq12_account_witness_projection_opening_digest(
                &account_witness_opening_frame,
            )
            .unwrap(),
            pad_seed_digest: reviewed_fq12_pad_seed_opening_digest(&pad_seed),
            carrier_handle_secret_digest: test_digest("masked-projection-carrier-handle"),
        };
        let opening_commitment = reviewed_fq12_state_assisted_opening_commitment_digest(&opening);
        assert_ne!(opening_commitment, [0_u8; DIGEST_BYTES]);
        let slot = ProductionReviewedFq12StateAssistedAccountSlot::new(
            slot_id as u32,
            ProductionAccountCommitment::new(witness_commitment, randomizer_commitment),
            opening_commitment,
            opening.restore_anchor_digest,
            opening.pad_seed_digest,
        );
        let pad_opening_statement =
            reviewed_fq12_pad_opening_statement_from_seed(&pad_seed, &[true; GROUPS]);
        let mut statement = ProductionReviewedFq12HiddenSourceStatement {
            digest: [0_u8; DIGEST_BYTES],
            slot_id: slot_id as u32,
            witness_commitment,
            randomizer_commitment,
            public_key_digest: test_digest("masked-projection-public-key"),
            message_digest: test_digest("masked-projection-message"),
            signature_digest: test_digest("masked-projection-signature"),
            pad_opening_statement,
        };
        statement.digest = reviewed_fq12_hidden_source_statement_digest(&statement);
        let projection_values = hidden_source_fallback_projection_values_from_hidden_material(
            &account_witness_opening,
            &pad_seed,
        )
        .unwrap();
        let (check_bytes, transcript_binding) =
            reviewed_fq12_state_assisted_projection_carrier_binding(
                &opening_commitment,
                &opening,
                &statement,
                &projection_values,
            )
            .unwrap();
        let mut carrier_bytes = [0_u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES];
        for (lane, value) in projection_values.iter().enumerate() {
            carrier_bytes[lane * 2..lane * 2 + 2].copy_from_slice(&value.to_le_bytes());
        }
        carrier_bytes[24..27].copy_from_slice(&check_bytes);
        carrier_bytes[27..56].copy_from_slice(&transcript_binding);
        let carrier = HiddenSourceFallbackProjectionCarrier::from_bytes(&carrier_bytes).unwrap();
        verify_reviewed_fq12_state_assisted_masked_witness_state18_slot_projection_carrier_tuple(
            &slot, &opening, &statement, &pad_seed, &carrier,
        )
        .unwrap();

        // Keep the mutable construction local; callers should mutate clones of fields.
        opening.slot_id = slot_id;
        MaskedProjectionFixture {
            slot,
            opening,
            statement,
            pad_seed,
            carrier,
        }
    }

    #[test]
    fn production_reviewed_fq12_public_account_state_digest_only() {
        let fixture = masked_projection_fixture();
        let account =
            ProductionReviewedFq12StateAssistedAccountState::new(vec![fixture.slot]).unwrap();
        let records = account.checked_slot_records().unwrap();
        let serialized = serde_json::to_string(&records).unwrap();
        assert_digest_only_selected_projection_record(&serialized);
        assert!(!serialized.contains("account_witness_projection_opening_frame"));
        assert!(!serialized.contains("account_projection"));
        assert!(!serialized.contains("projection_masks"));
    }

    #[test]
    fn production_reviewed_fq12_snapshot_restore_digest_only() {
        let fixture = masked_projection_fixture();
        let account =
            ProductionReviewedFq12StateAssistedAccountState::new(vec![fixture.slot]).unwrap();
        let manager =
            ProductionReviewedFq12StateAssistedAccountLifecycleManager::new(account).unwrap();
        let snapshot = manager.snapshot().unwrap();
        let serialized = serde_json::to_string(&snapshot).unwrap();
        assert_digest_only_selected_projection_record(&serialized);

        let restored = ProductionReviewedFq12StateAssistedAccountLifecycleManager::from_snapshot_with_restore_anchor(
            snapshot.clone(),
            ProductionLifecycleRestoreAnchor {
                minimum_snapshot_sequence: 0,
            },
        )
        .unwrap();
        let restored_serialized = serde_json::to_string(&restored.snapshot().unwrap()).unwrap();
        assert_digest_only_selected_projection_record(&restored_serialized);
        assert_eq!(restored.snapshot().unwrap(), snapshot);
    }

