    #[test]
    fn selected_projection_spent_replay_rejects_digest_only_no_opening() {
        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let pad_seed_digest = test_digest("selected-projection-pad-seed-digest");
        let account_witness_opening = HiddenSourceFallbackProjectionAccountWitnessOpening {
            selected_source_values: [3_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
        };
        let account_witness_opening_frame =
            encode_hidden_source_fallback_account_witness_opening_frame(&account_witness_opening)
                .unwrap();
        let witness_commitment = pack_reviewed_fq12_account_carried_syndrome_digest(
            &[1_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS],
        )
        .unwrap();
        let randomizer_commitment = pack_reviewed_fq12_account_carried_syndrome_digest(
            &[7_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS],
        )
        .unwrap();
        let account = hidden_source_fallback_projection_account_state_from_slot_frames([
            HiddenSourceFallbackProjectionAccountSlotFrameSeed {
                witness_commitment,
                randomizer_commitment,
                account_witness_opening_frame: account_witness_opening_frame.clone(),
                restore_anchor_digest: test_digest("selected-projection-restore-anchor"),
                pad_seed_digest,
                unused: true,
            },
        ])
        .unwrap();
        let manager =
            ProductionReviewedFq12StateAssistedAccountLifecycleManager::new(account).unwrap();
        let snapshot = manager.snapshot().unwrap();
        let restore_anchor = ProductionLifecycleRestoreAnchor {
            minimum_snapshot_sequence: 0,
        };

        let transition = apply_selected_projection_consensus_opening_frame(
            snapshot.clone(),
            Vec::new(),
            restore_anchor.clone(),
            &public_key,
            0,
            &account_witness_opening_frame,
        )
        .unwrap();
        assert_eq!(transition.spend_record.slot_id, 0);
        assert_eq!(transition.spend_record.pad_seed_digest, pad_seed_digest);
        assert_eq!(
            transition.spend_record.spent_record.pad_seed_digest,
            Some(pad_seed_digest)
        );
        let spend_debug = format!("{:?}", transition.spend_record);
        assert!(spend_debug.contains("pad_seed_digest"));
        assert_no_selected_projection_material(&spend_debug);

        let replay = apply_selected_projection_consensus_opening_frame(
            transition.next_lifecycle_snapshot.clone(),
            transition.next_spent_slot_records.clone(),
            ProductionLifecycleRestoreAnchor {
                minimum_snapshot_sequence: 0,
            },
            &public_key,
            0,
            &account_witness_opening_frame,
        )
        .unwrap_err();
        assert_eq!(replay.reason(), "slot is already in spent ledger");
        assert_no_selected_projection_material(&format!("{replay:?}"));

        let stale_replay = apply_selected_projection_consensus_opening_frame(
            snapshot,
            transition.next_spent_slot_records.clone(),
            restore_anchor,
            &public_key,
            0,
            &account_witness_opening_frame,
        )
        .unwrap_err();
        assert_eq!(stale_replay.reason(), "slot is already in spent ledger");
        assert_no_selected_projection_material(&format!("{stale_replay:?}"));

        let duplicate_digest = ProductionSpentSlotRecord {
            key: ProductionSpentSlotLedger::key(&public_key, 1),
            snapshot_sequence: 9,
            source: "selected projection accepted verification".to_string(),
            pad_seed_digest: Some(pad_seed_digest),
        };
        let duplicate_err = ProductionSpentSlotLedger::from_records(vec![
            transition.spend_record.spent_record,
            duplicate_digest,
        ])
        .unwrap_err();
        assert_eq!(
            duplicate_err.reason(),
            "pad seed digest is already in spent ledger"
        );
        assert_no_selected_projection_material(&format!("{duplicate_err:?}"));
    }

    #[test]
    fn state_assisted_account_state_checked_records_no_selected_material() {
        let fixture = masked_projection_fixture();
        let account =
            ProductionReviewedFq12StateAssistedAccountState::new(vec![fixture.slot.clone()])
                .unwrap();
        let records = account.checked_slot_records().unwrap();
        assert_eq!(records.len(), 1);
        assert_eq!(records[0].slot_id, fixture.slot.slot_id());
        assert_eq!(
            records[0].witness_commitment,
            fixture.slot.commitment().witness_commitment()
        );
        assert_eq!(
            records[0].randomizer_commitment,
            fixture.slot.commitment().randomizer_commitment()
        );
        assert_eq!(
            records[0].hidden_source_opening_commitment,
            fixture.slot.hidden_source_opening_commitment()
        );
        assert_eq!(
            records[0].restore_anchor_digest,
            fixture.slot.restore_anchor_digest()
        );
        assert_eq!(records[0].pad_seed_digest, fixture.slot.pad_seed_digest());
        assert!(records[0].unused);

        let serialized_records = serde_json::to_string(&records).unwrap();
        for expected_field in [
            "slot_id",
            "witness_commitment",
            "randomizer_commitment",
            "hidden_source_opening_commitment",
            "restore_anchor_digest",
            "pad_seed_digest",
            "unused",
        ] {
            assert!(
                serialized_records.contains(expected_field),
                "checked slot records omitted public digest field {expected_field}: {serialized_records}"
            );
        }
        assert_no_selected_projection_material(&serialized_records);

        let restored =
            reviewed_fq12_state_assisted_account_state_from_slot_records(records.clone()).unwrap();
        let restored_records = restored.checked_slot_records().unwrap();
        assert_eq!(restored_records, records);
        assert_no_selected_projection_material(&serde_json::to_string(&restored_records).unwrap());
    }

    #[test]
    fn selected_projection_lifecycle_snapshot_roundtrips_digest_only() {
        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let fixture = masked_projection_fixture();
        let account =
            ProductionReviewedFq12StateAssistedAccountState::new(vec![fixture.slot.clone()])
                .unwrap();
        let manager =
            ProductionReviewedFq12StateAssistedAccountLifecycleManager::new(account).unwrap();
        let snapshot = manager.snapshot().unwrap();
        let serialized_snapshot = serde_json::to_string(&snapshot).unwrap();
        assert!(serialized_snapshot.contains("hidden_source_opening_commitment"));
        assert!(serialized_snapshot.contains("pad_seed_digest"));
        assert_no_selected_projection_material(&serialized_snapshot);

        let decoded_snapshot: ProductionReviewedFq12StateAssistedLifecycleSnapshot =
            serde_json::from_str(&serialized_snapshot).unwrap();
        assert_eq!(decoded_snapshot, snapshot);
        let restored = ProductionReviewedFq12StateAssistedAccountLifecycleManager::from_snapshot_with_restore_anchor(
            decoded_snapshot.clone(),
            ProductionLifecycleRestoreAnchor {
                minimum_snapshot_sequence: decoded_snapshot.snapshot_sequence,
            },
        )
        .unwrap();
        assert_eq!(restored.snapshot().unwrap(), decoded_snapshot);

        let spent_record = ProductionSpentSlotRecord {
            key: ProductionSpentSlotLedger::key(&public_key, fixture.slot.slot_id()),
            snapshot_sequence: snapshot.snapshot_sequence,
            source: "selected projection accepted verification".to_string(),
            pad_seed_digest: Some(fixture.slot.pad_seed_digest()),
        };
        let consensus_spend = ProductionSelectedProjectionConsensusSpendRecord {
            slot_id: fixture.slot.slot_id(),
            snapshot_sequence: snapshot.snapshot_sequence,
            hidden_source_opening_commitment: fixture.slot.hidden_source_opening_commitment(),
            pad_seed_digest: fixture.slot.pad_seed_digest(),
            spent_record,
        };
        let serialized_spent = serde_json::to_string(&consensus_spend).unwrap();
        assert!(serialized_spent.contains("hidden_source_opening_commitment"));
        assert!(serialized_spent.contains("pad_seed_digest"));
        assert_no_selected_projection_material(&serialized_spent);

        let decoded_spent: ProductionSelectedProjectionConsensusSpendRecord =
            serde_json::from_str(&serialized_spent).unwrap();
        assert_eq!(decoded_spent, consensus_spend);
        assert_eq!(
            decoded_spent.spent_record.pad_seed_digest,
            Some(fixture.slot.pad_seed_digest())
        );
    }

