    #[test]
    fn verify_account_binding_checks_slot_state_and_randomizer() {
        let (account, signature) = sample_account_and_signature();
        let checked = verify_account_binding(&account, &signature).unwrap();
        assert_eq!(checked.slot_id(), 0);

        let mut consumed = account.clone();
        consumed.mark_consumed(0).unwrap();
        let err = verify_account_binding(&consumed, &signature).unwrap_err();
        assert_eq!(err.slot_id(), Some(0));
        assert_eq!(err.reason(), "slot is already consumed");

        let mut mismatch = signature.as_bytes().to_vec();
        let proof_start = STATEFUL_TRANSACTION_SIGNATURE_BYTES;
        mismatch[proof_start] ^= 1;
        let err =
            verify_account_binding(&account, &ProductionSignature::new(mismatch)).unwrap_err();
        assert_eq!(err.slot_id(), Some(0));
        assert_eq!(err.reason(), "account randomizer commitment mismatch");
    }

    #[test]
    fn verify_with_account_binding_hands_checked_context_to_callback() {
        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let message = b"checked verifier callback";
        let (account, signature) = sample_account_and_signature();

        let (checked, result) = verify_with_account_binding(
            &public_key,
            message,
            &account,
            &signature,
            |checked_public_key, checked_message, checked_account, checked_signature, checked| {
                assert_eq!(checked_public_key.as_bytes(), public_key.as_bytes());
                assert_eq!(checked_message, message);
                assert_eq!(checked_account.len(), 1);
                assert_eq!(checked_signature.as_bytes(), signature.as_bytes());
                assert_eq!(checked.slot_id(), 0);
                Ok("legacy verifier accepted")
            },
        )
        .unwrap();
        assert_eq!(checked.slot_id(), 0);
        assert_eq!(result, "legacy verifier accepted");

        let next_account = consume_verified_signature(&account, &checked).unwrap();
        assert!(!next_account.get_slot(0).unwrap().is_unused());
        assert_eq!(
            consume_verified_signature(&next_account, &checked).unwrap_err(),
            "slot is already consumed"
        );
        let completed =
            complete_verified_signature(&account, checked.clone(), "accepted report", true)
                .unwrap();
        assert_eq!(completed.checked().slot_id(), 0);
        assert_eq!(completed.report(), &"accepted report");
        assert!(!completed.next_account().get_slot(0).unwrap().is_unused());
        let (report, completed_account) = completed.into_report_and_account();
        assert_eq!(report, "accepted report");
        assert!(!completed_account.get_slot(0).unwrap().is_unused());
        let consumed_err = complete_verified_signature(
            &completed_account,
            checked.clone(),
            "accepted again",
            true,
        )
        .unwrap_err();
        assert_eq!(consumed_err.slot_id(), Some(0));
        assert_eq!(consumed_err.reason(), "slot is already consumed");

        let rejected =
            complete_verified_signature(&account, checked, "rejected report", false).unwrap();
        assert!(rejected.next_account().get_slot(0).unwrap().is_unused());

        let err = verify_with_account_binding(
            &public_key,
            message,
            &account,
            &signature,
            |_public_key, _message, _account, _signature, _checked| {
                Err::<(), String>("legacy verifier rejected".to_string())
            },
        )
        .unwrap_err();
        assert_eq!(err.slot_id(), Some(0));
        assert_eq!(err.reason(), "legacy verifier rejected");
        let rejection = err.into_rejection();
        assert_eq!(rejection.slot_id(), Some(0));
        assert_eq!(rejection.reason(), "legacy verifier rejected");
        let fields = rejection_report_fields(&signature, rejection);
        assert_eq!(fields.proof_model, PRODUCTION_REFERENCE_FACADE_PROOF_MODEL);
        assert_eq!(
            fields.expected_signature_bytes,
            LINEAR_SIGMA_TARGET_TRANSACTION_SIGNATURE_BYTES
        );
        assert_eq!(fields.slot_id, Some(0));
        assert_eq!(fields.claimed_challenge, Some([0_u8; CHALLENGE_BYTES]));
        assert_eq!(fields.reason, "legacy verifier rejected");

        let short_signature = ProductionSignature::new(vec![0_u8; SLOT_ID_BYTES]);
        let short_fields = rejection_report_fields(
            &short_signature,
            ProductionVerificationRejection::new(None, "short signature"),
        );
        assert_eq!(short_fields.slot_id, None);
        assert_eq!(short_fields.claimed_challenge, None);
        assert_eq!(short_fields.reason, "short signature");
    }

    #[test]
    fn generated_rejection_reports_expose_only_public_metadata() {
        let (_account, signature) = sample_account_and_signature();
        let _secret_key = ProductionSecretKey::new("DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE");
        let mut public_attacker_signature = signature.as_bytes().to_vec();
        let response_start = SLOT_ID_BYTES + CHALLENGE_BYTES;
        let proof_start = STATEFUL_TRANSACTION_SIGNATURE_BYTES;
        public_attacker_signature[response_start] = u8::MAX;
        public_attacker_signature[proof_start..][..b"DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE".len()]
            .copy_from_slice(b"DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE");
        let attacker_signature = ProductionSignature::new(public_attacker_signature);

        let decode_err = attacker_signature.decode().unwrap_err();
        assert!(decode_err.contains("active response coordinate"));
        let fields = rejection_report_fields(
            &attacker_signature,
            ProductionVerificationRejection::new(None, decode_err),
        );

        assert_eq!(fields.proof_model, PRODUCTION_REFERENCE_FACADE_PROOF_MODEL);
        assert_eq!(
            fields.expected_signature_bytes,
            LINEAR_SIGMA_TARGET_TRANSACTION_SIGNATURE_BYTES
        );
        assert_eq!(fields.slot_id, None);
        assert_eq!(fields.claimed_challenge, Some([0_u8; CHALLENGE_BYTES]));
        assert_public_report_excludes_secret_sentinels(&fields);

        let lifecycle_error = ProductionLifecycleError::new(Some(7), "slot is already consumed");
        assert_eq!(lifecycle_error.slot_id(), Some(7));
        assert_eq!(lifecycle_error.reason(), "slot is already consumed");
        assert_public_report_excludes_secret_sentinels(&lifecycle_error);

        let binding_error =
            ProductionAccountBindingError::new(Some(3), "account randomizer commitment mismatch");
        assert_eq!(binding_error.slot_id(), Some(3));
        assert_eq!(
            binding_error.reason(),
            "account randomizer commitment mismatch"
        );
        assert_public_report_excludes_secret_sentinels(&binding_error);
    }

    #[test]
    fn sanitized_callback_wrappers_do_not_echo_secret_errors() {
        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let message = b"sanitized callback wrapper";
        let (account, signature) = sample_account_and_signature();
        let slot = account.get_slot(0).unwrap();
        let secret_key = ProductionSecretKey::new("DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE");

        let sign_error =
            sign_with_secret_key_sanitized(&secret_key, slot, |_secret, _slot_id, _witness| {
                Err("DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE signer detail".to_string())
            })
            .unwrap_err();
        assert_eq!(sign_error, PRODUCTION_SIGNER_CALLBACK_FAILURE_REASON);
        assert_serialized_public_state_excludes_secret_sentinels(&sign_error);

        let verify_error = verify_with_account_binding_sanitized(
            &public_key,
            message,
            &account,
            &signature,
            |_public_key, _message, _account, _signature, _checked| {
                Err::<(), String>(
                    "DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE verifier detail".to_string(),
                )
            },
        )
        .unwrap_err();
        assert_eq!(verify_error.slot_id(), Some(0));
        assert_eq!(
            verify_error.reason(),
            PRODUCTION_VERIFIER_CALLBACK_FAILURE_REASON
        );
        assert_public_report_excludes_secret_sentinels(&verify_error);

        let mut manager = ProductionAccountLifecycleManager::new(account.clone()).unwrap();
        let reservation = manager.reserve_slot(0).unwrap();
        let lifecycle_sign_error = manager
            .sign_reserved_and_consume_sanitized(reservation, |_slot_id, _witness| {
                Err("DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE lifecycle signer detail".to_string())
            })
            .unwrap_err();
        assert_eq!(lifecycle_sign_error.slot_id(), Some(0));
        assert_eq!(
            lifecycle_sign_error.reason(),
            PRODUCTION_SIGNER_CALLBACK_FAILURE_REASON
        );
        assert_public_report_excludes_secret_sentinels(&lifecycle_sign_error);
        assert_eq!(manager.snapshot_sequence(), 1);
        assert_eq!(manager.active_reservation_count(), 1);
        assert!(manager.is_reserved(0));
        assert!(manager.account().get_slot(0).unwrap().is_unused());

        let mut manager = ProductionAccountLifecycleManager::new(account.clone()).unwrap();
        let lifecycle_verify_error = manager
            .verify_and_consume_sanitized(
                &public_key,
                message,
                &signature,
                |_public_key, _message, _account, _signature, _checked| {
                    Err::<(), String>(
                        "DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE lifecycle verifier detail"
                            .to_string(),
                    )
                },
            )
            .unwrap_err();
        assert_eq!(lifecycle_verify_error.slot_id(), Some(0));
        assert_eq!(
            lifecycle_verify_error.reason(),
            PRODUCTION_VERIFIER_CALLBACK_FAILURE_REASON
        );
        assert_public_report_excludes_secret_sentinels(&lifecycle_verify_error);
        assert_eq!(manager.snapshot_sequence(), 0);
        assert!(manager.account().get_slot(0).unwrap().is_unused());

        let mut manager = ProductionAccountLifecycleManager::new(account).unwrap();
        let mut ledger = ProductionSpentSlotLedger::new();
        let spent_verify_error = manager
            .verify_consume_and_record_spent_sanitized(
                &mut ledger,
                &public_key,
                message,
                &signature,
                |_public_key, _message, _account, _signature, _checked| {
                    Err::<(), String>(
                        "DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE spent verifier detail".to_string(),
                    )
                },
            )
            .unwrap_err();
        assert_eq!(spent_verify_error.slot_id(), Some(0));
        assert_eq!(
            spent_verify_error.reason(),
            PRODUCTION_VERIFIER_CALLBACK_FAILURE_REASON
        );
        assert_public_report_excludes_secret_sentinels(&spent_verify_error);
        assert_eq!(manager.snapshot_sequence(), 0);
        assert!(manager.account().get_slot(0).unwrap().is_unused());
        assert!(ledger.is_empty());

        let lifecycle_path = temp_json_path("descender-chain-sanitized-lifecycle");
        let ledger_path = temp_json_path("descender-chain-sanitized-ledger");
        let stores = ProductionChainStateFileStores::new(&lifecycle_path, &ledger_path);
        let (account, signature) = sample_account_and_signature();
        stores
            .lifecycle_store()
            .save_manager(&ProductionAccountLifecycleManager::new(account).unwrap())
            .unwrap();
        let chain_verify_error = stores
            .verify_consume_record_and_save_sanitized(
                None,
                &public_key,
                message,
                &signature,
                |_public_key, _message, _account, _signature, _checked| {
                    Err::<(), String>(
                        "DESCENDER_TEST_SECRET_DO_NOT_SERIALIZE chain verifier detail".to_string(),
                    )
                },
            )
            .unwrap_err();
        assert_eq!(chain_verify_error.slot_id(), Some(0));
        assert_eq!(
            chain_verify_error.reason(),
            PRODUCTION_VERIFIER_CALLBACK_FAILURE_REASON
        );
        assert_public_report_excludes_secret_sentinels(&chain_verify_error);
        let restored_manager = stores.lifecycle_store().load_manager().unwrap().unwrap();
        assert_eq!(restored_manager.snapshot_sequence(), 0);
        assert!(restored_manager.account().get_slot(0).unwrap().is_unused());
        assert!(stores.spent_ledger_store().load_ledger().unwrap().is_none());
        let _ = std::fs::remove_file(lifecycle_path);
        let _ = std::fs::remove_file(ledger_path);
        let _ = std::fs::remove_file(stores.lifecycle_store().lock_path());
        let _ = std::fs::remove_file(stores.spent_ledger_store().lock_path());
    }

    #[test]
    fn sanitized_callback_wrappers_have_bounded_invocation_shape() {
        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let message = b"sanitized callback invocation shape";
        let (account, signature) = sample_account_and_signature();
        let slot = account.get_slot(0).unwrap();
        let secret_key = ProductionSecretKey::new("reference-secret");

        let calls = Cell::new(0_usize);
        let err =
            sign_with_secret_key_sanitized(&secret_key, slot, |_secret, _slot_id, _witness| {
                calls.set(calls.get() + 1);
                Err("signer detail".to_string())
            })
            .unwrap_err();
        assert_eq!(err, PRODUCTION_SIGNER_CALLBACK_FAILURE_REASON);
        assert_eq!(calls.get(), 1);

        let mut consumed_account = account.clone();
        consumed_account.mark_consumed(0).unwrap();
        let calls = Cell::new(0_usize);
        let err = sign_with_secret_key_sanitized(
            &secret_key,
            consumed_account.get_slot(0).unwrap(),
            |_secret, _slot_id, _witness| {
                calls.set(calls.get() + 1);
                Err("must not run".to_string())
            },
        )
        .unwrap_err();
        assert_eq!(err, "slot is already consumed");
        assert_eq!(calls.get(), 0);

        let calls = Cell::new(0_usize);
        let err = verify_with_account_binding_sanitized(
            &public_key,
            message,
            &account,
            &signature,
            |_public_key, _message, _account, _signature, _checked| {
                calls.set(calls.get() + 1);
                Err::<(), String>("verifier detail".to_string())
            },
        )
        .unwrap_err();
        assert_eq!(err.reason(), PRODUCTION_VERIFIER_CALLBACK_FAILURE_REASON);
        assert_eq!(calls.get(), 1);

        let calls = Cell::new(0_usize);
        let short_signature = ProductionSignature::new(vec![0_u8; SLOT_ID_BYTES]);
        let err = verify_with_account_binding_sanitized(
            &public_key,
            message,
            &account,
            &short_signature,
            |_public_key, _message, _account, _signature, _checked| {
                calls.set(calls.get() + 1);
                Err::<(), String>("must not run".to_string())
            },
        )
        .unwrap_err();
        assert!(err.reason().starts_with("signature has"));
        assert_eq!(calls.get(), 0);

        let mut manager = ProductionAccountLifecycleManager::new(account.clone()).unwrap();
        let calls = Cell::new(0_usize);
        let err = manager
            .verify_and_consume_sanitized(
                &public_key,
                message,
                &signature,
                |_public_key, _message, _account, _signature, _checked| {
                    calls.set(calls.get() + 1);
                    Err::<(), String>("lifecycle verifier detail".to_string())
                },
            )
            .unwrap_err();
        assert_eq!(err.reason(), PRODUCTION_VERIFIER_CALLBACK_FAILURE_REASON);
        assert_eq!(calls.get(), 1);

        let mut ledger = ProductionSpentSlotLedger::new();
        let checked = verify_account_binding(&account, &signature).unwrap();
        ledger
            .record_checked_signature(&public_key, &checked, 0, "accepted verification")
            .unwrap();
        let mut manager = ProductionAccountLifecycleManager::new(account).unwrap();
        let calls = Cell::new(0_usize);
        let err = manager
            .verify_consume_and_record_spent_sanitized(
                &mut ledger,
                &public_key,
                message,
                &signature,
                |_public_key, _message, _account, _signature, _checked| {
                    calls.set(calls.get() + 1);
                    Err::<(), String>("must not run".to_string())
                },
            )
            .unwrap_err();
        assert_eq!(err.reason(), "slot is already in spent ledger");
        assert_eq!(calls.get(), 0);
    }

    #[test]
    fn callback_boundary_classification_marks_only_sanitized_paths_deployment_facing() {
        let diagnostic = [
            "sign_with_account_binding",
            "sign_with_secret_key",
            "verify_with_account_binding",
            "sign_reserved_and_consume",
            "verify_and_consume",
            "verify_consume_and_record_spent",
            "verify_consume_record_and_save",
        ];
        let sanitized = [
            "sign_with_account_binding_sanitized",
            "sign_with_secret_key_sanitized",
            "verify_with_account_binding_sanitized",
            "verify_reviewed_fq12_account_carried_hidden_source_proof",
            "verify_reviewed_fq12_account_carried_hidden_source_proof_with_transcript",
            "sign_reserved_and_consume_sanitized",
            "verify_and_consume_sanitized",
            "verify_consume_and_record_spent_sanitized",
            "verify_consume_record_and_save_sanitized",
        ];

        assert_eq!(
            PRODUCTION_CALLBACK_BOUNDARIES.len(),
            diagnostic.len() + sanitized.len()
        );
        for boundary in diagnostic {
            let classification = production_callback_boundary_classification(boundary).unwrap();
            assert_eq!(
                classification.error_policy,
                ProductionCallbackErrorPolicy::DiagnosticRawCallbackErrors
            );
            assert!(!classification.deployment_facing);
        }
        for boundary in sanitized {
            let classification = production_callback_boundary_classification(boundary).unwrap();
            assert_eq!(
                classification.error_policy,
                ProductionCallbackErrorPolicy::SanitizedFixedPublicErrors
            );
            assert!(classification.deployment_facing);
        }
        assert!(production_callback_boundary_classification("unknown").is_none());
        assert!(PRODUCTION_CALLBACK_BOUNDARIES
            .iter()
            .filter(|classification| classification.deployment_facing)
            .all(|classification| classification.error_policy
                == ProductionCallbackErrorPolicy::SanitizedFixedPublicErrors));
    }

    #[test]
    fn deployment_callback_boundary_gate_rejects_diagnostic_paths() {
        let sanitized = [
            "sign_with_account_binding_sanitized",
            "sign_with_secret_key_sanitized",
            "verify_with_account_binding_sanitized",
            "verify_reviewed_fq12_account_carried_hidden_source_proof_with_transcript",
            "sign_reserved_and_consume_sanitized",
            "verify_and_consume_sanitized",
            "verify_consume_and_record_spent_sanitized",
            "verify_consume_record_and_save_sanitized",
        ];
        assert!(require_deployment_callback_boundaries(sanitized).is_ok());

        let raw_err = require_deployment_callback_boundaries([
            "sign_with_secret_key_sanitized",
            "verify_with_account_binding",
        ])
        .unwrap_err();
        assert_eq!(
            raw_err,
            "callback boundary verify_with_account_binding is diagnostic-only and not deployment-facing"
        );

        let unknown_err = require_deployment_callback_boundaries(["unknown_boundary"]).unwrap_err();
        assert_eq!(unknown_err, "unknown callback boundary: unknown_boundary");
    }

