        let mut rebound = soundness.clone();
        rebound.statement_digest[0] ^= 1;
        assert_eq!(
            path2_reviewed_fq12_hidden_relation_extraction_certificate_v1(
                &payload_binding,
                &rebound,
            )
            .unwrap_err(),
            "Path 2 extraction certificate statement digest mismatch"
        );
