    #[test]
    fn spent_slot_ledger_file_store_lock_serializes_writers() {
        let path = std::env::temp_dir().join(format!(
            "descender-spent-ledger-lock-{}-{}.json",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        let store = ProductionSpentSlotLedgerFileStore::new(&path);
        let lock_path = store.lock_path();
        let lock = store.try_lock().unwrap();
        assert_eq!(lock.path(), lock_path.as_path());
        assert!(lock_path.exists());

        let duplicate = store.try_lock().unwrap_err();
        assert_eq!(duplicate.reason(), "spent-slot ledger is locked");

        drop(lock);
        assert!(!lock_path.exists());
        let reacquired = store.try_lock().unwrap();
        drop(reacquired);

        let _ = std::fs::remove_file(path);
        let _ = std::fs::remove_file(lock_path);
    }

    #[test]
    fn chain_state_file_stores_verify_record_and_persist_together() {
        let nonce = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let lifecycle_path = std::env::temp_dir().join(format!(
            "descender-chain-lifecycle-{}-{nonce}.json",
            std::process::id()
        ));
        let ledger_path = std::env::temp_dir().join(format!(
            "descender-chain-ledger-{}-{nonce}.json",
            std::process::id()
        ));
        let stores = ProductionChainStateFileStores::new(&lifecycle_path, &ledger_path);
        assert_eq!(stores.lifecycle_store().path(), lifecycle_path.as_path());
        assert_eq!(stores.spent_ledger_store().path(), ledger_path.as_path());

        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let message = b"chain state transition";
        let (account, signature) = sample_account_and_signature();
        let manager = ProductionAccountLifecycleManager::new(account.clone()).unwrap();
        stores.lifecycle_store().save_manager(&manager).unwrap();

        let verification = stores
            .verify_consume_record_and_save(
                Some(ProductionLifecycleRestoreAnchor {
                    minimum_snapshot_sequence: 0,
                }),
                &public_key,
                message,
                &signature,
                |_public_key, checked_message, _account, _signature, checked| {
                    assert_eq!(checked_message, message);
                    assert_eq!(checked.slot_id(), 0);
                    Ok("accepted")
                },
            )
            .unwrap();
        assert_eq!(verification.report(), &"accepted");

        let restored_manager = stores.lifecycle_store().load_manager().unwrap().unwrap();
        assert!(!restored_manager.account().get_slot(0).unwrap().is_unused());
        let restored_ledger = stores.spent_ledger_store().load_ledger().unwrap().unwrap();
        let key = ProductionSpentSlotLedger::key(&public_key, 0);
        assert!(restored_ledger.is_spent(&key));
        let record = restored_ledger.record(&key).unwrap();
        assert_eq!(record.source, "accepted verification");
        assert_eq!(
            record.snapshot_sequence,
            restored_manager.snapshot_sequence()
        );

        stores
            .lifecycle_store()
            .save_manager(&ProductionAccountLifecycleManager::new(account).unwrap())
            .unwrap();
        let replay = stores
            .verify_consume_record_and_save(
                None,
                &public_key,
                message,
                &signature,
                |_public_key, _message, _account, _signature, _checked| Ok("replay"),
            )
            .unwrap_err();
        assert_eq!(replay.reason(), "slot is already in spent ledger");

        let _ = std::fs::remove_file(lifecycle_path);
        let _ = std::fs::remove_file(ledger_path);
        let _ = std::fs::remove_file(stores.lifecycle_store().lock_path());
        let _ = std::fs::remove_file(stores.spent_ledger_store().lock_path());
    }

